@Slf4j
@PluginDescriptor(
	name = "Codex Log Insight",
	description = "Collection log analytics: your luck at your kill counts, time left on each page and the fastest slots to chase",
	tags = {"collection", "log", "clog", "luck", "dry", "drop", "rate", "pet", "kc", "codex"}
)
public class CodexLogInsightPlugin extends Plugin
{
	private static final String PROGRESS_KEY = "progress";
	/** Added to a key's name to keep aside a saved value that could not be read in full. */
	private static final String UNREADABLE = "Unreadable";
	/** The script that sends the client every owned slot when the log's Search is opened. */
	private static final int COLLECTION_TRANSMIT = 4100;
	/** Enum of the log's tabs; each tab struct points to its pages, each page to its slots. */
	private static final int TAB_ENUM = 2102;
	private static final int TAB_PAGES_PARAM = 683;
	private static final int PAGE_NAME_PARAM = 689;
	private static final int PAGE_ITEMS_PARAM = 690;
	/** Slots whose id the log swaps for a stand-in, mapping the stand-in back. */
	private static final int REPLACEMENT_ENUM = 3721;
	private static final String[] TAB_NAMES = {"Bosses", "Raids", "Clues", "Minigames", "Other"};
	private static final int TRANSMIT_SETTLE_TICKS = 3;
	private static final int SAVE_TICKS = 100;
	private static final int ANALYSE_GAP_TICKS = 2;
	private static final String POPUP_PREFIX = "New item:";
	/** Skill levels and quests are read again this often, to notice what has opened up. */
	private static final int UNLOCKS_TICKS = 100;
	/**
	 * After a stat changes (the levels sent at login, or a level up) the levels are read again this many ticks on,
	 * once the burst has passed, rather than waiting a minute with the pets at the wrong odds.
	 */
	private static final int UNLOCKS_AFTER_STATS_TICKS = 3;
	/** Varbits sent at login have all arrived by this many ticks after it; a setting read sooner may be a blank. */
	private static final int SETTLE_TICKS = 10;

	/** How many items the game has (the highest id plus one), or 0 until the client has its item table. */
	private volatile int itemCount;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	@Inject
	private CodexLogInsightConfig config;

	private final FindPlaque plaque = new FindPlaque();
	private final AtomicInteger generation = new AtomicInteger();
	private final Set<Integer> harvest = new HashSet<>();
	/** The log's count of each slot in the read under way. */
	private final Map<Integer, Integer> harvestCounts = new HashMap<>();
	private final Map<Integer, Integer> replacements = new HashMap<>();

	/** The tables as bundled, with skilling pets at level 99. */
	private LogData baseData;
	/** The tables at this account's levels; what every read uses. */
	private LogData data;
	private Analyst analyst;
	/** The levels {@link #data} was scaled to, only for the skills a rate depends on. */
	private Map<String, Integer> scaledAt;
	private ChatReader chat;
	private LogInsightPanel panel;
	private NavigationButton navButton;

	private LogStructure structure = LogStructure.empty();
	private Progress progress;
	private String profile;
	private boolean dirty;
	private boolean unsaved;
	private int ticksSinceSave;
	private int ticksSinceAnalysis;
	private int lastTransmitTick = -1;
	private int officialOwned = -1;
	private int officialTotal = -1;
	private final Map<String, Quest> questsNeeded = new HashMap<>();
	private Unlocks unlocks = Unlocks.UNKNOWN;
	private int unlocksReadAt = -1;
	/** The tick a level last changed, or -1; levels are read again shortly after. */
	private int statsChangedAt = -1;
	/** Each skill's level as last reported, to tell a level up from experience alone. */
	private final Map<Skill, Integer> statLevels = new EnumMap<>(Skill.class);
	/** Whether the last analysis used ironman rates, so a change of account type once varbits arrive is noticed. */
	private Boolean ironShown;
	/** The game's new-slot notification setting once settled after login, or {@link Setup#NOTICES_UNKNOWN}. */
	private int notices = Setup.NOTICES_UNKNOWN;
	/** The tick of the last login, for {@link #SETTLE_TICKS}; -1 while logged out. */
	private int loginTick = -1;
	/** The "notifications are off" chat line is said once a session. */
	private boolean noticesWarned;
	/** This play session, from the login that loaded the progress; a world hop keeps it. */
	private Session session;
	private boolean notificationStarted;
	/** The chat line and the pop-up can both announce one slot; the second is ignored. */
	private final Announcements announcements = new Announcements();
	/** Kill count changes waiting a few ticks for the same kill's new-slot messages before milestones are checked. */
	private final DryWatch.Queue milestones = new DryWatch.Queue();
	private final GrindCard grindCard = new GrindCard();
	/** The counter the last kill count message moved, and when, for the grind card; null until one moves. */
	/** How long after a kill count rises a new slot is taken to have come from that kill. */
	private static final long RECENT_KILL_MS = 120_000;

	private String grindLabel;
	private long grindAt;

	@Provides
	CodexLogInsightConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexLogInsightConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		baseData = LogData.load(gson);
		data = baseData;
		analyst = new Analyst(data);
		scaledAt = null;
		chat = new ChatReader(data.getLabels());
		Map<String, Quest> quests = new HashMap<>();
		for (Quest quest : Quest.values())
		{
			quests.putIfAbsent(Unlocks.normalise(quest.name()), quest);
			quests.putIfAbsent(Unlocks.normalise(quest.getName()), quest);
		}
		for (String name : data.questsNeeded())
		{
			Quest quest = quests.get(Unlocks.normalise(name));
			if (quest != null)
			{
				questsNeeded.put(name, quest);
			}
		}
		// Pictures that have been drawn in, held weakly by the very image handed out (the item manager may later hand
		// out a fresh blank for the same item), so a card can wait for exactly the pictures it will draw.
		Set<BufferedImage> arrived = Collections.synchronizedSet(Collections.newSetFromMap(new WeakHashMap<>()));
		ItemIcons icons = new ItemIcons()
		{
			@Override
			public BufferedImage icon(int itemId, Runnable onLoaded)
			{
				// A find's id comes from the save: one the game does not have would never draw, and the item manager
				// would try again for it on every client tick.
				int known = itemCount;
				if (itemId <= 0 || known > 0 && itemId >= known)
				{
					return null;
				}
				AsyncBufferedImage image = itemManager.getImage(itemId);
				image.onLoaded(() ->
				{
					arrived.add(image);
					if (onLoaded != null)
					{
						onLoaded.run();
					}
				});
				return image;
			}

			@Override
			public boolean ready(BufferedImage image)
			{
				return image != null && arrived.contains(image);
			}
		};
		panel = new LogInsightPanel(icons);
		panel.setShare(new ShareActions()
		{
			@Override
			public void save(BufferedImage card, String fileName)
			{
				saveCard(card, fileName);
			}

			@Override
			public void copy(BufferedImage card)
			{
				copyCard(card);
			}
		}, config::nameOnCard);
		panel.setOnWant(itemId -> clientThread.invokeLater(() -> toggleWanted(itemId)));
		navButton = NavigationButton.builder()
			.tooltip("Codex Log Insight")
			.icon(Sigil.icon(16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(plaque);
		overlayManager.add(grindCard);
		clientThread.invokeLater(() ->
		{
			if (client.getGameState().ordinal() >= GameState.LOGIN_SCREEN.ordinal())
			{
				itemCount = client.getItemCount();
			}
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadProgress();
				buildStructure();
				dirty = true;
			}
		});
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(() ->
		{
			save();
			milestones.clear();
			progress = null;
			profile = null;
		});
		overlayManager.remove(plaque);
		overlayManager.remove(grindCard);
		grindCard.clear();
		clientToolbar.removeNavigation(navButton);
		plaque.clear();
		generation.incrementAndGet();
		structure = LogStructure.empty();
		harvest.clear();
		harvestCounts.clear();
		lastTransmitTick = -1;
		loginTick = -1;
		notices = Setup.NOTICES_UNKNOWN;
		noticesWarned = false;
		ironShown = null;
		statsChangedAt = -1;
		statLevels.clear();
		if (panel != null)
		{
			panel.shutDown();
		}
		panel = null;
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		// ConfigManager writes its changes to disk in this same event, before a save queued on the
		// client thread runs, so a save made here has to be sent on by hand or it is never written.
		CompletableFuture<Void> done = new CompletableFuture<>();
		clientThread.invokeLater(() ->
		{
			try
			{
				if (save())
				{
					configManager.sendConfig();
				}
			}
			finally
			{
				done.complete(null);
			}
		});
		event.waitFor(done);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.LOGGED_IN)
		{
			// The item table is loaded by the login screen; read here, on the client thread, for the panel's pictures.
			itemCount = client.getItemCount();
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			harvest.clear();
			harvestCounts.clear();
			lastTransmitTick = -1;
			// A hop logs in afresh and the varbits arrive again: settings read in between may be blanks.
			loginTick = -1;
		}
		if (event.getGameState() == GameState.LOGGED_IN && loginTick < 0)
		{
			loginTick = client.getTickCount();
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			loginTick = -1;
			notices = Setup.NOTICES_UNKNOWN;
			noticesWarned = false;
			ironShown = null;
			statsChangedAt = -1;
			statLevels.clear();
			save();
			progress = null;
			profile = null;
			session = null;
			officialOwned = -1;
			officialTotal = -1;
			unlocks = Unlocks.UNKNOWN;
			unlocksReadAt = -1;
			// The next account's levels are its own; until they are read, pets go back to the bundled odds.
			if (scaledAt != null)
			{
				scaledAt = null;
				data = baseData;
				analyst = new Analyst(data);
			}
			announcements.clear();
			milestones.clear();
			grindLabel = null;
			// An analysis still running for the account just left must not land after this: it would put that
			// account's report back in the panel, and its grind card back on screen, while logged out.
			generation.incrementAndGet();
			grindCard.clear();
			plaque.clear();
			publish(Report.loggedOut(), null);
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		save();
		// A kill counted on the account before the switch is not this account's milestone.
		milestones.clear();
		grindLabel = null;
		grindCard.clear();
		progress = null;
		loadProgress();
		dirty = true;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CodexLogInsightConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (!config.showPlaque())
		{
			plaque.clear();
		}
		dirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (progress == null)
		{
			loadProgress();
			dirty |= progress != null;
		}
		if (structure.isEmpty())
		{
			buildStructure();
			dirty |= !structure.isEmpty();
		}
		if (!milestones.isEmpty() && progress != null)
		{
			for (DryWatch.Pending due : milestones.due(client.getTickCount()))
			{
				if (config.dryMilestones() && DryWatch.ownedKnown(progress.getFullReadAt(), officialOwned, progress.getOwned().size()))
				{
					announceMilestones(due.getLabel(), due.getBefore(), due.getAfter());
				}
			}
		}
		if (lastTransmitTick >= 0 && client.getTickCount() - lastTransmitTick > TRANSMIT_SETTLE_TICKS)
		{
			finishFullRead();
		}

		int owned = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		if (total > 0 && (owned != officialOwned || total != officialTotal))
		{
			officialOwned = owned;
			officialTotal = total;
			dirty = true;
		}

		int now = client.getTickCount();
		boolean statsSettled = statsChangedAt >= 0 && now - statsChangedAt >= UNLOCKS_AFTER_STATS_TICKS;
		if (progress != null && (unlocksReadAt < 0 || now - unlocksReadAt >= UNLOCKS_TICKS || statsSettled))
		{
			statsChangedAt = -1;
			readUnlocks();
		}
		if (loginTick < 0)
		{
			// Turned on while already logged in: count from now.
			loginTick = now;
		}
		if (now - loginTick >= SETTLE_TICKS)
		{
			watchNotices();
			// The account type arrives with the varbits at login: an analysis made before it used the wrong rates.
			if (ironShown != null && ironShown != ironRates())
			{
				dirty = true;
			}
		}

		ticksSinceAnalysis++;
		if (dirty && ticksSinceAnalysis >= ANALYSE_GAP_TICKS)
		{
			dirty = false;
			ticksSinceAnalysis = 0;
			analyse();
		}
		if (unsaved && ++ticksSinceSave >= SAVE_TICKS)
		{
			save();
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() == ScriptID.NOTIFICATION_START)
		{
			notificationStarted = true;
			return;
		}
		if (event.getScriptId() == ScriptID.NOTIFICATION_DELAY)
		{
			readNotification();
			return;
		}
		if (event.getScriptId() != COLLECTION_TRANSMIT || progress == null || isAnotherPlayersLog())
		{
			return;
		}
		ScriptEvent script = event.getScriptEvent();
		Object[] args = script == null ? null : script.getArguments();
		if (args == null || args.length < 3 || !(args[1] instanceof Integer) || !(args[2] instanceof Integer))
		{
			return;
		}
		int itemId = (Integer) args[1];
		int quantity = (Integer) args[2];
		if (itemId > 0 && quantity > 0)
		{
			int slot = replacements.getOrDefault(itemId, itemId);
			harvest.add(slot);
			harvestCounts.merge(slot, quantity, Math::max);
			lastTransmitTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.COLLECTION_DRAW_LIST)
		{
			// The page's header and slots are filled in after the script returns.
			clientThread.invokeLater(this::readOpenPage);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (progress == null || type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
			&& type != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}
		String message = event.getMessage();
		ChatReader.Count count = chat.count(message);
		if (count != null && count.value >= 0)
		{
			Integer before = progress.counter(count.label);
			if (session != null)
			{
				session.observe(count.label, count.value, true);
			}
			progress.setCounter(count.label, count.value);
			if (before != null && count.value > before)
			{
				grindLabel = count.label;
				grindAt = System.currentTimeMillis();
			}
			if (config.dryMilestones() && before != null)
			{
				// Checked a few ticks on, once this kill's own "new item" line or pop-up has marked its slot owned.
				milestones.add(count.label, before, count.value, client.getTickCount());
			}
			if (config.learnPace())
			{
				progress.paceFor(count.label).record(count.value, System.currentTimeMillis());
			}
			changed();
			return;
		}
		String slot = ChatReader.newSlot(message);
		if (slot != null)
		{
			announced(slot, Announcements.Channel.CHAT);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// Only a new level matters (experience moves with every action while skilling, and the read runs quest
		// scripts); at login every skill arrives at once, so the read waits for the burst to pass.
		Integer before = statLevels.put(event.getSkill(), event.getLevel());
		if (before == null || before != event.getLevel())
		{
			statsChangedAt = client.getTickCount();
		}
	}

	/**
	 * Notices when the game is set to announce no new slots, which leaves Log Insight blind to finds: the Ledger says
	 * so, and one chat line says it once a session.
	 */
	private void watchNotices()
	{
		int setting = client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM);
		if (setting != notices)
		{
			notices = setting;
			dirty = true;
		}
		if (setting == 0 && !noticesWarned && progress != null && config.chatLine())
		{
			noticesWarned = true;
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(new ChatMessageBuilder()
					.append(ChatColorType.HIGHLIGHT).append("Log Insight: ")
					.append(ChatColorType.NORMAL).append("the game is set to announce no new collection log slots, so finds"
						+ " go unseen. Turn on new addition notifications in the game's settings.")
					.build())
				.build());
		}
	}

	/** The game's pop-up for a new slot, for players who turned the chat line off. */
	private void readNotification()
	{
		if (!notificationStarted)
		{
			return;
		}
		notificationStarted = false;
		String title = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
		String body = client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN);
		if (progress == null || title == null || body == null || !"Collection log".equalsIgnoreCase(title.trim()))
		{
			return;
		}
		String text = Text.removeTags(body).trim();
		if (text.startsWith(POPUP_PREFIX))
		{
			announced(text.substring(POPUP_PREFIX.length()).trim(), Announcements.Channel.POPUP);
		}
	}

	private void announced(String slot, Announcements.Channel channel)
	{
		if (!announcements.fresh(slot, channel, System.currentTimeMillis()))
		{
			return;
		}
		onNewSlot(slot.trim());
	}

	/** Reads the account's real skill levels and which needed quests are still unfinished. */
	private void readUnlocks()
	{
		unlocksReadAt = client.getTickCount();
		Map<String, Integer> levels = new HashMap<>();
		Set<String> maxed = new HashSet<>();
		for (Skill skill : Skill.values())
		{
			levels.put(skill.name(), client.getRealSkillLevel(skill));
			if (client.getSkillExperience(skill) >= Experience.MAX_SKILL_XP)
			{
				maxed.add(skill.name());
			}
		}
		rescale(levels, maxed);
		Set<String> unfinished = new HashSet<>();
		for (Map.Entry<String, Quest> quest : questsNeeded.entrySet())
		{
			if (quest.getValue().getState(client) != QuestState.FINISHED)
			{
				unfinished.add(quest.getKey());
			}
		}
		Unlocks read = new Unlocks(levels, unfinished);
		if (!read.equals(unlocks))
		{
			unlocks = read;
			dirty = true;
		}
	}

	/** Puts skilling pets at this account's levels; only a change in one of their skills builds new tables. */
	private void rescale(Map<String, Integer> levels, Set<String> maxed)
	{
		Map<String, Integer> key = new HashMap<>();
		for (String skill : baseData.scaledSkills())
		{
			Integer level = levels.get(skill);
			// A 200M skill is keyed apart from a 99 one: its pet is fifteen times likelier.
			key.put(skill, level == null ? 0 : maxed.contains(skill) ? level + 1000 : level);
		}
		if (key.equals(scaledAt))
		{
			return;
		}
		scaledAt = key;
		data = baseData.atLevels(levels, maxed);
		analyst = new Analyst(data);
		dirty = true;
	}

	/** Reads the page open in the collection log: its counters and which slots are owned. */
	private void readOpenPage()
	{
		if (progress == null || isAnotherPlayersLog())
		{
			return;
		}
		Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		Widget[] lines = header == null ? null : header.getDynamicChildren();
		if (lines == null || lines.length == 0 || lines[0] == null)
		{
			return;
		}
		String page = Text.removeTags(lines[0].getText()).trim();
		if (page.isEmpty())
		{
			return;
		}
		List<String> labels = new ArrayList<>();
		for (int i = 1; i < lines.length; i++)
		{
			ChatReader.Count counter = lines[i] == null ? null : ChatReader.pageCounter(lines[i].getText());
			if (counter != null)
			{
				labels.add(counter.label);
				if (session != null)
				{
					session.observe(counter.label, counter.value, false);
				}
				progress.setCounter(counter.label, counter.value);
			}
		}
		Widget items = client.getWidget(InterfaceID.Collection.ITEMS);
		Widget[] slots = items == null ? null : items.getDynamicChildren();
		if (slots != null)
		{
			for (Widget slot : slots)
			{
				// The log draws owned slots solid and missing ones faded.
				if (slot != null && slot.getItemId() > 0 && slot.getOpacity() == 0)
				{
					int id = replacements.getOrDefault(slot.getItemId(), slot.getItemId());
					progress.addOwned(id);
					recordCount(id, slot.getItemQuantity());
				}
			}
		}
		progress.setPageLabels(page, labels);
		progress.markPageRead(page, System.currentTimeMillis());
		changed();
	}

	/** Keeps the log's count of a slot together with the counters it drops from, as they stand now. */
	private void recordCount(int itemId, int count)
	{
		ItemOdds odds = data.odds(itemId);
		java.util.List<String> labels = new java.util.ArrayList<>();
		if (odds != null)
		{
			for (ItemOdds.Roll roll : odds.getRolls())
			{
				labels.add(roll.getLabel());
			}
		}
		progress.setObtained(itemId, count, labels);
	}

	private void finishFullRead()
	{
		lastTransmitTick = -1;
		if (progress == null || harvest.isEmpty())
		{
			harvest.clear();
			harvestCounts.clear();
			return;
		}
		// Every id the game sent must be one the log's pages use, or replacing would drop a slot the next page open
		// adds back.
		boolean known = harvest.stream().noneMatch(id -> structure.pagesOf(id).isEmpty());
		if (officialOwned > 0 && harvest.size() >= officialOwned && known)
		{
			// The read holds the whole log, so it is the truth: a slot once marked in error goes.
			progress.replaceOwned(harvest);
		}
		else
		{
			for (int id : harvest)
			{
				progress.addOwned(id);
			}
		}
		for (Map.Entry<Integer, Integer> count : harvestCounts.entrySet())
		{
			recordCount(count.getKey(), count.getValue());
		}
		harvest.clear();
		harvestCounts.clear();
		progress.setFullReadAt(System.currentTimeMillis());
		changed();
		save();
	}

	private void onNewSlot(String name)
	{
		// Several slots share some names; the counter that just rose says which one, else none is marked.
		String recent = grindLabel != null && System.currentTimeMillis() - grindAt < RECENT_KILL_MS ? grindLabel : null;
		SlotResolver.Result resolved = SlotResolver.resolve(structure.idsNamed(name), progress.getOwned(), data::odds, recent);
		int itemId = resolved.shown;
		boolean ambiguous = resolved.ambiguous();

		ItemOdds odds = itemId > 0 ? data.odds(itemId) : null;
		String label = null;
		int count = 0;
		double chance = 0;
		double luckier = -1;
		if (odds != null)
		{
			label = odds.mainLabel();
			Integer value = progress.counter(label);
			count = value == null ? 0 : value;
			chance = odds.mainChance();
			luckier = odds.dryChance(progress.getCounters());
		}
		else if (itemId > 0)
		{
			for (Activity.Drop drop : data.dropsOf(itemId))
			{
				chance = Math.max(chance, 1 / Math.max(1, drop.getAttempts()));
			}
		}
		List<LogStructure.Page> pages = itemId > 0 && !ambiguous ? structure.pagesOf(itemId) : java.util.Collections.emptyList();
		String page = pages.isEmpty() ? null : pages.get(0).getName();
		boolean wasWanted = !ambiguous && itemId > 0 && progress.isWanted(itemId);
		if (resolved.owned > 0 && progress.addOwned(resolved.owned))
		{
			// A new slot is one copy until the log is read again.
			recordCount(resolved.owned, 1);
		}
		progress.addFind(new Progress.Find(itemId, name, page, label, count, chance, luckier, System.currentTimeMillis()));
		changed();
		save();

		String odd = chance > 0 ? Format.chance(chance) + (count > 0 ? " at " + Format.count(count) + " " + Format.counterName(label) + " kc" : "") : page;
		String verdict = luckier >= 0 ? "Luckier than " + Math.round(luckier * 100) + "% of players" : null;
		Color color = luckier >= 0 ? Theme.luck(Luck.verdict(luckier)) : Theme.GOLD;
		if (config.showPlaque())
		{
			plaque.show(new FindPlaque.View(name, page, odd, verdict, color, itemId > 0 && data.isPet(itemId),
				itemId > 0 ? itemManager.getImage(itemId) : null, System.currentTimeMillis(), config.plaqueSeconds() * 1000L,
				wasWanted));
		}
		if (config.chatLine() && (chance > 0 || verdict != null))
		{
			ChatMessageBuilder line = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Log Insight: ")
				.append(ChatColorType.NORMAL).append(name);
			if (odd != null)
			{
				line.append(", " + odd);
			}
			if (verdict != null)
			{
				line.append(". ").append(ChatColorType.HIGHLIGHT).append(verdict).append(ChatColorType.NORMAL);
			}
			line.append(wasWanted ? ". Off your wanted list." : ".");
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(line.build())
				.build());
		}
	}

	/** Marks a slot wanted or not, from a click in the panel, and shows the change at the next tick. */
	private void toggleWanted(int itemId)
	{
		if (progress == null || !progress.toggleWanted(itemId))
		{
			return;
		}
		changed();
		// A click deserves an answer now, not after the usual pause between analyses.
		ticksSinceAnalysis = ANALYSE_GAP_TICKS;
	}

	/** One chat line when a kill takes you past a dry milestone on a slot you are still missing. */
	private void announceMilestones(String label, int before, int after)
	{
		List<DryWatch.Milestone> passed = DryWatch.passed(data, progress.getOwned(), progress.getCounters(), label, before, after);
		if (passed.isEmpty())
		{
			return;
		}
		DryWatch.Milestone top = passed.get(0);
		String name = structure.name(top.getItemId());
		if (name == null || name.isEmpty())
		{
			return;
		}
		ChatMessageBuilder line = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Log Insight: ")
			.append(ChatColorType.NORMAL).append(Format.count(after) + " " + Format.counterName(label) + " kc. ")
			.append(capitalise(top.players()) + " would have ")
			.append(ChatColorType.HIGHLIGHT).append(name)
			.append(ChatColorType.NORMAL).append((passed.size() > 1 ? " and " + (passed.size() - 1) + " more" : "")
				+ " by now (" + Format.chance(top.getChance()) + ").");
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(line.build())
			.build());
	}

	private static String capitalise(String text)
	{
		return text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}

	private void changed()
	{
		dirty = true;
		unsaved = true;
	}

	private boolean isAnotherPlayersLog()
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
	}

	private boolean ironRates()
	{
		switch (config.rates())
		{
			case IRON:
				return true;
			case MAIN:
				return false;
			default:
				return client.getVarbitValue(VarbitID.IRONMAN) != 0;
		}
	}

	/** Reads the log's tabs, pages and slots from the game cache. */
	private void buildStructure()
	{
		EnumComposition tabEnum = client.getEnum(TAB_ENUM);
		int[] tabStructs = tabEnum == null ? null : tabEnum.getIntVals();
		if (tabStructs == null || tabStructs.length == 0)
		{
			return;
		}
		replacements.clear();
		EnumComposition swap = client.getEnum(REPLACEMENT_ENUM);
		if (swap != null)
		{
			int[] keys = swap.getKeys();
			int[] values = swap.getIntVals();
			for (int i = 0; i < Math.min(keys.length, values.length); i++)
			{
				replacements.put(keys[i], values[i]);
			}
		}

		List<LogStructure.Tab> tabs = new ArrayList<>();
		Map<Integer, String> names = new HashMap<>();
		for (int t = 0; t < tabStructs.length; t++)
		{
			StructComposition tabStruct = client.getStructComposition(tabStructs[t]);
			EnumComposition pageEnum = tabStruct == null ? null : client.getEnum(tabStruct.getIntValue(TAB_PAGES_PARAM));
			if (pageEnum == null)
			{
				continue;
			}
			String tabName = t < TAB_NAMES.length ? TAB_NAMES[t] : "Tab " + (t + 1);
			List<LogStructure.Page> pages = new ArrayList<>();
			for (int pageStructId : pageEnum.getIntVals())
			{
				StructComposition pageStruct = client.getStructComposition(pageStructId);
				EnumComposition itemEnum = pageStruct == null ? null : client.getEnum(pageStruct.getIntValue(PAGE_ITEMS_PARAM));
				if (itemEnum == null)
				{
					continue;
				}
				List<Integer> items = new ArrayList<>();
				for (int raw : itemEnum.getIntVals())
				{
					int id = replacements.getOrDefault(raw, raw);
					items.add(id);
					names.computeIfAbsent(id, k -> Text.removeTags(itemManager.getItemComposition(k).getName()));
				}
				pages.add(new LogStructure.Page(tabName, pageStruct.getStringValue(PAGE_NAME_PARAM), items));
			}
			tabs.add(new LogStructure.Tab(tabName, pages));
		}
		structure = new LogStructure(tabs, names);
		log.debug("Collection log read: {} tabs, {} slots", tabs.size(), structure.getUniqueSlots());
	}

	private void loadProgress()
	{
		String key = configManager.getRSProfileKey();
		if (key == null)
		{
			return;
		}
		profile = key;
		String json = configManager.getRSProfileConfiguration(CodexLogInsightConfig.GROUP, PROGRESS_KEY);
		SavedJson.Read<Progress> read = Progress.load(gson, json);
		if (read.isDamaged() && json != null
			&& !json.equals(configManager.getRSProfileConfiguration(CodexLogInsightConfig.GROUP, PROGRESS_KEY + UNREADABLE)))
		{
			// Kept aside before the next save writes over it, so damaged or newer-version progress is never lost.
			log.warn("Could not read all of the saved collection log progress; the saved text is kept as {}", PROGRESS_KEY + UNREADABLE);
			configManager.setConfiguration(CodexLogInsightConfig.GROUP, key, PROGRESS_KEY + UNREADABLE, json);
		}
		Progress loaded = read.getValue();
		progress = loaded == null ? new Progress() : loaded;
		seedFromChatCommands();
		session = new Session(progress.getOwned(), System.currentTimeMillis());
	}

	/**
	 * Brings counters up to the kill counts RuneLite's chat commands remember, which can be
	 * newer than the last time a log page was opened. Counts only ever go up.
	 */
	private void seedFromChatCommands()
	{
		for (String label : data.getLabels())
		{
			Integer known = progress.counter(label);
			for (String key : ChatReader.savedKeys(label))
			{
				Integer count = configManager.getRSProfileConfiguration("killcount", key, Integer.class);
				if (count != null && count > 0)
				{
					if (known == null || count > known)
					{
						progress.setCounter(label, count);
					}
					break;
				}
			}
		}
	}

	/** Writes progress to the profile if it changed, and says whether it did. */
	private boolean save()
	{
		ticksSinceSave = 0;
		if (progress == null || profile == null || !unsaved)
		{
			return false;
		}
		unsaved = false;
		configManager.setConfiguration(CodexLogInsightConfig.GROUP, profile, PROGRESS_KEY, gson.toJson(progress));
		return true;
	}

	private void analyse()
	{
		if (progress == null)
		{
			publish(Report.loggedOut(), null);
			return;
		}
		Progress snapshot = progress.copy();
		LogStructure shape = structure;
		boolean iron = ironRates();
		ironShown = iron;
		int setting = notices;
		boolean pace = config.learnPace();
		Unlocks can = unlocks;
		int owned = officialOwned;
		int total = officialTotal;
		Player player = client.getLocalPlayer();
		String name = player == null ? null : player.getName();
		int ticket = generation.incrementAndGet();
		Analyst reader = analyst;
		// Read here, on the client thread that updates the session, rather than beside the analysis.
		Session.Summary summary = session == null ? null : session.read(data, snapshot, System.currentTimeMillis());
		String grindOn = config.grindCard() ? grindLabel : null;
		long grindSince = grindAt;
		executor.execute(() ->
		{
			try
			{
				Report report = reader.analyse(shape, snapshot, iron, pace, owned, total, can).withSession(summary)
					.withNotices(setting);
				if (ticket == generation.get())
				{
					grindCard.setGrind(Grind.of(report, grindOn, grindSince));
					publish(report, name);
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Log Insight analysis failed", e);
			}
		});
	}

	private void publish(Report report, String name)
	{
		LogInsightPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(report, name));
		}
	}

	/** Asks where to save the finest finds card (on the Swing thread), then writes it off that thread. */
	private void saveCard(BufferedImage card, String fileName)
	{
		LogInsightPanel view = panel;
		if (view == null)
		{
			return;
		}
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save finest finds card")
			.addExtensionFilter("PNG image", "png")
			.setDefaultExtension("png")
			.setFileName(fileName)
			.showDialog(view);
		if (chosen == null || chosen.isEmpty())
		{
			return;
		}
		Filepath target = chosen.get(0);
		executor.execute(() ->
		{
			String note;
			try (OutputStream out = target.openOutputStream())
			{
				ImageIO.write(card, "png", out);
				note = "Saved as " + target.getFileName() + ".";
			}
			catch (IOException e)
			{
				log.warn("Could not save the finest finds card", e);
				note = "The card could not be saved: " + e.getMessage();
			}
			String shown = note;
			SwingUtilities.invokeLater(() ->
			{
				LogInsightPanel p = panel;
				if (p != null)
				{
					p.shareNote(shown);
				}
			});
		});
	}

	/** Puts the finest finds card on the clipboard; called on the Swing thread. */
	private void copyCard(BufferedImage card)
	{
		String note;
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new ImageTransfer(ImageTransfer.opaque(card)), null);
			note = "Copied. Paste it anywhere you share pictures.";
		}
		catch (IllegalStateException e)
		{
			note = "The clipboard is busy, try again in a moment.";
		}
		LogInsightPanel p = panel;
		if (p != null)
		{
			p.shareNote(note);
		}
	}
}

package com.codex.loginsight;

import com.codex.loginsight.ui.Theme;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

/** Hands the finest finds card to the system clipboard as a picture. */
final class ImageTransfer implements Transferable
{
	private final BufferedImage image;

	ImageTransfer(BufferedImage image)
	{
		this.image = image;
	}

	/**
	 * The card on a solid backing. Some clipboards (Windows among them) drop transparency and
	 * would paint its rounded corners black, so they are filled with the card's own ink.
	 */
	static BufferedImage opaque(BufferedImage card)
	{
		BufferedImage out = new BufferedImage(card.getWidth(), card.getHeight(), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.setColor(Theme.INK_DEEP);
		g.fillRect(0, 0, out.getWidth(), out.getHeight());
		g.drawImage(card, 0, 0, null);
		g.dispose();
		return out;
	}

	@Override
	public DataFlavor[] getTransferDataFlavors()
	{
		return new DataFlavor[]{DataFlavor.imageFlavor};
	}

	@Override
	public boolean isDataFlavorSupported(DataFlavor flavor)
	{
		return DataFlavor.imageFlavor.equals(flavor);
	}

	@Override
	public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
	{
		if (!isDataFlavorSupported(flavor))
		{
			throw new UnsupportedFlavorException(flavor);
		}
		return image;
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.Activity;
import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Turns the log's shape, the bundled rates and this account's progress into a Report.
 * Pure Java over immutable inputs, so it runs off the client thread and is tested
 * without a game.
 */
public final class Analyst
{
	/** Kill count gaps needed before your own pace replaces the typical rate. */
	static final int PACE_SAMPLES = 15;
	private static final int DRIEST = 6;
	/** At most this many of the driest slots come from one page, so one dry casket tier cannot fill the list. */
	private static final int DRIEST_PER_PAGE = 2;
	private static final double DRY_SHOWN_BELOW = 0.35;

	private final LogData data;
	/** The counter each activity advances, when its slots agree on one. */
	private final Map<Integer, String> activityLabels = new HashMap<>();
	private static final int MAX_CACHED = 20_000;
	/**
	 * Curves are kilobytes each and a new own pace misses for every page it touches, so they get a much
	 * smaller budget than evaluations: about ten full reports' worth.
	 */
	private static final int MAX_CURVES = 2_500;
	private final Map<String, Eval> evaluations = new java.util.concurrent.ConcurrentHashMap<>();
	/** Page curves by the evaluations and rates they came from; null values are kept too, for pages with none. */
	private final Map<List<Object>, Projection> projections = java.util.Collections.synchronizedMap(new HashMap<>());

	public Analyst(LogData data)
	{
		this.data = data;
		for (Activity activity : data.getActivities())
		{
			Map<String, Integer> votes = new HashMap<>();
			for (Activity.Drop drop : activity.getDrops())
			{
				ItemOdds odds = data.odds(drop.getItemId());
				if (odds != null)
				{
					votes.merge(odds.mainLabel(), 1, Integer::sum);
				}
			}
			votes.entrySet().stream()
				.max(Map.Entry.comparingByValue())
				.filter(e -> e.getValue() * 2 >= activity.getDrops().size())
				.ifPresent(e -> activityLabels.put(activity.getIndex(), e.getKey()));
		}
	}

	/**
	 * @param ownPace use the pace learned from your kill counts where there is enough of it
	 */
	public Report analyse(LogStructure structure, Progress progress, boolean iron, boolean ownPace, int officialOwned,
		int officialTotal)
	{
		return analyse(structure, progress, iron, ownPace, officialOwned, officialTotal, Unlocks.UNKNOWN);
	}

	/**
	 * @param unlocks what the account can do yet; activities it cannot do sink below the rest
	 */
	public Report analyse(LogStructure structure, Progress progress, boolean iron, boolean ownPace, int officialOwned,
		int officialTotal, Unlocks unlocks)
	{
		Rates rates = new Rates(progress, iron, ownPace);
		Set<Integer> owned = progress.getOwned();
		Map<String, Integer> counters = progress.getCounters();

		List<Report.PageReport> pages = new ArrayList<>();
		Set<Integer> unique = new LinkedHashSet<>();
		int complete = 0;
		for (LogStructure.Tab tab : structure.getTabs())
		{
			for (LogStructure.Page page : tab.getPages())
			{
				Report.PageReport report = page(structure, page, progress, rates, unlocks);
				pages.add(report);
				if (report.isComplete())
				{
					complete++;
				}
				unique.addAll(page.getItems());
			}
		}

		int knownOwned = 0;
		List<Integer> missing = new ArrayList<>();
		for (int id : unique)
		{
			if (owned.contains(id))
			{
				knownOwned++;
			}
			else
			{
				missing.add(id);
			}
		}

		Finish finish = finish(missing, owned, rates, unlocks);
		// Before the owned slots are read every slot reads as missing, which would say "very dry" of any log.
		boolean ownedRead = progress.getFullReadAt() > 0 || officialOwned >= 0 && knownOwned >= officialOwned;
		Luck luck = ownedRead ? luck(unique, owned, counters) : null;
		List<Report.ItemReport> driest = driest(structure, missing, progress, rates);
		List<Prospect> prospects = new ArrayList<>();
		List<Report.Hunt> hunts = hunts(structure, owned, rates, unlocks, prospects);
		List<PetPlan> pets = pets(structure, unique, owned, rates, unlocks);

		Report report = new Report(true, !structure.isEmpty(), officialOwned, officialTotal, knownOwned, unique.size(),
			progress.getFullReadAt(), progress.pagesReadCount(), pages.size(), complete, luck, finish.hours,
			finish.unrated, iron, pages, hunts, driest, progress.getFinds(), prospects, pets);
		List<Report.ItemReport> wanted = new ArrayList<>();
		for (int id : progress.getWanted())
		{
			if (!owned.contains(id) && unique.contains(id))
			{
				List<LogStructure.Page> where = structure.pagesOf(id);
				wanted.add(item(structure, id, where.isEmpty() ? null : where.get(0).getName(), progress, rates));
			}
		}
		report.setWanted(wanted);
		report.setTrophies(progress.getTrophies());
		report.setDrops(ownedRead ? drops(unique, progress) : null);
		return report;
	}

	/** Builds the report for one slot, for the panel and for the drop plaque. */
	public Report.ItemReport item(LogStructure structure, int itemId, String page, Progress progress, boolean iron)
	{
		return item(structure, itemId, page, progress, new Rates(progress, iron, true));
	}

	private Report.PageReport page(LogStructure structure, LogStructure.Page page, Progress progress, Rates rates,
		Unlocks unlocks)
	{
		Set<Integer> owned = progress.getOwned();
		Map<String, Integer> counters = progress.getCounters();
		List<Report.ItemReport> items = new ArrayList<>();
		List<Integer> missing = new ArrayList<>();
		Map<String, Integer> labelVotes = new LinkedHashMap<>();
		int ownedCount = 0;
		for (int id : page.getItems())
		{
			items.add(item(structure, id, page.getName(), progress, rates));
			if (owned.contains(id))
			{
				ownedCount++;
			}
			else
			{
				missing.add(id);
			}
			ItemOdds odds = data.odds(id);
			if (odds != null)
			{
				for (ItemOdds.Roll roll : odds.getRolls())
				{
					labelVotes.merge(roll.getLabel(), roll.getLabel().equals(odds.mainLabel()) ? 2 : 1, Integer::sum);
				}
			}
		}

		String mainLabel = labelVotes.entrySet().stream()
			.max(Map.Entry.comparingByValue())
			.map(Map.Entry::getKey)
			.orElse(null);
		List<String> shownLabels = progress.pageLabels(page.getName());
		if (shownLabels == null)
		{
			shownLabels = new ArrayList<>(labelVotes.keySet());
		}
		List<String> lines = new ArrayList<>();
		for (String label : shownLabels)
		{
			Integer value = counters.get(label);
			if (value != null)
			{
				lines.add(label + ": " + String.format("%,d", value));
			}
		}
		if (mainLabel == null && !shownLabels.isEmpty())
		{
			mainLabel = shownLabels.get(0);
		}
		Integer count = mainLabel == null ? null : counters.get(mainLabel);

		Finish finish = finish(missing, owned, rates, unlocks);
		Next next = next(missing, owned, rates, unlocks);
		Luck luck = luck(page.getItems(), owned, counters);
		Report.PageReport report = new Report.PageReport(page.getTab(), page.getName(), ownedCount, page.getItems().size(),
			lines, count == null ? -1 : count, mainLabel, luck, finish.hours, next.hours, next.source, finish.unrated,
			progress.isPageRead(page.getName()), items, projection(structure, missing, owned, rates, unlocks));
		// A page's counts are known once it, or the whole log, has been read.
		boolean counted = progress.isPageRead(page.getName()) || progress.getFullReadAt() > 0;
		report.setDrops(counted ? drops(page.getItems(), progress) : null);
		return report;
	}

	private Report.ItemReport item(LogStructure structure, int id, String page, Progress progress, Rates rates)
	{
		ItemOdds odds = data.odds(id);
		double chance = 0;
		String label = null;
		int count = -1;
		double dry = -1;
		if (odds != null)
		{
			label = odds.mainLabel();
			chance = odds.mainChance();
			Integer value = progress.counter(label);
			count = value == null ? -1 : value;
			dry = odds.dryChance(progress.getCounters());
		}
		Activity.Drop fastest = rates.fastest(id);
		String source = null;
		double hours = Double.POSITIVE_INFINITY;
		if (fastest != null)
		{
			Activity activity = data.activity(fastest.getActivityIndex());
			source = activity.getName();
			hours = rates.hours(activity, fastest.getAttempts());
			if (chance == 0)
			{
				chance = 1 / fastest.getAttempts();
			}
		}
		Report.ItemReport report = new Report.ItemReport(id, structure.name(id), page, progress.owns(id), data.isPet(id),
			chance, label, count, dry, source, hours);
		if (progress.owns(id))
		{
			double expected = countable(id, odds) ? odds.expectedCount(progress.countedAt(id)) : -1;
			report.setObtained(progress.obtained(id), expected);
		}
		return report;
	}

	/**
	 * Every copy of these slots the log counts against the odds at your counts, or null when there is nothing to count
	 * or an owned slot's count has not been read yet (a guess there would read as dry). Pets are left out, and so are
	 * slots whose drop is not one item per roll (stacks, dupe-protected sets, guaranteed ones).
	 */
	private Drops drops(Collection<Integer> items, Progress progress)
	{
		Map<String, Integer> counters = progress.getCounters();
		int got = 0;
		double expected = 0;
		int slots = 0;
		Set<Integer> seen = new HashSet<>();
		for (int id : items)
		{
			ItemOdds odds = data.odds(id);
			if (!seen.add(id) || !countable(id, odds))
			{
				continue;
			}
			// An owned slot is set against the counts as they stood when its copies were read; a missing one against now.
			double mean = odds.expectedCount(progress.owns(id) ? progress.countedAt(id) : counters);
			if (mean < 0)
			{
				continue;
			}
			if (progress.owns(id))
			{
				int count = progress.obtained(id);
				if (count <= 0)
				{
					return null;
				}
				got += count;
			}
			expected += mean;
			slots++;
		}
		return slots == 0 || got == 0 && expected < 0.5 ? null : new Drops(got, expected, slots);
	}

	/**
	 * Whether the log's count of a slot can be set against its odds: one item per roll, not a pet, and rare enough that
	 * the odds' own rounding stays small beside the spread. A 1/20 drop over a few thousand kills would pin the reading to
	 * either end on a few percent of model error alone.
	 */
	private boolean countable(int id, ItemOdds odds)
	{
		return odds != null && odds.isCountable() && !data.isPet(id) && odds.mainChance() <= COMMON;
	}

	/** The commonest drop whose copies are counted, per kill. */
	private static final double COMMON = 1 / 40.0;

	private Luck luck(Collection<Integer> items, Set<Integer> owned, Map<String, Integer> counters)
	{
		List<Double> chances = new ArrayList<>();
		int have = 0;
		Set<Integer> seen = new HashSet<>();
		for (int id : items)
		{
			if (!seen.add(id))
			{
				continue;
			}
			ItemOdds odds = data.odds(id);
			if (odds == null)
			{
				continue;
			}
			double dry = odds.dryChance(counters);
			if (dry < 0)
			{
				continue;
			}
			chances.add(1 - dry);
			if (owned.contains(id))
			{
				have++;
			}
		}
		if (chances.isEmpty())
		{
			return null;
		}
		double[] array = new double[chances.size()];
		for (int i = 0; i < array.length; i++)
		{
			array[i] = chances.get(i);
		}
		return Luck.of(array, have);
	}

	private List<Report.ItemReport> driest(LogStructure structure, List<Integer> missing, Progress progress, Rates rates)
	{
		List<Report.ItemReport> dry = new ArrayList<>();
		for (int id : missing)
		{
			ItemOdds odds = data.odds(id);
			if (odds == null)
			{
				continue;
			}
			double chance = odds.dryChance(progress.getCounters());
			if (chance >= 0 && chance < DRY_SHOWN_BELOW)
			{
				List<LogStructure.Page> pages = structure.pagesOf(id);
				dry.add(item(structure, id, pages.isEmpty() ? null : pages.get(0).getName(), progress, rates));
			}
		}
		dry.sort(Comparator.comparingDouble(Report.ItemReport::getDryChance));
		List<Report.ItemReport> shown = new ArrayList<>();
		Map<String, Integer> perPage = new HashMap<>();
		for (Report.ItemReport item : dry)
		{
			if (perPage.merge(String.valueOf(item.getPage()), 1, Integer::sum) <= DRIEST_PER_PAGE)
			{
				shown.add(item);
			}
			if (shown.size() == DRIEST)
			{
				break;
			}
		}
		return shown;
	}

	private List<Report.Hunt> hunts(LogStructure structure, Set<Integer> owned, Rates rates, Unlocks unlocks,
		List<Prospect> prospects)
	{
		Set<Integer> inLog = new HashSet<>();
		for (LogStructure.Tab tab : structure.getTabs())
		{
			for (LogStructure.Page page : tab.getPages())
			{
				inLog.addAll(page.getItems());
			}
		}
		List<Report.Hunt> hunts = new ArrayList<>();
		for (Activity activity : data.getActivities())
		{
			double perHour = rates.perHour(activity);
			if (perHour <= 0)
			{
				continue;
			}
			Eval eval = evaluate(activity, owned, id -> inLog.isEmpty() || inLog.contains(id));
			if (eval.remaining == 0 || Double.isInfinite(eval.nextAttempts))
			{
				continue;
			}
			boolean pet = false;
			for (int id : eval.missing)
			{
				pet |= data.isPet(id);
			}
			double petHours = Double.POSITIVE_INFINITY;
			int petItem = -1;
			if (pet)
			{
				Eval pets = evaluate(activity, owned, id -> data.isPet(id) && (inLog.isEmpty() || inLog.contains(id)));
				petHours = rates.hoursFor(activity, pets.nextAttempts);
				petItem = pets.nextItem;
			}
			hunts.add(new Report.Hunt(activity.getName(), activity.getCategory(),
				rates.hoursFor(activity, eval.nextAttempts), rates.hoursFor(activity, eval.allAttempts), eval.remaining,
				eval.nextItem, eval.nextItem < 0 ? null : structure.name(eval.nextItem), eval.nextChance, eval.nextExact, perHour,
				rates.isOwnPace(activity), pet, eval.missing, petHours, petItem, petItem < 0 ? null : structure.name(petItem),
				unlocks.missing(activity)));
			prospects.add(prospect(structure, activity, eval, rates, unlocks.missing(activity)));
		}
		// What can be done now comes first, each part ranked by the wait for a new slot.
		hunts.sort(Comparator.comparing((Report.Hunt h) -> h.getLockedBy() != null)
			.thenComparingDouble(Report.Hunt::getHoursToNext));
		return hunts;
	}

	/**
	 * Every missing pet as a hunt at its quickest source the account can do, or its quickest
	 * source at all when it can do none yet. Pets it can hunt now come first, quickest first.
	 */
	private List<PetPlan> pets(LogStructure structure, Set<Integer> unique, Set<Integer> owned, Rates rates, Unlocks unlocks)
	{
		List<PetPlan> plans = new ArrayList<>();
		for (int id : unique)
		{
			if (!data.isPet(id) || owned.contains(id))
			{
				continue;
			}
			Activity.Drop best = null;
			boolean bestOpen = false;
			double bestHours = Double.POSITIVE_INFINITY;
			for (Activity.Drop drop : data.dropsOf(id))
			{
				Activity activity = data.activity(drop.getActivityIndex());
				double hours = rates.hoursFor(activity, drop.getAttempts());
				boolean open = unlocks.missing(activity) == null;
				if (Double.isFinite(hours) && (best == null || open && !bestOpen || open == bestOpen && hours < bestHours))
				{
					best = drop;
					bestOpen = open;
					bestHours = hours;
				}
			}
			if (best == null)
			{
				continue;
			}
			Activity activity = data.activity(best.getActivityIndex());
			String locked = unlocks.missing(activity);
			double attempts = Math.max(1, best.getAttempts());
			Prospect hunt = new Prospect(activity.getName(), activity.getCategory(), rates.perHour(activity),
				activity.getSetupHours(), rates.isOwnPace(activity), locked, id, structure.name(id),
				best.isExact() ? new double[0] : new double[]{attempts}, best.isExact() ? new int[0] : new int[]{1},
				best.isExact() ? new double[]{attempts} : new double[0], java.util.Collections.singletonList(id));
			Eval rest = evaluate(activity, owned, other -> other != id && unique.contains(other));
			Prospect alongside = prospect(structure, activity, rest, rates, locked);
			List<LogStructure.Page> pages = structure.pagesOf(id);
			plans.add(new PetPlan(id, structure.name(id), pages.isEmpty() ? null : pages.get(0).getName(), hunt, alongside,
				1 / attempts, levelUp(best, unlocks)));
		}
		plans.sort(Comparator.comparing((PetPlan p) -> p.getLockedBy() != null).thenComparingDouble(PetPlan::getMedian));
		return plans;
	}

	/**
	 * For a skilling pet, what more of its skill would do for the odds: the chance at 99, or once there, at 200M
	 * experience. Null for any other pet, and when the account's level is not known.
	 */
	static PetPlan.LevelUp levelUp(Activity.Drop drop, Unlocks unlocks)
	{
		Integer level = drop.isLevelScaled() ? unlocks.level(drop.getScaleSkill()) : null;
		if (level == null || level <= 0)
		{
			return null;
		}
		double base = drop.getScaleBase();
		boolean maxed = level >= 99 && Math.abs(drop.getAttempts() - Activity.Drop.petAttempts(base, 99, true)) < 1e-6;
		if (maxed)
		{
			return null;
		}
		boolean at99 = level >= 99;
		return new PetPlan.LevelUp(drop.getScaleSkill(), Math.min(99, level), at99,
			1 / Activity.Drop.petAttempts(base, 99, at99));
	}

	/** When these missing slots of one page are likely all owned, each hunted at its fastest source in turn. */
	private Projection projection(LogStructure structure, List<Integer> missing, Set<Integer> owned, Rates rates,
		Unlocks unlocks)
	{
		if (missing.isEmpty())
		{
			return null;
		}
		Map<Integer, Set<Integer>> byActivity = new LinkedHashMap<>();
		int unrated = 0;
		for (int id : missing)
		{
			Activity.Drop fastest = fastestOpen(id, rates, unlocks);
			if (fastest == null)
			{
				unrated++;
				continue;
			}
			byActivity.computeIfAbsent(fastest.getActivityIndex(), k -> new HashSet<>()).add(id);
		}
		// Evaluations are shared between reports for the same shape, so the same evaluations at the same rates
		// give the same curve: a new kill count reuses it, and only a new slot or a new pace works it out again.
		List<Object> key = new ArrayList<>();
		key.add(unrated);
		List<Activity> activities = new ArrayList<>();
		List<Eval> evals = new ArrayList<>();
		for (Map.Entry<Integer, Set<Integer>> e : byActivity.entrySet())
		{
			Activity activity = data.activity(e.getKey());
			Eval eval = evaluate(activity, owned, e.getValue()::contains);
			activities.add(activity);
			evals.add(eval);
			key.add(eval);
			key.add(rates.perHour(activity));
			key.add(String.valueOf(unlocks.missing(activity)));
		}
		Projection cached = projections.get(key);
		if (cached != null || projections.containsKey(key))
		{
			return cached;
		}
		List<Prospect> parts = new ArrayList<>();
		for (int i = 0; i < activities.size(); i++)
		{
			parts.add(prospect(structure, activities.get(i), evals.get(i), rates, unlocks.missing(activities.get(i))));
		}
		Projection projection = Projection.of(parts, unrated);
		if (projections.size() > MAX_CURVES)
		{
			projections.clear();
		}
		projections.put(key, projection);
		return projection;
	}

	/**
	 * The quickest source of a slot that the account can do now, or its quickest source at all when it can do
	 * none yet, so a page is only shown as locked when every way to finish it is.
	 */
	private Activity.Drop fastestOpen(int itemId, Rates rates, Unlocks unlocks)
	{
		Activity.Drop fastest = rates.fastest(itemId);
		if (fastest == null || unlocks.missing(data.activity(fastest.getActivityIndex())) == null)
		{
			return fastest;
		}
		Activity.Drop best = null;
		double bestHours = Double.POSITIVE_INFINITY;
		for (Activity.Drop drop : data.dropsOf(itemId))
		{
			Activity activity = data.activity(drop.getActivityIndex());
			double hours = rates.hoursFor(activity, drop.getAttempts());
			if (hours < bestHours && unlocks.missing(activity) == null)
			{
				bestHours = hours;
				best = drop;
			}
		}
		return best == null ? fastest : best;
	}

	private Prospect prospect(LogStructure structure, Activity activity, Eval eval, Rates rates, String lockedBy)
	{
		return new Prospect(activity.getName(), activity.getCategory(), rates.perHour(activity), activity.getSetupHours(),
			rates.isOwnPace(activity), lockedBy, eval.nextItem, eval.nextItem < 0 ? null : structure.name(eval.nextItem),
			eval.means, eval.stages, eval.exact, eval.missing);
	}

	/** Hours to finish these slots, each hunted at its fastest source you can do now (any source when none is open). */
	private Finish finish(List<Integer> missing, Set<Integer> owned, Rates rates, Unlocks unlocks)
	{
		Map<Integer, Set<Integer>> byActivity = new LinkedHashMap<>();
		int unrated = 0;
		for (int id : missing)
		{
			Activity.Drop fastest = fastestOpen(id, rates, unlocks);
			if (fastest == null)
			{
				unrated++;
				continue;
			}
			byActivity.computeIfAbsent(fastest.getActivityIndex(), k -> new HashSet<>()).add(id);
		}
		double hours = 0;
		for (Map.Entry<Integer, Set<Integer>> e : byActivity.entrySet())
		{
			Activity activity = data.activity(e.getKey());
			Eval eval = evaluate(activity, owned, e.getValue()::contains);
			hours += rates.hoursFor(activity, eval.allAttempts);
		}
		return new Finish(byActivity.isEmpty() ? (unrated > 0 ? Double.POSITIVE_INFINITY : 0) : hours, unrated);
	}

	/**
	 * The soonest new slot among these, from an activity you can do now; from any activity only when none of them is
	 * open yet, so a page never names a boss you cannot reach as its next slot while another source is open.
	 */
	private Next next(List<Integer> missing, Set<Integer> owned, Rates rates, Unlocks unlocks)
	{
		Next open = next(missing, owned, rates, unlocks, true);
		return open.source != null ? open : next(missing, owned, rates, unlocks, false);
	}

	private Next next(List<Integer> missing, Set<Integer> owned, Rates rates, Unlocks unlocks, boolean openOnly)
	{
		Set<Integer> wanted = new HashSet<>(missing);
		Set<Integer> activities = new LinkedHashSet<>();
		for (int id : missing)
		{
			for (Activity.Drop drop : data.dropsOf(id))
			{
				activities.add(drop.getActivityIndex());
			}
		}
		double best = Double.POSITIVE_INFINITY;
		String source = null;
		for (int index : activities)
		{
			Activity activity = data.activity(index);
			if (rates.perHour(activity) <= 0 || openOnly && unlocks.missing(activity) != null)
			{
				continue;
			}
			Eval eval = evaluate(activity, owned, wanted::contains);
			double hours = rates.hoursFor(activity, eval.nextAttempts);
			if (hours < best)
			{
				best = hours;
				source = activity.getName();
			}
		}
		return new Next(best, source);
	}

	/**
	 * Walks an activity's table in order. A slot can roll when it is missing and, if it
	 * only drops after the slot before it, that slot is owned. Slots earned outright are
	 * paid for one by one, so their counts add up; rolled slots wait side by side, and a
	 * run of rolled slots that only drop in order waits one piece after another.
	 */
	private Eval evaluate(Activity activity, Set<Integer> owned, java.util.function.IntPredicate include)
	{
		// The result depends only on which slots are wanted and which are owned, so it is kept between
		// reports: a new kill count costs nothing here, only a new slot does.
		StringBuilder key = new StringBuilder().append(activity.getIndex());
		boolean previousOwned = false;
		for (Activity.Drop drop : activity.getDrops())
		{
			int id = drop.getItemId();
			boolean has = owned.contains(id);
			if (!has && include.test(id))
			{
				key.append(drop.isSequential() && previousOwned ? ',' : ';').append(id);
			}
			previousOwned = has;
		}
		String cacheKey = key.toString();
		Eval cached = evaluations.get(cacheKey);
		if (cached != null)
		{
			return cached;
		}
		Eval eval = compute(activity, owned, include);
		if (evaluations.size() > MAX_CACHED)
		{
			// Curves hold on to evaluations by identity, so they go with them.
			evaluations.clear();
			projections.clear();
		}
		evaluations.put(cacheKey, eval);
		return eval;
	}

	private Eval compute(Activity activity, Set<Integer> owned, java.util.function.IntPredicate include)
	{
		Eval eval = new Eval();
		double chanceSum = 0;
		double exactNext = Double.POSITIVE_INFINITY;
		int exactItem = -1;
		double bestChance = 0;
		double fixed = 0;
		List<Double> exactCosts = new ArrayList<>();
		List<double[]> runs = new ArrayList<>();
		boolean previousOwned = false;
		boolean previousRolledOpen = false;
		for (Activity.Drop drop : activity.getDrops())
		{
			int id = drop.getItemId();
			boolean has = owned.contains(id);
			boolean rolledOpen = false;
			if (!has && include.test(id))
			{
				eval.missing.add(id);
				boolean canRoll = !drop.isSequential() || previousOwned;
				double attempts = Math.max(1, drop.getAttempts());
				if (drop.isExact())
				{
					fixed += attempts;
					exactCosts.add(attempts);
					if (canRoll && attempts < exactNext)
					{
						exactNext = attempts;
						exactItem = id;
					}
				}
				else
				{
					if (canRoll)
					{
						double chance = 1 / attempts;
						chanceSum += chance;
						if (chance > bestChance)
						{
							bestChance = chance;
							eval.nextItem = id;
						}
					}
					if (drop.isSequential() && previousRolledOpen && !runs.isEmpty())
					{
						double[] run = runs.get(runs.size() - 1);
						run[0] += attempts;
						run[1]++;
					}
					else
					{
						runs.add(new double[]{attempts, 1});
					}
					rolledOpen = true;
				}
			}
			previousRolledOpen = rolledOpen;
			previousOwned = has;
		}
		if (exactItem >= 0 && (eval.nextItem < 0 || exactNext < 1 / chanceSum))
		{
			eval.nextItem = exactItem;
			eval.nextExact = true;
			bestChance = 1 / exactNext;
		}
		double[] means = new double[runs.size()];
		int[] stages = new int[runs.size()];
		for (int i = 0; i < means.length; i++)
		{
			means[i] = runs.get(i)[0];
			stages[i] = (int) runs.get(i)[1];
		}
		eval.means = means;
		eval.stages = stages;
		eval.exact = new double[exactCosts.size()];
		for (int i = 0; i < eval.exact.length; i++)
		{
			eval.exact[i] = exactCosts.get(i);
		}
		eval.remaining = eval.missing.size();
		eval.nextChance = bestChance;
		eval.nextAttempts = eval.remaining == 0 ? Double.POSITIVE_INFINITY : Odds.attemptsToNext(chanceSum, exactNext);
		double all = Odds.attemptsToAll(fixed, means, stages);
		eval.allAttempts = eval.remaining == 0 ? 0
			: Double.isFinite(eval.nextAttempts) ? Math.max(eval.nextAttempts, all) : all;
		return eval;
	}

	/** Completions per hour for each activity: your own pace where it is known, the typical rate otherwise. */
	private final class Rates
	{
		private final Progress progress;
		private final boolean iron;
		private final boolean ownPace;
		private final Map<Integer, Activity.Drop> fastest = new HashMap<>();

		Rates(Progress progress, boolean iron, boolean ownPace)
		{
			this.progress = progress;
			this.iron = iron;
			this.ownPace = ownPace;
		}

		boolean isOwnPace(Activity activity)
		{
			if (!ownPace)
			{
				return false;
			}
			String label = activityLabels.get(activity.getIndex());
			Progress.Pace pace = label == null ? null : progress.pace(label);
			return pace != null && pace.getSamples() >= PACE_SAMPLES && pace.perHour() > 0;
		}

		double perHour(Activity activity)
		{
			if (isOwnPace(activity))
			{
				return progress.pace(activityLabels.get(activity.getIndex())).perHour();
			}
			return activity.perHour(iron);
		}

		double hours(Activity activity, double attempts)
		{
			return hoursFor(activity, attempts);
		}

		double hoursFor(Activity activity, double attempts)
		{
			double perHour = perHour(activity);
			if (perHour <= 0 || Double.isInfinite(attempts))
			{
				return Double.POSITIVE_INFINITY;
			}
			return attempts / perHour + activity.getSetupHours();
		}

		/** The source that gives this slot soonest on its own, or null. */
		Activity.Drop fastest(int itemId)
		{
			if (fastest.containsKey(itemId))
			{
				return fastest.get(itemId);
			}
			Activity.Drop best = null;
			double bestHours = Double.POSITIVE_INFINITY;
			for (Activity.Drop drop : data.dropsOf(itemId))
			{
				double hours = hoursFor(data.activity(drop.getActivityIndex()), drop.getAttempts());
				if (hours < bestHours)
				{
					bestHours = hours;
					best = drop;
				}
			}
			fastest.put(itemId, best);
			return best;
		}
	}

	private static final class Eval
	{
		final List<Integer> missing = new ArrayList<>();
		int remaining;
		int nextItem = -1;
		/** The next slot is earned after a fixed number of attempts rather than rolled. */
		boolean nextExact;
		double nextChance;
		double nextAttempts;
		double allAttempts;
		double[] means = new double[0];
		int[] stages = new int[0];
		double[] exact = new double[0];
	}

	private static final class Finish
	{
		final double hours;
		final int unrated;

		Finish(double hours, int unrated)
		{
			this.hours = hours;
			this.unrated = unrated;
		}
	}

	private static final class Next
	{
		final double hours;
		final String source;

		Next(double hours, String source)
		{
			this.hours = hours;
			this.source = source;
		}
	}
}

package com.codex.loginsight.core;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Iterator;
import java.util.Locale;

/**
 * The game can announce one new slot twice: once in chat and once in the pop-up. Several
 * slots from one casket arrive in chat together, while their pop-ups queue and show one
 * after another, so each announcement is matched against an unclaimed one of the same
 * slot from the other channel rather than only the last one seen.
 */
public final class Announcements
{
	public enum Channel
	{
		CHAT,
		POPUP
	}

	/** Pop-ups queue behind each other, so their partner can be a while behind. */
	static final long WINDOW_MS = 120_000;

	private final Deque<Entry> recent = new ArrayDeque<>();

	/** @return true when this slot has not already been announced by the other channel */
	public boolean fresh(String slot, Channel channel, long now)
	{
		if (slot == null || slot.trim().isEmpty())
		{
			return false;
		}
		while (!recent.isEmpty() && now - recent.peekFirst().at > WINDOW_MS)
		{
			recent.removeFirst();
		}
		String key = slot.trim().toLowerCase(Locale.ENGLISH);
		for (Iterator<Entry> it = recent.iterator(); it.hasNext(); )
		{
			Entry entry = it.next();
			if (entry.channel != channel && entry.slot.equals(key))
			{
				it.remove();
				return false;
			}
		}
		recent.addLast(new Entry(key, channel, now));
		return true;
	}

	public void clear()
	{
		recent.clear();
	}

	private static final class Entry
	{
		final String slot;
		final Channel channel;
		final long at;

		Entry(String slot, Channel channel, long at)
		{
			this.slot = slot;
			this.channel = channel;
			this.at = at;
		}
	}
}

package com.codex.loginsight.core;

import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/** Reads the game messages that move the collection log: new slots and kill counts. */
public final class ChatReader
{
	private static final Pattern NEW_SLOT = Pattern.compile("New item added to your collection log: (.+)");
	// The same shape RuneLite's chat commands read, so every boss, raid and minigame count is caught.
	private static final Pattern COUNT = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?<name>.+?) (?<post>(?:(?:kill|harvest|lap|completion|success|chest|opened) )?(?:count )?)is: ?(?<count>[0-9,]+)");
	private static final Pattern CLUES = Pattern.compile("You have completed (?<count>[0-9,]+) (?<tier>beginner|easy|medium|hard|elite|master) Treasure Trails?", Pattern.CASE_INSENSITIVE);
	private static final Pattern COFFINS = Pattern.compile("You have opened the Grand Hallowed Coffin (?<count>[0-9,]+) times?!");
	private static final Pattern RIFTS = Pattern.compile("Amount of Rifts you have closed: (?<count>[0-9,]+)\\.", Pattern.CASE_INSENSITIVE);
	private static final Pattern RUMOURS = Pattern.compile("You have completed (?<count>[0-9,]+) rumours? for the Hunter Guild\\.");
	private static final Pattern SUFFIX = Pattern.compile(" (kills|completions|completion count|opened|chests opened|kill count|count)$", Pattern.CASE_INSENSITIVE);

	/** Chat names that differ from the counter the collection log shows. */
	private static final Map<String, String> ALIASES = new HashMap<>();

	static
	{
		ALIASES.put("barrows", "Barrows Chests opened");
		ALIASES.put("barrows chest", "Barrows Chests opened");
		ALIASES.put("barrows chests", "Barrows Chests opened");
		ALIASES.put("lunar chest", "Lunar Chests opened");
		ALIASES.put("lunar chests", "Lunar Chests opened");
		ALIASES.put("gauntlet", "Gauntlet completion count");
		ALIASES.put("corrupted gauntlet", "Corrupted Gauntlet completion count");
		ALIASES.put("theatre of blood: hard mode", "Theatre of Blood (Hard) completions");
		ALIASES.put("theatre of blood: entry mode", "Theatre of Blood (Entry) completions");
		ALIASES.put("theatre of blood: story mode", "Theatre of Blood (Entry) completions");
		ALIASES.put("tombs of amascut: expert mode", "Tombs of Amascut (Expert) completions");
		ALIASES.put("tombs of amascut: entry mode", "Tombs of Amascut (Entry) completions");
		ALIASES.put("chambers of xeric challenge mode", "Chambers of Xeric (CM) completions");
		ALIASES.put("chambers of xeric: challenge mode", "Chambers of Xeric (CM) completions");
		ALIASES.put("the leviathan", "Leviathan kills");
		ALIASES.put("the whisperer", "Whisperer kills");
		ALIASES.put("the nightmare", "Nightmare kills");
		ALIASES.put("the hueycoatl", "Hueycoatl kills");
		ALIASES.put("tztok-jad", "TzTok-Jad kills");
		ALIASES.put("tzkal-zuk", "TzKal-Zuk kills");
		ALIASES.put("wintertodt", "Wintertodt kills");
		ALIASES.put("hespori", "Hespori kills");
		ALIASES.put("grotesque guardians", "Grotesque Guardian kills");
		ALIASES.put("royal titans", "Royal Titan kills");
		ALIASES.put("high-level gamble", "High-level Gambles");
		ALIASES.put("barrows chests", "Barrows Chests opened");
	}

	/** Counters RuneLite's chat commands save under a name of their own. */
	private static final Map<String, String> SAVED_AS = new HashMap<>();

	static
	{
		SAVED_AS.put("Barrows Chests opened", "barrows chests");
		SAVED_AS.put("Grand Hallowed Coffins opened", "hallowed sepulchre");
		SAVED_AS.put("Rifts closed", "guardians of the rift");
		SAVED_AS.put("Rumours Completed", "hunter rumours");
	}

	private final Map<String, String> labelsByBase = new HashMap<>();
	private final java.util.Set<String> labels = new java.util.HashSet<>();

	/** @param labels every counter name the odds use */
	public ChatReader(List<String> labels)
	{
		for (String label : labels)
		{
			labelsByBase.put(base(label), label);
			this.labels.add(label);
		}
	}

	/** The item name of a "New item added" message, or null. */
	public static String newSlot(String message)
	{
		Matcher m = NEW_SLOT.matcher(Text.removeTags(message));
		return m.find() ? m.group(1).trim() : null;
	}

	private static final Pattern PAGE_COUNTER = Pattern.compile("^(?<label>[^:]+?):\\s*(?<count>[0-9,]+)$");

	/** A counter line from a collection log page header, such as "Vorkath kills: 312", or null. */
	public static Count pageCounter(String line)
	{
		Matcher m = PAGE_COUNTER.matcher(Text.removeTags(line).trim());
		if (!m.find())
		{
			return null;
		}
		int value = parse(m.group("count"));
		return value < 0 ? null : new Count(m.group("label").trim(), value);
	}

	/** A kill count message read as a collection log counter, or null. */
	public Count count(String message)
	{
		// Some counters arrive with colour shorthand such as @red@ as well as tags.
		String text = Text.removeTags(message).replaceAll("@[a-z]{2,6}@", "");
		Matcher clue = CLUES.matcher(text);
		if (clue.find())
		{
			String tier = clue.group("tier");
			String label = Character.toUpperCase(tier.charAt(0)) + tier.substring(1).toLowerCase(Locale.ENGLISH) + " clues completed";
			return new Count(label, parse(clue.group("count")));
		}
		Count other = fixed(text, COFFINS, "Grand Hallowed Coffins opened");
		other = other != null ? other : fixed(text, RIFTS, "Rifts closed");
		other = other != null ? other : fixed(text, RUMOURS, "Rumours Completed");
		if (other != null)
		{
			return other;
		}
		Matcher m = COUNT.matcher(text);
		if (!m.find())
		{
			return null;
		}
		String name = m.group("name").trim();
		String label = labelFor(name);
		return label == null ? null : new Count(label, parse(m.group("count")));
	}

	private Count fixed(String text, Pattern pattern, String label)
	{
		if (!labels.contains(label))
		{
			return null;
		}
		Matcher m = pattern.matcher(text);
		return m.find() ? new Count(label, parse(m.group("count"))) : null;
	}

	/**
	 * Where RuneLite's chat commands may have saved this counter, best guess first. They
	 * save the name as the chat message gives it, lower case and without colons.
	 */
	public static List<String> savedKeys(String label)
	{
		List<String> keys = new java.util.ArrayList<>();
		String saved = SAVED_AS.get(label);
		if (saved != null)
		{
			keys.add(saved);
		}
		keys.add(base(label));
		for (Map.Entry<String, String> alias : ALIASES.entrySet())
		{
			String key = alias.getKey().replace(":", "");
			if (alias.getValue().equals(label) && !keys.contains(key))
			{
				keys.add(key);
			}
		}
		return keys;
	}

	/** The counter a chat name refers to, or null if the log has no such counter. */
	String labelFor(String chatName)
	{
		String key = chatName.trim().toLowerCase(Locale.ENGLISH);
		String alias = ALIASES.get(key);
		if (alias != null)
		{
			return alias;
		}
		String label = labelsByBase.get(key);
		if (label == null && key.startsWith("the "))
		{
			label = labelsByBase.get(key.substring(4));
		}
		return label;
	}

	/** "Vorkath kills" to "vorkath", the key RuneLite's chat commands save counts under. */
	public static String base(String label)
	{
		return SUFFIX.matcher(label.trim()).replaceFirst("").toLowerCase(Locale.ENGLISH);
	}

	private static int parse(String digits)
	{
		try
		{
			return Integer.parseInt(digits.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	public static final class Count
	{
		public final String label;
		public final int value;

		Count(String label, int value)
		{
			this.label = label;
			this.value = value;
		}
	}
}

package com.codex.loginsight.core;

import lombok.Getter;

/**
 * Every copy of a set of slots the log counts, held against the odds at your counts: luck that keeps meaning
 * something after a page is green, where owning a slot or not says nothing more.
 */
@Getter
public final class Drops
{
	/** Copies the log counts. */
	private final int got;
	/** Copies an average player would have had by these counts. */
	private final double expected;
	/** 0 is the driest account possible, 1 the luckiest. */
	private final double percentile;
	/** How many slots are counted. */
	private final int slots;

	public Drops(int got, double expected, int slots)
	{
		this.got = got;
		this.expected = expected;
		this.slots = slots;
		this.percentile = Odds.dropPercentile(expected, got);
	}

	public Luck.Verdict verdict()
	{
		return Luck.verdict(percentile);
	}

	/** Whole percent of players this account is luckier than, 1 to 99: no count of drops beats every player. */
	public int luckierThan()
	{
		return (int) Math.max(1, Math.min(99, Math.round(percentile * 100)));
	}

	/** The same reading as a luck dial shows it. */
	public Luck asLuck()
	{
		return new Luck(percentile, expected, got, slots);
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/**
 * Notices the kill that takes you past a dry milestone on a slot you are missing: the count by which nine in ten
 * players would have it, then ninety-nine in a hundred. Said once, as it happens, so a long grind has its
 * landmarks; the panel already says how dry you are at any time. Half of players is only the average, so it is
 * left to the tooltips rather than said in chat.
 */
public final class DryWatch
{
	/** Shares of players who would own the slot by now, in order. */
	static final double[] MILESTONES = {0.9, 0.99};

	/**
	 * Ticks a milestone waits before it is checked. On the kill that drops a new slot the game may send the kill
	 * count before the "New item added to your collection log" line, or the pop-up a moment later; checked at once,
	 * the chat would call you dry on the very slot you just got.
	 */
	public static final int SETTLE_TICKS = 3;

	private DryWatch()
	{
	}

	/** A kill count change waiting for the new-slot messages of the same kill before its milestones are checked. */
	@Getter
	public static final class Pending
	{
		private final String label;
		private final int before;
		private int after;
		private int dueTick;
		/** The latest it may wait: a counter that keeps moving is still checked, three settles after its first move. */
		private final int lastTick;

		Pending(String label, int before, int after, int dueTick)
		{
			this.label = label;
			this.before = before;
			this.after = after;
			this.dueTick = dueTick;
			this.lastTick = dueTick + 2 * SETTLE_TICKS;
		}
	}

	/**
	 * Holds kill count changes until the messages of the same kill have arrived. Two changes of one counter before
	 * the first is due become one (the earlier "before", the later "after"), so a fast kill does not say a
	 * milestone twice or skip one.
	 */
	public static final class Queue
	{
		private final List<Pending> pending = new ArrayList<>();

		/** Notes a counter moving from {@code before} to {@code after} at game tick {@code tick}. */
		public void add(String label, int before, int after, int tick)
		{
			for (Pending p : pending)
			{
				if (p.label.equals(label))
				{
					p.after = after;
					p.dueTick = Math.min(p.lastTick, tick + SETTLE_TICKS);
					return;
				}
			}
			pending.add(new Pending(label, before, after, tick + SETTLE_TICKS));
		}

		/** The changes whose messages have settled by game tick {@code tick}, taken out of the queue. */
		public List<Pending> due(int tick)
		{
			List<Pending> out = new ArrayList<>();
			pending.removeIf(p ->
			{
				// A tick count that went backwards is a new login: whatever waited is settled too.
				if (tick >= p.dueTick || tick < p.lastTick - 3 * SETTLE_TICKS)
				{
					out.add(p);
					return true;
				}
				return false;
			});
			return out;
		}

		public void clear()
		{
			pending.clear();
		}

		public boolean isEmpty()
		{
			return pending.isEmpty();
		}
	}

	/** One slot passing a milestone. */
	@Getter
	public static final class Milestone
	{
		private final int itemId;
		/** The share of players who would own it by now that was just passed: 0.9 or 0.99. */
		private final double share;
		/** The chance per count of the main counter, for "1 in N". */
		private final double chance;

		Milestone(int itemId, double share, double chance)
		{
			this.itemId = itemId;
			this.share = share;
			this.chance = chance;
		}

		/** "9 in 10 players" or "99 in 100 players". */
		public String players()
		{
			return share >= 0.99 ? "99 in 100 players" : "9 in 10 players";
		}
	}

	/**
	 * The milestones passed when a counter moves from {@code before} to {@code after}, for slots still missing,
	 * the most notable first (the furthest milestone, then the rarest slot). Nothing when the counter went back
	 * or jumped from nothing, as when a count is first read.
	 */
	public static List<Milestone> passed(LogData data, Set<Integer> owned, Map<String, Integer> counters, String label,
		int before, int after)
	{
		List<Milestone> out = new ArrayList<>();
		if (label == null || before <= 0 || after <= before)
		{
			return out;
		}
		Map<String, Integer> then = new HashMap<>(counters);
		then.put(label, before);
		Map<String, Integer> now = new HashMap<>(counters);
		now.put(label, after);
		for (Map.Entry<Integer, ItemOdds> e : data.allOdds().entrySet())
		{
			ItemOdds odds = e.getValue();
			if (owned.contains(e.getKey()) || !label.equals(odds.mainLabel()) || odds.getGuaranteedBy() > 0)
			{
				continue;
			}
			double shareThen = 1 - odds.dryChance(then);
			double shareNow = 1 - odds.dryChance(now);
			double passed = 0;
			for (double m : MILESTONES)
			{
				if (shareThen < m && shareNow >= m)
				{
					passed = m;
				}
			}
			if (passed > 0)
			{
				out.add(new Milestone(e.getKey(), passed, odds.mainChance()));
			}
		}
		out.sort((a, b) -> a.share != b.share ? Double.compare(b.share, a.share) : Double.compare(a.chance, b.chance));
		return out;
	}

	/**
	 * True when Log Insight knows which slots you own well enough to call one missing: the whole log has been read
	 * once, and the game's own count is no higher than the slots it can name. Before that, a slot owned for years
	 * would read as one you are dry on.
	 */
	public static boolean ownedKnown(long fullReadAt, int officialOwned, int knownOwned)
	{
		return fullReadAt > 0 && officialOwned <= knownOwned;
	}

	/**
	 * The count of the main counter by which this share of players would have a slot of this chance per count,
	 * or -1 when the chance is unknown.
	 */
	public static int countFor(double chance, double share)
	{
		if (!(chance > 0) || chance >= 1)
		{
			return chance >= 1 ? 1 : -1;
		}
		return (int) Math.ceil(Math.log1p(-share) / Math.log1p(-chance));
	}
}

package com.codex.loginsight.core;

import lombok.Getter;

/**
 * The card for the grind you are on: the log page your last kill count belongs to, the count and what this session
 * added to it, the wait for the page's next slot, and the one slot most worth watching there (a wanted one first,
 * else the one you are driest on). Built from a finished report, so it costs nothing on the client thread.
 */
@Getter
public final class Grind
{
	/** The card stays up this long after the last kill count, then steps aside. */
	public static final long SHOW_MS = 5 * 60_000L;

	private final String page;
	private final String label;
	private final int count;
	/** Counts added to this counter since logging in, or 0. */
	private final int added;
	private final double hoursToNext;
	private final int missing;
	/** The slot to watch, or null when the page has none with odds. */
	private final Report.ItemReport focus;
	private final boolean focusWanted;
	/** When the kill count that put this grind on screen arrived. */
	private final long at;

	private Grind(String page, String label, int count, int added, double hoursToNext, int missing, Report.ItemReport focus,
		boolean focusWanted, long at)
	{
		this.page = page;
		this.label = label;
		this.count = count;
		this.added = added;
		this.hoursToNext = hoursToNext;
		this.missing = missing;
		this.focus = focus;
		this.focusWanted = focusWanted;
		this.at = at;
	}

	/**
	 * The grind for a counter, or null when no unfinished page counts by it or what you own there is not known yet
	 * (neither the page nor the whole log has been read). Of several pages counted by one
	 * counter, the one with the most slots left is the grind.
	 *
	 * @param at when the counter last moved
	 */
	public static Grind of(Report report, String label, long at)
	{
		if (report == null || label == null)
		{
			return null;
		}
		Report.PageReport best = null;
		for (Report.PageReport page : report.getPages())
		{
			if (label.equals(page.getCountLabel()) && !page.isComplete()
				&& (best == null || page.getTotal() - page.getOwned() > best.getTotal() - best.getOwned()))
			{
				best = page;
			}
		}
		// Until the page (or the whole log) has been read, every slot looks missing: "6 slots left" and a dry
		// slot you have owned for years would be wrong, so the card waits for the log to be opened.
		if (best == null || !best.isRead() && report.getFullReadAt() <= 0)
		{
			return null;
		}
		Report.ItemReport focus = null;
		boolean wanted = false;
		for (Report.ItemReport item : report.getWanted())
		{
			if (label.equals(item.getLabel()) && !item.isOwned())
			{
				focus = item;
				wanted = true;
				break;
			}
		}
		if (focus == null)
		{
			for (Report.ItemReport item : best.getItems())
			{
				if (!item.isOwned() && item.getDryChance() >= 0 && label.equals(item.getLabel())
					&& (focus == null || item.getDryChance() < focus.getDryChance()))
				{
					focus = item;
				}
			}
		}
		int added = 0;
		Session.Summary session = report.getSession();
		if (session != null)
		{
			for (Session.Gain gain : session.getGains())
			{
				if (label.equals(gain.getLabel()))
				{
					added = gain.getAdded();
				}
			}
		}
		return new Grind(best.getName(), label, Math.max(0, best.getCount()), added, best.getHoursToNext(),
			best.getTotal() - best.getOwned(), focus, wanted, at);
	}

	/** True while the card should be on screen. */
	public boolean isShowing(long now)
	{
		return now - at < SHOW_MS;
	}
}

package com.codex.loginsight.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/**
 * The shape of the collection log as the game defines it: tabs, their pages and the
 * slots on each page, with item names. Read from the game cache once per session, so
 * new pages and slots appear without a plugin update.
 */
public final class LogStructure
{
	@Getter
	private final List<Tab> tabs;
	private final Map<Integer, String> names;
	private final Map<String, List<Integer>> idsByName;
	private final Map<Integer, List<Page>> pagesByItem;
	@Getter
	private final int uniqueSlots;

	public LogStructure(List<Tab> tabs, Map<Integer, String> names)
	{
		this.tabs = Collections.unmodifiableList(new ArrayList<>(tabs));
		this.names = Collections.unmodifiableMap(new HashMap<>(names));
		Map<String, List<Integer>> byName = new HashMap<>();
		Map<Integer, List<Page>> byItem = new HashMap<>();
		Set<Integer> unique = new LinkedHashSet<>();
		for (Tab tab : this.tabs)
		{
			for (Page page : tab.getPages())
			{
				for (int id : page.getItems())
				{
					unique.add(id);
					byItem.computeIfAbsent(id, k -> new ArrayList<>()).add(page);
				}
			}
		}
		for (int id : unique)
		{
			byName.computeIfAbsent(key(name(id)), k -> new ArrayList<>()).add(id);
		}
		this.idsByName = byName;
		this.pagesByItem = byItem;
		this.uniqueSlots = unique.size();
	}

	public static LogStructure empty()
	{
		return new LogStructure(Collections.emptyList(), Collections.emptyMap());
	}

	public boolean isEmpty()
	{
		return tabs.isEmpty();
	}

	public String name(int itemId)
	{
		String name = names.get(itemId);
		return name == null ? "Item " + itemId : name;
	}

	/** Slots with this exact name; several when variants share one, such as coloured ornaments. */
	public List<Integer> idsNamed(String name)
	{
		List<Integer> ids = idsByName.get(key(name));
		return ids == null ? Collections.emptyList() : ids;
	}

	public List<Page> pagesOf(int itemId)
	{
		List<Page> pages = pagesByItem.get(itemId);
		return pages == null ? Collections.emptyList() : pages;
	}

	public Page page(String name)
	{
		for (Tab tab : tabs)
		{
			for (Page page : tab.getPages())
			{
				if (page.getName().equalsIgnoreCase(name))
				{
					return page;
				}
			}
		}
		return null;
	}

	private static String key(String name)
	{
		return name.trim().toLowerCase(Locale.ENGLISH);
	}

	@Getter
	public static final class Tab
	{
		private final String name;
		private final List<Page> pages;

		public Tab(String name, List<Page> pages)
		{
			this.name = name;
			this.pages = Collections.unmodifiableList(new ArrayList<>(pages));
		}
	}

	@Getter
	public static final class Page
	{
		private final String tab;
		private final String name;
		private final List<Integer> items;

		public Page(String tab, String name, List<Integer> items)
		{
			this.tab = tab;
			this.name = name;
			this.items = Collections.unmodifiableList(new ArrayList<>(items));
		}
	}
}

package com.codex.loginsight.core;

import lombok.Getter;

/** How a set of slots compares with everyone else at the same counts. */
@Getter
public final class Luck
{
	public enum Verdict
	{
		PARCHED("Parched"),
		DRY("Dry"),
		EVEN("Even"),
		FORTUNATE("Fortunate"),
		BLESSED("Blessed");

		@Getter
		private final String label;

		Verdict(String label)
		{
			this.label = label;
		}
	}

	/** 0 is the driest account possible, 1 the luckiest. */
	private final double percentile;
	/** Slots an average player would own by now. */
	private final double expected;
	private final int owned;
	/** How many slots the read covers. */
	private final int slots;

	public Luck(double percentile, double expected, int owned, int slots)
	{
		this.percentile = percentile;
		this.expected = expected;
		this.owned = owned;
		this.slots = slots;
	}

	public static Luck of(double[] chances, int owned)
	{
		double expected = 0;
		for (double c : chances)
		{
			expected += c;
		}
		return new Luck(Odds.luckPercentile(chances, owned), expected, owned, chances.length);
	}

	public Verdict verdict()
	{
		return verdict(percentile);
	}

	public static Verdict verdict(double percentile)
	{
		if (percentile >= 0.85)
		{
			return Verdict.BLESSED;
		}
		if (percentile >= 0.65)
		{
			return Verdict.FORTUNATE;
		}
		if (percentile > 0.35)
		{
			return Verdict.EVEN;
		}
		return percentile > 0.15 ? Verdict.DRY : Verdict.PARCHED;
	}

	/** Whole percent of players this account is luckier than. */
	public int luckierThan()
	{
		return (int) Math.round(percentile * 100);
	}
}

package com.codex.loginsight.core;

/**
 * The probability behind every number Log Insight shows. Kept free of game types so
 * it can be tested on its own.
 */
public final class Odds
{
	private static final int STEPS = 1600;

	private Odds()
	{
	}

	/**
	 * Where an account sits among everyone at the same counts, from 0 (driest) to 1
	 * (luckiest): the share of players who would own fewer of these slots, counting
	 * half of those who own exactly as many.
	 *
	 * @param chances each slot's chance of being owned by now
	 * @param owned   how many of those slots are owned
	 */
	public static double luckPercentile(double[] chances, int owned)
	{
		int n = chances.length;
		if (n == 0)
		{
			return 0.5;
		}
		// Distribution of the number of owned slots (Poisson binomial), built one slot at a time.
		double[] dist = new double[n + 1];
		dist[0] = 1;
		for (int i = 0; i < n; i++)
		{
			double q = clamp(chances[i]);
			for (int k = i + 1; k >= 1; k--)
			{
				dist[k] = dist[k] * (1 - q) + dist[k - 1] * q;
			}
			dist[0] *= 1 - q;
		}
		owned = Math.max(0, Math.min(n, owned));
		double below = 0;
		for (int k = 0; k < owned; k++)
		{
			below += dist[k];
		}
		return Math.max(0, Math.min(1, below + dist[owned] / 2));
	}

	/**
	 * Where a count of drops sits among everyone at the same counts, from 0 (driest) to 1 (luckiest): the share of
	 * players who would have had fewer, counting half of those with exactly as many. Rare drops at fixed counts add
	 * up to a Poisson count with the expected number as its mean.
	 */
	public static double dropPercentile(double expected, int got)
	{
		if (!(expected > 0))
		{
			return got > 0 ? 1 : 0.5;
		}
		got = Math.max(0, got);
		double logMean = Math.log(expected);
		double logFactorial = 0;
		double below = 0;
		double at = 0;
		for (int k = 0; k <= got; k++)
		{
			if (k > 0)
			{
				logFactorial += Math.log(k);
			}
			double p = Math.exp(k * logMean - expected - logFactorial);
			if (k < got)
			{
				below += p;
			}
			else
			{
				at = p;
			}
		}
		return Math.max(0, Math.min(1, below + at / 2));
	}

	/**
	 * Expected attempts until any one of these slots arrives: the first success of a roll
	 * with this summed chance per attempt, or the fixed count, whichever comes first.
	 *
	 * @param chanceSum the summed chance per attempt of the slots that can roll
	 * @param exact     attempts until a slot that is earned outright, or infinity
	 */
	public static double attemptsToNext(double chanceSum, double exact)
	{
		if (chanceSum <= 0)
		{
			return exact;
		}
		if (chanceSum >= 1)
		{
			return Math.min(1, exact);
		}
		if (Double.isInfinite(exact))
		{
			return 1 / chanceSum;
		}
		// E[min(T, n)] for a geometric T is the sum of P(T > t) for t below n.
		double attempts = Math.ceil(exact);
		return -Math.expm1(attempts * Math.log1p(-chanceSum)) / chanceSum;
	}

	/**
	 * Expected attempts until every one of these slots is owned, for slots rolled on their
	 * own odds. Each value is one slot's average attempts.
	 */
	public static double attemptsToAll(double[] attempts, double fixed)
	{
		int[] stages = new int[attempts.length];
		java.util.Arrays.fill(stages, 1);
		return attemptsToAll(fixed, attempts, stages);
	}

	/**
	 * Expected attempts until every slot is owned: the expected latest of every waiting time,
	 * integrated numerically.
	 *
	 * @param fixed  attempts spent on slots earned outright (points, permits, milestones), which add up
	 *               because each one is paid for separately
	 * @param means  for each run of rolled slots, its average attempts in total; a run is one slot, or
	 *               several that only drop in order (bludgeon pieces), which wait one after another
	 * @param stages how many slots each run holds
	 */
	public static double attemptsToAll(double fixed, double[] means, int[] stages)
	{
		int n = means.length;
		if (n == 0)
		{
			return fixed;
		}
		double slowest = 0;
		for (double mean : means)
		{
			slowest = Math.max(slowest, mean);
		}
		if (slowest <= 0)
		{
			return fixed;
		}
		// Every run is done by then, apart from a negligible chance.
		double end = fixed + slowest * (Math.log(n) + 14);
		double h = (end - fixed) / STEPS;
		double total = fixed;
		double previous = missing(means, stages, fixed);
		for (int s = 1; s <= STEPS; s++)
		{
			double t = fixed + s * h;
			double current = missing(means, stages, t);
			total += (previous + current) / 2 * h;
			previous = current;
		}
		return total;
	}

	/** The chance that at time t some run still has a slot missing. */
	private static double missing(double[] means, int[] stages, double t)
	{
		double all = 1;
		for (int i = 0; i < means.length; i++)
		{
			all *= runDone(means[i], Math.max(1, stages[i]), t);
		}
		return 1 - all;
	}

	/**
	 * The chance a run of k slots, each waited for in turn, is done by time t. The waits are
	 * taken as equal shares of the run's mean, which makes the total an Erlang wait: much
	 * tighter than one long wait with the same mean, as several pieces in a row really are.
	 */
	static double runDone(double mean, int k, double t)
	{
		if (mean <= 0)
		{
			return 1;
		}
		double x = t * k / mean;
		if (k == 1)
		{
			return -Math.expm1(-x);
		}
		double term = 1;
		double sum = 1;
		for (int j = 1; j < k; j++)
		{
			term *= x / j;
			sum += term;
		}
		return Math.max(0, 1 - Math.exp(-x) * sum);
	}

	private static double clamp(double p)
	{
		return Math.max(0, Math.min(1, p));
	}
}

package com.codex.loginsight.core;

import lombok.Getter;

/**
 * One missing pet as a hunt: where it comes quickest, how long half and nine in ten players
 * take to see it there, and what else that activity is likely to give along the way.
 */
@Getter
public final class PetPlan
{
	private final int itemId;
	private final String name;
	private final String page;
	/** The pet alone at its quickest source. */
	private final Prospect hunt;
	/** Everything else still missing at that source. */
	private final Prospect alongside;
	/** Chance per attempt, for "1 in N". */
	private final double chance;
	private final double median;
	private final double likely;
	/** For a skilling pet, what more levels would do for its odds, or null. */
	private final LevelUp levelUp;

	public PetPlan(int itemId, String name, String page, Prospect hunt, Prospect alongside, double chance)
	{
		this(itemId, name, page, hunt, alongside, chance, null);
	}

	public PetPlan(int itemId, String name, String page, Prospect hunt, Prospect alongside, double chance, LevelUp levelUp)
	{
		this.levelUp = levelUp;
		this.itemId = itemId;
		this.name = name;
		this.page = page;
		this.hunt = hunt;
		this.alongside = alongside;
		this.chance = chance;
		this.median = hunt.hoursToAll(0.5);
		this.likely = hunt.hoursToAll(0.9);
	}

	public String getSource()
	{
		return hunt.getName();
	}

	public String getLockedBy()
	{
		return hunt.getLockedBy();
	}

	/** The chance of the pet within this many hours of hunting it. */
	public double chanceWithin(double hours)
	{
		return hunt.chanceOfAll(hours);
	}

	/** Other new slots an average player picks up in the hours it takes half of them to see the pet. */
	public double slotsAlongside()
	{
		return Double.isFinite(median) ? alongside.expectedSlots(median) : 0;
	}

	/** A skilling pet's odds at a higher level: at 99, or at 200M experience for a 99. */
	@Getter
	public static final class LevelUp
	{
		/** The skill, by RuneLite name such as "THIEVING". */
		private final String skill;
		private final int level;
		/** True when the better odds are 200M experience's, the account already being 99. */
		private final boolean maxedExperience;
		private final double chance;

		public LevelUp(String skill, int level, boolean maxedExperience, double chance)
		{
			this.skill = skill;
			this.level = level;
			this.maxedExperience = maxedExperience;
			this.chance = chance;
		}

		/** "Thieving", for a sentence. */
		public String skillName()
		{
			return skill.isEmpty() ? skill : skill.charAt(0) + skill.substring(1).toLowerCase(java.util.Locale.ENGLISH);
		}
	}
}

package com.codex.loginsight.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * What this account has done, saved per RuneScape profile: owned slots, the
 * collection log's counters, the finds Log Insight saw happen and your own pace.
 * Plain fields so Gson can save it as it is.
 */
public final class Progress
{
	private static final int MAX_FINDS = 40;
	/** Finest finds kept for the trophy shelf, however long ago they dropped. */
	static final int TROPHIES = 5;
	/** The most slots that can be wanted at once: a short list stays a list of goals. */
	public static final int MAX_WANTED = 6;

	/** Slots known to be owned. Only ever grows; the game never takes a slot back. */
	private Set<Integer> owned = new HashSet<>();
	/** Collection log counters, such as "Vorkath kills" to 312. */
	private Map<String, Integer> counters = new HashMap<>();
	/** Finds seen as they happened, newest first. */
	private List<Find> finds = new ArrayList<>();
	/** Your own pace per counter. */
	private Map<String, Pace> pace = new HashMap<>();
	/** When the whole log was last read from the game, or 0. */
	private long fullReadAt;
	/** Pages whose counters were read from the log itself. */
	private Map<String, Long> pagesRead = new LinkedHashMap<>();
	/** The counter names each read page shows, in its own order. */
	private Map<String, List<String>> pageLabels = new HashMap<>();
	/** Slots you marked as wanted, in the order you marked them. */
	private List<Integer> wanted = new ArrayList<>();
	/**
	 * The rarest finds ever seen, rarest first, kept apart from {@link #finds} so a great drop is not pushed off the
	 * shelf by forty ordinary ones. Missing from older saves, which start it from the finds they still have.
	 */
	private List<Find> trophies;
	/**
	 * How many of each owned slot the log counts, as it shows them; read with the whole log and with each page opened.
	 * Missing from older saves, and for slots only ever seen announced.
	 */
	private Map<Integer, Integer> obtained;
	/**
	 * The counters each slot's count was read at, so the average it is set against stops where the count stopped: the
	 * game announces only a slot's first copy, and later kills would otherwise read as ever drier. Only the counters the
	 * slot drops from are kept. Missing from older saves, which use the counters as they are.
	 */
	private Map<Integer, Map<String, Integer>> countedAt;

	/**
	 * Reads saved progress, keeping every field and entry that reads on its own: one odd value never costs the log.
	 * Null with nothing saved, or with nothing in it readable; the result says when anything was left out.
	 */
	public static SavedJson.Read<Progress> load(com.google.gson.Gson gson, String json)
	{
		SavedJson.Read<Progress> read = SavedJson.read(gson, json, Progress.class);
		Progress value = read.getValue();
		// More finds or trophies than this version keeps (a newer one may keep more): the repair trims them, so the
		// saved text is kept aside first.
		boolean trimmed = value != null && (value.finds != null && value.finds.size() > MAX_FINDS
			|| value.trophies != null && value.trophies.size() > TROPHIES);
		return new SavedJson.Read<>(value == null ? null : value.repair(), read.isDamaged() || trimmed);
	}

	/** Drops what no game could have saved (empty entries, negative counts, a broken pace) and holds every list to its limit. */
	Progress repair()
	{
		owned().removeIf(id -> id == null || id <= 0);
		counters().entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || e.getValue() < 0);
		finds().removeIf(f -> f == null);
		while (finds.size() > MAX_FINDS)
		{
			finds.remove(finds.size() - 1);
		}
		if (trophies != null)
		{
			if (trophies.removeIf(f -> f == null) && trophies.isEmpty())
			{
				// Nothing readable left on the shelf: it is set again from the finds, as for an older save.
				trophies = null;
			}
			while (trophies != null && trophies.size() > TROPHIES)
			{
				trophies.remove(trophies.size() - 1);
			}
		}
		pace().entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || !e.getValue().sane());
		obtained().entrySet().removeIf(e -> e.getKey() == null || e.getKey() <= 0 || e.getValue() == null || e.getValue() <= 0);
		countedAt().entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || !obtained().containsKey(e.getKey()));
		countedAt().values().forEach(m -> m.entrySet().removeIf(c -> c.getKey() == null || c.getValue() == null || c.getValue() < 0));
		pagesRead().entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null);
		pageLabels().entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null);
		pageLabels().values().forEach(list -> list.removeIf(label -> label == null));
		List<Integer> kept = new ArrayList<>();
		for (Integer id : wanted())
		{
			if (id != null && id > 0 && !owned().contains(id) && !kept.contains(id) && kept.size() < MAX_WANTED)
			{
				kept.add(id);
			}
		}
		wanted = kept;
		return this;
	}

	public Progress copy()
	{
		Progress p = new Progress();
		p.owned = new HashSet<>(owned());
		p.counters = new HashMap<>(counters());
		p.finds = new ArrayList<>(finds());
		p.pace = new HashMap<>();
		for (Map.Entry<String, Pace> e : pace().entrySet())
		{
			p.pace.put(e.getKey(), e.getValue().copy());
		}
		p.fullReadAt = fullReadAt;
		p.pagesRead = new LinkedHashMap<>(pagesRead());
		p.pageLabels = new HashMap<>(pageLabels());
		p.wanted = new ArrayList<>(wanted());
		p.trophies = new ArrayList<>(trophies());
		p.obtained = new HashMap<>(obtained());
		p.countedAt = new HashMap<>(countedAt());
		return p;
	}

	// Gson leaves fields null when an older save lacks them, so every read goes through these.

	private Map<Integer, Map<String, Integer>> countedAt()
	{
		if (countedAt == null)
		{
			countedAt = new HashMap<>();
		}
		return countedAt;
	}

	private Map<Integer, Integer> obtained()
	{
		if (obtained == null)
		{
			obtained = new HashMap<>();
		}
		return obtained;
	}

	private Set<Integer> owned()
	{
		if (owned == null)
		{
			owned = new HashSet<>();
		}
		return owned;
	}

	private Map<String, Integer> counters()
	{
		if (counters == null)
		{
			counters = new HashMap<>();
		}
		return counters;
	}

	private List<Find> finds()
	{
		if (finds == null)
		{
			finds = new ArrayList<>();
		}
		return finds;
	}

	private List<Find> trophies()
	{
		if (trophies == null)
		{
			List<Find> seeded = new ArrayList<>();
			for (Find f : finds())
			{
				offer(seeded, f);
			}
			trophies = seeded;
		}
		return trophies;
	}

	/** Puts a find on the shelf if it is among the rarest; only finds with known odds compete. */
	private static void offer(List<Find> shelf, Find find)
	{
		if (find == null || find.getChance() <= 0)
		{
			return;
		}
		for (Find f : shelf)
		{
			if (f.getItemId() == find.getItemId())
			{
				return;
			}
		}
		shelf.add(find);
		shelf.sort(Progress::rarer);
		while (shelf.size() > TROPHIES)
		{
			shelf.remove(shelf.size() - 1);
		}
	}

	/** Rarer odds first; at the same odds, the luckier find (the one fewer players would have had by then). */
	private static int rarer(Find a, Find b)
	{
		int byOdds = Double.compare(a.getChance(), b.getChance());
		return byOdds != 0 ? byOdds : Double.compare(b.getLuckier(), a.getLuckier());
	}

	private Map<String, Pace> pace()
	{
		if (pace == null)
		{
			pace = new HashMap<>();
		}
		return pace;
	}

	private Map<String, Long> pagesRead()
	{
		if (pagesRead == null)
		{
			pagesRead = new LinkedHashMap<>();
		}
		return pagesRead;
	}

	private Map<String, List<String>> pageLabels()
	{
		if (pageLabels == null)
		{
			pageLabels = new HashMap<>();
		}
		return pageLabels;
	}

	private List<Integer> wanted()
	{
		if (wanted == null)
		{
			wanted = new ArrayList<>();
		}
		return wanted;
	}

	/** Slots marked as wanted, oldest mark first. */
	public List<Integer> getWanted()
	{
		return Collections.unmodifiableList(wanted());
	}

	public boolean isWanted(int itemId)
	{
		return wanted().contains(itemId);
	}

	/**
	 * Marks a missing slot wanted, or unmarks it. An owned slot cannot be wanted, and a full list refuses a new one.
	 *
	 * @return true if the list changed
	 */
	public boolean toggleWanted(int itemId)
	{
		if (wanted().remove((Integer) itemId))
		{
			return true;
		}
		if (itemId <= 0 || owns(itemId) || wanted().size() >= MAX_WANTED)
		{
			return false;
		}
		wanted().add(itemId);
		return true;
	}

	public boolean owns(int itemId)
	{
		return owned().contains(itemId);
	}

	public Set<Integer> getOwned()
	{
		return Collections.unmodifiableSet(owned());
	}

	/** @return true if this slot is new */
	public boolean addOwned(int itemId)
	{
		// A slot found is no longer wanted.
		wanted().remove((Integer) itemId);
		return owned().add(itemId);
	}

	/** How many of this slot the log counts, or 0 when that has not been read. */
	public int obtained(int itemId)
	{
		Integer count = obtained().get(itemId);
		return count == null ? 0 : count;
	}

	/** Records the log's count of a slot as read from the game. @return true if it changed */
	public boolean setObtained(int itemId, int count)
	{
		if (itemId <= 0 || count <= 0)
		{
			return false;
		}
		Integer before = obtained().put(itemId, count);
		return before == null || before != count;
	}

	/**
	 * Records the log's count of a slot along with the counters it drops from as they stand now.
	 *
	 * @param labels the counters the slot drops from
	 */
	public void setObtained(int itemId, int count, java.util.Collection<String> labels)
	{
		if (itemId <= 0 || count <= 0)
		{
			return;
		}
		setObtained(itemId, count);
		// Read again at the same count, the log still says this many at these counts: the counters move on with it.
		Map<String, Integer> at = new HashMap<>();
		for (String label : labels)
		{
			Integer value = counters().get(label);
			if (value != null)
			{
				at.put(label, value);
			}
		}
		countedAt().put(itemId, at);
	}

	/** The counters this slot's count was read at, or the counters now when that was not kept. */
	public Map<String, Integer> countedAt(int itemId)
	{
		Map<String, Integer> at = countedAt().get(itemId);
		return at == null ? counters() : at;
	}

	/**
	 * Replaces every owned slot with a read of the whole log, which repairs a slot once marked owned in error. Only a
	 * read holding at least as many slots as the game counts may do this; a shorter one only adds.
	 */
	public void replaceOwned(Set<Integer> read)
	{
		for (int id : read)
		{
			wanted().remove((Integer) id);
		}
		owned().retainAll(read);
		owned().addAll(read);
		obtained().keySet().retainAll(read);
		countedAt().keySet().retainAll(read);
	}

	public Map<String, Integer> getCounters()
	{
		return Collections.unmodifiableMap(counters());
	}

	public Integer counter(String label)
	{
		return counters().get(label);
	}

	/** @return true if the value changed */
	public boolean setCounter(String label, int value)
	{
		Integer old = counters().put(label, value);
		return old == null || old != value;
	}

	public List<Find> getFinds()
	{
		return Collections.unmodifiableList(finds());
	}

	public void addFind(Find find)
	{
		offer(trophies(), find);
		finds().add(0, find);
		while (finds().size() > MAX_FINDS)
		{
			finds().remove(finds().size() - 1);
		}
	}

	/** The finest finds, rarest first: at most {@link #TROPHIES}. */
	public List<Find> getTrophies()
	{
		return Collections.unmodifiableList(new ArrayList<>(trophies()));
	}

	public Pace pace(String label)
	{
		return pace().get(label);
	}

	public Pace paceFor(String label)
	{
		return pace().computeIfAbsent(label, k -> new Pace());
	}

	public long getFullReadAt()
	{
		return fullReadAt;
	}

	public void setFullReadAt(long fullReadAt)
	{
		this.fullReadAt = fullReadAt;
	}

	public void markPageRead(String page, long at)
	{
		pagesRead().put(page, at);
	}

	public void setPageLabels(String page, List<String> labels)
	{
		pageLabels().put(page, new ArrayList<>(labels));
	}

	/** Counter names the page showed when it was last read, or null. */
	public List<String> pageLabels(String page)
	{
		List<String> labels = pageLabels().get(page);
		return labels == null ? null : Collections.unmodifiableList(labels);
	}

	public int pagesReadCount()
	{
		return pagesRead().size();
	}

	public boolean isPageRead(String page)
	{
		return pagesRead().containsKey(page);
	}

	/** A slot that arrived while Log Insight was watching. */
	public static final class Find
	{
		private int itemId;
		private String name;
		private String page;
		private String label;
		private int count;
		private double chance;
		/** Share of players who would still be waiting at this count: higher is luckier. */
		private double luckier;
		private long at;

		public Find(int itemId, String name, String page, String label, int count, double chance, double luckier, long at)
		{
			this.itemId = itemId;
			this.name = name;
			this.page = page;
			this.label = label;
			this.count = count;
			this.chance = chance;
			this.luckier = luckier;
			this.at = at;
		}

		public int getItemId()
		{
			return itemId;
		}

		public String getName()
		{
			return name;
		}

		public String getPage()
		{
			return page;
		}

		public String getLabel()
		{
			return label;
		}

		/** Kill count when it dropped, or 0 if unknown. */
		public int getCount()
		{
			return count;
		}

		/** Chance per count, or 0 if unknown. */
		public double getChance()
		{
			return chance;
		}

		/** 0 to 1, or -1 if unknown. */
		public double getLuckier()
		{
			return luckier;
		}

		public long getAt()
		{
			return at;
		}
	}

	/**
	 * Your own speed at one counter, learned from the gaps between kill count messages.
	 * Gaps longer than a break are ignored so banking trips count but logging off does not.
	 */
	public static final class Pace
	{
		static final long MAX_GAP_MS = 12 * 60_000L;
		private static final double WEIGHT = 0.12;

		private double secondsPerCount;
		private int samples;
		private long lastAt;
		private int lastCount;

		Pace copy()
		{
			Pace p = new Pace();
			p.secondsPerCount = secondsPerCount;
			p.samples = samples;
			p.lastAt = lastAt;
			p.lastCount = lastCount;
			return p;
		}

		public void record(int count, long at)
		{
			if (lastAt > 0 && count > lastCount && at > lastAt && at - lastAt <= MAX_GAP_MS * (count - lastCount))
			{
				double seconds = (at - lastAt) / 1000.0 / (count - lastCount);
				secondsPerCount = samples == 0 ? seconds : secondsPerCount + (seconds - secondsPerCount) * WEIGHT;
				samples++;
			}
			lastAt = at;
			lastCount = count;
		}

		public int getSamples()
		{
			return samples;
		}

		/** False for a saved pace no kills could have given: a negative or endless time per kill, or negative samples. */
		boolean sane()
		{
			return samples >= 0 && lastCount >= 0 && (samples == 0 || secondsPerCount > 0 && Double.isFinite(secondsPerCount));
		}

		/** Completions per hour, or 0 if not learned yet. */
		public double perHour()
		{
			return samples == 0 || secondsPerCount <= 0 ? 0 : 3600 / secondsPerCount;
		}
	}
}

package com.codex.loginsight.core;

import java.util.ArrayList;
import java.util.List;
import lombok.Getter;

/**
 * When a page is likely to be finished: the chance it is done after any number of hours,
 * with the hours by which half and nine in ten players would be done. A page hunted at
 * several activities is done one activity after another, so their waits add up.
 */
@Getter
public final class Projection
{
	/** Points on the curve, enough for a smooth line at panel width. */
	static final int POINTS = 64;
	private static final int BINS = 480;
	/** Each part's wait is followed out to this chance, so the tail lost to the cut is negligible. */
	private static final double TAIL = 0.9995;

	/** Hours on the curve, from 0 up. */
	private final double[] hours;
	/** The chance the page is done by each of those hours. */
	private final double[] chance;
	private final double median;
	private final double likely;
	/** Missing slots with no rates, which the curve cannot include. */
	private final int unrated;
	/** What the account still needs before it can hunt every part, or null. */
	private String lockedBy;

	Projection(double[] hours, double[] chance, double median, double likely, int unrated)
	{
		this.hours = hours;
		this.chance = chance;
		this.median = median;
		this.likely = likely;
		this.unrated = unrated;
	}

	/**
	 * @param parts   each activity's share of the missing slots, hunted in turn
	 * @param unrated missing slots no activity has rates for
	 * @return null when nothing here can be projected
	 */
	public static Projection of(List<Prospect> parts, int unrated)
	{
		List<Prospect> live = new ArrayList<>();
		for (Prospect p : parts)
		{
			if (p.getRemaining() > 0)
			{
				if (p.getPerHour() <= 0)
				{
					return null;
				}
				live.add(p);
			}
		}
		if (live.isEmpty())
		{
			return null;
		}
		Projection projection = curve(live, unrated);
		if (projection != null)
		{
			for (Prospect p : live)
			{
				if (p.getLockedBy() != null)
				{
					projection.lockedBy = p.getLockedBy();
					break;
				}
			}
		}
		return projection;
	}

	private static Projection curve(List<Prospect> live, int unrated)
	{
		if (live.size() == 1)
		{
			Prospect p = live.get(0);
			double median = p.hoursToAll(0.5);
			double likely = p.hoursToAll(0.9);
			double end = p.hoursToAll(0.995);
			if (!Double.isFinite(end))
			{
				return null;
			}
			double[] h = new double[POINTS];
			double[] c = new double[POINTS];
			for (int i = 0; i < POINTS; i++)
			{
				h[i] = end * i / (POINTS - 1);
				c[i] = p.chanceOfAll(h[i]);
			}
			return new Projection(h, c, median, likely, unrated);
		}
		return convolved(live, unrated);
	}

	/** The waits of several activities added up, on a grid of hours. */
	private static Projection convolved(List<Prospect> parts, int unrated)
	{
		double span = 0;
		for (Prospect p : parts)
		{
			double end = p.hoursToAll(TAIL);
			if (!Double.isFinite(end))
			{
				return null;
			}
			span += end;
		}
		if (span <= 0)
		{
			return null;
		}
		double width = span / BINS;
		double[] sum = null;
		for (Prospect p : parts)
		{
			// The part's chance of finishing within each bin of hours.
			double[] mass = new double[BINS];
			double before = 0;
			for (int b = 0; b < BINS; b++)
			{
				double upTo = p.chanceOfAll((b + 1) * width);
				mass[b] = Math.max(0, upTo - before);
				before = upTo;
			}
			if (sum == null)
			{
				sum = mass;
				continue;
			}
			double[] next = new double[BINS];
			for (int a = 0; a < BINS; a++)
			{
				if (sum[a] == 0)
				{
					continue;
				}
				for (int b = 0; a + b < BINS; b++)
				{
					next[a + b] += sum[a] * mass[b];
				}
			}
			sum = next;
		}
		// Each part's mass sits at its bin's middle, so the sum of k parts sits k half-bins further on.
		double shift = parts.size() * 0.5;
		double[] cumulative = new double[BINS];
		double total = 0;
		for (int b = 0; b < BINS; b++)
		{
			total += sum[b];
			cumulative[b] = Math.min(1, total);
		}
		double[] h = new double[POINTS];
		double[] c = new double[POINTS];
		double end = Math.min(span, quantile(cumulative, width, shift, 0.995) * 1.02);
		if (!Double.isFinite(end) || end <= 0)
		{
			end = span;
		}
		for (int i = 0; i < POINTS; i++)
		{
			h[i] = end * i / (POINTS - 1);
			c[i] = at(cumulative, width, shift, h[i]);
		}
		return new Projection(h, c, quantile(cumulative, width, shift, 0.5), quantile(cumulative, width, shift, 0.9),
			unrated);
	}

	private static double at(double[] cumulative, double width, double shift, double hours)
	{
		double index = hours / width - shift - 0.5;
		if (index < 0)
		{
			return Math.max(0, index + 1) * cumulative[0];
		}
		int lo = (int) Math.floor(index);
		if (lo >= cumulative.length - 1)
		{
			return cumulative[cumulative.length - 1];
		}
		double f = index - lo;
		return cumulative[lo] * (1 - f) + cumulative[lo + 1] * f;
	}

	private static double quantile(double[] cumulative, double width, double shift, double q)
	{
		for (int b = 0; b < cumulative.length; b++)
		{
			if (cumulative[b] >= q)
			{
				double previous = b == 0 ? 0 : cumulative[b - 1];
				double f = cumulative[b] == previous ? 0 : (q - previous) / (cumulative[b] - previous);
				return Math.max(0, (b - 1 + f + shift + 0.5) * width);
			}
		}
		return Double.POSITIVE_INFINITY;
	}

	/** The chance the page is done within this many hours, read off the curve. */
	public double chanceBy(double h)
	{
		if (h <= 0)
		{
			return 0;
		}
		if (h >= hours[hours.length - 1])
		{
			return chance[chance.length - 1];
		}
		for (int i = 1; i < hours.length; i++)
		{
			if (hours[i] >= h)
			{
				double f = (h - hours[i - 1]) / (hours[i] - hours[i - 1]);
				return chance[i - 1] + (chance[i] - chance[i - 1]) * f;
			}
		}
		return chance[chance.length - 1];
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.Activity;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Getter;

/**
 * What a stretch of time at one activity is likely to give: the missing slots it can drop,
 * set out so the chance of each by any number of attempts can be read off. Rolled slots
 * wait side by side, pieces that drop in order wait one after another, and slots earned
 * outright (points, permits) are paid for one by one, cheapest first.
 */
@Getter
public final class Prospect
{
	private final String name;
	private final Activity.Category category;
	/** Completions per hour, your own pace where it is known. */
	private final double perHour;
	private final double setupHours;
	private final boolean ownPace;
	/** What the account still needs to do this, or null. */
	private final String lockedBy;
	/** The slot most likely to come first, or -1. */
	private final int nextItemId;
	private final String nextItemName;
	private final int remaining;
	/** For each run of rolled slots, its average attempts in total. */
	private final double[] means;
	/** How many slots each run holds; more than one only drop in order. */
	private final int[] stages;
	/** Attempts each slot earned outright costs, cheapest first. */
	private final double[] exact;
	/** The slots this covers, for showing them. */
	private final List<Integer> missing;

	public Prospect(String name, Activity.Category category, double perHour, double setupHours, boolean ownPace,
		String lockedBy, int nextItemId, String nextItemName, double[] means, int[] stages, double[] exact,
		List<Integer> missing)
	{
		this.name = name;
		this.category = category;
		this.perHour = perHour;
		this.setupHours = setupHours;
		this.ownPace = ownPace;
		this.lockedBy = lockedBy;
		this.nextItemId = nextItemId;
		this.nextItemName = nextItemName;
		this.means = means.clone();
		this.stages = stages.clone();
		this.exact = exact.clone();
		Arrays.sort(this.exact);
		this.missing = Collections.unmodifiableList(missing);
		int slots = this.exact.length;
		for (int k : this.stages)
		{
			slots += Math.max(1, k);
		}
		this.remaining = slots;
	}

	/** Attempts that fit in this many hours once the one-off setup is done. */
	public double attemptsIn(double hours)
	{
		return perHour <= 0 ? 0 : Math.max(0, hours - setupHours) * perHour;
	}

	/** Hours these attempts take, setup included. */
	public double hoursFor(double attempts)
	{
		if (perHour <= 0 || Double.isInfinite(attempts))
		{
			return Double.POSITIVE_INFINITY;
		}
		return setupHours + attempts / perHour;
	}

	/** New slots an average player would have after this many hours here. */
	public double expectedSlots(double hours)
	{
		double n = attemptsIn(hours);
		if (n <= 0)
		{
			return 0;
		}
		double slots = 0;
		for (int i = 0; i < means.length; i++)
		{
			int k = Math.max(1, stages[i]);
			if (k == 1)
			{
				slots += 1 - miss(means[i], n);
			}
			else
			{
				double x = n * k / means[i];
				for (int j = 1; j <= k; j++)
				{
					slots += Odds.runDone(j, j, x);
				}
			}
		}
		double paid = 0;
		for (double cost : exact)
		{
			paid += cost;
			if (paid > n)
			{
				break;
			}
			slots++;
		}
		return slots;
	}

	/** The chance of at least one new slot in this many hours. */
	public double chanceOfAny(double hours)
	{
		double n = attemptsIn(hours);
		if (n <= 0 || remaining == 0)
		{
			return 0;
		}
		if (exact.length > 0 && exact[0] <= n)
		{
			return 1;
		}
		double none = 1;
		for (int i = 0; i < means.length; i++)
		{
			int k = Math.max(1, stages[i]);
			// Only a run's first piece can come first; with k pieces sharing the run's mean, it takes a k-th of it.
			none *= k == 1 ? miss(means[i], n) : Math.exp(-n * k / means[i]);
		}
		return 1 - none;
	}

	/** The chance every slot here is owned after this many hours. */
	public double chanceOfAll(double hours)
	{
		return chanceOfAllBy(attemptsIn(hours));
	}

	double chanceOfAllBy(double n)
	{
		if (remaining == 0)
		{
			return 1;
		}
		double fixed = 0;
		for (double cost : exact)
		{
			fixed += cost;
		}
		if (n <= 0 || n < fixed)
		{
			return 0;
		}
		double all = 1;
		for (int i = 0; i < means.length; i++)
		{
			int k = Math.max(1, stages[i]);
			all *= k == 1 ? 1 - miss(means[i], n) : Odds.runDone(means[i], k, n);
		}
		return all;
	}

	/**
	 * Hours until the chance of owning every slot here reaches q: 0.5 for the hours by which
	 * half of all players would be done, 0.9 for nine in ten.
	 */
	public double hoursToAll(double q)
	{
		if (remaining == 0)
		{
			return 0;
		}
		if (perHour <= 0)
		{
			return Double.POSITIVE_INFINITY;
		}
		double lo = 0;
		double hi = 1;
		while (chanceOfAllBy(hi) < q)
		{
			lo = hi;
			hi *= 2;
			if (hi > 1e12)
			{
				return Double.POSITIVE_INFINITY;
			}
		}
		for (int i = 0; i < 60; i++)
		{
			double mid = (lo + hi) / 2;
			if (chanceOfAllBy(mid) < q)
			{
				lo = mid;
			}
			else
			{
				hi = mid;
			}
		}
		return hoursFor(hi);
	}

	/** The chance of still not having a slot of this average wait after n attempts. */
	private static double miss(double mean, double n)
	{
		double p = 1 / Math.max(1, mean);
		if (p >= 1)
		{
			return n >= 1 ? 0 : 1 - n;
		}
		return Math.exp(n * Math.log1p(-p));
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.Activity;
import java.util.Collections;
import java.util.List;
import lombok.Getter;

/** Everything the panel shows, computed in one pass and handed over as a read-only value. */
@Getter
public final class Report
{
	private final boolean loggedIn;
	private final boolean structureLoaded;
	/** Owned slots according to the game's own counter, or -1. */
	private final int officialOwned;
	private final int officialTotal;
	/** Owned slots Log Insight can name. */
	private final int knownOwned;
	private final int totalSlots;
	private final long fullReadAt;
	private final int pagesRead;
	private final int pagesTotal;
	private final int pagesComplete;
	private final Luck luck;
	/** Hours to finish every slot that has rates, at your rates. */
	private final double hoursLeft;
	/** Missing slots without rates (bought, rewarded or unmodelled). */
	private final int unratedMissing;
	private final boolean ironRates;
	private final List<PageReport> pages;
	private final List<Hunt> hunts;
	private final List<ItemReport> driest;
	private final List<Progress.Find> finds;
	/** Every activity with slots left that can be timed, for planning a stretch of play. */
	private final List<Prospect> prospects;
	/** Every missing pet as a hunt, quickest first. */
	private final List<PetPlan> pets;
	/** This play session, or null when logged out. Set once, before the report is handed to the panel. */
	private Session.Summary session;
	/** The slots you marked as wanted and still miss, in the order marked. */
	private List<ItemReport> wanted = Collections.emptyList();
	/** The game's new-slot notification setting, as {@link Setup#of} reads it. Set once, like the session. */
	private int notices = Setup.NOTICES_UNKNOWN;
	/** The finest finds for the trophy shelf, rarest first. Set once, like the wanted list. */
	private List<Progress.Find> trophies = Collections.emptyList();
	/** Every copy the whole log counts against the odds, or null until the counts are read. Set once, like the wanted list. */
	private Drops drops;

	public Report(boolean loggedIn, boolean structureLoaded, int officialOwned, int officialTotal, int knownOwned,
		int totalSlots, long fullReadAt, int pagesRead, int pagesTotal, int pagesComplete, Luck luck, double hoursLeft,
		int unratedMissing, boolean ironRates, List<PageReport> pages, List<Hunt> hunts, List<ItemReport> driest,
		List<Progress.Find> finds)
	{
		this(loggedIn, structureLoaded, officialOwned, officialTotal, knownOwned, totalSlots, fullReadAt, pagesRead,
			pagesTotal, pagesComplete, luck, hoursLeft, unratedMissing, ironRates, pages, hunts, driest, finds,
			Collections.emptyList(), Collections.emptyList());
	}

	public Report(boolean loggedIn, boolean structureLoaded, int officialOwned, int officialTotal, int knownOwned,
		int totalSlots, long fullReadAt, int pagesRead, int pagesTotal, int pagesComplete, Luck luck, double hoursLeft,
		int unratedMissing, boolean ironRates, List<PageReport> pages, List<Hunt> hunts, List<ItemReport> driest,
		List<Progress.Find> finds, List<Prospect> prospects, List<PetPlan> pets)
	{
		this.prospects = Collections.unmodifiableList(prospects);
		this.pets = Collections.unmodifiableList(pets);
		this.loggedIn = loggedIn;
		this.structureLoaded = structureLoaded;
		this.officialOwned = officialOwned;
		this.officialTotal = officialTotal;
		this.knownOwned = knownOwned;
		this.totalSlots = totalSlots;
		this.fullReadAt = fullReadAt;
		this.pagesRead = pagesRead;
		this.pagesTotal = pagesTotal;
		this.pagesComplete = pagesComplete;
		this.luck = luck;
		this.hoursLeft = hoursLeft;
		this.unratedMissing = unratedMissing;
		this.ironRates = ironRates;
		this.pages = Collections.unmodifiableList(pages);
		this.hunts = Collections.unmodifiableList(hunts);
		this.driest = Collections.unmodifiableList(driest);
		this.finds = Collections.unmodifiableList(finds);
	}

	/** This report with the session's summary attached. */
	public Report withSession(Session.Summary summary)
	{
		Report copy = new Report(loggedIn, structureLoaded, officialOwned, officialTotal, knownOwned, totalSlots, fullReadAt,
			pagesRead, pagesTotal, pagesComplete, luck, hoursLeft, unratedMissing, ironRates, pages, hunts, driest, finds,
			prospects, pets);
		copy.session = summary;
		copy.wanted = wanted;
		copy.notices = notices;
		copy.trophies = trophies;
		copy.drops = drops;
		return copy;
	}

	/** Records the game's new-slot notification setting; called once before the report is handed to the panel. */
	public Report withNotices(int setting)
	{
		notices = setting;
		return this;
	}

	/**
	 * Whether the slots you own have been read: the whole log once, or every slot the game counts found some other way.
	 * Before that every slot reads as missing, so waits and rankings would describe an empty log.
	 */
	public boolean ownedRead()
	{
		return fullReadAt > 0 || officialOwned >= 0 && knownOwned >= officialOwned;
	}

	/** What is left to set up, for the Ledger's first card. */
	public Setup setup()
	{
		return Setup.of(this, notices);
	}

	/** Sets the wanted slots; called once by the analyst before the report is handed on. */
	void setWanted(List<ItemReport> wanted)
	{
		this.wanted = Collections.unmodifiableList(wanted);
	}

	/** Sets the whole log's drop count; called once by the analyst before the report is handed on. */
	void setDrops(Drops drops)
	{
		this.drops = drops;
	}

	/** Sets the trophy shelf; called once by the analyst before the report is handed on. */
	void setTrophies(List<Progress.Find> trophies)
	{
		this.trophies = Collections.unmodifiableList(trophies);
	}

	/** The rarest finds ever seen, rarest first. */
	public List<Progress.Find> getTrophies()
	{
		return trophies;
	}

	/** True when this slot is on the wanted list. */
	public boolean isWanted(int itemId)
	{
		for (ItemReport item : wanted)
		{
			if (item.getItemId() == itemId)
			{
				return true;
			}
		}
		return false;
	}

	public static Report loggedOut()
	{
		return new Report(false, false, -1, -1, 0, 0, 0, 0, 0, 0, null, Double.POSITIVE_INFINITY, 0, false,
			Collections.emptyList(), Collections.emptyList(), Collections.emptyList(), Collections.emptyList());
	}

	/** The owned count to show: the game's own when it has sent one. */
	public int owned()
	{
		return officialOwned >= 0 ? Math.max(officialOwned, knownOwned) : knownOwned;
	}

	public int total()
	{
		return officialTotal > 0 ? officialTotal : totalSlots;
	}

	/** True when Log Insight knows fewer slots than the game says you own. */
	public boolean needsFullRead()
	{
		return officialOwned > knownOwned || fullReadAt == 0 && knownOwned == 0;
	}

	/** One slot as Log Insight sees it. */
	@Getter
	public static final class ItemReport
	{
		private final int itemId;
		private final String name;
		private final String page;
		private final boolean owned;
		private final boolean pet;
		/** Chance per count of the main counter, or 0 when unknown. */
		private final double chance;
		/** The counter the chance refers to, or null. */
		private final String label;
		/** Count so far on that counter, or -1. */
		private final int count;
		/** Chance of still being without it at these counts, or -1. */
		private final double dryChance;
		/** Where it comes fastest, or null. */
		private final String source;
		/** Expected hours to get it alone from its fastest source, or infinity. */
		private final double hours;
		/** How many of it the log counts, or 0 when not read. Set once by the analyst. */
		private int obtained;
		/** How many an average player would have had by now, or -1 when unknown or not one per roll. */
		private double expectedCount = -1;

		public ItemReport(int itemId, String name, String page, boolean owned, boolean pet, double chance, String label,
			int count, double dryChance, String source, double hours)
		{
			this.itemId = itemId;
			this.name = name;
			this.page = page;
			this.owned = owned;
			this.pet = pet;
			this.chance = chance;
			this.label = label;
			this.count = count;
			this.dryChance = dryChance;
			this.source = source;
			this.hours = hours;
		}

		void setObtained(int obtained, double expectedCount)
		{
			this.obtained = obtained;
			this.expectedCount = expectedCount;
		}
	}

	/** One page of the log. */
	@Getter
	public static final class PageReport
	{
		private final String tab;
		private final String name;
		private final int owned;
		private final int total;
		/** Counter lines in the order the page shows them, such as "Vorkath kills: 312". */
		private final List<String> counters;
		/** The page's main counter value, or -1. */
		private final int count;
		private final String countLabel;
		/** Null when no slot on the page has odds and a known count. */
		private final Luck luck;
		/** Expected hours to finish the slots with rates, or infinity. */
		private final double hoursToFinish;
		/** Expected hours to the next new slot, or infinity. */
		private final double hoursToNext;
		private final String nextSource;
		/** Missing slots without rates. */
		private final int unrated;
		private final boolean read;
		private final List<ItemReport> items;
		/** When the page is likely to be finished, or null when it is or cannot be projected. */
		private final Projection projection;
		/** Every copy the page's slots have dropped against the odds, or null until the counts are read. */
		private Drops drops;

		public PageReport(String tab, String name, int owned, int total, List<String> counters, int count,
			String countLabel, Luck luck, double hoursToFinish, double hoursToNext, String nextSource, int unrated,
			boolean read, List<ItemReport> items)
		{
			this(tab, name, owned, total, counters, count, countLabel, luck, hoursToFinish, hoursToNext, nextSource, unrated,
				read, items, null);
		}

		public PageReport(String tab, String name, int owned, int total, List<String> counters, int count,
			String countLabel, Luck luck, double hoursToFinish, double hoursToNext, String nextSource, int unrated,
			boolean read, List<ItemReport> items, Projection projection)
		{
			this.projection = projection;
			this.tab = tab;
			this.name = name;
			this.owned = owned;
			this.total = total;
			this.counters = Collections.unmodifiableList(counters);
			this.count = count;
			this.countLabel = countLabel;
			this.luck = luck;
			this.hoursToFinish = hoursToFinish;
			this.hoursToNext = hoursToNext;
			this.nextSource = nextSource;
			this.unrated = unrated;
			this.read = read;
			this.items = Collections.unmodifiableList(items);
		}

		void setDrops(Drops drops)
		{
			this.drops = drops;
		}

		public boolean isComplete()
		{
			return total > 0 && owned >= total;
		}

		public double progress()
		{
			return total == 0 ? 0 : owned / (double) total;
		}
	}

	/** One activity ranked by how soon it gives a new slot. */
	@Getter
	public static final class Hunt
	{
