package com.codex.loginsight.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonPrimitive;
import java.util.Map;
import java.util.function.Function;

/**
 * Reads saved JSON so that damage costs only the damaged part. A value Gson cannot read as a whole is taken apart
 * field by field, entry by entry, and every piece that reads on its own is kept; the rest is dropped and the result
 * says so, so the caller can keep the original text aside rather than save over it. Nothing here throws.
 */
public final class SavedJson
{
	/** How deep into lists and objects a damaged value is taken apart. */
	private static final int MAX_DEPTH = 4;
	/** A number written with more characters than this is not a time, a count or an amount. */
	private static final int MAX_NUMBER_LENGTH = 40;

	/** What a read gave: the value (null when nothing could be read) and whether anything was left out. */
	public static final class Read<T>
	{
		private final T value;
		private final boolean damaged;

		Read(T value, boolean damaged)
		{
			this.value = value;
			this.damaged = damaged;
		}

		/** The value read, or null when there was nothing saved or nothing in it could be read. */
		public T getValue()
		{
			return value;
		}

		/** True when something saved could not be read and was left out, so the saved text should be kept aside. */
		public boolean isDamaged()
		{
			return damaged;
		}
	}

	private SavedJson()
	{
	}

	/** Parses saved JSON into a tree, or null when it is empty or not JSON at all. */
	public static JsonElement tree(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, JsonElement.class);
		}
		catch (JsonParseException | IllegalStateException | NumberFormatException | StackOverflowError e)
		{
			// StackOverflowError: a value nested thousands deep is damage, and Gson reads trees recursively.
			return null;
		}
	}

	/**
	 * Reads a saved object of {@code type}, keeping every field and entry that reads on its own. Empty or missing
	 * text gives no value and no damage; text that is not a JSON object gives no value and is damaged.
	 */
	public static <T> Read<T> read(Gson gson, String json, Class<T> type)
	{
		if (json == null || json.trim().isEmpty())
		{
			return new Read<>(null, false);
		}
		T whole = null;
		try
		{
			// The usual case, read straight from the text: Gson's text reader never expands a huge exponent.
			whole = gson.fromJson(json, type);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			// Taken apart below.
		}
		JsonElement root = tree(gson, json);
		if (whole != null)
		{
			// Read without an error, but a newer version's fields (or a kind of entry this one does not know) are
			// passed over in silence and would be lost at the next save: flagged, so the text is kept aside.
			return new Read<>(whole, root == null || !covers(root, toTree(gson, whole)));
		}
		if (root == null || !root.isJsonObject())
		{
			return new Read<>(null, true);
		}
		boolean[] damaged = {false};
		JsonElement kept = salvage(gson, type, root, x -> x, 0, damaged);
		T value = kept == null ? null : parse(gson, kept, type);
		return new Read<>(value, true);
	}

	/**
	 * The part of {@code value} that reads where {@code wrap} puts it in the whole: all of it when it reads as it
	 * is, else each list entry or object field that reads on its own; null when none of it does.
	 */
	private static <T> JsonElement salvage(Gson gson, Class<T> type, JsonElement value,
		Function<JsonElement, JsonElement> wrap, int depth, boolean[] damaged)
	{
		if (parse(gson, wrap.apply(value), type) != null)
		{
			return value;
		}
		damaged[0] = true;
		if (depth >= MAX_DEPTH)
		{
			return null;
		}
		if (value.isJsonArray())
		{
			JsonArray out = new JsonArray();
			for (JsonElement item : value.getAsJsonArray())
			{
				JsonElement kept = salvage(gson, type, item, x ->
				{
					JsonArray one = new JsonArray();
					one.add(x);
					return wrap.apply(one);
				}, depth + 1, damaged);
				if (kept != null)
				{
					out.add(kept);
				}
			}
			return parse(gson, wrap.apply(out), type) != null ? out : null;
		}
		if (value.isJsonObject())
		{
			JsonObject out = new JsonObject();
			for (Map.Entry<String, JsonElement> field : value.getAsJsonObject().entrySet())
			{
				String name = field.getKey();
				JsonElement kept = salvage(gson, type, field.getValue(), x ->
				{
					JsonObject one = new JsonObject();
					one.add(name, x);
					return wrap.apply(one);
				}, depth + 1, damaged);
				if (kept != null)
				{
					out.add(name, kept);
				}
			}
			return parse(gson, wrap.apply(out), type) != null ? out : null;
		}
		return null;
	}

	/** {@code value} as Gson would save it, or null when it cannot be written. */
	private static JsonElement toTree(Gson gson, Object value)
	{
		try
		{
			return gson.toJsonTree(value);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			return null;
		}
	}

	/**
	 * True when every field and list entry saved in {@code saved} is still there in {@code reread}, the value read
	 * from it written out again: nothing was passed over. Only the shape is compared, not the figures, which the
	 * reader may round or bring back to sense. A field saved as null was nothing to lose.
	 */
	static boolean covers(JsonElement saved, JsonElement reread)
	{
		if (saved == null || saved.isJsonNull())
		{
			return true;
		}
		if (reread == null || reread.isJsonNull())
		{
			return false;
		}
		if (saved.isJsonObject())
		{
			if (!reread.isJsonObject())
			{
				return false;
			}
			JsonObject now = reread.getAsJsonObject();
			for (Map.Entry<String, JsonElement> field : saved.getAsJsonObject().entrySet())
			{
				if (!field.getValue().isJsonNull() && !covers(field.getValue(), now.get(field.getKey())))
				{
					return false;
				}
			}
			return true;
		}
		if (saved.isJsonArray())
		{
			if (!reread.isJsonArray() || reread.getAsJsonArray().size() < saved.getAsJsonArray().size())
			{
				return false;
			}
			JsonArray then = saved.getAsJsonArray();
			JsonArray now = reread.getAsJsonArray();
			for (int i = 0; i < then.size(); i++)
			{
				if (!covers(then.get(i), now.get(i)))
				{
					return false;
				}
			}
			return true;
		}
		return true;
	}

	private static <T> T parse(Gson gson, JsonElement tree, Class<T> type)
	{
		try
		{
			return gson.fromJson(tree, type);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			return null;
		}
	}

	/** A field of an object as a whole number, or -1 when it is missing, not a number, or beyond a long. */
	public static long number(JsonObject o, String key)
	{
		return o == null ? -1 : number(o.get(key));
	}

	/**
	 * A saved whole number, or -1 when it is missing, not a number, or beyond a long. Read from its text: Gson's own
	 * conversion of a number like {@code 1e100000000} expands every digit on older Java, which can freeze the client.
	 */
	public static long number(JsonElement e)
	{
		double d = decimal(e);
		if (Double.isNaN(d))
		{
			return -1;
		}
		try
		{
			return Long.parseLong(e.getAsString());
		}
		catch (NumberFormatException ex)
		{
			// Written with a point or an exponent ("1.5e9"): whole numbers within a long still count.
			return Double.isInfinite(d) || d < Long.MIN_VALUE || d >= Long.MAX_VALUE ? -1 : (long) d;
		}
	}

	/** A saved number as a double, or NaN when it is missing or not a number; Infinity for one too big to hold. */
	public static double decimal(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !((JsonPrimitive) e).isNumber())
		{
			return Double.NaN;
		}
		String text = e.getAsString();
		if (text.length() > MAX_NUMBER_LENGTH)
		{
			return Double.NaN;
		}
		try
		{
			return Double.parseDouble(text);
		}
		catch (NumberFormatException ex)
		{
			return Double.NaN;
		}
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/**
 * This play session: the kill counts you have added since logging in, the new slots they gave, and how that
 * compares with an average player doing the same kills. A long dry evening and a lucky hour both show up here,
 * where the whole log's luck barely moves.
 *
 * <p>Only slots you were missing when the session began count, and only the slots that dropped as you played are
 * counted as found, so a log read in mid-session never reads as a lucky night. A slot's chance this session is the
 * chance of it dropping within the kills you added; one guaranteed by a count you passed this session is certain.
 *
 * <p>A saved count can be stale (it was last read weeks ago), so a counter's first update in a session only sets
 * where it starts: a kill message that jumps from 100 to 301 counts as the one kill it is, and a page that shows
 * a higher count than was saved counts as none.
 */
public final class Session
{
	/** Where each counter stood when the session first saw it move. */
	private final Map<String, Integer> startCounters = new HashMap<>();
	private final Set<Integer> startOwned;
	private final long startedAt;

	public Session(Set<Integer> owned, long startedAt)
	{
		this.startOwned = new HashSet<>(owned);
		this.startedAt = startedAt;
	}

	/**
	 * Records a counter's new value. The first one in a session sets its starting point: one below the value for a
	 * kill message, the value itself for a page read or anything else.
	 */
	public void observe(String label, int value, boolean fromKill)
	{
		if (label != null && value >= 0)
		{
			startCounters.putIfAbsent(label, fromKill ? Math.max(0, value - 1) : value);
		}
	}

	public long getStartedAt()
	{
		return startedAt;
	}

	/** Kill counts added this session, by counter, largest first. */
	public List<Gain> gains(Map<String, Integer> counters)
	{
		List<Gain> gains = new ArrayList<>();
		for (Map.Entry<String, Integer> e : counters.entrySet())
		{
			Integer before = startCounters.get(e.getKey());
			if (before != null && e.getValue() != null && e.getValue() > before)
			{
				gains.add(new Gain(e.getKey(), e.getValue() - before));
			}
		}
		gains.sort((a, b) -> b.added != a.added ? Integer.compare(b.added, a.added) : a.label.compareTo(b.label));
		return gains;
	}

	/** The session so far, against the slots and counters as they are now. */
	public Summary read(LogData data, Progress now, long nowMs)
	{
		Map<String, Integer> counters = now.getCounters();
		Map<String, Integer> added = new HashMap<>();
		for (Gain gain : gains(counters))
		{
			added.put(gain.label, gain.added);
		}
		List<Progress.Find> finds = new ArrayList<>();
		Set<Integer> dropped = new HashSet<>();
		for (Progress.Find find : now.getFinds())
		{
			if (find.getAt() >= startedAt)
			{
				finds.add(find);
				dropped.add(find.getItemId());
			}
		}
		List<Double> chances = new ArrayList<>();
		int found = 0;
		for (int id : rated(data, added))
		{
			if (now.owns(id) && !dropped.contains(id))
			{
				// Owned, but it never dropped tonight: read in from the log, so owned before the session began.
				continue;
			}
			chances.add(chance(data.odds(id), added));
			found += dropped.contains(id) ? 1 : 0;
		}
		double[] array = new double[chances.size()];
		for (int i = 0; i < array.length; i++)
		{
			array[i] = chances.get(i);
		}
		Luck luck = array.length == 0 ? null : Luck.of(array, found);
		return new Summary(Math.max(0, nowMs - startedAt), gains(counters), finds, luck);
	}

	/** Slots missing at the start with odds on a counter that moved this session. */
	private List<Integer> rated(LogData data, Map<String, Integer> added)
	{
		List<Integer> ids = new ArrayList<>();
		if (added.isEmpty())
		{
			return ids;
		}
		for (Map.Entry<Integer, ItemOdds> e : data.allOdds().entrySet())
		{
			if (startOwned.contains(e.getKey()))
			{
				continue;
			}
			for (ItemOdds.Roll roll : e.getValue().getRolls())
			{
				if (added.containsKey(roll.getLabel()))
				{
					ids.add(e.getKey());
					break;
				}
			}
		}
		Collections.sort(ids);
		return ids;
	}

	/** The chance of a slot dropping within the kills added this session. */
	private double chance(ItemOdds odds, Map<String, Integer> added)
	{
		int g = odds.getGuaranteedBy();
		if (g > 0)
		{
			String main = odds.mainLabel();
			Integer before = startCounters.get(main);
			Integer more = added.get(main);
			if (before != null && more != null && before < g && before + more >= g)
			{
				return 1;
			}
		}
		double logMiss = 0;
		for (ItemOdds.Roll roll : odds.getRolls())
		{
			Integer more = added.get(roll.getLabel());
			if (more != null)
			{
				logMiss += roll.getRolls() * (double) more * Math.log1p(-Math.min(roll.getChance(), 0.999999));
			}
		}
		return 1 - Math.exp(logMiss);
	}

	/** Kill count added to one counter. */
	@Getter
	public static final class Gain
	{
		private final String label;
		private final int added;

		Gain(String label, int added)
		{
			this.label = label;
			this.added = added;
		}
	}

	/** What the panel shows of the session. */
	@Getter
	public static final class Summary
	{
		private final long millis;
		private final List<Gain> gains;
		/** New slots that dropped this session, newest first. */
		private final List<Progress.Find> finds;
		/** Luck over the slots this session's kills could have given, or null before any kills with known odds. */
		private final Luck luck;

		public Summary(long millis, List<Gain> gains, List<Progress.Find> finds, Luck luck)
		{
			this.millis = millis;
			this.gains = Collections.unmodifiableList(gains);
			this.finds = Collections.unmodifiableList(finds);
			this.luck = luck;
		}

		public int addedTotal()
		{
			int total = 0;
			for (Gain gain : gains)
			{
				total += gain.added;
			}
			return total;
		}

		public boolean isEmpty()
		{
			return gains.isEmpty() && finds.isEmpty();
		}
	}
}

package com.codex.loginsight.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * What still stands between a fresh install and numbers worth trusting: the whole log read once, the game set to
 * announce new slots (Log Insight only sees a find the game announces), and kill counts on the pages you have
 * played. Worked out from a report and the game's notification setting; nothing here touches the client.
 */
public final class Setup
{
	/** The game's setting before it has arrived after login. */
	public static final int NOTICES_UNKNOWN = -1;
	/** Pages named as worth opening, the ones hiding the most finds first. */
	static final int PAGES_SHOWN = 3;

	private final boolean logRead;
	private final int notices;
	private final int pagesCounted;
	private final int pagesCountable;
	private final List<Report.PageReport> toOpen;
	private final int toOpenTotal;

	private Setup(boolean logRead, int notices, int pagesCounted, int pagesCountable, List<Report.PageReport> toOpen,
		int toOpenTotal)
	{
		this.logRead = logRead;
		this.notices = notices;
		this.pagesCounted = pagesCounted;
		this.pagesCountable = pagesCountable;
		this.toOpen = Collections.unmodifiableList(toOpen);
		this.toOpenTotal = toOpenTotal;
	}

	/**
	 * @param notices the game's "new addition" setting for the collection log: 0 none, 1 chat, 2 pop-up, 3 both,
	 *                or {@link #NOTICES_UNKNOWN} before it has been read
	 */
	public static Setup of(Report report, int notices)
	{
		int counted = 0;
		int countable = 0;
		List<Report.PageReport> open = new ArrayList<>();
		for (Report.PageReport page : report.getPages())
		{
			if (page.getCountLabel() == null)
			{
				continue;
			}
			countable++;
			if (page.getCount() >= 0)
			{
				counted++;
			}
			// A page you own something on has been played; without its count, those finds earn no luck. A page
			// already opened that still shows no count would not show one next time either.
			else if (page.getOwned() > 0 && !page.isRead())
			{
				open.add(page);
			}
		}
		open.sort(Comparator.comparingInt(Report.PageReport::getOwned).reversed()
			.thenComparing(Report.PageReport::getName));
		int total = open.size();
		return new Setup(!report.needsFullRead(), notices, counted, countable,
			new ArrayList<>(open.subList(0, Math.min(PAGES_SHOWN, total))), total);
	}

	/** True once the log has been read through its Search button and Log Insight knows every slot the game counts. */
	public boolean isLogRead()
	{
		return logRead;
	}

	/** True when the game is set to announce no new slots, so a find goes unseen. */
	public boolean noticesOff()
	{
		return notices == 0;
	}

	public boolean noticesKnown()
	{
		return notices >= 0;
	}

	public int getPagesCounted()
	{
		return pagesCounted;
	}

	public int getPagesCountable()
	{
		return pagesCountable;
	}

	/** Pages you have finds on but no kill count for, most finds first, at most {@link #PAGES_SHOWN}. */
	public List<Report.PageReport> getToOpen()
	{
		return toOpen;
	}

	/** How many pages in all have finds but no kill count. */
	public int getToOpenTotal()
	{
		return toOpenTotal;
	}

	/** Nothing left to set up: the card steps aside. An unread setting is not held against you. */
	public boolean isDone()
	{
		return logRead && !noticesOff() && toOpenTotal == 0;
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.ItemOdds;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.function.IntFunction;

/**
 * Works out which slot a "new item" announcement means. The game names the item but not the slot, and about twenty
 * names belong to several slots (Mysterious page, Graceful hood, Rum, the Castle Wars decorative pieces). Taking the
 * first one still missing would mark the wrong slot owned, and nothing would ever take it back.
 */
public final class SlotResolver
{
	private SlotResolver()
	{
	}

	public static final class Result
	{
		/** The slot to mark owned, or -1 when the announcement cannot say which slot it was. */
		public final int owned;
		/** The slot to show on the plaque and in recent finds: the owned one, or one of the candidates. */
		public final int shown;

		Result(int owned, int shown)
		{
			this.owned = owned;
			this.shown = shown;
		}

		public boolean ambiguous()
		{
			return owned < 0 && shown > 0;
		}
	}

	/**
	 * @param ids every slot with the announced name
	 * @param owned slots already owned
	 * @param odds a slot's odds, or null
	 * @param recentLabel the counter that rose just before the announcement, or null
	 */
	public static Result resolve(List<Integer> ids, Set<Integer> owned, IntFunction<ItemOdds> odds, String recentLabel)
	{
		if (ids.isEmpty())
		{
			return new Result(-1, -1);
		}
		List<Integer> missing = new ArrayList<>();
		for (int id : ids)
		{
			if (!owned.contains(id))
			{
				missing.add(id);
			}
		}
		if (missing.isEmpty())
		{
			// Every slot with this name is owned already: nothing new to mark, but the find is still shown.
			return new Result(ids.get(0), ids.get(0));
		}
		if (missing.size() == 1)
		{
			return new Result(missing.get(0), missing.get(0));
		}
		List<Integer> fromKill = new ArrayList<>();
		if (recentLabel != null)
		{
			for (int id : missing)
			{
				if (rolledBy(odds.apply(id), recentLabel))
				{
					fromKill.add(id);
				}
			}
			if (fromKill.size() == 1)
			{
				return new Result(fromKill.get(0), fromKill.get(0));
			}
		}
		// Still more than one: mark none. The game's own slot count then runs ahead of Log Insight's, and the Ledger
		// asks for the log to be read again, which settles it.
		return new Result(-1, fromKill.isEmpty() ? missing.get(0) : fromKill.get(0));
	}

	private static boolean rolledBy(ItemOdds odds, String label)
	{
		if (odds == null)
		{
			return false;
		}
		for (ItemOdds.Roll roll : odds.getRolls())
		{
			if (roll.getLabel().equals(label))
			{
				return true;
			}
		}
		return false;
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.Activity;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * What this account can do yet: its real skill levels and the quests it still has to
 * finish. Read on the client thread and handed to the analysis as a plain value.
 */
public final class Unlocks
{
	/** Before the account has been read: nothing counts as locked. */
	public static final Unlocks UNKNOWN = new Unlocks(null, Collections.emptySet());

	private final Map<String, Integer> levels;
	private final Set<String> unfinished;

	/**
	 * @param levels     real level by RuneLite skill name, or null when unknown
	 * @param unfinished quests known to be unfinished, by name
	 */
	public Unlocks(Map<String, Integer> levels, Set<String> unfinished)
	{
		this.levels = levels == null ? null : new HashMap<>(levels);
		this.unfinished = new HashSet<>();
		for (String quest : unfinished)
		{
			this.unfinished.add(normalise(quest));
		}
	}

	/** The account's real level in a skill, by RuneLite name, or null when unknown. */
	public Integer level(String skill)
	{
		return levels == null ? null : levels.get(skill);
	}

	/** The first thing this activity still needs, such as "85 Slayer", or null when it can be done. */
	public String missing(Activity activity)
	{
		if (levels != null)
		{
			for (Map.Entry<String, Integer> need : activity.getSkills().entrySet())
			{
				Integer level = levels.get(need.getKey());
				if (level != null && level < need.getValue())
				{
					String skill = need.getKey().toLowerCase(Locale.ENGLISH);
					return need.getValue() + " " + Character.toUpperCase(skill.charAt(0)) + skill.substring(1);
				}
			}
		}
		for (String quest : activity.getQuests())
		{
			if (unfinished.contains(normalise(quest)))
			{
				return quest;
			}
		}
		return null;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof Unlocks))
		{
			return false;
		}
		Unlocks other = (Unlocks) o;
		return java.util.Objects.equals(levels, other.levels) && unfinished.equals(other.unfinished);
	}

	@Override
	public int hashCode()
	{
		return java.util.Objects.hash(levels, unfinished);
	}

	/** Quest names compared on letters and digits only, so "Heroes' Quest" matches "HEROES_QUEST". */
	public static String normalise(String name)
	{
		return name == null ? "" : name.toUpperCase(Locale.ENGLISH).replaceAll("[^A-Z0-9]", "");
	}
}

package com.codex.loginsight.core;

/**
 * The sums behind a wanted slot: how many more counts until half, or nine in ten, of players would have it, and
 * the chance of it turning up in a stretch of play. All of it comes from the slot's own report, so it uses the
 * same odds and pace as the rest of the panel.
 */
public final class Wanted
{
	private Wanted()
	{
	}

	/** The count of the slot's main counter by which this share of players would have it, or -1 when unknown. */
	public static int countFor(Report.ItemReport item, double share)
	{
		if (item.getChance() <= 0 || item.getLabel() == null)
		{
			return -1;
		}
		return DryWatch.countFor(item.getChance(), share);
	}

	/**
	 * More counts from where you are until this share of players would have the slot: 0 once you are past it,
	 * -1 when the odds or your count are unknown.
	 */
	public static int moreUntil(Report.ItemReport item, double share)
	{
		int at = countFor(item, share);
		if (at < 0 || item.getCount() < 0)
		{
			return -1;
		}
		return Math.max(0, at - item.getCount());
	}

	/**
	 * The chance of the slot in the next {@code hours} of play at its fastest source and your pace, or -1 when it
	 * cannot be timed. Each attempt is a fresh roll, so the hours already spent change nothing here.
	 */
	public static double chanceWithin(Report.ItemReport item, double hours)
	{
		double expected = item.getHours();
		if (!(expected > 0) || Double.isInfinite(expected) || hours <= 0)
		{
			return -1;
		}
		return 1 - Math.exp(-hours / expected);
	}

	/**
	 * The play, in hours, after which there is an even chance of having the slot from its fastest source: the
	 * median wait, which reads better than the mean for a single rare drop. -1 when it cannot be timed.
	 */
	public static double evenChanceHours(Report.ItemReport item)
	{
		double expected = item.getHours();
		if (!(expected > 0) || Double.isInfinite(expected))
		{
			return -1;
		}
		return expected * Math.log(2);
	}
}

package com.codex.loginsight.data;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.List;
import java.util.Set;
import lombok.Getter;

/** Something you can repeat to fill log slots: a boss, a raid, a casket, a minigame round. */
@Getter
public final class Activity
{
	public enum Category
	{
		COMBAT("Combat"),
		MINIGAME("Minigames"),
		OTHER("Other");

		@Getter
		private final String label;

		Category(String label)
		{
			this.label = label;
		}

		static Category of(String code)
		{
			if ("C".equals(code))
			{
				return COMBAT;
			}
			return "M".equals(code) ? MINIGAME : OTHER;
		}
	}

	private final int index;
	private final String name;
	private final Category category;
	/** Typical completions per hour on a normal account. */
	private final double perHourMain;
	/** Typical completions per hour for an ironman, who has to supply everything themselves. */
	private final double perHourIron;
	/** One-off hours before the first attempt, such as unlocking the content. */
	private final double setupHours;
	/** In table order, which matters for slots that only drop once the one before is owned. */
	private final List<Drop> drops;
	/** Real skill levels needed, by RuneLite skill name such as "SLAYER". */
	private final Map<String, Integer> skills;
	/** Quests that must be finished, by name. */
	private final List<String> quests;

	public Activity(int index, String name, Category category, double perHourMain, double perHourIron, double setupHours, List<Drop> drops)
	{
		this(index, name, category, perHourMain, perHourIron, setupHours, drops, Collections.emptyMap(), Collections.emptyList());
	}

	public Activity(int index, String name, Category category, double perHourMain, double perHourIron, double setupHours,
		List<Drop> drops, Map<String, Integer> skills, List<String> quests)
	{
		this.skills = Collections.unmodifiableMap(new LinkedHashMap<>(skills));
		this.quests = Collections.unmodifiableList(new ArrayList<>(quests));
		this.index = index;
		this.name = name;
		this.category = category;
		this.perHourMain = perHourMain;
		this.perHourIron = perHourIron;
		this.setupHours = setupHours;
		this.drops = Collections.unmodifiableList(drops);
	}

	public double perHour(boolean iron)
	{
		return iron ? perHourIron : perHourMain;
	}

	/** This activity with its drops at an account's levels; itself when none of its rates depend on a level. */
	public Activity atLevels(Map<String, Integer> levels, Set<String> maxed)
	{
		List<Drop> scaled = null;
		for (int i = 0; i < drops.size(); i++)
		{
			Drop drop = drops.get(i);
			Drop at = drop.atLevels(levels, maxed);
			if (at != drop)
			{
				if (scaled == null)
				{
					scaled = new ArrayList<>(drops);
				}
				scaled.set(i, at);
			}
		}
		return scaled == null ? this : new Activity(index, name, category, perHourMain, perHourIron, setupHours, scaled, skills, quests);
	}

	/** One slot on an activity's table. */
	@Getter
	public static final class Drop
	{
		private static final int EXACT = 1;
		private static final int INDEPENDENT = 2;
		private static final int SEQUENTIAL = 4;
		/** Skilling pets roll 1 in (base - 25 x level). */
		static final int PET_LEVEL_STEP = 25;
		/** With 200M experience in the skill, a skilling pet is this many times likelier. */
		static final int MAXED_BOOST = 15;

		private final int activityIndex;
		private final int itemId;
		/** Average attempts per drop, so 512 means 1 in 512. For a skilling pet, at level 99 until levels are known. */
		private final double attempts;
		private final int flags;
		/** The skill a skilling pet's chance depends on, by RuneLite name, or null when the chance is flat. */
		private final String scaleSkill;
		/** A skilling pet's base: the chance per action is 1 in (base - 25 x level). */
		private final double scaleBase;

		public Drop(int activityIndex, int itemId, double attempts, int flags)
		{
			this(activityIndex, itemId, attempts, flags, null, 0);
		}

		public Drop(int activityIndex, int itemId, double attempts, int flags, String scaleSkill, double scaleBase)
		{
			this.activityIndex = activityIndex;
			this.itemId = itemId;
			this.attempts = attempts;
			this.flags = flags;
			this.scaleSkill = scaleBase > 0 ? scaleSkill : null;
			this.scaleBase = scaleBase;
		}

		/** Average attempts for a skilling pet at this level, with 200M experience or without. */
		public static double petAttempts(double base, int level, boolean maxed)
		{
			int clamped = Math.max(1, Math.min(99, level));
			double attempts = Math.max(1, base - PET_LEVEL_STEP * clamped);
			return maxed ? Math.max(1, attempts / MAXED_BOOST) : attempts;
		}

		/**
		 * This slot at an account's real levels: a skilling pet's odds follow its skill, everything else is
		 * unchanged. Itself when the level is unknown or the odds do not move.
		 */
		public Drop atLevels(Map<String, Integer> levels, Set<String> maxed)
		{
			if (scaleSkill == null || levels == null)
			{
				return this;
			}
			Integer level = levels.get(scaleSkill);
			if (level == null || level <= 0)
			{
				return this;
			}
			double at = petAttempts(scaleBase, level, maxed != null && maxed.contains(scaleSkill));
			return at == attempts ? this : new Drop(activityIndex, itemId, at, flags, scaleSkill, scaleBase);
		}

		/** True when this slot's odds depend on a skill level. */
		public boolean isLevelScaled()
		{
			return scaleSkill != null;
		}

		/** Earned after a fixed number of attempts (points, permits, a shop) rather than rolled. */
		public boolean isExact()
		{
			return (flags & EXACT) != 0;
		}

		/** Only drops once the slot listed before it on the table is owned (such as bludgeon pieces). */
		public boolean isSequential()
		{
			return (flags & SEQUENTIAL) != 0;
		}

		public boolean isIndependent()
		{
			return (flags & INDEPENDENT) != 0;
		}
	}
}

package com.codex.loginsight.data;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.Getter;

/**
 * A slot's chance per kill count, possibly from several counters at once
 * (a gilded item can come from hard, elite or master caskets).
 */
@Getter
public final class ItemOdds
{
	private final List<Roll> rolls;
	/** Kill count at which the slot is guaranteed, or 0. */
	private final int guaranteedBy;
	/** Each successful roll gives one of the item, so the log's count of it can be held against these odds. */
	private final boolean countable;

	public ItemOdds(List<Roll> rolls, int guaranteedBy)
	{
		this(rolls, guaranteedBy, false);
	}

	public ItemOdds(List<Roll> rolls, int guaranteedBy, boolean countable)
	{
		this.rolls = Collections.unmodifiableList(rolls);
		this.guaranteedBy = guaranteedBy;
		this.countable = countable;
	}

	/**
	 * How many of the item an average player would have had by these counts, or -1 unless every counter it drops from
	 * is known. The log counts copies from every source, so a source left out would read the log as lucky.
	 */
	public double expectedCount(Map<String, Integer> counters)
	{
		double expected = 0;
		for (Roll roll : rolls)
		{
			Integer count = counters.get(roll.label);
			if (count == null)
			{
				return -1;
			}
			expected += roll.chance * roll.rolls * count;
		}
		return rolls.isEmpty() ? -1 : expected;
	}

	/** The counter most of this slot's chance comes from, used to label it. */
	public String mainLabel()
	{
		Roll best = rolls.get(0);
		for (Roll roll : rolls)
		{
			if (roll.chancePerCount() > best.chancePerCount())
			{
				best = roll;
			}
		}
		return best.label;
	}

	/** Chance in one kill count of the main counter, for showing "1 in N". */
	public double mainChance()
	{
		String label = mainLabel();
		double miss = 1;
		for (Roll roll : rolls)
		{
			if (roll.label.equals(label))
			{
				miss *= Math.pow(1 - roll.chance, roll.rolls);
			}
		}
		return 1 - miss;
	}

	/**
	 * The chance of still not having this slot at these counts, or -1 when none of its
	 * counters is known. Counters that are unknown count as zero.
	 */
	public double dryChance(Map<String, Integer> counters)
	{
		boolean known = false;
		double logMiss = 0;
		int main = 0;
		for (Roll roll : rolls)
		{
			Integer count = counters.get(roll.label);
			if (count == null)
			{
				continue;
			}
			known = true;
			logMiss += roll.rolls * (double) count * Math.log1p(-Math.min(roll.chance, 0.999999));
			if (roll.label.equals(mainLabel()))
			{
				main = Math.max(main, count);
			}
		}
		if (!known)
		{
			return -1;
		}
		if (guaranteedBy > 0 && main >= guaranteedBy)
		{
			return 0;
		}
		// Never exactly 0 unless guaranteed: a dry streak of hundreds of thousands of kills underflows a double.
		return Math.max(Double.MIN_VALUE, Math.exp(logMiss));
	}

	@Getter
	public static final class Roll
	{
		private final String label;
		private final double chance;
		private final int rolls;

		public Roll(String label, double chance, int rolls)
		{
			this.label = label;
			this.chance = chance;
			this.rolls = rolls;
		}

		double chancePerCount()
		{
			return 1 - Math.pow(1 - chance, rolls);
		}
	}
}

package com.codex.loginsight.data;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The bundled tables: every activity that fills collection log slots, how often it
 * can be done in an hour and what it drops, plus each slot's odds per kill count.
 * Built by tools/build_data.py; see THIRD_PARTY_NOTICES.md for where it comes from.
 */
public final class LogData
{
	private static final String RESOURCE = "/com/codex/loginsight/codex-log.json";

	private final List<Activity> activities;
	private final Map<Integer, List<Activity.Drop>> dropsByItem;
	private final Map<Integer, ItemOdds> odds;
	private final List<String> labels;
	private final Set<Integer> pets;

	public LogData(List<Activity> activities, List<String> labels, Map<Integer, ItemOdds> odds, Set<Integer> pets)
	{
		this.activities = Collections.unmodifiableList(new ArrayList<>(activities));
		this.labels = Collections.unmodifiableList(new ArrayList<>(labels));
		this.odds = Collections.unmodifiableMap(new HashMap<>(odds));
		this.pets = Collections.unmodifiableSet(new HashSet<>(pets));
		Map<Integer, List<Activity.Drop>> byItem = new HashMap<>();
		for (Activity activity : this.activities)
		{
			for (Activity.Drop drop : activity.getDrops())
			{
				byItem.computeIfAbsent(drop.getItemId(), k -> new ArrayList<>()).add(drop);
			}
		}
		this.dropsByItem = byItem;
	}

	public static LogData load(Gson gson) throws IOException
	{
		try (InputStream in = LogData.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing " + RESOURCE);
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				return fromRaw(gson.fromJson(reader, Raw.class));
			}
		}
	}

	static LogData fromRaw(Raw raw)
	{
		List<Activity> activities = new ArrayList<>();
		for (RawActivity a : raw.activities)
		{
			List<Activity.Drop> drops = new ArrayList<>();
			Map<Integer, Integer> positions = new HashMap<>();
			int index = activities.size();
			Map<Integer, RawPet> scaled = new HashMap<>();
			if (a.p != null)
			{
				for (RawPet pet : a.p)
				{
					if (pet != null && pet.s != null && pet.b > 0)
					{
						scaled.put(pet.i, pet);
					}
				}
			}
			for (double[] d : a.d)
			{
				RawPet pet = scaled.get((int) d[0]);
				Activity.Drop drop = pet == null ? new Activity.Drop(index, (int) d[0], d[1], (int) d[2])
					: new Activity.Drop(index, (int) d[0], d[1], (int) d[2], pet.s, pet.b);
				Integer at = positions.putIfAbsent(drop.getItemId(), drops.size());
				if (at == null)
				{
					drops.add(drop);
				}
				else if (better(drop, drops.get(at)))
				{
					// A second row for the same slot is another way to earn it on the same activity (destroying
					// Araxxor instead of looting, buying with points instead of rolling). They are alternatives,
					// not extra rolls, so the slot takes whichever is quicker, in the first row's place.
					drops.set(at, drop);
				}
			}
			Map<String, Integer> skills = a.r == null || a.r.s == null ? Collections.emptyMap() : a.r.s;
			List<String> quests = a.r == null || a.r.q == null ? Collections.emptyList() : a.r.q;
			activities.add(new Activity(index, a.n, Activity.Category.of(a.c), a.m, a.i, a.f, drops, skills, quests));
		}
		Map<Integer, ItemOdds> odds = new HashMap<>();
		for (Map.Entry<String, RawOdds> e : raw.odds.entrySet())
		{
			List<ItemOdds.Roll> rolls = new ArrayList<>();
			for (double[] r : e.getValue().r)
			{
				rolls.add(new ItemOdds.Roll(raw.labels.get((int) r[0]), r[1], (int) r[2]));
			}
			odds.put(Integer.parseInt(e.getKey()), new ItemOdds(rolls, e.getValue().g, e.getValue().c == 1));
		}
		Set<Integer> pets = new HashSet<>();
		for (int id : raw.pets)
		{
			pets.add(id);
		}
		return new LogData(activities, raw.labels, odds, pets);
	}

	/**
	 * These tables at an account's real levels, so a skilling pet's odds are the ones this account rolls: a
	 * level 40 thief waits longer for Rocky than a level 99 one. Itself when no rate moves.
	 *
	 * @param levels real level by RuneLite skill name, or null when unknown
	 * @param maxed  skills with 200M experience, whose pets are 15 times likelier
	 */
	public LogData atLevels(Map<String, Integer> levels, Set<String> maxed)
	{
		if (levels == null)
		{
			return this;
		}
		List<Activity> scaled = new ArrayList<>(activities.size());
		boolean changed = false;
		for (Activity activity : activities)
		{
			Activity at = activity.atLevels(levels, maxed);
			changed |= at != activity;
			scaled.add(at);
		}
		return changed ? new LogData(scaled, labels, odds, pets) : this;
	}

	/** The skills any rate depends on, by RuneLite name. */
	public Set<String> scaledSkills()
	{
		Set<String> skills = new java.util.TreeSet<>();
		for (Activity activity : activities)
		{
			for (Activity.Drop drop : activity.getDrops())
			{
				if (drop.isLevelScaled())
				{
					skills.add(drop.getScaleSkill());
				}
			}
		}
		return skills;
	}

	/** True when this row earns its slot sooner than the other, a fixed count winning ties. */
	private static boolean better(Activity.Drop drop, Activity.Drop other)
	{
		if (drop.getAttempts() != other.getAttempts())
		{
			return drop.getAttempts() < other.getAttempts();
		}
		return drop.isExact() && !other.isExact();
	}

	public List<Activity> getActivities()
	{
		return activities;
	}

	/** Every activity row that can drop this item, possibly none. */
	public List<Activity.Drop> dropsOf(int itemId)
	{
		List<Activity.Drop> drops = dropsByItem.get(itemId);
		return drops == null ? Collections.emptyList() : drops;
	}

	public Activity activity(int index)
	{
		return activities.get(index);
	}

	/** Odds per kill count, or null for slots that are bought, guaranteed or not modelled. */
	public ItemOdds odds(int itemId)
	{
		return odds.get(itemId);
	}

	/** Every slot with odds per kill count, by item id. */
	public Map<Integer, ItemOdds> allOdds()
	{
		return odds;
	}

	/** Every quest any activity needs, by name. */
	public Set<String> questsNeeded()
	{
		Set<String> quests = new java.util.TreeSet<>();
		for (Activity activity : activities)
		{
			quests.addAll(activity.getQuests());
		}
		return quests;
	}

	/** The collection log counter names the odds refer to, such as "Vorkath kills". */
	public List<String> getLabels()
	{
		return labels;
	}

	public boolean isPet(int itemId)
	{
		return pets.contains(itemId);
	}

	static final class Raw
	{
		List<RawActivity> activities = new ArrayList<>();
		int[] pets = new int[0];
		List<String> labels = new ArrayList<>();
		Map<String, RawOdds> odds = new HashMap<>();
	}

	static final class RawActivity
	{
		String n;
		String c;
		double m;
		double i;
		double f;
		List<double[]> d = new ArrayList<>();
		RawNeeds r;
		/** Skilling pets on this table whose odds follow a level. */
		List<RawPet> p;
	}

	static final class RawPet
	{
		int i;
		String s;
		double b;
	}

	static final class RawNeeds
	{
		Map<String, Integer> s;
		List<String> q;
	}

	static final class RawOdds
	{
		List<double[]> r = new ArrayList<>();
		int g;
		/** 1 when the log's count of the item can be held against its odds. */
		int c;
	}
}

package com.codex.loginsight.overlay;

import com.codex.loginsight.ui.Sigil;
import com.codex.loginsight.ui.Theme;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A gilt plaque that rises in the game view when a new slot lands: the item, its odds,
 * the count it came at, and how lucky that was. It draws a view the plugin prepares,
 * so rendering never touches game state.
 */
public class FindPlaque extends Overlay
{
	private static final int WIDTH = 228;
	private static final int PAD = 9;
	private static final int ICON = 40;
	private static final long FADE_MS = 450;

	/** What the plaque shows. */
	public static final class View
	{
		final String name;
		final String page;
		final String odds;
		final String verdict;
		final Color color;
		final boolean pet;
		final BufferedImage icon;
		final long shownAt;
		final long durationMs;
		/** The slot was on the wanted list: the plaque says the hunt is over. */
		final boolean wanted;

		public View(String name, String page, String odds, String verdict, Color color, boolean pet, BufferedImage icon,
			long shownAt, long durationMs)
		{
			this(name, page, odds, verdict, color, pet, icon, shownAt, durationMs, false);
		}

		public View(String name, String page, String odds, String verdict, Color color, boolean pet, BufferedImage icon,
			long shownAt, long durationMs, boolean wanted)
		{
			this.wanted = wanted;
			this.name = name;
			this.page = page;
			this.odds = odds;
			this.verdict = verdict;
			this.color = color;
			this.pet = pet;
			this.icon = icon;
			this.shownAt = shownAt;
			this.durationMs = durationMs;
		}
	}

	private volatile View view;

	public FindPlaque()
	{
		setPosition(OverlayPosition.TOP_CENTER);
	}

	public void show(View view)
	{
		this.view = view;
	}

	public void clear()
	{
		view = null;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		View v = view;
		if (v == null)
		{
			return null;
		}
		long age = System.currentTimeMillis() - v.shownAt;
		if (age > v.durationMs)
		{
			view = null;
			return null;
		}
		float alpha = (float) Math.min(1, Math.min(age / (double) FADE_MS, (v.durationMs - age) / (double) FADE_MS));
		Composite old = g.getComposite();
		g.setComposite(FADE[Math.max(0, Math.min(FADE_STEPS, Math.round(alpha * FADE_STEPS)))]);
		Theme.smooth(g);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Layout l = layout;
		if (l == null || l.view != v || !l.small.getFont().equals(small.getFont()) || !l.bold.getFont().equals(bold.getFont()))
		{
			// The plaque's text, shape and paints are worked out once per find, not every frame it is up.
			l = new Layout(v, small, bold);
			layout = l;
		}

		g.setPaint(l.fill);
		g.fill(l.shape);
		double beat = 0.5 + 0.5 * Math.sin(age / 220.0);
		g.setStroke(GLOW);
		g.setColor(l.pulse[(int) Math.round(beat * PULSE_STEPS)]);
		g.draw(l.shape);
		g.setStroke(LINE);
		g.setColor(l.rim);
		g.draw(l.shape);

		// The item sits in a lit well.
		g.setPaint(l.wellPaint);
		g.fill(l.well);
		g.setColor(l.wellRim);
		g.draw(l.well);
		if (v.icon != null)
		{
			g.drawImage(v.icon, l.wellX + (ICON - v.icon.getWidth()) / 2, l.wellY + (ICON - v.icon.getHeight()) / 2, null);
		}
		else
		{
			Sigil.paint(g, l.wellX + 8, l.wellY + 8, ICON - 16);
		}

		int x = PAD + ICON + 9;
		int y = l.textY;
		g.setFont(Theme.small());
		shadow(g, l.heading, x, y + small.getAscent(), l.tint);
		y += small.getHeight();
		g.setFont(Theme.title());
		shadow(g, l.name, x, y + bold.getAscent(), Theme.GOLD_BRIGHT);
		y += bold.getHeight();
		g.setFont(Theme.small());
		if (l.odds != null)
		{
			shadow(g, l.odds, x, y + small.getAscent(), Theme.TEXT_MUTED);
			y += small.getHeight() + 1;
		}
		if (l.verdict != null)
		{
			shadow(g, l.verdict, x, y + small.getAscent(), v.color);
		}
		g.setComposite(old);
		return l.size;
	}

	private static final int FADE_STEPS = 32;
	/** The fade in and out in 32 steps, so no composite is made while the plaque is up. */
	private static final AlphaComposite[] FADE = new AlphaComposite[FADE_STEPS + 1];
	private static final int PULSE_STEPS = 35;
	private static final BasicStroke GLOW = new BasicStroke(3f);
	private static final BasicStroke LINE = new BasicStroke(1f);

	static
	{
		for (int i = 0; i <= FADE_STEPS; i++)
		{
			FADE[i] = AlphaComposite.getInstance(AlphaComposite.SRC_OVER, i / (float) FADE_STEPS);
		}
	}

	private volatile Layout layout;

	/** Everything about the plaque that depends only on the find and the fonts. */
	private static final class Layout
	{
		final View view;
		final FontMetrics small;
		final FontMetrics bold;
		final Color tint;
		final Color rim;
		/** The beating outer glow, from faint to full. */
		final Color[] pulse = new Color[PULSE_STEPS + 1];
		final String heading;
		final String name;
		final String odds;
		final String verdict;
		final int wellX;
		final int wellY;
		final int textY;
		final RoundRectangle2D shape;
		final GradientPaint fill;
		final Ellipse2D well;
		final RadialGradientPaint wellPaint;
		final Color wellRim;
		final Dimension size;

		Layout(View v, FontMetrics small, FontMetrics bold)
		{
			view = v;
			this.small = small;
			this.bold = bold;
			int lines = 2 + (v.odds == null ? 0 : 1) + (v.verdict == null ? 0 : 1);
			int textHeight = small.getHeight() + bold.getHeight() + (lines - 2) * (small.getHeight() + 1);
			int height = PAD * 2 + Math.max(ICON, textHeight);
			tint = v.pet ? Theme.VIOLET : Theme.GOLD;
			rim = Theme.alpha(tint, 200);
			for (int i = 0; i <= PULSE_STEPS; i++)
			{
				pulse[i] = Theme.alpha(tint, 40 + 70 * i / PULSE_STEPS);
			}
			shape = new RoundRectangle2D.Float(0.5f, 0.5f, WIDTH - 1, height - 1, 12, 12);
			fill = new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 238), 0, height, Theme.alpha(Theme.INK_DEEP, 238));
			wellX = PAD;
			wellY = (height - ICON) / 2;
			well = new Ellipse2D.Float(wellX, wellY, ICON, ICON);
			wellPaint = new RadialGradientPaint(wellX + ICON / 2f, wellY + ICON / 2f, ICON / 2f,
				new float[]{0f, 1f}, new Color[]{Theme.alpha(tint, 110), Theme.alpha(Theme.INK_DEEP, 220)});
			wellRim = Theme.alpha(tint, 170);
			int width = WIDTH - (PAD + ICON + 9) - PAD;
			textY = PAD + Math.max(0, (Math.max(ICON, textHeight) - textHeight) / 2);
			heading = v.wanted ? "WANTED, AND FOUND" : v.pet ? "A NEW COMPANION" : "NEW LOG SLOT";
			name = clip(v.name, bold, width);
			odds = v.odds == null ? null : clip(v.odds, small, width);
			verdict = v.verdict == null ? null : clip(v.verdict, small, width);
			size = new Dimension(WIDTH, height);
		}
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static String clip(String text, FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String ellipsis = "...";
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + ellipsis) > width)
		{
			end--;
		}
		return text.substring(0, end) + ellipsis;
	}
}

package com.codex.loginsight.overlay;

import com.codex.loginsight.core.Grind;
import com.codex.loginsight.core.Report;
import com.codex.loginsight.ui.Format;
import com.codex.loginsight.ui.Theme;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A small card in the game view while you grind a page of the log: the kill count and what tonight added, the wait
 * for the page's next slot, and the slot most worth watching with how dry you are on it. It steps aside a few
 * minutes after the last kill count, so it is only there while the grind is.
 */
public class GrindCard extends Overlay
{
	private static final int WIDTH = 176;
	private static final int PAD = 8;

	private volatile Grind grind;

	public GrindCard()
	{
		setPosition(OverlayPosition.TOP_LEFT);
	}

	public void setGrind(Grind grind)
	{
		this.grind = grind;
	}

	public void clear()
	{
		grind = null;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Grind v = grind;
		if (v == null || !v.isShowing(System.currentTimeMillis()))
		{
			return null;
		}
		Theme.smooth(g);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Layout l = layout;
		if (l == null || l.grind != v || !l.small.getFont().equals(small.getFont()) || !l.bold.getFont().equals(bold.getFont()))
		{
			// Every line, its clipping and the card's shape are worked out once per grind update, not every frame.
			l = new Layout(v, small, bold);
			layout = l;
		}

		g.setPaint(l.fill);
		g.fill(l.shape);
		g.setColor(l.rim);
		g.draw(l.shape);

		int x = PAD;
		int y = PAD;
		g.setFont(Theme.title());
		shadow(g, l.page, x, y + bold.getAscent(), Theme.GOLD_BRIGHT);
		g.setFont(Theme.small());
		shadow(g, l.kc, x + WIDTH - PAD * 2 - l.kcWidth, y + bold.getAscent(), Theme.GOLD);
		y += bold.getHeight();
		shadow(g, l.tonight, x, y + small.getAscent(), Theme.TEXT_MUTED);
		y += small.getHeight() + 1;
		shadow(g, l.next, x, y + small.getAscent(), Theme.TEAL);
		y += small.getHeight() + 1;
		if (l.name != null)
		{
			shadow(g, l.name, x, y + small.getAscent(), v.isFocusWanted() ? Theme.GOLD : Theme.TEXT);
			shadow(g, l.dry, x + WIDTH - PAD * 2 - l.dryWidth, y + small.getAscent(), l.dryColor);
			y += small.getHeight() + 2;
			if (l.barFill > 0)
			{
				bar(g, l, x, y);
			}
		}
		return l.size;
	}

	private static final Color FILL_TOP = Theme.alpha(Theme.CARD_TOP, 228);
	private static final Color FILL_BOTTOM = Theme.alpha(Theme.INK_DEEP, 228);
	private static final Color RIM_WANTED = Theme.alpha(Theme.GOLD, 220);
	private static final Color RIM = Theme.alpha(Theme.STROKE, 220);
	private static final Color NOTCH = Theme.alpha(Theme.TEXT, 110);
	private static final int BAR_H = 4;

	private volatile Layout layout;

	/** The card's text and shapes for one grind update. */
	private static final class Layout
	{
		final Grind grind;
		final FontMetrics small;
		final FontMetrics bold;
		final String page;
		final String kc;
		final int kcWidth;
		final String tonight;
		final String next;
		final String name;
		final String dry;
		final int dryWidth;
		final Color dryColor;
		final float barFill;
		final GradientPaint barPaint;
		final RoundRectangle2D shape;
		final GradientPaint fill;
		final Color rim;
		final Dimension size;

		Layout(Grind v, FontMetrics small, FontMetrics bold)
		{
			grind = v;
			this.small = small;
			this.bold = bold;
			int width = WIDTH - PAD * 2;
			kc = Format.count(v.getCount()) + " kc";
			kcWidth = small.stringWidth(kc);
			page = clip(v.getPage(), bold, width - kcWidth - 6);
			tonight = clip((v.getAdded() > 0 ? "+" + Format.count(v.getAdded()) + " this session  ·  " : "")
				+ v.getMissing() + (v.getMissing() == 1 ? " slot left" : " slots left"), small, width);
			next = clip(Double.isFinite(v.getHoursToNext()) ? "Next slot " + Format.about(v.getHoursToNext()) : "Next slot not timed",
				small, width);
			Report.ItemReport focus = v.getFocus();
			float bar = 0;
			GradientPaint paint = null;
			if (focus != null)
			{
				dry = focus.getDryChance() >= 0 ? Format.dry(focus.getDryChance()) : Format.chance(focus.getChance());
				dryWidth = small.stringWidth(dry);
				dryColor = focus.getDryChance() >= 0 ? Theme.dry(focus.getDryChance()) : Theme.TEXT;
				name = clip((v.isFocusWanted() ? "Wanted: " : "") + focus.getName(), small, width - dryWidth - 6);
				if (focus.getDryChance() >= 0)
				{
					double still = focus.getDryChance();
					bar = (float) Math.max(BAR_H, width * Math.max(0, Math.min(1, 1 - still)));
					paint = new GradientPaint(PAD, 0, Theme.GOLD_DIM, PAD + bar, 0, Theme.dry(still));
				}
			}
			else
			{
				dry = null;
				dryWidth = 0;
				dryColor = Theme.TEXT;
				name = null;
			}
			barFill = bar;
			barPaint = paint;
			int lines = 2 + (focus != null ? 1 : 0);
			int height = PAD * 2 + bold.getHeight() + lines * (small.getHeight() + 1) + (focus != null && focus.getDryChance() >= 0 ? 7 : 0);
			shape = new RoundRectangle2D.Float(0.5f, 0.5f, WIDTH - 1, height - 1, 10, 10);
			fill = new GradientPaint(0, 0, FILL_TOP, 0, height, FILL_BOTTOM);
			rim = v.isFocusWanted() ? RIM_WANTED : RIM;
			size = new Dimension(WIDTH, height);
		}
	}

	/** The share of players who would have the slot by now, with notches at half and nine in ten. */
	private static void bar(Graphics2D g, Layout l, int x, int y)
	{
		int width = WIDTH - PAD * 2;
		g.setColor(Theme.INK_DEEP);
		g.fillRoundRect(x, y, width, BAR_H, BAR_H, BAR_H);
		g.setPaint(l.barPaint);
		g.fillRoundRect(x, y, Math.round(l.barFill), BAR_H, BAR_H, BAR_H);
		g.setColor(NOTCH);
		g.drawLine(x + width / 2, y, x + width / 2, y + BAR_H - 1);
		g.drawLine(x + width * 9 / 10, y, x + width * 9 / 10, y + BAR_H - 1);
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static String clip(String text, FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String dots = "...";
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + dots) > width)
		{
			end--;
		}
		return text.substring(0, end).trim() + dots;
	}
}

package com.codex.loginsight.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.loginsight.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.loginsight.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Luck;
import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.geom.Path2D;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/**
 * The crest at the top of the panel: a ring for the whole log, the slot count, and
 * three ledgers for finished pages, luck and the hours still ahead.
 */
public class Crest extends JPanel
{
	private final ProgressRing ring = new ProgressRing(70, 7f);
	private final JLabel title = Ui.label("Log Insight", Theme.title(), Theme.GOLD_BRIGHT);
	private final JLabel slots = Ui.label("Log in to read your log", Theme.small(), Theme.TEXT_MUTED);
	private final Ledger pages = new Ledger("Pages done", true);
	private final Ledger luck = new Ledger("Luck", false);
	private final Ledger left = new Ledger("Hours left", false);
	private Color glow = Theme.GOLD_DIM;

	public Crest()
	{
		super(new BorderLayout(10, 0));
		setOpaque(false);
		setBorder(new EmptyBorder(12, 10, 12, 10));

		JPanel ringHolder = new JPanel(new BorderLayout());
		ringHolder.setOpaque(false);
		ringHolder.add(ring, BorderLayout.NORTH);
		add(ringHolder, BorderLayout.WEST);

		JPanel right = new JPanel();
		right.setOpaque(false);
		right.setLayout(new BoxLayout(right, BoxLayout.Y_AXIS));
		title.setAlignmentX(LEFT_ALIGNMENT);
		slots.setAlignmentX(LEFT_ALIGNMENT);
		right.add(title);
		right.add(slots);
		JPanel ledgers = new JPanel(new GridLayout(3, 1, 0, 2));
		ledgers.setOpaque(false);
		ledgers.setBorder(new EmptyBorder(4, 0, 0, 0));
		ledgers.add(pages);
		ledgers.add(luck);
		ledgers.add(left);
		ledgers.setAlignmentX(LEFT_ALIGNMENT);
		right.add(ledgers);
		add(right, BorderLayout.CENTER);
		ring.setCaption("logged");
		ring.setProgress(0, false, false);
	}

	public void update(Report report, String playerName)
	{
		if (!report.isLoggedIn())
		{
			title.setText("Log Insight");
			slots.setText("Log in to read your log");
			ring.setProgress(0, false, true);
			// Logged out the log is unknown, not empty: no "0% logged".
			ring.setCentre("-");
			ring.setCaption("log in");
			pages.set("-", 0, Theme.TEXT);
			luck.set("-", -1, Theme.TEXT);
			left.set("-", -1, Theme.TEXT);
			glow = Theme.GOLD_DIM;
			repaint();
			return;
		}
		ring.setCentre(null);
		ring.setCaption("logged");
		int owned = report.owned();
		int total = report.total();
		title.setText(playerName == null ? "Log Insight" : playerName);
		slots.setText(total <= 0 ? "Reading the log..." : Format.count(owned) + " / " + Format.count(total) + " slots");
		ring.setProgress(total <= 0 ? 0 : owned / (double) total, total > 0 && owned >= total, true);
		pages.set(report.getPagesComplete() + "/" + report.getPagesTotal(),
			report.getPagesTotal() == 0 ? 0 : report.getPagesComplete() / (double) report.getPagesTotal(), Theme.TEXT);
		Luck l = report.getLuck();
		if (l == null)
		{
			luck.set("Unread", -1, Theme.TEXT_MUTED);
			glow = Theme.GOLD_DIM;
		}
		else
		{
			Color c = Theme.luck(l.verdict());
			luck.set(l.verdict().getLabel(), -1, c);
			glow = Theme.mix(Theme.GOLD_DIM, c, 0.45);
		}
		if (report.ownedRead())
		{
			left.set(Format.hours(report.getHoursLeft()), -1, Theme.TEXT);
		}
		else
		{
			left.set("-", -1, Theme.TEXT_MUTED);
		}
		left.setToolTipText(report.isIronRates() ? "At ironman rates" : "At typical rates, or your own pace where Log Insight has learned it");
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, glow, 0.2), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// Gilt rule along the bottom with a small diamond at its centre.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
		super.paintComponent(graphics);
	}

	/** One labelled value, with a hairline bar under it when the value is a share of something. */
	private static final class Ledger extends JPanel
	{
		private final JLabel value = Ui.label("-", Theme.small(), Theme.TEXT);
		private final ProgressBar bar;

		Ledger(String label, boolean withBar)
		{
			super(new BorderLayout(0, 1));
			setOpaque(false);
			JPanel line = new JPanel(new BorderLayout());
			line.setOpaque(false);
			line.add(Ui.label(label, Theme.small(), Theme.TEXT_MUTED), BorderLayout.WEST);
			line.add(value, BorderLayout.EAST);
			add(line, BorderLayout.CENTER);
			bar = withBar ? new ProgressBar(3) : null;
			if (bar != null)
			{
				add(bar, BorderLayout.SOUTH);
			}
			setPreferredSize(new Dimension(10, 17));
		}

		void set(String text, double share, Color color)
		{
			value.setText(text);
			value.setForeground(color);
			if (bar != null)
			{
				bar.setProgress(Math.max(0, share), share >= 1, true);
			}
		}
	}
}

package com.codex.loginsight.ui;

import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Line2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * How far into a slot's odds you are: the bar fills with the share of players who would have it by your count,
 * gilt while that is ordinary and ember to blood as it gets rare, with notches where half and nine in ten of
 * players would have it.
 */
final class DryBar extends JComponent
{
	private static final int HEIGHT = 7;
	private final double stillWaiting;

	/** @param stillWaiting the share of players still without the slot at your count */
	DryBar(double stillWaiting)
	{
		this.stillWaiting = stillWaiting;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setAlignmentX(0f);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = HEIGHT - 1;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(0, 0, w - 1, h, h, h));
		double share = Math.max(0, Math.min(1, 1 - stillWaiting));
		if (stillWaiting >= 0 && share > 0)
		{
			float fill = (float) Math.max(h, (w - 1) * share);
			g.setPaint(new GradientPaint(0, 0, Theme.GOLD_DIM, fill, 0, Theme.dry(stillWaiting)));
			g.fill(new RoundRectangle2D.Float(0, 0, fill, h, h, h));
		}
		g.setColor(Theme.alpha(Theme.TEXT, 120));
		for (double notch : new double[]{0.5, 0.9})
		{
			float x = (float) ((w - 1) * notch);
			g.draw(new Line2D.Float(x, 1, x, h - 1));
		}
		g.setColor(Theme.alpha(Theme.STROKE, 160));
		g.draw(new RoundRectangle2D.Float(0, 0, w - 1, h, h, h));
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Progress;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Finest finds as a card to share: whose log it is and how full, then the podium as the Ledger draws it, fourth and
 * fifth beneath. It is drawn only once every picture is in (see {@link IconWait}), so no plinth stands empty.
 */
public final class FindsShare
{
	static final int WIDTH = 260;
	static final int SCALE = 2;
	private static final int PAD = 16;
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("d MMMM yyyy", Locale.ENGLISH);

	private FindsShare()
	{
	}

	/** Everything the card shows, taken once so a saved card and a copied one read the same. */
	public static final class Spec
	{
		final String player;
		final List<Progress.Find> finds;
		final int owned;
		final int total;
		final long now;
		final ZoneId zone;

		private Spec(String player, List<Progress.Find> finds, int owned, int total, long now, ZoneId zone)
		{
			this.player = player;
			this.finds = finds;
			this.owned = owned;
			this.total = total;
			this.now = now;
			this.zone = zone;
		}

		/**
		 * @param player the name to print, or null to leave it off
		 * @param owned  slots logged, shown with the total when the log has been read (total above 0)
		 * @return the card, or null with no finds yet
		 */
		public static Spec of(List<Progress.Find> finds, String player, int owned, int total, long now, ZoneId zone)
		{
			if (finds == null || finds.isEmpty())
			{
				return null;
			}
			String name = player == null || player.trim().isEmpty() ? null : player.trim();
			return new Spec(name, Collections.unmodifiableList(new ArrayList<>(finds)), owned, total, now, zone);
		}

		/** The large line: the player's name, or "Finest finds" when it is left off. */
		String heading()
		{
			return player != null ? player : "Finest finds";
		}

		/** The line under it: what the card is (when the name heads it) and how full the log is. */
		String subheading()
		{
			String slots = total > 0 ? Format.count(owned) + " of " + Format.count(total) + " slots" : null;
			if (player == null)
			{
				return slots;
			}
			return slots == null ? "Finest finds" : "Finest finds  ·  " + slots;
		}

		/** The item ids whose pictures the card needs. */
		public List<Integer> itemIds()
		{
			return IconWait.ids(finds);
		}
	}

	/** "codex-finds-2026-10-19.png". */
	public static String fileName(long now, ZoneId zone)
	{
		return "codex-finds-" + Instant.ofEpochMilli(now).atZone(zone).toLocalDate() + ".png";
	}

	/**
	 * Waits for the finds' pictures, then draws the card and hands it over on the Swing thread.
	 */
	static IconWait whenReady(Spec spec, ItemIcons icons, java.util.function.Consumer<BufferedImage> done)
	{
		return IconWait.forItems(icons, spec.itemIds(), images -> done.accept(render(spec, images)));
	}

	/** @param images each find's picture by item id; a find without one stands on its plinth as a dark disc */
	public static BufferedImage render(Spec spec, Map<Integer, BufferedImage> images)
	{
		TrophyShelf shelf = new TrophyShelf(spec.finds, (itemId, onLoaded) -> images.get(itemId));
		int shelfW = WIDTH - 2 * PAD;
		int shelfH = shelf.getPreferredSize().height;
		shelf.setSize(shelfW, shelfH);

		String sub = spec.subheading();
		int headTop = PAD + 16;
		int shelfTop = headTop + (sub != null ? 52 : 40);
		int footTop = shelfTop + shelfH + 12;
		int height = footTop + 26;

		BufferedImage image = new BufferedImage(WIDTH * SCALE, height * SCALE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.scale(SCALE, SCALE);
		Theme.smooth(g);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);

		RoundRectangle2D outer = new RoundRectangle2D.Float(0.5f, 0.5f, WIDTH - 1, height - 1, 14, 14);
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.16), 0, height, Theme.INK_DEEP));
		g.fill(outer);
		g.setColor(Theme.GOLD_DIM);
		g.draw(outer);
		g.setColor(Theme.alpha(Theme.GOLD, 60));
		g.draw(new RoundRectangle2D.Float(4.5f, 4.5f, WIDTH - 9, height - 9, 10, 10));

		// The masthead: the plugin's mark on the left, today's date on the right.
		g.setFont(Theme.small());
		FontMetrics sm = g.getFontMetrics();
		int mastY = PAD + 4 + sm.getAscent() / 2 - 1;
		diamond(g, PAD + 3, PAD + 4, 3, Theme.GOLD);
		g.setColor(Theme.GOLD);
		g.drawString("CODEX LOG INSIGHT", PAD + 11, mastY);
		String today = Instant.ofEpochMilli(spec.now).atZone(spec.zone).format(DATE);
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(today, WIDTH - PAD - sm.stringWidth(today), mastY);

		String heading = spec.heading();
		int textW = WIDTH - 2 * PAD;
		if (g.getFontMetrics(Theme.title()).stringWidth(heading) * 2 <= textW)
		{
			large(g, heading, PAD, headTop);
		}
		else
		{
			g.setFont(Theme.title());
			g.setColor(Theme.GOLD_BRIGHT);
			g.drawString(clip(heading, g.getFontMetrics(), textW), PAD, headTop + g.getFontMetrics().getAscent() + 6);
		}
		if (sub != null)
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_MUTED);
			g.drawString(clip(sub, g.getFontMetrics(), textW), PAD, headTop + 44);
		}

		Graphics2D sg = (Graphics2D) g.create(PAD, shelfTop, shelfW, shelfH);
		shelf.paint(sg);
		sg.dispose();

		int fy = footTop;
		g.setPaint(new GradientPaint(PAD, 0, Theme.alpha(Theme.GOLD, 0), WIDTH / 2f, 0, Theme.alpha(Theme.GOLD, 140), true));
		g.drawLine(PAD, fy, WIDTH - PAD, fy);
		diamond(g, WIDTH / 2, fy, 3, Theme.GOLD);
		g.setFont(Theme.small());
		String foot = "Read by Codex Log Insight";
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(foot, (WIDTH - g.getFontMetrics().stringWidth(foot)) / 2, fy + 16);
		g.dispose();
		return image;
	}

	/** The game's bold font doubled pixel for pixel, the way the game draws large lettering. */
	private static void large(Graphics2D g, String text, int x, int y)
	{
		Font font = Theme.title();
		FontMetrics fm = g.getFontMetrics(font);
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(new GradientPaint(0, 3, Theme.GOLD_BRIGHT, 0, base, Theme.GOLD));
		sg.drawString(text, 0, base);
		sg.dispose();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(small, x, y, w * 2, h * 2, null);
		lg.dispose();
	}

	private static void diamond(Graphics2D g, int cx, int cy, int r, Color c)
	{
		Path2D d = new Path2D.Float();
		d.moveTo(cx, cy - r);
		d.lineTo(cx + r, cy);
		d.lineTo(cx, cy + r);
		d.lineTo(cx - r, cy);
		d.closePath();
		g.setColor(c);
		g.fill(d);
	}

	private static String clip(String s, FontMetrics fm, int width)
	{
		if (fm.stringWidth(s) <= width)
		{
			return s;
		}
		String out = s;
		while (out.length() > 1 && fm.stringWidth(out.trim() + "…") > width)
		{
			out = out.substring(0, out.length() - 1);
		}
		return out.trim() + "…";
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** Every page of the log, grouped by tab, each with its progress, kill count and luck. */
final class FoliosView
{
	private FoliosView()
	{
	}

	static StackPanel build(Report report, String filter, Consumer<String> openPage)
	{
		StackPanel stack = new StackPanel(5, 8);
		if (!report.isLoggedIn())
		{
			stack.add(Rows.note("Log in to see your log page by page.", 190));
			return stack;
		}
		if (report.getPages().isEmpty())
		{
			stack.add(Rows.note("Reading the log's pages from the game...", 190));
			return stack;
		}
		String needle = filter == null ? "" : filter.trim().toLowerCase(Locale.ENGLISH);
		Map<String, List<Report.PageReport>> byTab = new LinkedHashMap<>();
		for (Report.PageReport page : report.getPages())
		{
			if (needle.isEmpty() || page.getName().toLowerCase(Locale.ENGLISH).contains(needle) || matchesItem(page, needle))
			{
				byTab.computeIfAbsent(page.getTab(), k -> new ArrayList<>()).add(page);
			}
		}
		if (byTab.isEmpty())
		{
			stack.add(Rows.note("No page or slot matches \"" + filter.trim() + "\".", 190));
			return stack;
		}
		for (Map.Entry<String, List<Report.PageReport>> tab : byTab.entrySet())
		{
			int done = 0;
			for (Report.PageReport page : tab.getValue())
			{
				done += page.isComplete() ? 1 : 0;
			}
			stack.add(new SectionHeader(tab.getKey(), done + "/" + tab.getValue().size()));
			for (Report.PageReport page : tab.getValue())
			{
				stack.add(row(page).onClick(() -> openPage.accept(page.getName())));
			}
		}
		return stack;
	}

	private static boolean matchesItem(Report.PageReport page, String needle)
	{
		for (Report.ItemReport item : page.getItems())
		{
			if (item.getName().toLowerCase(Locale.ENGLISH).contains(needle))
			{
				return true;
			}
		}
		return false;
	}

	static Card row(Report.PageReport page)
	{
		Card card = new Card(new BorderLayout(0, 3));
		card.setBorder(new EmptyBorder(6, 10, 7, 10));
		if (page.isComplete())
		{
			card.accent(Theme.GREEN);
		}
		else if (page.getLuck() != null)
		{
			card.accent(Theme.luck(page.getLuck().verdict()));
		}

		JPanel line = new JPanel(new BorderLayout(6, 0));
		line.setOpaque(false);
		line.add(Ui.label(page.getName(), Theme.body(), page.isComplete() ? Theme.GOLD_BRIGHT : Theme.TEXT), BorderLayout.CENTER);
		line.add(Ui.label(page.getOwned() + "/" + page.getTotal(), Theme.small(), page.isComplete() ? Theme.GREEN : Theme.TEXT_MUTED),
			BorderLayout.EAST);
		card.add(line, BorderLayout.NORTH);

		ProgressBar bar = new ProgressBar(4);
		bar.setProgress(page.progress(), page.isComplete(), false);
		card.add(bar, BorderLayout.CENTER);

		JPanel meta = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		meta.setOpaque(false);
		if (page.getLuck() != null && !page.isComplete())
		{
			meta.add(new Pill(page.getLuck().verdict().getLabel(), Theme.luck(page.getLuck().verdict())));
		}
		if (page.getCount() >= 0)
		{
			meta.add(Ui.label(Format.count(page.getCount()) + " kc", Theme.small(), Theme.TEXT_MUTED));
		}
		if (!page.isComplete() && Double.isFinite(page.getHoursToNext()))
		{
			meta.add(Ui.label("next " + Format.about(page.getHoursToNext()), Theme.small(), Theme.TEXT_FAINT));
		}
		if (meta.getComponentCount() > 0)
		{
			((FlowLayout) meta.getLayout()).setHgap(5);
			card.add(meta, BorderLayout.SOUTH);
		}
		return card;
	}
}

package com.codex.loginsight.ui;

/** Turns hours, odds and counts into the short phrases the panel uses. */
public final class Format
{
	private Format()
	{
	}

	/** "<1m", "45m", "3h 12m", "120h" or "8,420h"; "-" when it cannot be estimated. */
	public static String hours(double hours)
	{
		if (Double.isNaN(hours) || Double.isInfinite(hours) || hours < 0)
		{
			return "-";
		}
		double minutes = hours * 60;
		if (minutes < 1)
		{
			return "<1m";
		}
		if (minutes < 60)
		{
			return Math.round(minutes) + "m";
		}
		if (hours < 10)
		{
			long h = (long) hours;
			long m = Math.round((hours - h) * 60);
			if (m == 60)
			{
				h++;
				m = 0;
			}
			return m == 0 ? h + "h" : h + "h " + m + "m";
		}
		return String.format("%,dh", Math.round(hours));
	}

	/** "about 3h", or "under 1m" when it is that short. */
	public static String about(double hours)
	{
		String text = hours(hours);
		if (text.startsWith("<"))
		{
			return "under " + text.substring(1);
		}
		return "-".equals(text) ? text : "~" + text;
	}

	/** "1/512", or "1/3.4" for common drops; "-" when unknown. */
	public static String chance(double chance)
	{
		if (chance <= 0 || Double.isNaN(chance))
		{
			return "-";
		}
		double in = 1 / chance;
		if (in < 1.05)
		{
			return "Always";
		}
		if (in < 10 && Math.abs(in - Math.round(in)) >= 0.05)
		{
			return String.format("1/%.1f", in);
		}
		return String.format("1/%,d", Math.round(in));
	}

	/**
	 * How dry a missing slot is, the way players say it: the share of players who would
	 * already have it at this kill count. "88% dry" means 88 in 100 would have it by now; "Overdue" means it is
	 * guaranteed by a count you have passed.
	 *
	 * @param stillWaiting the share of players still without it
	 */
	public static String dry(double stillWaiting)
	{
		// Only a slot guaranteed by a count you have passed leaves nobody waiting: "100% dry" beside ">99% dry" rows
		// read as a figure, where it is a slot that should have come.
		return stillWaiting == 0 ? "Overdue" : have(stillWaiting) + " dry";
	}

	/**
	 * The share of players who would have it by now, from the share still without it. Worked from the share still
	 * waiting, since one minus a tiny share rounds to exactly 1 in a double and would read as a certain 100%.
	 */
	public static String have(double stillWaiting)
	{
		if (stillWaiting > 0 && stillWaiting < 0.01)
		{
			return ">99%";
		}
		return percent(1 - stillWaiting);
	}

	/**
	 * An expected number of slots: "0.48", "2.4", "12"; "<0.01" when it rounds to nothing. A figure that rounds to a
	 * whole number drops its zeros ("9", not "9.0"), so a list reads 74, 39, 11, 9 rather than switching to decimals.
	 */
	public static String slots(double slots)
	{
		if (Double.isNaN(slots) || slots <= 0)
		{
			return "0";
		}
		if (slots < 0.01)
		{
			return "<0.01";
		}
		if (slots < 1)
		{
			return trimZeros(String.format(java.util.Locale.ENGLISH, "%.2f", slots));
		}
		if (slots < 9.95)
		{
			return trimZeros(String.format(java.util.Locale.ENGLISH, "%.1f", slots));
		}
		return String.valueOf(Math.round(slots));
	}

	/** "slot" for a figure that reads as exactly one, "slots" for any other: "1 slot", "0.99 slots", "2.4 slots". */
	public static String slotWord(double slots)
	{
		return "1".equals(slots(slots)) ? "slot" : "slots";
	}

	/** "9.0" to "9", "0.50" to "0.5"; whole numbers and other decimals are left as they are. */
	private static String trimZeros(String number)
	{
		if (number.indexOf('.') < 0)
		{
			return number;
		}
		String out = number.replaceAll("0+$", "");
		return out.endsWith(".") ? out.substring(0, out.length() - 1) : out;
	}

	public static String count(long value)
	{
		return String.format("%,d", value);
	}

	/** Whole percent, with "<1%" and ">99%" at the ends so rare cases never read as 0 or 100. */
	public static String percent(double share)
	{
		if (share <= 0)
		{
			return "0%";
		}
		if (share < 0.01)
		{
			return "<1%";
		}
		if (share > 0.99 && share < 1)
		{
			return ">99%";
		}
		return Math.round(share * 100) + "%";
	}

	/** A stretch of play: "12m", "1h 20m", "6h". */
	public static String duration(long millis)
	{
		long minutes = Math.max(0, millis / 60_000);
		if (minutes < 60)
		{
			return minutes + "m";
		}
		long h = minutes / 60;
		long m = minutes % 60;
		return m == 0 ? h + "h" : h + "h " + m + "m";
	}

	/** "just now", "5m ago", "3h ago", "2d ago". */
	public static String ago(long then, long now)
	{
		long seconds = Math.max(0, (now - then) / 1000);
		if (seconds < 60)
		{
			return "just now";
		}
		if (seconds < 3600)
		{
			return seconds / 60 + "m ago";
		}
		if (seconds < 86400)
		{
			return seconds / 3600 + "h ago";
		}
		return seconds / 86400 + "d ago";
	}

	/** "Vorkath kills" to "Vorkath", for compact lines that already say "kc". */
	public static String counterName(String label)
	{
		if (label == null)
		{
			return "";
		}
		return label.replaceAll("(?i) (kills|completions|completion count|opened|completed)$", "");
	}

	private static final java.util.regex.Pattern LEAD_VERB =
		java.util.regex.Pattern.compile("^(?i)(killing|defeating|looting|opening|finishing|completing) (the )?");
	private static final java.util.Set<String> SMALL_WORDS = new java.util.HashSet<>(java.util.Arrays.asList(
		"of", "the", "and", "at", "in", "on", "from", "with", "for", "to", "a", "an", "or", "by"));

	/**
	 * Where a slot comes from, as a short name: "Killing king black dragon" reads "King Black
	 * Dragon", "Opening hard caskets" reads "Hard Caskets". The bracketed detail is left out.
	 */
	public static String source(String name)
	{
		String text = LEAD_VERB.matcher(activity(name)).replaceFirst("");
		StringBuilder out = new StringBuilder();
		for (String word : text.split(" "))
		{
			if (word.isEmpty())
			{
				continue;
			}
			boolean small = out.length() > 0 && SMALL_WORDS.contains(word.toLowerCase(java.util.Locale.ENGLISH));
			out.append(out.length() > 0 ? " " : "")
				.append(small ? word : Character.toUpperCase(word.charAt(0)) + word.substring(1));
		}
		if (out.length() == 0)
		{
			return name;
		}
		String full = out.toString();
		String shortName = SHORT_SOURCES.get(full);
		if (shortName != null)
		{
			return shortName;
		}
		// "Sorting Through Barracuda Salvage" and the barracuda trials are named by what sets them apart.
		return full.replaceFirst("^Sorting Through ", "").replaceFirst(" Barracuda Trials$", " Trials");
	}

	/** Places and activities that name an activity's variant in Log Adviser's names, longest first. */
	private static final String[] PROPER_NAMES = {
		"chambers of xeric challenge mode", "stronghold of security", "guardians of the rift", "hallowed sepulchre",
		"chambers of xeric", "champion's challenge", "corrupted gauntlet", "doom of mokhaiotl", "last man standing",
		"mastering mixology", "creature creation", "fortis colosseum", "temple trekking", "trouble brewing",
		"pyramid plunder", "moons of peril", "royal titans", "pest control", "vale totems", "wintertodt", "prifddinas",
		"zemouregal", "tempoross", "wyrmscraig", "non-zaros"};

	/** Long activity names, as the short name a card has room for. */
	private static final java.util.Map<String, String> SHORT_SOURCES = new java.util.HashMap<>();

	static
	{
		String[][] shorts = {
			{"Spending 100 Numulite at the Fossil Island Notes Chest", "Fossil Island Notes"},
			{"Collecting Unidentified Minerals at the Mining Guild", "Mining Guild Minerals"},
			{"Collecting Gold Nuggets at the Motherlode Mine", "Motherlode Mine"},
			{"Wasting Hours at the Magic Training Arena", "Magic Training Arena"},
			{"Charging Glories at the Fountain of Rune", "Fountain of Rune"},
			{"Earning Mahogany Homes Carpenter Points", "Mahogany Homes"},
			{"Collecting Pearls While Aerial Fishing", "Aerial Fishing"},
			{"Soldiers in the Shayzien Combat Ring", "Shayzien Combat Ring"},
			{"Pickpocketing from Prifddinas Elves", "Prifddinas Elves"},
			{"Mining Stardust from Shooting Stars", "Shooting Stars"},
			{"Earning Volcanic Mine Reward Points", "Volcanic Mine"},
			{"Chests with Shades of Mort'ton Keys", "Shades of Mort'ton"},
			{"Stealing from the Rogues' Den Maze", "Rogues' Den"},
			{"Pickpocketing from Darkmeyer Vyres", "Darkmeyer Vyres"},
			{"In the Wilderness God Wars Dungeon", "Wilderness God Wars"},
			{"Earning Giants' Foundry Reputation", "Giants' Foundry"},
			{"Doing Entling Events for God Eggs", "Entling Events"},
			{"Pulling from the Reward Guardian", "Guardians of the Rift"},
			{"Finding Lumberjack Zombie Events", "Lumberjack Zombies"},
			{"Earning Tithe Farm Reward Points", "Tithe Farm"},
			{"Earning Last Man Standing Points", "Last Man Standing"},
			{"Skeletons in the Ancient Cavern", "Ancient Cavern"},
			{"Cyclopes at the Warriors' Guild", "Warriors' Guild"},
			{"Barronite Deposits in Camdozaal", "Barronite Deposits"},
			{"Tombs of Amascut Reward Chests", "Tombs of Amascut Chests"},
			{"Running Laps of Monkey Agility", "Ape Atoll Agility"},
			{"Barbarian Assault High Gambles", "High Gambles"},
			{"Collecting Anima-infused Bark", "Anima-infused Bark"},
		};
		for (String[] pair : shorts)
		{
			SHORT_SOURCES.put(pair[0], pair[1]);
		}
	}

	private static String titleCase(String text)
	{
		StringBuilder out = new StringBuilder();
		for (String word : text.split(" "))
		{
			boolean small = out.length() > 0 && SMALL_WORDS.contains(word.toLowerCase(java.util.Locale.ENGLISH));
			out.append(out.length() > 0 ? " " : "")
				.append(small || word.isEmpty() ? word : capitalise(word));
		}
		return out.toString();
	}

	/** "zaros" to "Zaros", and each part of a hyphenated name: "non-zaros" to "Non-Zaros". */
	private static String capitalise(String word)
	{
		StringBuilder out = new StringBuilder();
		for (String part : word.split("-", -1))
		{
			out.append(out.length() > 0 ? "-" : "")
				.append(part.isEmpty() ? part : Character.toUpperCase(part.charAt(0)) + part.substring(1));
		}
		return out.toString();
	}

	/** The bracketed detail of an activity name, such as "on task" or "300", or null. */
	public static String detail(String name)
	{
		java.util.regex.Matcher m = java.util.regex.Pattern.compile("\\(([^)]*)\\)").matcher(name);
		if (!m.find())
		{
			return null;
		}
		String detail = m.group(1).trim();
		// Tombs of Amascut rows differ only by raid level.
		detail = detail.matches("[0-9]+") && name.toLowerCase(java.util.Locale.ENGLISH).contains("amascut")
			? "raid level " + detail : detail;
		// Names of places and activities read as names, the way the log's own pages write them.
		String lower = detail.toLowerCase(java.util.Locale.ENGLISH);
		for (String proper : PROPER_NAMES)
		{
			int at = lower.indexOf(proper);
			if (at >= 0)
			{
				detail = detail.substring(0, at) + titleCase(detail.substring(at, at + proper.length()))
					+ detail.substring(at + proper.length());
			}
		}
		// A detail that only repeats the short name says nothing.
		if (detail.equalsIgnoreCase(source(name)))
		{
			return null;
		}
		// A tag under a title starts with a capital, like every other line on the card.
		return detail.isEmpty() ? detail : Character.toUpperCase(detail.charAt(0)) + detail.substring(1);
	}

	/** An activity name for a card title: the parenthetical detail moves to the tooltip. */
	public static String activity(String name)
	{
		String shortName = name.replaceAll("\\s*\\([^)]*\\)", "").replaceAll("\\s+", " ").trim();
		return shortName.isEmpty() ? name : Character.toUpperCase(shortName.charAt(0)) + shortName.substring(1);
	}
}

package com.codex.loginsight.ui;

import java.awt.AlphaComposite;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/** An item picture sitting in a small dark well, used at the start of list rows. */
class IconBadge extends JComponent
{
	private final boolean owned;
	private BufferedImage image;

	IconBadge(int itemId, ItemIcons icons, boolean owned)
	{
		this.owned = owned;
		Dimension d = new Dimension(28, 26);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
		if (icons != null && itemId > 0)
		{
			image = icons.icon(itemId, this::repaint);
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.fill(new Ellipse2D.Float(1, 1, w - 2, h - 2));
		g.setColor(Theme.alpha(owned ? Theme.GOLD : Theme.STROKE, owned ? 120 : 200));
		g.draw(new Ellipse2D.Float(1, 1, w - 2, h - 2));
		if (image != null)
		{
			int iw = Math.min(image.getWidth(), 36);
			int ih = Math.min(image.getHeight(), 32);
			double scale = Math.min((w - 2) / (double) iw, (h - 2) / (double) ih);
			int dw = (int) Math.round(iw * scale);
			int dh = (int) Math.round(ih * scale);
			if (!owned)
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.45f));
			}
			g.drawImage(image, (w - dw) / 2, (h - dh) / 2, dw, dh, null);
		}
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import javax.swing.Timer;

/**
 * Gathers the item pictures a card needs and hands them over once every one has been drawn in, so a saved card never
 * shows an empty plinth. Each picture is asked for once per wait; the instance handed out is the one waited on, since
 * the item manager may hand out a fresh blank for the same item later. A picture that never comes is given up on
 * after a few seconds and the card is made without it. Swing thread only.
 */
final class IconWait
{
	static final int GIVE_UP_MS = 4000;

	private final ItemIcons icons;
	private final Map<Integer, BufferedImage> images = new LinkedHashMap<>();
	private final Consumer<Map<Integer, BufferedImage>> done;
	private Timer giveUp;
	private boolean finished;

	private IconWait(ItemIcons icons, Consumer<Map<Integer, BufferedImage>> done)
	{
		this.icons = icons;
		this.done = done;
	}

	/**
	 * @param done called on the Swing thread exactly once, with each item's picture (or none for one that never came)
	 */
	static IconWait forItems(ItemIcons icons, List<Integer> itemIds, Consumer<Map<Integer, BufferedImage>> done)
	{
		return forItems(icons, itemIds, GIVE_UP_MS, done);
	}

	/** @return the wait, so it can be called off when the plugin stops */
	static IconWait forItems(ItemIcons icons, List<Integer> itemIds, int giveUpMs, Consumer<Map<Integer, BufferedImage>> done)
	{
		IconWait wait = new IconWait(icons, done);
		for (int id : itemIds)
		{
			if (id > 0 && !wait.images.containsKey(id) && icons != null)
			{
				BufferedImage image = icons.icon(id, () -> SwingUtilities.invokeLater(wait::check));
				// No picture at all will never arrive: the card draws that find without one rather than waiting.
				if (image != null)
				{
					wait.images.put(id, image);
				}
			}
		}
		if (!wait.check())
		{
			wait.giveUp = new Timer(giveUpMs, e -> wait.finish());
			wait.giveUp.setRepeats(false);
			wait.giveUp.start();
		}
		return wait;
	}

	/** Calls the wait off: the card is never made, and the give-up timer is stopped. */
	void cancel()
	{
		finished = true;
		if (giveUp != null)
		{
			giveUp.stop();
		}
	}

	/** Finishes once every picture is in; true when it has. */
	private boolean check()
	{
		if (finished)
		{
			return true;
		}
		for (BufferedImage image : images.values())
		{
			if (!icons.ready(image))
			{
				return false;
			}
		}
		finish();
		return true;
	}

	private void finish()
	{
		if (finished)
		{
			return;
		}
		finished = true;
		if (giveUp != null)
		{
			giveUp.stop();
		}
		Map<Integer, BufferedImage> out = new LinkedHashMap<>();
		for (Map.Entry<Integer, BufferedImage> e : images.entrySet())
		{
			if (icons.ready(e.getValue()))
			{
				out.put(e.getKey(), e.getValue());
			}
		}
		done.accept(out);
	}

	/** The item ids a list of finds needs pictures for, in order. */
	static List<Integer> ids(List<com.codex.loginsight.core.Progress.Find> finds)
	{
		List<Integer> out = new ArrayList<>();
		for (com.codex.loginsight.core.Progress.Find f : finds)
		{
			out.add(f.getItemId());
		}
		return out;
	}
}

package com.codex.loginsight.ui;

import java.awt.image.BufferedImage;

/** Where the panel gets item pictures; the plugin answers from RuneLite's item manager. */
public interface ItemIcons
{
	/**
	 * @param onLoaded run once if the picture arrives later than this call
	 * @return the picture, possibly still blank, or null
	 */
	BufferedImage icon(int itemId, Runnable onLoaded);

	/**
	 * True once this picture has been drawn in, so a card made from it shows the item rather than a blank. A source
	 * whose pictures are whole when handed out (as in tests) keeps this default.
	 */
	default boolean ready(BufferedImage image)
	{
		return image != null;
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Report;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * One slot as a small inlaid tile: owned slots sit bright on a gilt rim, missing ones
 * are a faded ghost, with a coloured bead when the wait has run long.
 */
public class ItemTile extends JComponent
{
	public static final int SIZE = 38;

	private final Report.ItemReport item;
	private BufferedImage image;

	public ItemTile(Report.ItemReport item, ItemIcons icons)
	{
		this.item = item;
		Dimension d = new Dimension(SIZE, SIZE - 4);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
		if (icons != null)
		{
			image = icons.icon(item.getItemId(), this::repaint);
		}
		setToolTipText(tooltip(item));
	}

	/** "Half of players by 2,080 kc, 9 in 10 by 6,907": the counts a grind can be measured against. */
	static String marks(double chance)
	{
		int half = com.codex.loginsight.core.DryWatch.countFor(chance, 0.5);
		int most = com.codex.loginsight.core.DryWatch.countFor(chance, 0.9);
		return "Half of players by " + Format.count(half) + " kc, 9 in 10 by " + Format.count(most);
	}

	static String tooltip(Report.ItemReport item)
	{
		StringBuilder sb = new StringBuilder("<html><b>").append(Ui.escape(item.getName())).append("</b>");
		if (item.isOwned())
		{
			sb.append("<br>Owned");
			if (item.getObtained() > 0)
			{
				sb.append(", ").append(Format.count(item.getObtained())).append(" in your log");
			}
			if (item.getExpectedCount() >= 0)
			{
				sb.append("<br>An average player would have ").append(Format.slots(item.getExpectedCount())).append(" by now");
			}
		}
		if (item.getChance() > 0)
		{
			sb.append("<br>").append(Format.chance(item.getChance()));
			if (item.getLabel() != null)
			{
				sb.append(" per ").append(Ui.escape(Format.counterName(item.getLabel()))).append(" kc");
			}
		}
		if (!item.isOwned() && item.getDryChance() >= 0)
		{
			sb.append("<br>").append(Format.dry(item.getDryChance())).append(": ")
				.append(item.getDryChance() == 0 ? "it is guaranteed by your count"
					: Format.have(item.getDryChance()) + " of players would have it by now");
		}
		if (!item.isOwned() && item.getChance() > 0 && item.getLabel() != null)
		{
			sb.append("<br>").append(marks(item.getChance()));
		}
		if (!item.isOwned() && item.getSource() != null)
		{
			sb.append("<br>Fastest: ").append(Ui.escape(item.getSource())).append(" (").append(Format.hours(item.getHours())).append(")");
		}
		return sb.append("</html>").toString();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		boolean owned = item.isOwned();
		g.setPaint(new GradientPaint(0, 0, owned ? Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.18) : Theme.INK_DEEP, 0, h,
			owned ? Theme.CARD : Theme.INK_DEEP));
		g.fill(shape);
		Color rim = owned ? (item.isPet() ? Theme.VIOLET : Theme.alpha(Theme.GOLD, 170)) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		if (image != null)
		{
			int iw = image.getWidth();
			int ih = image.getHeight();
			int x = (w - iw) / 2;
			int y = (h - ih) / 2;
			Composite old = g.getComposite();
			if (!owned)
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.28f));
			}
			g.drawImage(image, x, y, null);
			g.setComposite(old);
		}

		if (!owned && item.getDryChance() >= 0 && item.getDryChance() < 0.35)
		{
			Color bead = Theme.dry(item.getDryChance());
			g.setColor(Theme.INK_DEEP);
			g.fill(new Ellipse2D.Float(w - 10, 2, 8, 8));
			g.setColor(bead);
			g.fill(new Ellipse2D.Float(w - 9, 3, 6, 6));
		}
		if (owned && item.getObtained() > 1)
		{
			// The log's own count, as the game prints it on a stack.
			String count = item.getObtained() > 99_999 ? "99k+" : Format.count(item.getObtained());
			g.setFont(Theme.small());
			java.awt.FontMetrics fm = g.getFontMetrics();
			int tx = w - fm.stringWidth(count) - 3;
			int ty = h - 3;
			g.setColor(Color.BLACK);
			g.drawString(count, tx + 1, ty + 1);
			g.setColor(Theme.GOLD_BRIGHT);
			g.drawString(count, tx, ty);
		}
		if (owned)
		{
			g.setStroke(new BasicStroke(1f));
			g.setColor(Theme.alpha(Color.WHITE, 18));
			g.drawLine(5, 1, w - 5, 1);
		}
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Luck;
import com.codex.loginsight.core.Progress;
import com.codex.loginsight.core.Report;
import com.codex.loginsight.core.Session;
import com.codex.loginsight.core.Setup;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The log at a glance: luck, the numbers, the best hunts, the longest waits and recent finds. */
final class LedgerView
{
	private static final int WIDTH = 190;

	private LedgerView()
	{
	}

	/** The Vs average tile's note before any kill count is read: short enough not to be cut at sidebar width. */
	static final String NO_COUNTS = "no kill counts";

	static StackPanel build(Report report, LuckDial dial, ItemIcons icons, Consumer<String> openPage, Runnable openQuarry, long now)
	{
		return build(report, dial, icons, openPage, openQuarry, now, null);
	}

	/** @param share the finest finds card's save and copy row, shown under the podium, or null for none */
	static StackPanel build(Report report, LuckDial dial, ItemIcons icons, Consumer<String> openPage, Runnable openQuarry, long now,
		javax.swing.JComponent share)
	{
		StackPanel stack = new StackPanel(6, 8);
		if (!report.isLoggedIn())
		{
			stack.add(welcome());
			return stack;
		}

		Setup setup = report.setup();
		if (!setup.isDone())
		{
			stack.add(setupCard(setup, openPage));
		}

		Card dialCard = new Card(new BorderLayout());
		dialCard.setBorder(new EmptyBorder(8, 8, 8, 8));
		dial.setLuck(report.getLuck(), true);
		dialCard.add(dial, BorderLayout.CENTER);
		Luck luck = report.getLuck();
		if (luck != null)
		{
			dialCard.setToolTipText("<html>Across " + luck.getSlots() + " slots with known odds and kill counts.<br>"
				+ "An average player would own " + Math.round(luck.getExpected()) + " of them; you own " + luck.getOwned() + ".</html>");
		}
		stack.add(dialCard);

		// The crest already carries slots, pages and hours; the tiles add what it cannot say.
		List<Report.Hunt> hunts = new java.util.ArrayList<>();
		for (Report.Hunt hunt : report.getHunts())
		{
			if (hunt.getLockedBy() == null && hunts.size() < 3)
			{
				hunts.add(hunt);
			}
		}
		JPanel tiles = new JPanel(new GridLayout(2, 2, 6, 6));
		tiles.setOpaque(false);
		if (luck != null)
		{
			long diff = Math.round(luck.getOwned() - luck.getExpected());
			tiles.add(new StatTile((diff > 0 ? "+" : "") + diff, "Vs average", "at your counts",
				diff >= 0 ? Theme.GREEN : Theme.EMBER));
		}
		else
		{
			tiles.add(new StatTile("-", "Vs average", report.ownedRead() ? NO_COUNTS : "after a log read", Theme.TEXT_MUTED));
		}
		if (!report.ownedRead())
		{
			tiles.add(new StatTile("-", "Next slot", "after a log read", Theme.TEXT_MUTED));
		}
		else if (hunts.isEmpty())
		{
			tiles.add(new StatTile("-", "Next slot", "nothing rated", Theme.TEXT_MUTED));
		}
		else
		{
			tiles.add(new StatTile(Format.hours(hunts.get(0).getHoursToNext()), "Next slot",
				Format.source(hunts.get(0).getName()), Theme.TEAL));
		}
		int pets = 0;
		int petsOwned = 0;
		java.util.Set<Integer> seen = new java.util.HashSet<>();
		for (Report.PageReport page : report.getPages())
		{
			for (Report.ItemReport item : page.getItems())
			{
				if (item.isPet() && seen.add(item.getItemId()))
				{
					pets++;
					petsOwned += item.isOwned() ? 1 : 0;
				}
			}
		}
		if (report.ownedRead())
		{
			tiles.add(new StatTile(petsOwned + "/" + pets, "Pets", pets == petsOwned ? "every one" : (pets - petsOwned) + " to go",
				Theme.VIOLET));
		}
		else
		{
			tiles.add(new StatTile("-", "Pets", "after a log read", Theme.TEXT_MUTED));
		}
		tiles.add(new StatTile(report.getPagesRead() + "/" + report.getPagesTotal(), "Pages read",
			report.getPagesRead() < report.getPagesTotal() ? "open for luck" : "all kill counts", Theme.GOLD));
		stack.add(tiles);
		if (report.getDrops() != null)
		{
			stack.add(PageView.drops(report.getDrops(), Format.count(report.getDrops().getSlots()) + (report.getDrops().getSlots() == 1 ? " slot" : " slots")));
		}

		// The finest drops on a podium: the card worth a screenshot.
		if (!report.getTrophies().isEmpty())
		{
			stack.add(new SectionHeader("Finest finds", "rarest seen"));
			stack.add(new TrophyShelf(report.getTrophies(), icons));
			if (share != null)
			{
				stack.add(share);
			}
		}

		if (!report.getWanted().isEmpty())
		{
			stack.add(new SectionHeader("Wanted", report.getWanted().size() + " of " + Progress.MAX_WANTED));
			for (Report.ItemReport item : report.getWanted())
			{
				Card card = wantedCard(item, icons);
				if (item.getPage() != null)
				{
					card.onClick(() -> openPage.accept(item.getPage()));
				}
				stack.add(card);
			}
		}

		Session.Summary session = report.getSession();
		if (session != null)
		{
			stack.add(new SectionHeader("This session", Format.duration(session.getMillis())));
			stack.add(sessionCard(session));
		}

		if (!hunts.isEmpty() && report.ownedRead())
		{
			stack.add(new SectionHeader("Best next hunts", "all in Quarry"));
			for (int i = 0; i < hunts.size(); i++)
			{
				stack.add(QuarryView.row(hunts.get(i), i + 1, icons).onClick(openQuarry));
			}
		}

		if (!report.getDriest().isEmpty() && report.ownedRead())
		{
			stack.add(new SectionHeader("Longest waits"));
			for (Report.ItemReport item : report.getDriest())
			{
				Card card = PageView.missingRow(item, icons, true);
				if (item.getPage() != null)
				{
					card.onClick(() -> openPage.accept(item.getPage()));
				}
				stack.add(card);
			}
		}

		List<Progress.Find> finds = report.getFinds();
		stack.add(new SectionHeader("Recent finds"));
		if (finds.isEmpty())
		{
			stack.add(Rows.note("New slots will be written here as they drop, with how lucky each one was.", WIDTH));
		}
		else
		{
			for (int i = 0; i < Math.min(6, finds.size()); i++)
			{
				stack.add(findRow(finds.get(i), icons, now));
			}
		}
		return stack;
	}

	/** Logged out: what the Ledger opens on, so the page promises something rather than sitting blank. */
	private static Card welcome()
	{
		Card card = new Card(new BorderLayout()).highlighted(true);
		card.setBorder(new EmptyBorder(10, 12, 12, 12));
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new javax.swing.BoxLayout(text, javax.swing.BoxLayout.Y_AXIS));
		JComponent head = Ui.label("YOUR LOG, READ", Theme.small(), Theme.GOLD);
		head.setAlignmentX(0f);
		text.add(head);
		JComponent body = Ui.wrapped("Log in and Log Insight reads your collection log: how lucky you have been, the slots "
			+ "quickest to get next, and your finest finds on a podium.", Theme.body(), Theme.TEXT, WIDTH - 12);
		body.setAlignmentX(0f);
		text.add(body);
		JComponent note = Ui.wrapped("It only reads what your client shows. Nothing leaves your computer.", Theme.small(),
			Theme.TEXT_MUTED, WIDTH - 12);
		note.setBorder(new EmptyBorder(6, 0, 0, 0));
		note.setAlignmentX(0f);
		text.add(note);
		card.add(text, BorderLayout.CENTER);
		return card;
	}

	/** Kill counts added since logging in, the slots they gave, and how that compares with an average player. */
	static Card sessionCard(Session.Summary session)
	{
		Card card = new Card(new BorderLayout(0, 6));
		card.setBorder(new EmptyBorder(7, 10, 8, 10));
		if (session.isEmpty())
		{
			card.add(Ui.wrapped("Kill counts you add from now on show here, with the slots they give and how lucky "
				+ "that was.", Theme.small(), Theme.TEXT_MUTED, 170), BorderLayout.CENTER);
			return card;
		}
		StackPanel rows = new StackPanel(3, 0);
		List<Session.Gain> gains = session.getGains();
		for (int i = 0; i < Math.min(3, gains.size()); i++)
		{
			Session.Gain gain = gains.get(i);
			rows.add(pair(Format.counterName(gain.getLabel()), "+" + Format.count(gain.getAdded()), Theme.TEXT, Theme.GOLD));
		}
		if (gains.size() > 3)
		{
			int rest = 0;
			for (int i = 3; i < gains.size(); i++)
			{
				rest += gains.get(i).getAdded();
			}
			rows.add(pair((gains.size() - 3) + " more", "+" + Format.count(rest), Theme.TEXT_MUTED, Theme.TEXT_MUTED));
		}
		Luck luck = session.getLuck();
		int found = session.getFinds().size();
		String expected = luck == null ? "" : "  ·  avg " + Format.slots(luck.getExpected());
		rows.add(pair("New slots", found + expected, Theme.TEXT, found > 0 ? Theme.GREEN : Theme.TEXT_MUTED));
		card.add(rows, BorderLayout.CENTER);
		if (luck != null)
		{
			Color color = Theme.luck(luck.getPercentile());
			card.add(Ui.label(luck.verdict().getLabel() + "  ·  luckier than " + luck.luckierThan() + "%", Theme.small(), color),
				BorderLayout.SOUTH);
			card.accent(color);
			card.setToolTipText("<html>Across the " + luck.getSlots() + " slots tonight's kills could have given.<br>"
				+ "An average player would have found " + String.format(java.util.Locale.ENGLISH, "%.2f", luck.getExpected())
				+ " of them; you found " + luck.getOwned() + ".</html>");
		}
		return card;
	}

	/**
	 * A slot you are after: how dry you are on it, the counts by which half and nine in ten of players have it, and
	 * the play after which the odds of it are even.
	 */
	static Card wantedCard(Report.ItemReport item, ItemIcons icons)
	{
		StringBuilder odds = new StringBuilder(Format.chance(item.getChance()));
		if (item.getCount() >= 0)
		{
			odds.append(" at ").append(Format.count(item.getCount())).append(" kc");
		}
		Pill dry = item.getDryChance() >= 0 ? new Pill(Format.dry(item.getDryChance()), Theme.dry(item.getDryChance())) : null;
		Card card = Rows.line(new IconBadge(item.getItemId(), icons, false), item.getName(), odds.toString(), dry, Theme.GOLD);
		card.highlighted(true);
		JPanel more = new JPanel();
		more.setOpaque(false);
		more.setLayout(new javax.swing.BoxLayout(more, javax.swing.BoxLayout.Y_AXIS));
		more.setBorder(new EmptyBorder(5, 0, 0, 0));
		if (item.getDryChance() >= 0)
		{
			more.add(new DryBar(item.getDryChance()));
			more.add(javax.swing.Box.createVerticalStrut(3));
		}
		String marks = marks(item);
		if (marks != null)
		{
			more.add(left(Ui.label(marks, Theme.small(), Theme.TEXT_MUTED)));
		}
		double even = com.codex.loginsight.core.Wanted.evenChanceHours(item);
		if (even > 0 && item.getSource() != null)
		{
			// The even-chance mark and the average are both said, so this card and the page's "~98h on its own" agree.
			JLabel when = Ui.label("Even odds in " + Format.hours(even) + "  ·  " + Format.about(item.getHours()) + " average",
				Theme.small(), Theme.TEAL);
			when.setToolTipText("Hunting it at " + Format.source(item.getSource()) + ": half of players have it within "
				+ Format.hours(even) + "; the average wait is " + Format.hours(item.getHours()) + ".");
			more.add(left(when));
		}
		else if (item.getSource() == null)
		{
			more.add(left(Ui.label("No timed source yet", Theme.small(), Theme.TEXT_FAINT)));
		}
		// The text column already lays out name and odds; the rest runs the card's full width beneath.
		card.add(more, BorderLayout.SOUTH);
		card.setToolTipText(ItemTile.tooltip(item));
		return card;
	}

	/** "Half by 2,079 · 1,667 to go" until you pass half, then the nine-in-ten mark; null without odds. */
	static String marks(Report.ItemReport item)
	{
		int half = com.codex.loginsight.core.Wanted.countFor(item, 0.5);
		int most = com.codex.loginsight.core.Wanted.countFor(item, 0.9);
		if (half < 0 || item.getCount() < 0)
		{
			return half < 0 ? null : "Half of players by " + Format.count(half) + " kc";
		}
		if (item.getCount() < half)
		{
			return "Half by " + Format.count(half) + "  ·  " + Format.count(half - item.getCount()) + " to go";
		}
		if (item.getCount() < most)
		{
			return "9 in 10 by " + Format.count(most) + "  ·  " + Format.count(most - item.getCount()) + " to go";
		}
		return "Past 9 in 10 at " + Format.count(most) + " kc";
	}

	private static JComponent left(JComponent c)
	{
		c.setAlignmentX(0f);
		return c;
	}

	private static JPanel pair(String left, String right, Color leftColor, Color rightColor)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		javax.swing.JLabel name = Ui.label(left, Theme.small(), leftColor);
		name.setMinimumSize(new java.awt.Dimension(10, name.getPreferredSize().height));
		name.setPreferredSize(new java.awt.Dimension(10, name.getPreferredSize().height));
		row.add(name, BorderLayout.CENTER);
		row.add(Ui.label(right, Theme.small(), rightColor), BorderLayout.EAST);
		return row;
	}

	/**
	 * The three things that make the numbers trustworthy, each ticked off as it is done: the whole log read, the
	 * game announcing new slots, and kill counts on the pages you have finds on. Gone once all three are done.
	 */
	static Card setupCard(Setup setup, Consumer<String> openPage)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD).highlighted(true);
		card.setBorder(new EmptyBorder(7, 10, 8, 10));
		card.add(Ui.label("Getting your log ready", Theme.body(), Theme.GOLD_BRIGHT), BorderLayout.NORTH);
		StackPanel steps = new StackPanel(5, 0);
		steps.add(step(setup.isLogRead() ? Mark.Kind.GOOD : Mark.Kind.WARN, "Whole log read",
			setup.isLogRead() ? null : "Open your collection log and press its Search button once."));
		if (setup.noticesKnown())
		{
			steps.add(step(setup.noticesOff() ? Mark.Kind.BAD : Mark.Kind.GOOD, "New slots announced",
				setup.noticesOff() ? "The game announces none, so finds go unseen. Turn on the collection log's new"
					+ " addition notification (chat or pop-up) in the game's settings." : null));
		}
		boolean counted = setup.getToOpenTotal() == 0;
		// On a first day nothing is owned, so nothing is missing a count, but "0 of 73" beside a tick reads as a
		// mistake: it says how the counts arrive instead.
		boolean firstDay = counted && setup.getPagesCounted() == 0 && setup.getPagesCountable() > 0;
		steps.add(step(firstDay ? Mark.Kind.NOTE : counted ? Mark.Kind.GOOD : Mark.Kind.NOTE, "Kill counts on "
			+ setup.getPagesCounted() + " of " + setup.getPagesCountable() + " pages", firstDay
			? "Each page's count is read when you open it." : counted ? null : "Open these once to count your finds there:"));
		for (Report.PageReport page : setup.getToOpen())
		{
			// The name gives way before the count does: "Fishing from the Reward Pool" is wider than the card.
			JPanel link = new JPanel(new BorderLayout(6, 0));
			link.setOpaque(false);
			JComponent name = Ui.label(page.getName(), Theme.small(), Theme.GOLD);
			name.setMinimumSize(new java.awt.Dimension(10, name.getPreferredSize().height));
			link.add(name, BorderLayout.CENTER);
			link.add(Ui.label(page.getOwned() + (page.getOwned() == 1 ? " slot" : " slots"), Theme.small(), Theme.TEXT_MUTED),
				BorderLayout.EAST);
			link.setToolTipText("Open " + page.getName());
			link.setBorder(new EmptyBorder(0, 18, 0, 0));
			link.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
			link.addMouseListener(new java.awt.event.MouseAdapter()
			{
				@Override
				public void mouseReleased(java.awt.event.MouseEvent e)
				{
					openPage.accept(page.getName());
				}
			});
			steps.add(link);
		}
		int more = setup.getToOpenTotal() - setup.getToOpen().size();
		if (more > 0)
		{
			JComponent rest = Ui.label("and " + more + " more", Theme.small(), Theme.TEXT_FAINT);
			rest.setBorder(new EmptyBorder(0, 18, 0, 0));
			steps.add(rest);
		}
		card.add(steps, BorderLayout.CENTER);
		return card;
	}

	/** One setup step: its mark, what it is, and what to do while it is not done. */
	private static JComponent step(Mark.Kind kind, String title, String todo)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		JPanel markHolder = new JPanel(new BorderLayout());
		markHolder.setOpaque(false);
		markHolder.add(new Mark(kind, 12), BorderLayout.NORTH);
		row.add(markHolder, BorderLayout.WEST);
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new javax.swing.BoxLayout(text, javax.swing.BoxLayout.Y_AXIS));
		JComponent head = Ui.label(title, Theme.small(), kind == Mark.Kind.GOOD ? Theme.TEXT_MUTED : Theme.TEXT);
		head.setAlignmentX(0f);
		text.add(head);
		if (todo != null)
		{
			JComponent body = Ui.wrapped(todo, Theme.small(), Theme.TEXT_MUTED, 152);
			body.setAlignmentX(0f);
			text.add(body);
		}
		row.add(text, BorderLayout.CENTER);
		return row;
	}

	/** A find: what, the odds and count it came at, then how lucky it was and when. */
	private static JComponent findRow(Progress.Find find, ItemIcons icons, long now)
	{
		StringBuilder detail = new StringBuilder();
		if (find.getChance() > 0)
		{
			detail.append(Format.chance(find.getChance()));
		}
		if (find.getCount() > 0)
		{
			detail.append(detail.length() > 0 ? " at " : "").append(Format.count(find.getCount())).append(" kc");
		}
		if (detail.length() == 0 && find.getPage() != null)
		{
			detail.append(find.getPage());
		}
		String when = Format.ago(find.getAt(), now);
		boolean known = find.getLuckier() >= 0;
		String verdict = known ? "Luckier than " + Math.round(find.getLuckier() * 100) + "%  ·  " + when : when;
		Color color = known ? Theme.luck(find.getLuckier()) : Theme.GOLD;
		return Rows.line(new IconBadge(find.getItemId(), icons, true), find.getName(), detail.toString(), verdict,
			known ? color : Theme.TEXT_FAINT, null, color);
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Graphics;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Log Insight side panel: the crest, then three pages. Ledger is the log at a
 * glance, Folios is the log page by page, and Quarry ranks where the next slots are.
 */
public class LogInsightPanel extends PluginPanel
{
	private static final String[] TABS = {"ledger", "folios", "quarry", "plan"};

	private final ItemIcons icons;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Ledger", "Folios", "Quarry", "Plan");
	private final Segmented quarryFilter = new Segmented(false, QuarryView.FILTERS);
	private final Segmented horizon = new Segmented(false, PlanView.HORIZONS);
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane ledger = scroller();
	private final JScrollPane folios = scroller();
	private final JScrollPane quarry = scroller();
	private final JScrollPane plan = scroller();
	private final JPanel folioHolder = new JPanel(new BorderLayout());
	private final JPanel searchHolder = new JPanel(new BorderLayout());
	private final LuckDial dial = new LuckDial(112);

	/** Tabs whose view was built from an older report and is rebuilt when next shown. */
	private final boolean[] stale = new boolean[TABS.length];
	private int shown;
	private Report report = Report.loggedOut();
	private String playerName;
	private String filter = "";
	private String openPage;
	/** Marks a slot wanted or not; set by the plugin. */
	private java.util.function.IntConsumer onWant;
	private ShareActions share;
	private java.util.function.BooleanSupplier nameOnCards = () -> true;
	private String shareNote;
	/** True while a card waits for its pictures, so a second click does not start a second wait. */
	private boolean sharing;
	/** The card waiting for its pictures, called off if the plugin stops first. */
	private IconWait pending;
	/** True while the panel is open in the sidebar; a closed panel only marks its tabs stale. */
	private boolean active;

	public LogInsightPanel(ItemIcons icons)
	{
		super(false);
		this.icons = icons;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		searchHolder.setOpaque(false);
		searchHolder.setBorder(new EmptyBorder(6, 8, 0, 8));
		searchHolder.add(new SearchField(text ->
		{
			filter = text;
			rebuildFolios();
		}), BorderLayout.CENTER);
		folioHolder.setOpaque(false);
		folioHolder.add(searchHolder, BorderLayout.NORTH);
		folioHolder.add(folios, BorderLayout.CENTER);

		JPanel quarryHolder = new JPanel(new BorderLayout());
		quarryHolder.setOpaque(false);
		JPanel filterHolder = new JPanel(new BorderLayout());
		filterHolder.setOpaque(false);
		filterHolder.setBorder(new EmptyBorder(6, 8, 0, 8));
		filterHolder.add(quarryFilter, BorderLayout.CENTER);
		quarryHolder.add(filterHolder, BorderLayout.NORTH);
		quarryHolder.add(quarry, BorderLayout.CENTER);

		JPanel planHolder = new JPanel(new BorderLayout());
		planHolder.setOpaque(false);
		JPanel horizonHolder = new JPanel(new BorderLayout());
		horizonHolder.setOpaque(false);
		horizonHolder.setBorder(new EmptyBorder(6, 8, 0, 8));
		horizonHolder.add(horizon, BorderLayout.CENTER);
		planHolder.add(horizonHolder, BorderLayout.NORTH);
		planHolder.add(plan, BorderLayout.CENTER);
		horizon.setSelected(1, false);

		content.setOpaque(false);
		content.add(ledger, TABS[0]);
		content.add(folioHolder, TABS[1]);
		content.add(quarryHolder, TABS[2]);
		content.add(planHolder, TABS[3]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		quarryFilter.onChange(i -> rebuildQuarry());
		horizon.onChange(i -> rebuildPlan());
		for (int tab = 0; tab < TABS.length; tab++)
		{
			rebuildTab(tab);
		}
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		Scrollbars.style(scroll.getVerticalScrollBar());
		return scroll;
	}

	/** Lets missing slots on a page be clicked onto the wanted list; {@code onWant} runs on the Swing thread. */
	public void setOnWant(java.util.function.IntConsumer onWant)
	{
		this.onWant = onWant;
	}

	/** Lets the Ledger save and copy the finest finds card; names go on it while the option is on. */
	public void setShare(ShareActions share, java.util.function.BooleanSupplier nameOnCards)
	{
		this.share = share;
		this.nameOnCards = nameOnCards == null ? () -> true : nameOnCards;
		ledgerChanged();
	}

	/**
	 * The plugin is stopping: a card still waiting for its pictures is called off, so it is never saved or copied
	 * after the plugin is gone. Swing thread only.
	 */
	public void shutDown()
	{
		if (pending != null)
		{
			pending.cancel();
			pending = null;
		}
		sharing = false;
		share = null;
	}

	/** Shows what became of a save or copy under the podium. Swing thread only. */
	public void shareNote(String note)
	{
		shareNote = note;
		ledgerChanged();
	}

	private void ledgerChanged()
	{
		stale[0] = true;
		if ((active || isShowing()) && shown == 0)
		{
			rebuildTab(0);
		}
	}

	/** Save and copy under the podium, with what became of the last one; null without sharing or finds. */
	private JComponent shareRow()
	{
		if (share == null || report.getTrophies().isEmpty())
		{
			return null;
		}
		JPanel row = new JPanel(new BorderLayout(0, 4));
		row.setOpaque(false);
		JPanel buttons = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.RIGHT, 0, 0));
		buttons.setOpaque(false);
		buttons.add(new CodexButton("Save finds card", false, () -> shareFinds(true)));
		buttons.add(javax.swing.Box.createHorizontalStrut(6));
		buttons.add(new CodexButton("Copy", false, () -> shareFinds(false)));
		row.add(buttons, BorderLayout.NORTH);
		if (shareNote != null)
		{
			row.add(Ui.wrapped(shareNote, Theme.small(), Theme.TEAL, 200), BorderLayout.CENTER);
		}
		return row;
	}

	private void shareFinds(boolean save)
	{
		if (sharing || share == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		java.time.ZoneId zone = java.time.ZoneId.systemDefault();
		String name = nameOnCards.getAsBoolean() && report.isLoggedIn() ? playerName : null;
		FindsShare.Spec spec = FindsShare.Spec.of(report.getTrophies(), name, report.owned(), report.total(), now, zone);
		if (spec == null)
		{
			return;
		}
		// The card waits for every picture, so it never shows an empty plinth.
		sharing = true;
		pending = FindsShare.whenReady(spec, icons, card ->
		{
			sharing = false;
			pending = null;
			ShareActions to = share;
			if (to == null)
			{
				return;
			}
			if (save)
			{
				to.save(card, FindsShare.fileName(now, zone));
			}
			else
			{
				to.copy(card);
			}
		});
	}

	/** Called on the Swing thread with each new report. */
	public void update(Report report, String playerName)
	{
		this.report = report;
		this.playerName = playerName;
		rebuild();
	}

	/** Opens the Folios tab at one page, for example the page a new slot landed on. */
	public void showPage(String page)
	{
		openPage = page;
		tabs.setSelected(1, false);
		shown = 1;
		cards.show(content, TABS[1]);
		rebuildFolios();
		SwingUtilities.invokeLater(() -> folios.getVerticalScrollBar().setValue(0));
	}

	/** Switches to a tab, rebuilding it first if a newer report arrived while it was hidden. */
	public void showTab(int tab)
	{
		tabs.setSelected(tab, false);
		shown = tab;
		if (stale[tab])
		{
			rebuildTab(tab);
		}
		cards.show(content, TABS[tab]);
	}

	/**
	 * Only the tab in view is rebuilt for each report, and only while the panel is open; the others, or all of them
	 * while it is closed, wait until they are seen. Reports come with every kill count, so a closed panel would
	 * otherwise rebuild a page nobody looks at after each kill.
	 */
	private void rebuild()
	{
		crest.update(report, playerName);
		java.util.Arrays.fill(stale, true);
		if (active || isShowing())
		{
			rebuildTab(shown);
		}
	}

	@Override
	public void onActivate()
	{
		active = true;
		if (stale[shown])
		{
			rebuildTab(shown);
		}
	}

	@Override
	public void onDeactivate()
	{
		active = false;
	}

	/** True when a tab was built from an older report and waits to be rebuilt. */
	boolean isStale(int tab)
	{
		return stale[tab];
	}

	private void rebuildTab(int tab)
	{
		stale[tab] = false;
		if (tab == 0)
		{
			replace(ledger, LedgerView.build(report, dial, icons, this::showPage, () -> showTab(2),
				System.currentTimeMillis(), shareRow()));
		}
		else if (tab == 1)
		{
			rebuildFolios();
		}
		else if (tab == 2)
		{
			rebuildQuarry();
		}
		else
		{
			rebuildPlan();
		}
	}

	private void rebuildPlan()
	{
		replace(plan, PlanView.build(report, horizon.getSelected(), icons, this::showPage));
	}

	private void rebuildFolios()
	{
		Report.PageReport page = null;
		if (openPage != null)
		{
			for (Report.PageReport p : report.getPages())
			{
				if (p.getName().equals(openPage))
				{
					page = p;
					break;
				}
			}
		}
		searchHolder.setVisible(page == null);
		if (page != null)
		{
			replace(folios, PageView.build(page, icons, () ->
			{
				openPage = null;
				rebuildFolios();
			}, report::isWanted, onWant, report.getWanted().size() >= com.codex.loginsight.core.Progress.MAX_WANTED));
		}
		else
		{
			openPage = null;
			replace(folios, FoliosView.build(report, filter, name ->
			{
				openPage = name;
				rebuildFolios();
				SwingUtilities.invokeLater(() -> folios.getVerticalScrollBar().setValue(0));
			}));
		}
		folioHolder.revalidate();
	}

	private void rebuildQuarry()
	{
		replace(quarry, QuarryView.build(report, quarryFilter.getSelected(), icons));
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Luck;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/**
 * A half-moon gauge from parched to blessed with a gilt needle at where the account
 * stands, and the verdict written underneath.
 */
public class LuckDial extends JComponent
{
	private static final String[] ENDS = {"PARCHED", "BLESSED"};

	private final Animator needle = new Animator(this);
	private final int height;
	private Luck luck;

	public LuckDial(int height)
	{
		this.height = height;
		setPreferredSize(new Dimension(10, height));
		setMinimumSize(new Dimension(10, height));
		setOpaque(false);
		needle.set(0.5, false);
	}

	public void setLuck(Luck luck, boolean animate)
	{
		this.luck = luck;
		needle.set(luck == null ? 0.5 : luck.getPercentile(), animate);
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();

		// Below the hub sit the end labels' gap, the verdict and the percentile line.
		int textBlock = small.getHeight() + 4 + bold.getHeight() + small.getHeight() + 2;
		float thickness = 9;
		float radius = Math.max(20, Math.min(w / 2f - 14, getHeight() - textBlock - thickness / 2 - 4));
		float cx = w / 2f;
		float cy = thickness / 2 + 4 + radius;
		Arc2D.Float box = new Arc2D.Float(cx - radius, cy - radius, radius * 2, radius * 2, 180, -180, Arc2D.OPEN);

		// The track, in short segments so the colour can travel from blood to green.
		g.setStroke(new BasicStroke(thickness + 4, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.INK_DEEP);
		g.draw(box);
		int segments = 60;
		boolean known = luck != null;
		g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
		for (int i = 0; i < segments; i++)
		{
			double t = (i + 0.5) / segments;
			Color c = Theme.luck(t);
			g.setColor(known ? Theme.alpha(c, 215) : Theme.alpha(Theme.STROKE, 200));
			g.draw(new Arc2D.Double(cx - radius, cy - radius, radius * 2, radius * 2, 180 - i * 180.0 / segments, -180.0 / segments - 0.4, Arc2D.OPEN));
		}
		// Tick marks at the verdict borders.
		g.setStroke(new BasicStroke(1.2f));
		for (double edge : new double[]{0.15, 0.35, 0.65, 0.85})
		{
			double a = Math.PI * (1 - edge);
			float inner = radius - thickness / 2 - 2;
			float outer = radius + thickness / 2 + 2;
			g.setColor(Theme.alpha(Theme.INK_DEEP, 220));
			g.drawLine(Math.round(cx + (float) Math.cos(a) * inner), Math.round(cy - (float) Math.sin(a) * inner),
				Math.round(cx + (float) Math.cos(a) * outer), Math.round(cy - (float) Math.sin(a) * outer));
		}
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 120));
		g.setStroke(new BasicStroke(1f));
		g.draw(new Arc2D.Float(cx - radius - thickness / 2 - 3, cy - radius - thickness / 2 - 3, (radius + thickness / 2 + 3) * 2,
			(radius + thickness / 2 + 3) * 2, 180, -180, Arc2D.OPEN));

		if (known)
		{
			double value = needle.get();
			double a = Math.PI * (1 - value);
			float len = radius - thickness / 2 - 4;
			float tipX = cx + (float) Math.cos(a) * len;
			float tipY = cy - (float) Math.sin(a) * len;
			float baseW = 3.2f;
			Path2D hand = new Path2D.Float();
			hand.moveTo(tipX, tipY);
			hand.lineTo(cx + (float) Math.cos(a + Math.PI / 2) * baseW, cy - (float) Math.sin(a + Math.PI / 2) * baseW);
			hand.lineTo(cx + (float) Math.cos(a - Math.PI / 2) * baseW, cy - (float) Math.sin(a - Math.PI / 2) * baseW);
			hand.closePath();
			g.setColor(Theme.alpha(java.awt.Color.BLACK, 120));
			g.translate(1, 1);
			g.fill(hand);
			g.translate(-1, -1);
			g.setColor(Theme.GOLD_BRIGHT);
			g.fill(hand);
			g.setColor(Theme.luck(value));
			g.fill(new Ellipse2D.Float(tipX - 2.5f, tipY - 2.5f, 5, 5));
		}
		g.setColor(Theme.GOLD);
		g.fill(new Ellipse2D.Float(cx - 5, cy - 5, 10, 10));
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(cx - 2, cy - 2, 4, 4));

		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(ENDS[0], Math.max(0, cx - radius - small.stringWidth(ENDS[0]) / 2f), cy + small.getAscent() + 2);
		g.drawString(ENDS[1], Math.min(w - small.stringWidth(ENDS[1]), cx + radius - small.stringWidth(ENDS[1]) / 2f), cy + small.getAscent() + 2);

		int y = Math.round(cy + small.getHeight() + 4);
		String verdict = known ? luck.verdict().getLabel() : "Not read yet";
		String line = known ? luckLine(luck.luckierThan()) : NOT_READ_LINE;
		g.setFont(Theme.title());
		ProgressRing.drawShadowed(g, verdict, Math.round(cx - bold.stringWidth(verdict) / 2f), y + bold.getAscent(),
			known ? Theme.luck(luck.verdict()) : Theme.TEXT_MUTED);
		g.setFont(Theme.small());
		ProgressRing.drawShadowed(g, line, Math.round(cx - small.stringWidth(line) / 2f), y + bold.getHeight() + small.getAscent(), Theme.TEXT_MUTED);
		g.dispose();
	}

	/** Under "Not read yet": short enough to sit inside the dial's card at sidebar width. */
	static final String NOT_READ_LINE = "Open log pages to read your luck";

	/**
	 * "Luckier than 68% of players", or for the unlucky half "Drier than 90% of players": never "luckier than 0%",
	 * which reads as a mistake. The figure stays between 1 and 99, since no read is ever certain.
	 */
	static String luckLine(int luckierThan)
	{
		if (luckierThan >= 50)
		{
			return "Luckier than " + Math.min(99, luckierThan) + "% of players";
		}
		return "Drier than " + Math.min(99, Math.max(1, 100 - luckierThan)) + "% of players";
	}
}

package com.codex.loginsight.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A drawn verdict: a sealed check, a warning, a cross, a quiet note, or an empty dashed ring. */
public class Mark extends JComponent
{
	public enum Kind
	{
		GOOD,
		NOTE,
		WARN,
		BAD,
		NONE
	}

	private final Kind kind;
	private final int size;

	public Mark(Kind kind, int size)
	{
		this.kind = kind;
		this.size = size;
		Dimension d = new Dimension(size, size);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
	}

	public static Color color(Kind kind)
	{
		switch (kind)
		{
			case GOOD:
				return Theme.GREEN;
			case WARN:
				return Theme.EMBER;
			case BAD:
				return Theme.BLOOD;
			case NOTE:
				return Theme.GOLD;
			default:
				return Theme.TEXT_FAINT;
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, kind, 0, 0, size);
		g.dispose();
	}

	/** Draws a mark anywhere, so the overlay can use the same shapes as the panel. */
	public static void paint(Graphics2D g, Kind kind, float x, float y, int size)
	{
		float s = size - 2;
		float o = 1;
		Color c = color(kind);
		Ellipse2D circle = new Ellipse2D.Float(x + o, y + o, s, s);
		g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		switch (kind)
		{
			case GOOD:
			{
				g.setColor(Theme.alpha(c, 60));
				g.fill(circle);
				g.setColor(c);
				g.draw(circle);
				Path2D check = new Path2D.Float();
				check.moveTo(x + o + s * 0.28, y + o + s * 0.52);
				check.lineTo(x + o + s * 0.44, y + o + s * 0.68);
				check.lineTo(x + o + s * 0.74, y + o + s * 0.34);
				g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.draw(check);
				break;
			}
			case WARN:
			{
				Path2D tri = new Path2D.Float();
				tri.moveTo(x + o + s / 2, y + o + s * 0.04);
				tri.lineTo(x + o + s, y + o + s * 0.94);
				tri.lineTo(x + o, y + o + s * 0.94);
				tri.closePath();
				g.setColor(Theme.alpha(c, 60));
				g.fill(tri);
				g.setColor(c);
				g.draw(tri);
				g.setStroke(new BasicStroke(1.7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.drawLine(Math.round(x + o + s / 2), Math.round(y + o + s * 0.36f), Math.round(x + o + s / 2), Math.round(y + o + s * 0.6f));
				g.fill(new Ellipse2D.Float(x + o + s / 2 - 1.1f, y + o + s * 0.72f, 2.2f, 2.2f));
				break;
			}
			case BAD:
			{
				g.setColor(Theme.alpha(c, 70));
				g.fill(circle);
				g.setColor(c);
				g.draw(circle);
				float a = s * 0.32f;
				float m = s / 2 + o;
				g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.drawLine(Math.round(x + m - a), Math.round(y + m - a), Math.round(x + m + a), Math.round(y + m + a));
				g.drawLine(Math.round(x + m + a), Math.round(y + m - a), Math.round(x + m - a), Math.round(y + m + a));
				break;
			}
			case NOTE:
			{
				g.setColor(Theme.alpha(c, 40));
				g.fill(circle);
				g.setColor(Theme.alpha(c, 170));
				g.draw(circle);
				float dot = s * 0.34f;
				g.setColor(c);
				g.fill(new Ellipse2D.Float(x + o + (s - dot) / 2, y + o + (s - dot) / 2, dot, dot));
				break;
			}
			default:
			{
				g.setColor(c);
				g.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1, new float[]{2f, 2f}, 0));
				g.draw(circle);
			}
		}
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Drops;
import com.codex.loginsight.core.Projection;
import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.IntConsumer;
import java.util.function.IntPredicate;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** One page in depth: its counts and luck, the wait for the next slot, and every slot with its odds. */
final class PageView
{
	private static final int COLUMNS = 5;

	private PageView()
	{
	}

	static StackPanel build(Report.PageReport page, ItemIcons icons, Runnable back)
	{
		return build(page, icons, back, id -> false, null);
	}

	/**
	 * @param wanted whether a slot is on the wanted list
	 * @param onWant marks a missing slot wanted or not when its row is clicked, or null to leave rows inert
	 */
	static StackPanel build(Report.PageReport page, ItemIcons icons, Runnable back, IntPredicate wanted, IntConsumer onWant)
	{
		return build(page, icons, back, wanted, onWant, false);
	}

	/** @param full the wanted list is full: slots not on it say so rather than taking a click that does nothing */
	static StackPanel build(Report.PageReport page, ItemIcons icons, Runnable back, IntPredicate wanted, IntConsumer onWant,
		boolean full)
	{
		StackPanel stack = new StackPanel(6, 8);
		JPanel top = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		top.setOpaque(false);
		top.add(new CodexButton("< All pages", false, back));
		stack.add(top);

		Card head = new Card(new BorderLayout(10, 0));
		head.setBorder(new EmptyBorder(9, 10, 9, 10));
		head.highlighted(true);
		ProgressRing ring = new ProgressRing(54, 6f);
		ring.setProgress(page.progress(), page.isComplete(), false);
		JPanel ringHolder = new JPanel(new BorderLayout());
		ringHolder.setOpaque(false);
		ringHolder.add(ring, BorderLayout.NORTH);
		head.add(ringHolder, BorderLayout.WEST);
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.add(Ui.label(page.getTab().toUpperCase(), Theme.small(), Theme.GOLD));
		text.add(Ui.wrapped(page.getName(), Theme.title(), Theme.GOLD_BRIGHT, 120));
		text.add(Ui.label(page.getOwned() + " of " + page.getTotal() + " slots", Theme.small(), Theme.TEXT_MUTED));
		for (String counter : page.getCounters())
		{
			text.add(Ui.label(counter, Theme.small(), Theme.TEXT));
		}
		head.add(text, BorderLayout.CENTER);
		stack.add(head);

		if (page.getLuck() != null)
		{
			Card dialCard = new Card(new BorderLayout());
			dialCard.setBorder(new EmptyBorder(8, 8, 8, 8));
			LuckDial dial = new LuckDial(104);
			dial.setLuck(page.getLuck(), false);
			dialCard.add(dial, BorderLayout.CENTER);
			dialCard.setToolTipText("An average player would own " + String.format(java.util.Locale.ENGLISH, "%.1f", page.getLuck().getExpected())
				+ " of these " + page.getLuck().getSlots() + " slots by now; you own " + page.getLuck().getOwned() + ".");
			stack.add(dialCard);
		}
		else if (!page.isComplete() && !page.isRead())
		{
			stack.add(Rows.note("Open this page in your collection log to read its kill count and see your luck here.", 190));
		}
		if (page.getDrops() != null)
		{
			stack.add(drops(page.getDrops(), page.getDrops().getSlots() == 1 ? "this slot" : "these " + page.getDrops().getSlots() + " slots"));
		}

		if (!page.isComplete())
		{
			JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 6));
			tiles.setOpaque(false);
			tiles.add(new StatTile(Format.hours(page.getHoursToNext()), "Next slot",
				page.getNextSource() == null ? "no rates" : Format.source(page.getNextSource()), Theme.TEAL));
			String finishNote = page.getUnrated() > 0 ? "+" + page.getUnrated() + " unrated" : "whole page";
			tiles.add(new StatTile(Format.hours(page.getHoursToFinish()), "To finish", finishNote, Theme.EMBER));
			stack.add(tiles);
			if (page.getProjection() != null)
			{
				stack.add(projection(page.getProjection()));
			}
		}

		List<Report.ItemReport> missing = new ArrayList<>();
		List<Report.ItemReport> owned = new ArrayList<>();
		for (Report.ItemReport item : page.getItems())
		{
			(item.isOwned() ? owned : missing).add(item);
		}
		if (!missing.isEmpty())
		{
			missing.sort(Comparator.comparingDouble(PageView::dryOrder));
			stack.add(new SectionHeader("Still to find", onWant == null ? String.valueOf(missing.size())
				: full ? "wanted list full" : "click to want"));
			for (Report.ItemReport item : missing)
			{
				boolean isWanted = wanted.test(item.getItemId());
				Card row = missingRow(item, icons, false, page.getNextSource(), isWanted);
				if (isWanted)
				{
					row.setToolTipText("<html>On your wanted list. Click to take it off.<br>" + stripHtml(row.getToolTipText()) + "</html>");
				}
				else if (onWant != null)
				{
					row.setToolTipText("<html>" + (full ? "Your wanted list is full. Take a slot off it to add this one."
						: "Click to add it to your wanted list.") + "<br>" + stripHtml(row.getToolTipText()) + "</html>");
				}
				if (onWant != null && (isWanted || !full))
				{
					row.onClick(() -> onWant.accept(item.getItemId()));
				}
				stack.add(row);
			}
		}
		if (!owned.isEmpty())
		{
			stack.add(new SectionHeader("Found", String.valueOf(owned.size())));
			stack.add(grid(owned, icons));
		}
		return stack;
	}

	/**
	 * Every copy the log counts against the odds: "14 drops, 9.6 average", with its verdict. It keeps saying how lucky
	 * a page has been after it is green, when owning the slots or not no longer can.
	 */
	static Card drops(Drops drops, String what)
	{
		Card card = new Card(new BorderLayout(8, 2));
		card.setBorder(new EmptyBorder(7, 9, 7, 9));
		JPanel head = new JPanel(new BorderLayout(6, 0));
		head.setOpaque(false);
		head.add(Ui.label("DROPS", Theme.small(), Theme.TEXT_MUTED), BorderLayout.WEST);
		Color tone = Theme.luck(drops.verdict());
		head.add(new Pill(drops.verdict().getLabel(), tone), BorderLayout.EAST);
		card.add(head, BorderLayout.NORTH);
		JPanel body = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		body.setOpaque(false);
		body.add(Ui.label(Format.count(drops.getGot()), Theme.title(), tone));
		body.add(Ui.label((drops.getGot() == 1 ? "  drop" : "  drops") + "  ·  average " + Format.slots(drops.getExpected()),
			Theme.small(), Theme.TEXT_MUTED));
		card.add(body, BorderLayout.CENTER);
		card.add(Ui.wrapped("Luckier than " + drops.luckierThan() + "% of players, counting every copy of " + what
			+ " in your log.", Theme.small(), Theme.TEXT_FAINT, 168), BorderLayout.SOUTH);
		card.setToolTipText("<html>Your log holds " + Format.count(drops.getGot()) + " copies of " + Ui.escape(what)
			+ ";<br>an average player would have " + Format.slots(drops.getExpected()) + " at your kill counts.<br>"
			+ "Pets, stacks and slots the game deals out in sets are left out.<br>Counts are as of your last read of the log.</html>");
		return card;
	}

	/** The green log curve: the chance the page is done against hours, with the half and nine-in-ten marks. */
	static Card projection(Projection projection)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.setBorder(new EmptyBorder(7, 9, 7, 9));
		JPanel head = new JPanel(new BorderLayout(6, 0));
		head.setOpaque(false);
		head.add(Ui.label("GREEN LOG", Theme.small(), Theme.TEXT_MUTED), BorderLayout.WEST);
		head.add(Ui.label("chance done", Theme.small(), Theme.TEXT_FAINT), BorderLayout.EAST);
		card.add(head, BorderLayout.NORTH);
		card.add(new ProjectionChart(projection), BorderLayout.CENTER);
		String text = "Half of players finish by " + Format.hours(projection.getMedian()) + ", nine in ten by "
			+ Format.hours(projection.getLikely()) + " at your rates.";
		if (projection.getUnrated() > 0)
		{
			text += " " + projection.getUnrated() + (projection.getUnrated() == 1 ? " slot has" : " slots have")
				+ " no rates and " + (projection.getUnrated() == 1 ? "is" : "are") + " not counted.";
		}
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, 168), BorderLayout.SOUTH);
		return card;
	}

	private static String stripHtml(String tip)
	{
		return tip == null ? "" : tip.replace("<html>", "").replace("</html>", "");
	}

	/** Missing slots with a known dry chance first, driest at the top. */
	private static double dryOrder(Report.ItemReport item)
	{
		return item.getDryChance() < 0 ? 2 + (Double.isFinite(item.getHours()) ? 0 : 1) : item.getDryChance();
	}

	static JPanel grid(List<Report.ItemReport> items, ItemIcons icons)
	{
		JPanel grid = new JPanel(new GridLayout(0, COLUMNS, 4, 4));
		grid.setOpaque(false);
		for (Report.ItemReport item : items)
		{
			grid.add(new ItemTile(item, icons));
		}
		for (int i = items.size(); i % COLUMNS != 0; i++)
		{
			JPanel filler = new JPanel();
			filler.setOpaque(false);
			grid.add(filler);
		}
		return grid;
	}

	/** A missing slot: its odds at your count, how dry you are, and where and how soon it comes alone. */
	static Card missingRow(Report.ItemReport item, ItemIcons icons, boolean withPage)
	{
		return missingRow(item, icons, withPage, null);
	}

	/** @param pageSource the activity the page is mostly hunted at, so its own slots just say "alone" */
	static Card missingRow(Report.ItemReport item, ItemIcons icons, boolean withPage, String pageSource)
	{
		return missingRow(item, icons, withPage, pageSource, false);
	}

	/** @param wanted the slot is on the wanted list: the card is gilt and its last line says so */
	static Card missingRow(Report.ItemReport item, ItemIcons icons, boolean withPage, String pageSource, boolean wanted)
	{
		StringBuilder detail = new StringBuilder(Format.chance(item.getChance()));
		if (item.getCount() >= 0)
		{
			detail.append(" at ").append(Format.count(item.getCount())).append(" kc");
		}
		String where = null;
		if (item.getSource() != null && Double.isFinite(item.getHours()))
		{
			where = item.getSource().equals(pageSource)
				? Format.about(item.getHours()) + " on its own"
				: Format.about(item.getHours()) + "  ·  " + Format.source(item.getSource());
		}
		if (withPage && item.getPage() != null)
		{
			where = item.getPage() + (where == null ? "" : "  ·  " + Format.about(item.getHours()));
		}
		Pill dry = null;
		if (item.getDryChance() >= 0)
		{
			dry = new Pill(Format.dry(item.getDryChance()), Theme.dry(item.getDryChance()));
		}
		if (wanted)
		{
			where = "Wanted" + (where == null ? "" : "  ·  " + where);
		}
		Card card = Rows.line(new IconBadge(item.getItemId(), icons, false), item.getName(), detail.toString(), where,
			wanted ? Theme.GOLD : Theme.TEXT_FAINT, dry,
			wanted ? Theme.GOLD : item.getDryChance() >= 0 && item.getDryChance() < 0.2 ? Theme.dry(item.getDryChance()) : null);
		if (wanted)
		{
			card.highlighted(true);
		}
		card.setToolTipText(ItemTile.tooltip(item));
		return card;
	}
}

package com.codex.loginsight.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tag, such as "Opens 12 more" or "Master". */
public class Pill extends JComponent
{
	private final String text;
	private final Color color;

	public Pill(String text, Color color)
	{
		this.text = text;
		this.color = color;
		setFont(Theme.small());
		setOpaque(false);
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 12, fm.getHeight() + 3);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, h, h);
		g.setColor(Theme.alpha(color, 34));
		g.fill(shape);
		g.setColor(Theme.alpha(color, 120));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(color);
		g.drawString(text, (w - fm.stringWidth(text)) / 2, (h + fm.getAscent()) / 2 - 1);
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.PetPlan;
import com.codex.loginsight.core.Projection;
import com.codex.loginsight.core.Prospect;
import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.function.Consumer;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/**
 * Planning a stretch of play: which activities give the most new slots in the time you have,
 * which pages are closest to a green log, and how long each missing pet is likely to take.
 */
final class PlanView
{
	static final String[] HORIZONS = {"1h", "5h", "20h", "100h"};
	static final double[] HOURS = {1, 5, 20, 100};
	private static final int WIDTH = 190;
	private static final int TEXT = 118;
	private static final int BEST = 8;
	private static final int PAGES = 6;
	private static final int PETS = 6;

	private PlanView()
	{
	}

	static StackPanel build(Report report, int horizon, ItemIcons icons, Consumer<String> openPage)
	{
		StackPanel stack = new StackPanel(5, 8);
		if (!report.isLoggedIn())
		{
			stack.add(Rows.note("Log in to plan your next stretch of collection logging.", WIDTH));
			return stack;
		}
		if (!report.isStructureLoaded())
		{
			stack.add(Rows.note("Log Insight is still reading the collection log's pages from the game.", WIDTH));
			return stack;
		}
		if (!report.ownedRead())
		{
			stack.add(Rows.note(QuarryView.UNREAD, WIDTH));
			return stack;
		}
		double hours = HOURS[Math.max(0, Math.min(HOURS.length - 1, horizon))];
		String span = HORIZONS[Math.max(0, Math.min(HORIZONS.length - 1, horizon))];

		best(stack, report, hours, span, icons);
		greenLogs(stack, report, hours, span, openPage);
		pets(stack, report, hours, span, icons, openPage);
		return stack;
	}

	/** Activities ranked by the new slots an average player would get from them in the time chosen. */
	private static void best(StackPanel stack, Report report, double hours, String span, ItemIcons icons)
	{
		List<Prospect> open = new ArrayList<>();
		int locked = 0;
		for (Prospect p : report.getProspects())
		{
			if (p.getLockedBy() != null)
			{
				locked++;
			}
			else if (p.getRemaining() > 0 && p.getPerHour() > 0)
			{
				open.add(p);
			}
		}
		open.sort(Comparator.comparingDouble((Prospect p) -> -p.expectedSlots(hours))
			.thenComparingDouble(p -> -p.chanceOfAny(hours)));
		stack.add(new SectionHeader("Best use of " + span, "new slots"));
		if (open.isEmpty())
		{
			stack.add(Rows.note("Nothing you can do yet has slots left with known rates.", WIDTH));
			return;
		}
		for (int i = 0; i < Math.min(BEST, open.size()); i++)
		{
			stack.add(prospectRow(open.get(i), i + 1, hours, icons));
		}
		stack.add(Rows.note("Expected new slots for an average player in " + span + " at "
			+ (report.isIronRates() ? "ironman" : "typical") + " rates or your own pace"
			+ (locked > 0 ? ". " + locked + (locked == 1 ? " activity" : " activities") + " you cannot do yet are left out." : "."),
			WIDTH));
	}

	static Card prospectRow(Prospect p, int rank, double hours, ItemIcons icons)
	{
		double slots = p.expectedSlots(hours);
		double any = p.chanceOfAny(hours);
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (rank == 1)
		{
			card.accent(Theme.TEAL);
		}
		JPanel lead = new JPanel(new BorderLayout());
		lead.setOpaque(false);
		lead.add(new QuarryView.Rank(rank, false), BorderLayout.NORTH);
		card.add(lead, BorderLayout.WEST);

		JPanel text = column();
		text.add(Ui.clamped(Format.source(p.getName()), Theme.body(), Theme.TEXT, TEXT, 2));
		String detail = Format.detail(p.getName());
		if (detail != null && !detail.isEmpty())
		{
			text.add(Ui.clamped(detail, Theme.small(), Theme.GOLD_DIM, TEXT, 1));
		}
		// Past near certainty the chance of one says nothing the count does not.
		text.add(Ui.label(Format.slots(slots) + " new " + Format.slotWord(slots)
			+ (any < 0.995 ? "  ·  " + Format.percent(any) + " any" : ""), Theme.small(), Theme.TEAL));
		String next = p.getNextItemName() == null ? "" : "likeliest " + p.getNextItemName();
		JComponent nextLabel = Ui.clamped(next, Theme.small(), Theme.TEXT_MUTED, TEXT, 2);
		nextLabel.setToolTipText(next);
		text.add(nextLabel);
		text.add(Ui.label(p.getRemaining() + " left  ·  " + Math.round(p.getPerHour()) + " an hour"
			+ (p.isOwnPace() ? ", your pace" : ""), Theme.small(), p.isOwnPace() ? Theme.GOLD : Theme.TEXT_FAINT));
		fix(text);
		card.add(text, BorderLayout.CENTER);
		if (p.getNextItemId() > 0)
		{
			JPanel trail = new JPanel(new BorderLayout());
			trail.setOpaque(false);
			trail.add(new IconBadge(p.getNextItemId(), icons, false), BorderLayout.NORTH);
			card.add(trail, BorderLayout.EAST);
		}
		card.setToolTipText("<html>" + Ui.escape(p.getName()) + "<br>In " + Format.hours(hours) + ": "
			+ String.format(Locale.ENGLISH, "%.2f", slots) + " new slots on average, " + Format.percent(any)
			+ " chance of at least one.</html>");
		return card;
	}

	/** Unfinished pages whose every missing slot has rates, nearest to done first. */
	private static void greenLogs(StackPanel stack, Report report, double hours, String span, Consumer<String> openPage)
	{
		List<Report.PageReport> pages = new ArrayList<>();
		for (Report.PageReport page : report.getPages())
		{
			Projection p = page.getProjection();
			if (!page.isComplete() && p != null && p.getUnrated() == 0 && Double.isFinite(p.getMedian()))
			{
				pages.add(page);
			}
		}
		pages.sort(Comparator.comparing((Report.PageReport page) -> page.getProjection().getLockedBy() != null)
			.thenComparingDouble(page -> page.getProjection().getMedian()));
		stack.add(new SectionHeader("Nearest green logs", "chance in " + span));
		if (pages.isEmpty())
		{
			stack.add(Rows.note("No unfinished page can be projected yet.", WIDTH));
			return;
		}
		for (int i = 0; i < Math.min(PAGES, pages.size()); i++)
		{
			Report.PageReport page = pages.get(i);
			Projection p = page.getProjection();
			double within = p.chanceBy(hours);
			ProgressRing ring = new ProgressRing(26, 3.5f);
			ring.setProgress(page.progress(), false, false);
			int left = page.getTotal() - page.getOwned();
			String source = page.getNextSource() == null ? "" : Format.source(page.getNextSource());
			Card card = Rows.line(ring, page.getName(),
				left + (left == 1 ? " slot left" : " slots left")
					+ (source.isEmpty() || source.equalsIgnoreCase(page.getName()) ? "" : "  ·  " + source),
				p.getLockedBy() != null ? "Needs " + p.getLockedBy() : odds(p.getMedian(), p.getLikely()),
				p.getLockedBy() != null ? Theme.EMBER : Theme.GOLD,
				new Pill(Format.percent(within), p.getLockedBy() != null ? Theme.TEXT_FAINT : chanceColor(within)), null);
			card.setToolTipText("<html>" + Ui.escape(page.getName()) + "<br>" + Format.percent(within)
				+ " chance to finish it within " + span + " at your rates.</html>");
			card.onClick(() -> openPage.accept(page.getName()));
			stack.add(card);
		}
	}

	/** Missing pets as hunts: the time to see each, and what else turns up on the way. */
	private static void pets(StackPanel stack, Report report, double hours, String span, ItemIcons icons,
		Consumer<String> openPage)
	{
		List<PetPlan> pets = report.getPets();
		stack.add(new SectionHeader("Pet hunt", pets.isEmpty() ? null : "chance in " + span));
		if (pets.isEmpty())
		{
			stack.add(Rows.note("Every pet Log Insight can rate is already yours.", WIDTH));
			return;
		}
		for (int i = 0; i < Math.min(PETS, pets.size()); i++)
		{
			PetPlan pet = pets.get(i);
			boolean locked = pet.getLockedBy() != null;
			double within = pet.chanceWithin(hours);
			double alongside = pet.slotsAlongside();
			Card card = new Card(new BorderLayout(8, 0));
			card.setBorder(new EmptyBorder(6, 8, 6, 8));
			if (i == 0 && !locked)
			{
				card.accent(Theme.VIOLET);
			}
			JPanel lead = new JPanel(new BorderLayout());
			lead.setOpaque(false);
			lead.add(new IconBadge(pet.getItemId(), icons, false), BorderLayout.NORTH);
			card.add(lead, BorderLayout.WEST);

			JPanel text = column();
			JPanel top = new JPanel(new BorderLayout(6, 0));
			top.setOpaque(false);
			JLabel name = Ui.label(pet.getName(), Theme.body(), locked ? Theme.TEXT_MUTED : Theme.TEXT);
			name.setMinimumSize(new Dimension(10, name.getPreferredSize().height));
			name.setPreferredSize(new Dimension(10, name.getPreferredSize().height));
			top.add(name, BorderLayout.CENTER);
			top.add(new Pill(Format.percent(within), locked ? Theme.TEXT_FAINT : chanceColor(within)), BorderLayout.EAST);
			top.setAlignmentX(0);
			text.add(top);
			text.add(Ui.label(Format.source(pet.getSource()) + "  ·  " + Format.chance(pet.getChance()), Theme.small(),
				Theme.TEXT_MUTED));
			if (locked)
			{
				text.add(Ui.label("Needs " + pet.getLockedBy(), Theme.small(), Theme.EMBER));
			}
			PetPlan.LevelUp up = pet.getLevelUp();
			if (up != null)
			{
				text.add(Ui.label(levelLine(up), Theme.small(), Theme.TEAL));
			}
			text.add(Ui.label(odds(pet.getMedian(), pet.getLikely()),
				Theme.small(), locked ? Theme.TEXT_FAINT : Theme.VIOLET));
			if (alongside >= 0.05)
			{
				text.add(Ui.label("+" + Format.slots(alongside) + " other " + Format.slotWord(alongside)
					+ " on the way", Theme.small(), Theme.TEXT_FAINT));
			}
			fix(text);
			card.add(text, BorderLayout.CENTER);
			card.setToolTipText("<html>" + Ui.escape(pet.getName()) + " from " + Ui.escape(pet.getSource()) + "<br>"
				+ Format.percent(within) + " chance within " + span + " of hunting it.<br>In the hours it takes half of players, "
				+ "they also find " + String.format(Locale.ENGLISH, "%.1f", alongside) + " other new slots there."
				+ (up == null ? "" : "<br>" + levelTip(up, pet.getChance())) + "</html>");
			if (pet.getPage() != null)
			{
				card.onClick(() -> openPage.accept(pet.getPage()));
			}
			stack.add(card);
		}
	}

	/** "At 99: 1 in 34,015", or for a 99, "At 200M xp: 1 in 2,268". */
	static String levelLine(PetPlan.LevelUp up)
	{
		return (up.isMaxedExperience() ? "At 200M xp: " : "At 99: ") + Format.chance(up.getChance());
	}

	static String levelTip(PetPlan.LevelUp up, double now)
	{
		return "Skilling pets get likelier as you level: " + Format.chance(now) + " at your " + up.skillName() + " "
			+ up.getLevel() + ", " + Format.chance(up.getChance())
			+ (up.isMaxedExperience() ? " with 200M experience." : " at 99.");
	}

	/** The hours by which half and nine in ten players are done: "50% 12h  ·  90% 31h". */
	static String odds(double median, double likely)
	{
		return "50% " + Format.hours(median) + "  ·  90% " + Format.hours(likely);
	}

	/** Faint when unlikely, gold through the middle, green once it is near certain. */
	static Color chanceColor(double chance)
	{
		if (chance >= 0.9)
		{
			return Theme.GREEN;
		}
		if (chance >= 0.5)
		{
			return Theme.mix(Theme.GOLD, Theme.TEAL, (chance - 0.5) / 0.4);
		}
		if (chance >= 0.1)
		{
			return Theme.GOLD;
		}
		return Theme.TEXT_MUTED;
	}

	private static JPanel column()
	{
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		return text;
	}

	/** Lets long lines clip instead of widening the card past the panel. */
	private static void fix(JComponent text)
	{
		text.setMinimumSize(new Dimension(10, 10));
		text.setPreferredSize(new Dimension(10, text.getPreferredSize().height));
	}
}

package com.codex.loginsight.ui;

import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A slim rounded bar that fills with the same ember-to-teal ramp as the rings. */
public class ProgressBar extends JComponent
{
	private final Animator animator = new Animator(this);
	private boolean complete;

	public ProgressBar(int height)
	{
		setPreferredSize(new Dimension(10, height));
		setMinimumSize(new Dimension(10, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		setOpaque(false);
	}

	public void setProgress(double progress, boolean complete, boolean animate)
	{
		this.complete = complete;
		animator.set(Math.max(0, Math.min(1, progress)), animate);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float arc = h;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(0, 0, w, h, arc, arc));
		double value = animator.get();
		if (value > 0)
		{
			float fill = (float) Math.max(h, w * value);
			if (complete)
			{
				g.setColor(Theme.GREEN);
			}
			else
			{
				g.setPaint(new GradientPaint(0, 0, Theme.progressColor(0), w, 0, Theme.progressColor(1)));
			}
			g.fill(new RoundRectangle2D.Float(0, 0, fill, h, arc, arc));
			g.setColor(Theme.alpha(java.awt.Color.WHITE, 40));
			g.drawLine(Math.round(arc / 2), 0, Math.round(fill - arc / 2), 0);
		}
		g.setColor(Theme.alpha(Theme.STROKE, 160));
		g.draw(new RoundRectangle2D.Float(0, 0, w - 1, h - 1, arc, arc));
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import javax.swing.JComponent;

/** A gilded progress ring with the percentage set in the game's bold font. */
public class ProgressRing extends JComponent
{
	private final int diameter;
	private final float thickness;
	private final Animator animator = new Animator(this);
	private String caption;
	private boolean complete;
	/** When set, the ring shows this instead of a percentage: "-" while nothing is known. */
	private String centre;

	public ProgressRing(int diameter, float thickness)
	{
		this.diameter = diameter;
		this.thickness = thickness;
		Dimension size = new Dimension(diameter, diameter);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		setOpaque(false);
	}

	public void setProgress(double progress, boolean complete, boolean animate)
	{
		this.complete = complete;
		animator.set(Math.max(0, Math.min(1, progress)), animate);
	}

	/** Text in place of the percentage, or null to show the percentage again. */
	public void setCentre(String text)
	{
		centre = text;
		repaint();
	}

	/** A small line under the percentage, for rings large enough to hold it. */
	public void setCaption(String caption)
	{
		this.caption = caption;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		double value = animator.get();
		float inset = thickness / 2f + 1;
		float size = diameter - inset * 2;

		// Inner well: a faint radial glow tinted by progress.
		Color glow = complete ? Theme.GREEN : Theme.progressColor(value);
		float r = size / 2f;
		g.setPaint(new RadialGradientPaint(diameter / 2f, diameter / 2f, r,
			new float[]{0f, 1f}, new Color[]{Theme.alpha(glow, 40), Theme.alpha(Theme.INK_DEEP, 0)}));
		g.fill(new Ellipse2D.Float(inset, inset, size, size));

		g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.STROKE, 200));
		g.draw(new Arc2D.Float(inset, inset, size, size, 0, 360, Arc2D.OPEN));

		if (value > 0)
		{
			g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			// Draw the arc in short segments so its colour can travel from ember to teal.
			int segments = Math.max(1, (int) Math.ceil(value * 72));
			double sweep = value * 360 / segments;
			for (int i = 0; i < segments; i++)
			{
				double t = (i + 1) / (double) segments * value;
				g.setColor(complete ? Theme.GREEN : Theme.progressColor(t));
				g.draw(new Arc2D.Double(inset, inset, size, size, 90 - i * sweep, -sweep - (i < segments - 1 ? 0.6 : 0), Arc2D.OPEN));
			}
		}

		// Fine gold rim outside the track.
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 90));
		g.draw(new Ellipse2D.Float(0.5f, 0.5f, diameter - 1, diameter - 1));

		g.setFont(diameter >= 48 ? Theme.title() : Theme.small());
		String text = centre != null ? centre : Math.round(value * 100) + "%";
		FontMetrics fm = g.getFontMetrics();
		if (complete)
		{
			drawCheck(g, diameter / 2f, diameter / 2f - (caption != null && diameter >= 60 ? 5 : 0), diameter * 0.16f);
			text = null;
		}
		int textY = diameter / 2 + fm.getAscent() / 2 - 2;
		if (caption != null && diameter >= 60)
		{
			textY -= 5;
		}
		// A small ring's hole holds the number only: "80" fits where "80%" would cross the rim.
		int hole = Math.round(diameter - thickness * 2 - 2);
		if (text != null && centre == null && fm.stringWidth(text) > hole)
		{
			text = text.substring(0, text.length() - 1);
		}
		if (text != null && fm.stringWidth(text) <= hole + 2)
		{
			drawShadowed(g, text, (diameter - fm.stringWidth(text)) / 2, textY, Theme.TEXT);
		}

		if (caption != null && diameter >= 60)
		{
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();
			drawShadowed(g, caption, (diameter - small.stringWidth(caption)) / 2, textY + small.getAscent() + 1, Theme.TEXT_MUTED);
		}
		g.dispose();
	}

	/** A drawn check mark, since the game fonts have no glyph for one. */
	static void drawCheck(Graphics2D g, float cx, float cy, float r)
	{
		java.awt.geom.Path2D check = new java.awt.geom.Path2D.Float();
		check.moveTo(cx - r, cy);
		check.lineTo(cx - r * 0.3f, cy + r * 0.7f);
		check.lineTo(cx + r, cy - r * 0.65f);
		g.setStroke(new BasicStroke(Math.max(1.6f, r * 0.32f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.GREEN);
		g.draw(check);
	}

	static void drawShadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Projection;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/**
 * The chance a page is finished against hours played, as a gilt curve rising from nothing
 * to near certain. Two engraved marks stand where half and nine in ten players would be done.
 */
class ProjectionChart extends JComponent
{
	private static final int HEIGHT = 78;
	private static final int LEFT = 4;
	private static final int RIGHT = 4;
	private static final int TOP = 6;
	/** Room under the plot for the hour labels. */
	private static final int AXIS = 14;

	private final Projection projection;

	ProjectionChart(Projection projection)
	{
		this.projection = projection;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
		setToolTipText("<html>The chance this page is finished after each number of hours at your rates.<br>"
			+ "Half of players would be done by " + Format.hours(projection.getMedian()) + ", nine in ten by "
			+ Format.hours(projection.getLikely()) + ".</html>");
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int plotW = w - LEFT - RIGHT;
		int plotH = HEIGHT - TOP - AXIS;
		int bottom = TOP + plotH;
		double[] hours = projection.getHours();
		double[] chance = projection.getChance();
		double end = hours[hours.length - 1];
		if (end <= 0 || plotW <= 0)
		{
			g.dispose();
			return;
		}

		// Faint rules at a quarter, half and three quarters.
		g.setColor(Theme.STROKE_SOFT);
		for (int q = 1; q <= 3; q++)
		{
			int y = bottom - plotH * q / 4;
			g.drawLine(LEFT, y, LEFT + plotW, y);
		}
		g.setColor(Theme.STROKE);
		g.drawLine(LEFT, bottom, LEFT + plotW, bottom);

		Path2D line = new Path2D.Float();
		Path2D area = new Path2D.Float();
		area.moveTo(LEFT, bottom);
		for (int i = 0; i < hours.length; i++)
		{
			float x = (float) (LEFT + plotW * hours[i] / end);
			float y = (float) (bottom - plotH * Math.max(0, Math.min(1, chance[i])));
			if (i == 0)
			{
				line.moveTo(x, y);
			}
			else
			{
				line.lineTo(x, y);
			}
			area.lineTo(x, y);
		}
		area.lineTo(LEFT + plotW, bottom);
		area.closePath();
		g.setPaint(new GradientPaint(0, TOP, Theme.alpha(Theme.GOLD, 70), 0, bottom, Theme.alpha(Theme.GOLD, 6)));
		g.fill(area);

		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int medianX = mark(g, projection.getMedian(), 0.5, end, plotW, plotH, bottom, Theme.GOLD_BRIGHT);
		int likelyX = mark(g, projection.getLikely(), 0.9, end, plotW, plotH, bottom, Theme.TEAL);

		g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.GOLD);
		g.draw(line);

		// Hour labels under the two marks, kept apart and inside the plot.
		String a = Format.hours(projection.getMedian());
		String b = Format.hours(projection.getLikely());
		int aw = fm.stringWidth(a);
		int bw = fm.stringWidth(b);
		int ax = Math.max(LEFT, Math.min(medianX - aw / 2, LEFT + plotW - aw));
		int bx = Math.max(LEFT, Math.min(likelyX - bw / 2, LEFT + plotW - bw));
		if (bx < ax + aw + 6)
		{
			bx = Math.min(LEFT + plotW - bw, ax + aw + 6);
			ax = Math.min(ax, bx - aw - 6);
		}
		int base = bottom + fm.getAscent() + 2;
		ProgressRing.drawShadowed(g, a, Math.max(LEFT, ax), base, Theme.GOLD_BRIGHT);
		ProgressRing.drawShadowed(g, b, bx, base, Theme.TEAL);
		g.dispose();
	}

	/** A dotted drop from the curve to the axis where it crosses this chance, with a bead on the curve. */
	private static int mark(Graphics2D g, double hours, double chance, double end, int plotW, int plotH, int bottom, Color color)
	{
		int x = (int) Math.round(LEFT + plotW * Math.min(1, hours / end));
		int y = (int) Math.round(bottom - plotH * chance);
		g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f, new float[]{2f, 2f}, 0f));
		g.setColor(Theme.alpha(color, 150));
		g.drawLine(x, y, x, bottom);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.INK_DEEP);
		g.fillOval(x - 3, y - 3, 7, 7);
		g.setColor(color);
		g.drawOval(x - 3, y - 3, 6, 6);
		return x;
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Report;
import com.codex.loginsight.data.Activity;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** Every activity ranked by the expected wait for its next new slot. */
final class QuarryView
{
	static final String[] FILTERS = {"All", "Combat", "Games", "Other", "Pets"};
	private static final int SHOWN = 40;

	private QuarryView()
	{
	}

	/** Until the owned slots are read every slot counts as missing, so nothing is ranked. */
	static final String UNREAD = "Open your collection log and press its Search button once. Until Log Insight has read"
		+ " which slots you own, it cannot say where your next ones come from.";

	static StackPanel build(Report report, int filter, ItemIcons icons)
	{
		StackPanel stack = new StackPanel(5, 8);
		if (!report.isLoggedIn())
		{
			stack.add(Rows.note("Log in to rank where your next slots will come from.", 190));
			return stack;
		}
		if (!report.ownedRead())
		{
			stack.add(Rows.note(UNREAD, 190));
			return stack;
		}
		boolean pets = filter == 4;
		stack.add(Rows.note((pets ? "Ranked by the wait for a pet" : "Ranked by the wait for a new slot")
			+ (report.isIronRates() ? " at ironman rates" : " at typical rates")
			+ ". Activities you do often switch to your own pace; ones you cannot do yet come last.", 190));
		List<Report.Hunt> hunts = new ArrayList<>();
		for (Report.Hunt hunt : report.getHunts())
		{
			if (matches(hunt, filter))
			{
				hunts.add(hunt);
			}
		}
		if (pets)
		{
			hunts.sort(Comparator.comparing((Report.Hunt h) -> h.getLockedBy() != null)
				.thenComparingDouble(Report.Hunt::getHoursToPet));
		}
		int rank = 0;
		for (Report.Hunt hunt : hunts)
		{
			rank++;
			stack.add(row(hunt, rank, icons, pets));
			if (rank >= SHOWN)
			{
				break;
			}
		}
		if (rank == 0)
		{
			stack.add(Rows.note("Nothing left to hunt here.", 190));
		}
		return stack;
	}

	private static boolean matches(Report.Hunt hunt, int filter)
	{
		switch (filter)
		{
			case 1:
				return hunt.getCategory() == Activity.Category.COMBAT;
			case 2:
				return hunt.getCategory() == Activity.Category.MINIGAME;
			case 3:
				return hunt.getCategory() == Activity.Category.OTHER;
			case 4:
				return hunt.isPet();
			default:
				return true;
		}
	}

	static Card row(Report.Hunt hunt, int rank, ItemIcons icons)
	{
		return row(hunt, rank, icons, false);
	}

	/** @param pets lead with the wait for this activity's pet rather than its next slot */
	static Card row(Report.Hunt hunt, int rank, ItemIcons icons, boolean pets)
	{
		boolean locked = hunt.getLockedBy() != null;
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (rank == 1 && !locked)
		{
			card.accent(Theme.TEAL);
		}
		JPanel lead = new JPanel(new BorderLayout());
		lead.setOpaque(false);
		lead.add(new Rank(rank, locked), BorderLayout.NORTH);
		card.add(lead, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.add(Ui.clamped(Format.source(hunt.getName()), Theme.body(), locked ? Theme.TEXT_MUTED : Theme.TEXT, 118, 2));
		String detail = Format.detail(hunt.getName());
		if (detail != null && !detail.isEmpty())
		{
			text.add(Ui.clamped(detail, Theme.small(), Theme.GOLD_DIM, 118, 1));
		}
		if (locked)
		{
			text.add(Ui.clamped("Needs " + hunt.getLockedBy(), Theme.small(), Theme.EMBER, 118, 1));
		}
		if (pets && hunt.getPetName() != null)
		{
			text.add(Ui.label("Pet " + Format.about(hunt.getHoursToPet()) + "  ·  " + hunt.getRemaining() + " left",
				Theme.small(), Theme.VIOLET));
		}
		else
		{
			text.add(Ui.label("Next " + Format.about(hunt.getHoursToNext()) + "  ·  " + hunt.getRemaining() + " left",
				Theme.small(), locked ? Theme.TEXT_MUTED : Theme.TEAL));
		}
		String next = "";
		if (hunt.getNextItemName() != null)
		{
			long after = Math.round(1 / hunt.getNextChance());
			next = hunt.getNextItemName() + (hunt.isNextEarned()
				? (after <= 1 ? ", every time" : ", earned in " + Format.count(after))
				: "Always".equals(Format.chance(hunt.getNextChance())) ? ", every time" : " " + Format.chance(hunt.getNextChance()));
		}
		if (pets && hunt.getPetName() != null)
		{
			next = hunt.getPetName();
		}
		// Two lines rather than a cut: "Hallowed mark, every time" is the point of the row.
		JLabel nextLabel = Ui.clamped(next, Theme.small(), Theme.TEXT_MUTED, 118, 2);
		nextLabel.setToolTipText(next);
		text.add(nextLabel);
		text.add(Ui.label("All " + hunt.getRemaining() + " " + Format.about(hunt.getHoursToFinish())
			+ (hunt.isOwnPace() ? "  ·  your pace" : ""), Theme.small(), hunt.isOwnPace() ? Theme.GOLD : Theme.TEXT_FAINT));
		text.setMinimumSize(new Dimension(10, 10));
		text.setPreferredSize(new Dimension(10, text.getPreferredSize().height));
		card.add(text, BorderLayout.CENTER);

		int shown = pets && hunt.getPetItemId() > 0 ? hunt.getPetItemId() : hunt.getNextItemId();
		if (shown > 0)
		{
			JPanel trail = new JPanel(new BorderLayout());
			trail.setOpaque(false);
			trail.add(new IconBadge(shown, icons, false), BorderLayout.NORTH);
			card.add(trail, BorderLayout.EAST);
		}
		card.setToolTipText("<html>" + Ui.escape(hunt.getName()) + "<br>" + Math.round(hunt.getPerHour()) + " per hour"
			+ (hunt.isOwnPace() ? " (your pace)" : "") + "</html>");
		return card;
	}

	/** A small gilt medallion with the rank number. */
	static final class Rank extends JComponent
	{
		private final int rank;
		private final boolean locked;

		Rank(int rank, boolean locked)
		{
			this.rank = rank;
			this.locked = locked;
			Dimension d = new Dimension(20, 20);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			boolean first = rank <= 3 && !locked;
			g.setColor(first ? Theme.alpha(Theme.GOLD, 60) : Theme.INK_DEEP);
			g.fill(new Ellipse2D.Float(1, 1, 18, 18));
			g.setColor(first ? Theme.GOLD : Theme.STROKE);
			g.draw(new Ellipse2D.Float(1, 1, 18, 18));
			g.setFont(Theme.small());
			FontMetrics fm = g.getFontMetrics();
			String text = String.valueOf(rank);
			ProgressRing.drawShadowed(g, text, 10 - fm.stringWidth(text) / 2, 10 + fm.getAscent() / 2 - 1,
				first ? Theme.GOLD_BRIGHT : Theme.TEXT_MUTED);
			g.dispose();
		}
	}
}

package com.codex.loginsight.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** Compact card lines: a verdict mark, a name, a quiet second line and an optional value. */
public final class Rows
{
	private Rows()
	{
	}

	public static Card check(Mark.Kind kind, String title, String detail, String value)
	{
		return line(new Mark(kind, 14), title, detail, value == null ? null : Ui.label(value, Theme.small(), Mark.color(kind)),
			kind == Mark.Kind.BAD ? Theme.BLOOD : null);
	}

	/** A verdict with a sentence that may run to two lines. */
	public static Card reason(Mark.Kind kind, String text)
	{
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (kind == Mark.Kind.BAD)
		{
			card.accent(Theme.BLOOD);
		}
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.setBorder(new EmptyBorder(1, 0, 0, 0));
		holder.add(new Mark(kind, 14), BorderLayout.NORTH);
		card.add(holder, BorderLayout.WEST);
		card.add(Ui.wrapped(text, Theme.body(), Theme.TEXT, 160), BorderLayout.CENTER);
		return card;
	}

	public static Card line(JComponent lead, String title, String detail, JComponent trailing, Color accent)
	{
		return line(lead, title, detail, null, null, trailing, accent);
	}

	/** As {@link #line}, with a third line in its own colour, such as a verdict or where to go. */
	public static Card line(JComponent lead, String title, String detail, String extra, Color extraColor,
		JComponent trailing, Color accent)
	{
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (accent != null)
		{
			card.accent(accent);
		}
		if (lead != null)
		{
			JPanel holder = new JPanel(new BorderLayout());
			holder.setOpaque(false);
			holder.setBorder(new EmptyBorder(1, 0, 0, 0));
			holder.add(lead, BorderLayout.NORTH);
			card.add(holder, BorderLayout.WEST);
		}
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		JLabel name = Ui.label(title, Theme.body(), Theme.TEXT);
		name.setToolTipText(title);
		if (trailing != null)
		{
			// The tag sits beside the name only, so the lines under it keep the card's full width.
			JPanel top = new JPanel(new BorderLayout(6, 0));
			top.setOpaque(false);
			name.setMinimumSize(new Dimension(10, name.getPreferredSize().height));
			name.setPreferredSize(new Dimension(10, Math.max(name.getPreferredSize().height, trailing.getPreferredSize().height)));
			top.add(name, BorderLayout.CENTER);
			top.add(trailing, BorderLayout.EAST);
			top.setAlignmentX(Component.LEFT_ALIGNMENT);
			text.add(top);
		}
		else
		{
			text.add(name);
		}
		if (detail != null && !detail.isEmpty())
		{
			JLabel sub = Ui.label(detail, Theme.small(), Theme.TEXT_MUTED);
			sub.setToolTipText(detail);
			text.add(sub);
		}
		if (extra != null && !extra.isEmpty())
		{
			JLabel third = Ui.label(extra, Theme.small(), extraColor == null ? Theme.TEXT_FAINT : extraColor);
			third.setToolTipText(extra);
			text.add(third);
		}
		// Long names clip with an ellipsis rather than push the value off the card.
		text.setMinimumSize(new Dimension(10, 10));
		text.setPreferredSize(new Dimension(10, text.getPreferredSize().height));
		card.add(text, BorderLayout.CENTER);
		return card;
	}

	/** A quiet line of text for empty states. */
	public static JComponent note(String text, int width)
	{
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.setBorder(new EmptyBorder(2, 4, 2, 4));
		holder.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_FAINT, width), BorderLayout.CENTER);
		return holder;
	}
}

