package com.codex.loginsight.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/** Log Insight's mark: an open, gilt-edged tome with a star of discovery above its spine. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the tome in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float spine = x + 8 * s;
		float top = y + 6 * s;
		float bottom = y + 14.5f * s;

		Path2D left = new Path2D.Float();
		left.moveTo(spine, top + 1 * s);
		left.curveTo(spine - 2 * s, top - 0.5f * s, spine - 5 * s, top - 0.5f * s, x + 1 * s, top + 0.5f * s);
		left.lineTo(x + 1 * s, bottom - 1 * s);
		left.curveTo(spine - 5 * s, bottom - 2 * s, spine - 2 * s, bottom - 2 * s, spine, bottom);
		left.closePath();
		Path2D right = new Path2D.Float();
		right.moveTo(spine, top + 1 * s);
		right.curveTo(spine + 2 * s, top - 0.5f * s, spine + 5 * s, top - 0.5f * s, x + 15 * s, top + 0.5f * s);
		right.lineTo(x + 15 * s, bottom - 1 * s);
		right.curveTo(spine + 5 * s, bottom - 2 * s, spine + 2 * s, bottom - 2 * s, spine, bottom);
		right.closePath();

		g.setPaint(new GradientPaint(x, top, Theme.GOLD_BRIGHT, x, bottom, Theme.GOLD_DIM));
		g.fill(left);
		g.fill(right);
		g.setStroke(new BasicStroke(Math.max(0.8f, 0.8f * s)));
		g.setColor(Theme.INK_DEEP);
		g.draw(left);
		g.draw(right);
		// Lines of script on each page.
		g.setColor(Theme.alpha(Theme.INK_DEEP, 150));
		for (int i = 0; i < 2; i++)
		{
			float ly = top + (3 + i * 2.6f) * s;
			g.drawLine(Math.round(x + 3 * s), Math.round(ly), Math.round(spine - 1.5f * s), Math.round(ly));
			g.drawLine(Math.round(spine + 1.5f * s), Math.round(ly), Math.round(x + 13 * s), Math.round(ly));
		}

		// The star above the spine.
		float cx = spine;
		float cy = y + 3 * s;
		Path2D star = new Path2D.Float();
		for (int i = 0; i < 8; i++)
		{
			double angle = Math.PI / 4 * i - Math.PI / 2;
			float r = (i % 2 == 0 ? 3f : 1.1f) * s;
			float px = cx + (float) Math.cos(angle) * r;
			float py = cy + (float) Math.sin(angle) * r;
			if (i == 0)
			{
				star.moveTo(px, py);
			}
			else
			{
				star.lineTo(px, py);
			}
		}
		star.closePath();
		g.setColor(Theme.TEAL);
		g.fill(star);
	}
}

package com.codex.loginsight.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.loginsight.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(Theme.RADIUS, 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), 8, 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		ProgressRing.drawShadowed(g, value, 8, 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null)
		{
			g.setFont(Theme.small());
			String clipped = note;
			while (clipped.length() > 1 && small.stringWidth(clipped) > w - 16)
			{
				clipped = clipped.substring(0, clipped.length() - 2) + "…";
			}
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(clipped, 8, h - 6);
		}
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Luck;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * Log Insight adds a violet for the rarest finds, the colour of a pet's glow.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Blood when parched, ember when dry, gold when even, teal when fortunate and green when blessed. */
	public static Color luck(Luck.Verdict verdict)
	{
		switch (verdict)
		{
			case PARCHED:
				return BLOOD;
			case DRY:
				return EMBER;
			case FORTUNATE:
				return TEAL;
			case BLESSED:
				return GREEN;
			default:
				return GOLD;
		}
	}

	/** The same scale as a smooth ramp, for gauges and bars. */
	public static Color luck(double percentile)
	{
		double p = Math.max(0, Math.min(1, percentile));
		if (p < 0.25)
		{
			return mix(BLOOD, EMBER, p / 0.25);
		}
		if (p < 0.5)
		{
			return mix(EMBER, GOLD, (p - 0.25) / 0.25);
		}
		if (p < 0.75)
		{
			return mix(GOLD, TEAL, (p - 0.5) / 0.25);
		}
		return mix(TEAL, GREEN, (p - 0.75) / 0.25);
	}

	/** How overdue a missing slot is: gold while it is normal, through ember to blood as it gets rare to be this dry. */
	public static Color dry(double dryChance)
	{
		if (dryChance < 0)
		{
			return TEXT_FAINT;
		}
		if (dryChance >= 0.5)
		{
			return TEXT_MUTED;
		}
		if (dryChance >= 0.2)
		{
			return GOLD;
		}
		return dryChance >= 0.07 ? EMBER : BLOOD;
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Progress;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;

/**
 * The trophy shelf: the rarest drops Log Insight has seen you get, on a podium, the rarest in the middle. Each
 * stands on a gilt plinth with its odds and how far ahead of other players it came. Drawn once per report; the
 * pictures arrive from the item manager and only repaint this card.
 */
final class TrophyShelf extends JComponent
{
	static final int HEIGHT = 158;
	/** Plinth heights for first, second and third. */
	private static final int[] PLINTH = {30, 21, 14};
	private static final Color[] MEDAL = {Theme.GOLD_BRIGHT, new Color(196, 198, 202), new Color(196, 132, 84)};

	/** Each find below the podium, fourth and fifth, gets a slim row. */
	static final int ROW = 20;

	private final List<Progress.Find> finds;
	private final BufferedImage[] images;
	/** The finds after the podium's three. */
	private final List<Progress.Find> rest;
	private final BufferedImage[] restImages;

	TrophyShelf(List<Progress.Find> trophies, ItemIcons icons)
	{
		finds = new ArrayList<>(trophies.subList(0, Math.min(3, trophies.size())));
		rest = new ArrayList<>(trophies.subList(finds.size(), trophies.size()));
		images = images(finds, icons);
		restImages = images(rest, icons);
		setOpaque(false);
		int h = height(rest.size());
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		StringBuilder tip = new StringBuilder("<html>The rarest drops Log Insight has seen you get:");
		List<Progress.Find> all = new ArrayList<>(finds);
		all.addAll(rest);
		for (int i = 0; i < all.size(); i++)
		{
			Progress.Find f = all.get(i);
			tip.append("<br>").append(i + 1).append(". ").append(Ui.escape(f.getName())).append(", ").append(Format.chance(f.getChance()));
			if (f.getCount() > 0)
			{
				tip.append(" at ").append(Format.count(f.getCount())).append(" kc");
			}
			if (f.getPage() != null)
			{
				tip.append(" (").append(Ui.escape(f.getPage())).append(")");
			}
		}
		setToolTipText(tip.append("</html>").toString());
	}

	private BufferedImage[] images(List<Progress.Find> list, ItemIcons icons)
	{
		BufferedImage[] out = new BufferedImage[list.size()];
		for (int i = 0; i < list.size(); i++)
		{
			int id = list.get(i).getItemId();
			out[i] = icons == null || id <= 0 ? null : icons.icon(id, this::repaint);
		}
		return out;
	}

	/** The card's height: the podium, and a row for each find after it. */
	static int height(int rest)
	{
		return rest == 0 ? HEIGHT : HEIGHT + 8 + rest * ROW;
	}

	/** Which find stands in each column, left to right: the rarest in the middle once there are three. */
	static int[] order(int count)
	{
		switch (count)
		{
			case 1:
				return new int[]{0};
			case 2:
				return new int[]{0, 1};
			default:
				return new int[]{1, 0, 2};
		}
	}

	/**
	 * "top 3%" for a find fewer players would have had by then, "a late one" for one most would have had sooner,
	 * so every plinth carries a line; null when the odds are unknown.
	 */
	static String standing(double luckier)
	{
		if (luckier < 0)
		{
			return null;
		}
		if (luckier < 0.5)
		{
			return "a late one";
		}
		long top = Math.max(1, Math.round((1 - luckier) * 100));
		return "top " + top + "%";
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();

		RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(card);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(card);
		g.setColor(Theme.alpha(Color.WHITE, 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);

		Font small = Theme.small();
		Font body = Theme.body();
		FontMetrics sm = g.getFontMetrics(small);
		FontMetrics bm = g.getFontMetrics(body);

		int[] order = order(finds.size());
		int cols = order.length;
		int colW = Math.min(70, (w - 12) / 3);
		int left = (w - colW * cols) / 2;
		int shelfY = 82;

		// The shelf: a gilt ledge the plinths stand on.
		g.setPaint(new GradientPaint(10, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.fillRect(10, shelfY, w - 20, 2);
		g.setColor(Theme.alpha(Color.BLACK, 90));
		g.fillRect(10, shelfY + 2, w - 20, 2);

		for (int c = 0; c < cols; c++)
		{
			int i = order[c];
			Progress.Find find = finds.get(i);
			int x = left + c * colW;
			int cx = x + colW / 2;
			int ph = PLINTH[i];
			int pw = colW - 14;
			int top = shelfY - ph;

			// The plinth, lit from above, its rank on the front.
			g.setPaint(new GradientPaint(0, top, Theme.mix(Theme.CARD_HOVER, Theme.GOLD_DIM, 0.35), 0, shelfY, Theme.INK_DEEP));
			g.fillRect(cx - pw / 2, top, pw, ph);
			g.setColor(Theme.alpha(MEDAL[i], 150));
			g.drawLine(cx - pw / 2, top, cx + pw / 2 - 1, top);
			g.setColor(Theme.alpha(Theme.STROKE, 220));
			g.drawRect(cx - pw / 2, top, pw - 1, ph - 1);
			String rank = String.valueOf(i + 1);
			if (ph >= sm.getAscent() + 3)
			{
				text(g, small, rank, cx - sm.stringWidth(rank) / 2, top + (ph + sm.getAscent()) / 2 - 1, MEDAL[i]);
			}

			// The prize, with a glow behind it: gold for the rarest.
			int iy = top - 34;
			float r = i == 0 ? 26 : 20;
			g.setPaint(new RadialGradientPaint(cx, iy + 16, r, new float[]{0f, 1f},
				new Color[]{Theme.alpha(MEDAL[i], i == 0 ? 90 : 55), Theme.alpha(MEDAL[i], 0)}));
			g.fill(new Ellipse2D.Float(cx - r, iy + 16 - r, r * 2, r * 2));
			BufferedImage img = images[i];
			if (img != null)
			{
				int iw = Math.min(img.getWidth(), 36);
				int ih = Math.min(img.getHeight(), 32);
				g.drawImage(img, cx - iw / 2, iy, iw, ih, null);
			}
			else
			{
				g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
				g.fill(new Ellipse2D.Float(cx - 12, iy + 4, 24, 24));
			}
			if (i == 0)
			{
				star(g, cx + 15, iy + 2);
			}

			// The plaque under the shelf: odds, name, and how early it came.
			int ty = shelfY + 8 + bm.getAscent();
			String odds = Format.chance(find.getChance());
			text(g, body, odds, cx - bm.stringWidth(odds) / 2, ty, i == 0 ? Theme.GOLD_BRIGHT : Theme.GOLD);
			// The name on up to two lines, so "Skeletal visage" is read whole rather than cut.
			for (String part : lines(find.getName(), sm, colW - 4))
			{
				ty += sm.getAscent() + 2;
				text(g, small, part, cx - sm.stringWidth(part) / 2, ty, Theme.TEXT);
			}
			if (find.getCount() > 0)
			{
				String kc = clip(Format.count(find.getCount()) + " kc", sm, colW - 2);
				ty += sm.getAscent() + 2;
				text(g, small, kc, cx - sm.stringWidth(kc) / 2, ty, Theme.TEXT_FAINT);
			}
			String standing = standing(find.getLuckier());
			if (standing != null)
			{
				standing = clip(standing, sm, colW - 2);
				ty += sm.getAscent() + 2;
				text(g, small, standing, cx - sm.stringWidth(standing) / 2, ty,
					find.getLuckier() < 0.5 ? Theme.TEXT_FAINT : Theme.luck(find.getLuckier()));
			}
		}
		paintRest(g, w, sm, bm);
		g.dispose();
	}

	/** Fourth and fifth on slim rows under the podium: rank, picture, name and odds. */
	private void paintRest(Graphics2D g, int w, FontMetrics sm, FontMetrics bm)
	{
		if (rest.isEmpty())
		{
			return;
		}
		int y = HEIGHT + 1;
		g.setPaint(new GradientPaint(14, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 90), true));
		g.drawLine(14, y, w - 14, y);
		for (int i = 0; i < rest.size(); i++)
		{
			Progress.Find find = rest.get(i);
			int top = y + 3 + i * ROW;
			int mid = top + ROW / 2;
			String rank = String.valueOf(i + 4);
			text(g, Theme.small(), rank, 14 - sm.stringWidth(rank) / 2 + 2, mid + sm.getAscent() / 2 - 1, Theme.TEXT_FAINT);
			BufferedImage img = restImages[i];
			if (img != null)
			{
				int iw = Math.min(img.getWidth(), 36);
				int ih = Math.min(img.getHeight(), 32);
				double scale = Math.min(22.0 / iw, 18.0 / ih);
				int dw = (int) Math.round(iw * scale);
				int dh = (int) Math.round(ih * scale);
				g.drawImage(img, 34 - dw / 2, mid - dh / 2, dw, dh, null);
			}
			String odds = Format.chance(find.getChance());
			int oddsX = w - 12 - sm.stringWidth(odds);
			text(g, Theme.small(), odds, oddsX, mid + sm.getAscent() / 2 - 1, Theme.GOLD);
			String name = clip(find.getName(), bm, oddsX - 50 - 6);
			text(g, Theme.body(), name, 50, mid + bm.getAscent() / 2 - 1, Theme.TEXT);
		}
	}

	/** A four-pointed glint for the rarest. */
	private static void star(Graphics2D g, int x, int y)
	{
		Path2D s = new Path2D.Float();
		s.moveTo(x, y - 5);
		s.lineTo(x + 1.3, y - 1.3);
		s.lineTo(x + 5, y);
		s.lineTo(x + 1.3, y + 1.3);
		s.lineTo(x, y + 5);
		s.lineTo(x - 1.3, y + 1.3);
		s.lineTo(x - 5, y);
		s.lineTo(x - 1.3, y - 1.3);
		s.closePath();
		g.setColor(Theme.GOLD_BRIGHT);
		g.fill(s);
	}

	private static void text(Graphics2D g, Font font, String s, int x, int y, Color c)
	{
		g.setFont(font);
		g.setColor(Theme.alpha(Color.BLACK, 170));
		g.drawString(s, x + 1, y + 1);
		g.setColor(c);
		g.drawString(s, x, y);
	}

	/** Up to two lines of a name, broken between words, the second cut short if it still does not fit. */
	static List<String> lines(String name, FontMetrics fm, int width)
	{
		List<String> out = new ArrayList<>();
		if (name == null || name.isEmpty())
		{
			return out;
		}
		if (fm.stringWidth(name) <= width)
		{
			out.add(name);
			return out;
		}
		String[] words = name.split(" ");
		StringBuilder first = new StringBuilder(words[0]);
		int i = 1;
		while (i < words.length && fm.stringWidth(first + " " + words[i]) <= width)
		{
			first.append(' ').append(words[i++]);
		}
		out.add(clip(first.toString(), fm, width));
		if (i < words.length)
		{
			StringBuilder rest = new StringBuilder(words[i++]);
			while (i < words.length)
			{
				rest.append(' ').append(words[i++]);
			}
			out.add(clip(rest.toString(), fm, width));
		}
		return out;
	}

	private static String clip(String s, FontMetrics fm, int width)
	{
		if (s == null)
		{
			return "";
		}
		if (fm.stringWidth(s) <= width)
		{
			return s;
		}
		String out = s;
		while (out.length() > 1 && fm.stringWidth(out.trim() + "…") > width)
		{
			out = out.substring(0, out.length() - 1);
		}
		return out.trim() + "…";
	}
}

package com.codex.loginsight.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	/**
	 * A label wrapped to the width and cut to at most this many lines, the last ending in an
	 * ellipsis when the text runs on. Long names stay tidy instead of growing a card.
	 */
	public static JLabel clamped(String text, Font font, Color color, int width, int lines)
	{
		JLabel label = label("", font, color);
		java.awt.FontMetrics fm = label.getFontMetrics(font);
		java.util.List<String> out = new java.util.ArrayList<>();
		StringBuilder line = new StringBuilder();
		String[] words = text.split(" ");
		int i = 0;
		while (i < words.length && out.size() < lines)
		{
			String next = line.length() == 0 ? words[i] : line + " " + words[i];
			if (fm.stringWidth(next) <= width || line.length() == 0)
			{
				line = new StringBuilder(next);
				i++;
			}
			else
			{
				out.add(line.toString());
				line = new StringBuilder();
			}
		}
		if (line.length() > 0 && out.size() < lines)
		{
			out.add(line.toString());
		}
		if (i < words.length || fm.stringWidth(out.get(out.size() - 1)) > width)
		{
			String last = out.get(out.size() - 1);
			while (last.length() > 1 && fm.stringWidth(last + "…") > width)
			{
				last = last.substring(0, last.length() - 1).trim();
			}
			out.set(out.size() - 1, last + "…");
		}
		StringBuilder html = new StringBuilder("<html>");
		for (int k = 0; k < out.size(); k++)
		{
			html.append(k == 0 ? "" : "<br>").append(escape(out.get(k)));
		}
		label.setText(html.append("</html>").toString());
		label.setToolTipText(text);
		return label;
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}
}

package com.codex.loginsight;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Test;

/** Every setting has a short name, one plain sentence, a section and a place of its own, worded as across the suite. */
public class SettingsTest
{
	@Test
	public void everySettingIsNamedAndPlacedClearly()
	{
		Set<String> sections = new HashSet<>();
		for (Field f : CodexLogInsightConfig.class.getFields())
		{
			if (f.isAnnotationPresent(ConfigSection.class))
			{
				ConfigSection section = f.getAnnotation(ConfigSection.class);
				assertFalse(section.name().isEmpty());
				assertFalse(section.description().isEmpty());
				try
				{
					sections.add((String) f.get(null));
				}
				catch (IllegalAccessException e)
				{
					throw new AssertionError(e);
				}
			}
		}
		Set<String> places = new HashSet<>();
		Set<String> names = new HashSet<>();
		for (Method m : CodexLogInsightConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item == null || item.hidden())
			{
				continue;
			}
			String name = item.name();
			String description = item.description();
			assertTrue(m.getName(), !name.isEmpty() && name.length() <= 26);
			assertTrue(m.getName(), names.add(name));
			assertTrue(m.getName(), Character.isUpperCase(name.charAt(0)) && !name.endsWith("."));
			assertTrue(m.getName(), description.length() >= 20 && description.length() <= 200);
			assertTrue(m.getName(), Character.isUpperCase(description.charAt(0)) && !description.endsWith("."));
			assertTrue(m.getName() + " has no section", sections.isEmpty() || sections.contains(item.section()));
			assertTrue(m.getName() + " shares its place", places.add(item.section() + "#" + item.position()));
			if ("nameOnCard".equals(item.keyName()))
			{
				assertEquals("Name on cards", name);
			}
			if ("worthOnCard".equals(item.keyName()))
			{
				assertEquals("Worth on cards", name);
			}
		}
		assertFalse(names.isEmpty());
	}

	@Test
	public void savedSettingsKeepTheirKeys()
	{
		// A setting's key is where its value is saved: renaming one quietly resets it for every player who changed it.
		Set<String> keys = new HashSet<>();
		for (Method m : CodexLogInsightConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				keys.add(item.keyName());
			}
		}
		for (String key : new String[]{"chatLine", "dryMilestones", "grindCard", "learnPace", "nameOnCard", "plaqueSeconds", "rates", "showPlaque"})
		{
			assertTrue(key, keys.contains(key));
		}
	}
}

package com.codex.loginsight.core;

import static org.junit.Assert.assertEquals;
