	@Test
	public void eachActivityBecomesAProspectForPlanning()
	{
		Report report = new Analyst(data).analyse(structure, new Progress(), false, true, -1, -1);
		assertEquals(1, report.getProspects().size());
		Prospect beast = report.getProspects().get(0);
		assertEquals(5, beast.getRemaining());
		assertEquals(50, beast.getPerHour(), 1e-9);
		// The next slot's wait the hunt shows and the prospect's chance of any slot agree.
		Report.Hunt hunt = report.getHunts().get(0);
		assertEquals(1 - Math.exp(-1), beast.chanceOfAny(hunt.getHoursToNext()), 0.03);
		// In a very long stretch every slot turns up.
		assertEquals(5, beast.expectedSlots(10_000), 1e-3);
	}

	@Test
	public void missingPetsArePlannedAtTheirSource()
	{
		Progress progress = new Progress();
		progress.addOwned(HEAD);
		Report report = new Analyst(data).analyse(structure, progress, false, true, -1, -1);
		assertEquals(1, report.getPets().size());
		PetPlan pet = report.getPets().get(0);
		assertEquals(PET, pet.getItemId());
		assertEquals("Beast", pet.getPage());
		assertEquals(Math.log(0.5) / Math.log(1 - 1 / 1000.0) / 50, pet.getMedian(), 1e-6);
		assertEquals(Math.log(0.1) / Math.log(1 - 1 / 1000.0) / 50, pet.getLikely(), 1e-6);
		// Half of all players see the pet after about 693 kills, by which the shield, spine and claw are near certain.
		assertEquals(3, pet.slotsAlongside(), 0.05);
		progress.addOwned(PET);
		assertTrue(new Analyst(data).analyse(structure, progress, false, true, -1, -1).getPets().isEmpty());
	}

	@Test
	public void aPetIsPlannedWhereTheAccountCanHuntIt()
	{
		// The pet drops quicker at hydra, but with 80 Slayer the plan points at cows.
		List<Activity.Drop> easy = Collections.singletonList(new Activity.Drop(0, 21, 1000, 0));
		List<Activity.Drop> hard = Collections.singletonList(new Activity.Drop(1, 21, 100, 0));
		Activity cows = new Activity(0, "Killing cows", Activity.Category.COMBAT, 100, 100, 0, easy);
		Activity hydra = new Activity(1, "Killing hydra", Activity.Category.COMBAT, 100, 100, 0, hard,
			Collections.singletonMap("SLAYER", 95), Collections.emptyList());
		LogData both = new LogData(Arrays.asList(cows, hydra), Collections.emptyList(), new HashMap<>(), Collections.singleton(21));
		LogStructure log = new LogStructure(Collections.singletonList(new LogStructure.Tab("Bosses",
			Collections.singletonList(new LogStructure.Page("Bosses", "Mixed", Collections.singletonList(21))))), new HashMap<>());
		Analyst analyst = new Analyst(both);
		assertEquals("Killing hydra", analyst.analyse(log, new Progress(), false, true, -1, -1).getPets().get(0).getSource());
		Unlocks low = new Unlocks(Collections.singletonMap("SLAYER", 80), Collections.emptySet());
		PetPlan pet = analyst.analyse(log, new Progress(), false, true, -1, -1, low).getPets().get(0);
		assertEquals("Killing cows", pet.getSource());
		assertNull(pet.getLockedBy());
	}

	@Test
	public void pagesProjectWhenTheyAreLikelyFinished()
	{
		Report report = new Analyst(data).analyse(structure, new Progress(), false, true, -1, -1);
		Report.PageReport page = report.getPages().get(0);
		Projection projection = page.getProjection();
		assertNotNull(projection);
		// The pet at 1 in 1000 sets the pace: the page is done no sooner than the pet alone would be.
		double pet = Math.log(0.5) / Math.log(1 - 1 / 1000.0) / 50;
		assertTrue(projection.getMedian() >= pet);
		assertTrue(projection.getMedian() < pet * 1.3);
		assertTrue(projection.getLikely() > projection.getMedian());
		// The mean the page shows lies between the median and the nine-in-ten mark for a right-skewed wait.
		assertTrue(page.getHoursToFinish() > projection.getMedian());
		assertTrue(page.getHoursToFinish() < projection.getLikely());

		Progress all = new Progress();
		for (int id = PET; id <= CLAW; id++)
		{
			all.addOwned(id);
		}
		assertNull(new Analyst(data).analyse(structure, all, false, true, -1, -1).getPages().get(0).getProjection());
	}

	// ---- Wanted ----

	@Test
	public void wantedSlotsAreReportedWithTheirMarksAndLeaveTheListWhenFound()
	{
		Progress p = new Progress();
		p.setCounter("Beast kills", 40);
		assertTrue(p.toggleWanted(HEAD));
		assertTrue(p.toggleWanted(PET));
		Report report = new Analyst(data).analyse(structure, p, false, true, -1, -1);
		assertEquals(2, report.getWanted().size());
		Report.ItemReport head = report.getWanted().get(0);
		assertEquals(HEAD, head.getItemId());
		assertEquals("Beast", head.getPage());
		assertTrue(report.isWanted(PET));
		// 1 in 100: half of players by 69 kills, nine in ten by 230.
		assertEquals(69, Wanted.countFor(head, 0.5));
		assertEquals(29, Wanted.moreUntil(head, 0.5));
		assertEquals(190, Wanted.moreUntil(head, 0.9));
		// Alone at 50 kills an hour, 100 kills are 2 hours on average: even odds after 2 ln 2 hours.
		assertEquals(2.0, head.getHours(), 1e-9);
		assertEquals(2 * Math.log(2), Wanted.evenChanceHours(head), 1e-9);
		assertEquals(1 - Math.exp(-1), Wanted.chanceWithin(head, 2), 1e-9);

		// Found: off the list, and a slot already owned cannot be wanted.
		p.addOwned(HEAD);
		assertEquals(Collections.singletonList(PET), p.getWanted());
		assertTrue(!p.toggleWanted(HEAD));
		report = new Analyst(data).analyse(structure, p, false, true, -1, -1);
		assertEquals(1, report.getWanted().size());
		// Clicking again takes it off.
		assertTrue(p.toggleWanted(PET));
		assertTrue(p.getWanted().isEmpty());
		// Attaching the session keeps the wanted list.
		assertEquals(1, new Analyst(data).analyse(structure, copyWanting(PET), false, true, -1, -1).withSession(null).getWanted().size());
	}

	private static Progress copyWanting(int id)
	{
		Progress p = new Progress();
		p.toggleWanted(id);
		return p.copy();
	}

	@Test
	public void theWantedListIsShortAndOlderSavesReadWithoutIt()
	{
		Progress p = new Progress();
		for (int id = 100; id < 100 + Progress.MAX_WANTED; id++)
		{
			assertTrue(p.toggleWanted(id));
		}
		assertTrue(!p.toggleWanted(999));
		assertEquals(Progress.MAX_WANTED, p.getWanted().size());
		com.google.gson.Gson gson = new com.google.gson.Gson();
		Progress back = gson.fromJson(gson.toJson(p), Progress.class);
		assertEquals(p.getWanted(), back.getWanted());
		Progress old = gson.fromJson("{\"owned\":[1],\"counters\":{}}", Progress.class);
		assertTrue(old.getWanted().isEmpty());
		assertTrue(old.toggleWanted(2));
		// A slot nobody can time still reports what it can.
		Report.ItemReport unknown = new Report.ItemReport(7, "Mystery", null, false, false, 0, null, -1, -1, null,
			Double.POSITIVE_INFINITY);
		assertEquals(-1, Wanted.countFor(unknown, 0.5));
		assertEquals(-1, Wanted.moreUntil(unknown, 0.5));
		assertEquals(-1, Wanted.evenChanceHours(unknown), 0);
		assertEquals(-1, Wanted.chanceWithin(unknown, 1), 0);
	}
}

package com.codex.loginsight.core;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.codex.loginsight.core.Announcements.Channel;
import org.junit.Test;

public class AnnouncementsTest
{
	@Test
	public void casketWithTwoNewSlotsIsCountedOnceEach()
	{
		// Chat announces both at once; the pop-ups queue and arrive one after another.
		Announcements a = new Announcements();
		assertTrue(a.fresh("Ranger boots", Channel.CHAT, 0));
		assertTrue(a.fresh("Robin hood hat", Channel.CHAT, 0));
		assertFalse(a.fresh("Ranger boots", Channel.POPUP, 3_000));
		assertFalse(a.fresh("Robin hood hat", Channel.POPUP, 14_000));
	}

	@Test
	public void popupOnlyPlayersStillGetEverySlot()
	{
		Announcements a = new Announcements();
		assertTrue(a.fresh("Ranger boots", Channel.POPUP, 0));
		assertTrue(a.fresh("Robin hood hat", Channel.POPUP, 5_000));
	}

	@Test
	public void popupBeforeChatIsAlsoMatched()
	{
		Announcements a = new Announcements();
		assertTrue(a.fresh("Pet snakeling", Channel.POPUP, 0));
		assertFalse(a.fresh("pet snakeling", Channel.CHAT, 600));
		// A later, separate announcement of a same-named slot is new again.
		assertTrue(a.fresh("Pet snakeling", Channel.POPUP, 1_000));
	}

	@Test
	public void oldAnnouncementsExpire()
	{
		Announcements a = new Announcements();
		assertTrue(a.fresh("Dragon pickaxe", Channel.CHAT, 0));
		assertTrue(a.fresh("Dragon pickaxe", Channel.POPUP, Announcements.WINDOW_MS + 1));
	}
}

package com.codex.loginsight.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import org.junit.Test;

public class ChatReaderTest
{
	private final ChatReader reader = new ChatReader(Arrays.asList(
		"Vorkath kills", "Chambers of Xeric completions", "Hard clues completed", "Barrows Chests opened",
		"Theatre of Blood (Hard) completions", "Corrupted Gauntlet completion count", "Kree'arra kills", "Grotesque Guardian kills",
		"Grand Hallowed Coffins opened", "Rifts closed", "Rumours Completed", "Royal Titan kills"));

	@Test
	public void readsBossKillCounts()
	{
		ChatReader.Count count = reader.count("Your Vorkath kill count is: <col=ff0000>1,203</col>.");
		assertEquals("Vorkath kills", count.label);
		assertEquals(1203, count.value);
		assertEquals("Kree'arra kills", reader.count("Your Kree'arra kill count is: 50.").label);
	}

	@Test
	public void readsRaidsAndSpecialNames()
	{
		ChatReader.Count cox = reader.count("Your completed Chambers of Xeric count is: <col=ff0000>87</col>.");
		assertEquals("Chambers of Xeric completions", cox.label);
		assertEquals(87, cox.value);
		assertEquals("Theatre of Blood (Hard) completions",
			reader.count("Your completed Theatre of Blood: Hard Mode count is: 12.").label);
		assertEquals("Barrows Chests opened", reader.count("Your Barrows chest count is: 310.").label);
		assertEquals("Corrupted Gauntlet completion count",
			reader.count("Your Corrupted Gauntlet completion count is: 44.").label);
	}

	@Test
	public void readsPluralBossNamesAndOtherCounters()
	{
		assertEquals("Grotesque Guardian kills", reader.count("Your Grotesque Guardians kill count is: 51.").label);
		assertEquals("Royal Titan kills", reader.count("Your Royal Titans kill count is: 8.").label);
		ChatReader.Count coffins = reader.count("You have opened the Grand Hallowed Coffin <col=ff0000>1,204</col> times!");
		assertEquals("Grand Hallowed Coffins opened", coffins.label);
		assertEquals(1204, coffins.value);
		assertEquals(330, reader.count("Amount of Rifts you have closed: <col=ff0000>330</col>.").value);
		assertEquals("Rumours Completed", reader.count("You have completed <col=ef1020>88</col> rumours for the Hunter Guild.").label);
	}

	@Test
	public void findsCountsSavedByChatCommands()
	{
		// RuneLite saves the name as the message gives it: "Barrows Chests", "Theatre of Blood Hard Mode".
		assertTrue(ChatReader.savedKeys("Barrows Chests opened").contains("barrows chests"));
		assertTrue(ChatReader.savedKeys("Theatre of Blood (Hard) completions").contains("theatre of blood hard mode"));
		assertTrue(ChatReader.savedKeys("Grotesque Guardian kills").contains("grotesque guardians"));
		assertEquals("vorkath", ChatReader.savedKeys("Vorkath kills").get(0));
	}

	@Test
	public void readsClueCounts()
	{
		ChatReader.Count clues = reader.count("You have completed 312 hard Treasure Trails.");
		assertEquals("Hard clues completed", clues.label);
		assertEquals(312, clues.value);
	}

	@Test
	public void ignoresOtherMessages()
	{
		assertNull(reader.count("Your Unknown Beast kill count is: 4."));
		assertNull(reader.count("Welcome to Old School RuneScape."));
	}

	@Test
	public void readsNewSlots()
	{
		assertEquals("Vorki", ChatReader.newSlot("New item added to your collection log: <col=ef1020>Vorki</col>"));
		assertNull(ChatReader.newSlot("You feel something weird sneaking into your backpack."));
	}

	@Test
	public void readsPageCounters()
	{
		ChatReader.Count line = ChatReader.pageCounter("Vorkath kills: <col=ff0000>312</col>");
		assertEquals("Vorkath kills", line.label);
		assertEquals(312, line.value);
		assertNull(ChatReader.pageCounter("Obtained: <col=ff0000>3/6</col>"));
	}

	@Test
	public void baseMatchesChatCommandKeys()
	{
		assertEquals("vorkath", ChatReader.base("Vorkath kills"));
		assertEquals("chambers of xeric", ChatReader.base("Chambers of Xeric completions"));
		assertEquals("corrupted gauntlet", ChatReader.base("Corrupted Gauntlet completion count"));
	}
}

package com.codex.loginsight.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.codex.loginsight.data.Activity;
import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import com.codex.loginsight.ui.Format;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

/**
 * The saved progress is read back from empty, cut-off, wrong-type, huge, negative, future-version and garbage values
 * without throwing, keeps whatever good part there is, and says when anything was left out so the saved text is kept
 * aside rather than written over. A whole log, owned or not, at absurd kill counts is analysed quickly and sensibly.
 */
public class DamagedDataTest
{
	private static final Gson GSON = new Gson();

	static List<String> garbage()
	{
		StringBuilder deep = new StringBuilder();
		for (int i = 0; i < 200; i++)
		{
			deep.append("{\"a\":");
		}
		StringBuilder longText = new StringBuilder("\"");
		for (int i = 0; i < 100_000; i++)
		{
			longText.append('x');
		}
		longText.append('"');
		return Arrays.asList(null, "", " ", "null", "{", "[", "{\"owned\":", "\"", "garbage", "{}", "[]", "0", "-1", "true",
			"NaN", "1e999999", "[null]", "{\"owned\":5}", "{\"owned\":[null,\"x\",1e100000000,-3]}", "{\"counters\":{\"Vorkath kills\":-7}}",
			"{\"finds\":[null,5,{}]}", "{\"trophies\":[null,{\"chance\":\"rare\"}]}", "{\"wanted\":[null,null,1,1,2,3,4,5,6,7,8]}",
			"{\"pace\":{\"Vorkath kills\":null,\"Zulrah kills\":{\"secondsPerCount\":-5,\"samples\":3}}}",
			"{\"pageLabels\":{\"Vorkath\":[null]}}", "{\"version\":9,\"slots\":{\"owned\":[1]}}", "\u0000\u0001", "<html>",
			deep.toString(), longText.toString());
	}

	private static Progress progress()
	{
		Progress p = new Progress();
		p.addOwned(22006);
		p.addOwned(21992);
		p.setCounter("Vorkath kills", 215);
		p.setCounter("Zulrah kills", 480);
		p.toggleWanted(11286);
		p.addFind(new Progress.Find(21992, "Vorki", "Vorkath", "Vorkath kills", 120, 1 / 3000.0, 0.96, 1_760_000_000_000L));
		p.paceFor("Vorkath kills").record(10, 1_000_000);
		p.paceFor("Vorkath kills").record(11, 1_150_000);
		return p;
	}

	@Test
	public void progressSurvivesAnySavedValue()
	{
		for (String value : garbage())
		{
			SavedJson.Read<Progress> read = Progress.load(GSON, value);
			Progress p = read.getValue() == null ? new Progress() : read.getValue();
			// Every reader the panel and the analysis use must work on what was loaded.
			p.copy();
			for (Integer id : p.getOwned())
			{
				assertNotNull(value, id);
			}
			for (Map.Entry<String, Integer> e : p.getCounters().entrySet())
			{
				assertTrue(value, e.getKey() != null && e.getValue() != null && e.getValue() >= 0);
			}
			for (Progress.Find f : p.getFinds())
			{
				assertNotNull(value, f);
			}
			p.getTrophies();
			assertTrue(value, p.getWanted().size() <= Progress.MAX_WANTED && !p.getWanted().contains(null));
			new Session(p.getOwned(), 0);
			boolean saved = value != null && !value.trim().isEmpty();
			if (saved && read.getValue() == null)
			{
				assertTrue(value, read.isDamaged());
			}
		}
	}

	@Test
	public void oneBadFieldNeverLosesTheLog()
	{
		// One field of the wrong type used to fail the whole save, and the next change saved an empty log over it.
		JsonObject saved = GSON.toJsonTree(progress()).getAsJsonObject();
		saved.addProperty("fullReadAt", "yesterday");
		saved.getAsJsonArray("owned").add("not an item");
		saved.getAsJsonObject("counters").addProperty("Zulrah kills", "lots");
		JsonArray finds = saved.getAsJsonArray("finds");
		finds.add(5);
		SavedJson.Read<Progress> read = Progress.load(GSON, GSON.toJson(saved));
		assertTrue(read.isDamaged());
		Progress p = read.getValue();
		assertNotNull(p);
		assertEquals(new LinkedHashSet<>(Arrays.asList(22006, 21992)), new LinkedHashSet<>(p.getOwned()));
		assertEquals(Integer.valueOf(215), p.counter("Vorkath kills"));
		assertEquals(null, p.counter("Zulrah kills"));
		assertEquals(Collections.singletonList(11286), p.getWanted());
		assertEquals(1, p.getFinds().size());
		assertEquals(1, p.pace("Vorkath kills").getSamples());
		assertFalse(Progress.load(GSON, GSON.toJson(progress())).isDamaged());
	}

	@Test
	public void fieldsFromANewerLogInsightAreKeptAside()
	{
		// A newer Log Insight adds a field to the save and to a find. Gson reads past both without an error, so the
		// read used to say nothing was left out and the next save wrote over them for good.
		JsonObject saved = GSON.toJsonTree(progress()).getAsJsonObject();
		saved.addProperty("sailingLog", 3);
		assertTrue(Progress.load(GSON, GSON.toJson(saved)).isDamaged());
		JsonObject inFind = GSON.toJsonTree(progress()).getAsJsonObject();
		inFind.getAsJsonArray("finds").get(0).getAsJsonObject().addProperty("world", 302);
		SavedJson.Read<Progress> read = Progress.load(GSON, GSON.toJson(inFind));
		assertTrue(read.isDamaged());
		assertEquals(1, read.getValue().getFinds().size());
		// More finds than this version keeps are trimmed, so they are kept aside too.
		JsonObject many = GSON.toJsonTree(progress()).getAsJsonObject();
		JsonArray finds = many.getAsJsonArray("finds");
		for (int i = 0; i < 60; i++)
		{
			finds.add(finds.get(0).deepCopy());
		}
		assertTrue(Progress.load(GSON, GSON.toJson(many)).isDamaged());
		// What this version writes reads back whole, so a normal save is never kept aside.
		assertFalse(Progress.load(GSON, GSON.toJson(progress())).isDamaged());
	}

	@Test
	public void absurdFiguresAreBroughtBackToSense()
	{
		Progress p = Progress.load(GSON, "{\"owned\":[1,null,2],\"counters\":{\"Vorkath kills\":-7,\"Zulrah kills\":2147483647},"
			+ "\"wanted\":[null,1,3,3,4,5,6,7,8,9],\"pace\":{\"Zulrah kills\":{\"secondsPerCount\":-5,\"samples\":3},\"Vorkath kills\":null},"
			+ "\"finds\":[null,{\"itemId\":4,\"chance\":0.001,\"luckier\":0.5}],\"trophies\":[null]}").getValue();
		assertFalse(p.getOwned().contains(null));
		assertEquals(null, p.counter("Vorkath kills"));
		assertEquals(Integer.valueOf(Integer.MAX_VALUE), p.counter("Zulrah kills"));
		// Owned slots can't be wanted; the list keeps its own limit.
		assertEquals(Arrays.asList(3, 4, 5, 6, 7, 8), p.getWanted());
		assertEquals(0, p.pace("Zulrah kills") == null ? 0 : p.pace("Zulrah kills").perHour(), 0);
		assertEquals(1, p.getFinds().size());
		assertEquals(1, p.getTrophies().size());
	}

	@Test
	public void aGuaranteedSlotStillMissingReadsAsOverdueNotAHundredPercentDry()
	{
		// Vorkath's head comes by the 50th kill; at 215 kills without it the row read "100% dry" beside ">99% dry".
		ItemOdds head = new ItemOdds(Collections.singletonList(new ItemOdds.Roll("Vorkath kills", 1 / 50.0, 1)), 50);
		double stillWaiting = head.dryChance(Collections.singletonMap("Vorkath kills", 215));
		assertEquals("Overdue", Format.dry(stillWaiting));
		// A slot merely astronomically dry is still ">99% dry", never "Overdue" or "100% dry".
		ItemOdds rare = new ItemOdds(Collections.singletonList(new ItemOdds.Roll("Zulrah kills", 1 / 50.0, 1)), 0);
		double dry = rare.dryChance(Collections.singletonMap("Zulrah kills", 200_000));
		assertTrue(dry > 0);
		assertEquals(">99% dry", Format.dry(dry));
		assertEquals(">99% dry", Format.dry(1e-9));
	}

	@Test
	public void aWholeLogAtAbsurdCountsIsAnalysedQuickly() throws Exception
	{
		LogData data = LogData.load(GSON);
		// Every slot the tables know, one page per activity.
		List<LogStructure.Page> pages = new ArrayList<>();
		Map<Integer, String> names = new HashMap<>();
		Set<Integer> all = new LinkedHashSet<>();
		for (Activity a : data.getActivities())
		{
			List<Integer> items = new ArrayList<>();
			for (Activity.Drop d : a.getDrops())
			{
				if (all.add(d.getItemId()))
				{
					items.add(d.getItemId());
					names.put(d.getItemId(), "Item " + d.getItemId());
				}
			}
			if (!items.isEmpty())
			{
				pages.add(new LogStructure.Page("Bosses", a.getName() + " " + a.getIndex(), items));
			}
		}
		LogStructure structure = new LogStructure(Collections.singletonList(new LogStructure.Tab("Bosses", pages)), names);
		assertTrue(all.size() > 1_000);
		Analyst analyst = new Analyst(data);

		Progress fresh = new Progress();
		Progress maxed = new Progress();
		Progress absurd = new Progress();
		for (int id : all)
		{
			maxed.addOwned(id);
		}
		for (String label : data.getLabels())
		{
			maxed.setCounter(label, 5_000);
			absurd.setCounter(label, Integer.MAX_VALUE);
		}
		for (Progress p : Arrays.asList(fresh, maxed, absurd))
		{
			analyst.analyse(structure, p, false, true, 0, all.size());
			long start = System.nanoTime();
			Progress copy = p.copy();
			long copyMs = (System.nanoTime() - start) / 1_000_000;
			start = System.nanoTime();
			Report report = analyst.analyse(structure, copy, false, true, 0, all.size());
			long ms = (System.nanoTime() - start) / 1_000_000;
			System.out.println(all.size() + " slots, " + p.getOwned().size() + " owned: copy " + copyMs + " ms, analysis " + ms + " ms");
			assertTrue(copyMs + " ms", copyMs < 10);
			assertTrue(ms + " ms", ms < 2_000);
			assertTrue(Double.isFinite(report.getHoursLeft()) && report.getHoursLeft() >= 0);
			for (Report.ItemReport item : report.getDriest())
			{
				assertFalse(Format.dry(item.getDryChance()), Format.dry(item.getDryChance()).startsWith("-"));
			}
		}
		// A long save round-trips quickly.
		String json = GSON.toJson(maxed);
		long start = System.nanoTime();
		assertEquals(all.size(), Progress.load(GSON, json).getValue().getOwned().size());
		assertTrue((System.nanoTime() - start) / 1_000_000 < 50);
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.Activity;
import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class DropsTest
{
	private static final int PET = 1;
	private static final int HEAD = 2;
	private static final int SHIELD = 3;
	private static final int STACK = 4;

	private final LogData data = data();
	private final LogStructure structure = new LogStructure(Collections.singletonList(new LogStructure.Tab("Bosses",
		Collections.singletonList(new LogStructure.Page("Bosses", "Beast", Arrays.asList(PET, HEAD, SHIELD, STACK))))),
		names());

	private static LogData data()
	{
		List<Activity.Drop> drops = Arrays.asList(
			new Activity.Drop(0, PET, 1000, 0),
			new Activity.Drop(0, HEAD, 100, 0),
			new Activity.Drop(0, SHIELD, 50, 0),
			new Activity.Drop(0, STACK, 10, 0));
		Activity beast = new Activity(0, "Killing the beast", Activity.Category.COMBAT, 50, 40, 0, drops);
		Map<Integer, ItemOdds> odds = new HashMap<>();
		odds.put(PET, odds(1000, true));
		odds.put(HEAD, odds(100, true));
		odds.put(SHIELD, odds(50, true));
		// A stack: the log's count says nothing about how many rolls came good.
		odds.put(STACK, odds(10, false));
		return new LogData(Collections.singletonList(beast), Collections.singletonList("Beast kills"), odds,
			Collections.singleton(PET));
	}

	private static ItemOdds odds(double in, boolean countable)
	{
		return new ItemOdds(Collections.singletonList(new ItemOdds.Roll("Beast kills", 1 / in, 1)), 0, countable);
	}

	private static Map<Integer, String> names()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(PET, "Beastling");
		names.put(HEAD, "Beast head");
		names.put(SHIELD, "Beast shield");
		names.put(STACK, "Beast bones");
		return names;
	}

	private Progress greenPage(int heads, int shields)
	{
		Progress progress = new Progress();
		progress.setCounter("Beast kills", 1000);
		for (int id : new int[]{PET, HEAD, SHIELD, STACK})
		{
			progress.addOwned(id);
		}
		progress.setObtained(PET, 3);
		progress.setObtained(HEAD, heads);
		progress.setObtained(SHIELD, shields);
		progress.setObtained(STACK, 400);
		progress.setFullReadAt(1);
		return progress;
	}

	@Test
	public void aGreenPageStillSaysHowLuckyItsDropsWere()
	{
		// 1,000 kills: 10 heads and 20 shields on average. Pets and stacks are not counted.
		Report.PageReport lucky = new Analyst(data).analyse(structure, greenPage(14, 26), false, true, -1, -1).getPages().get(0);
		Drops drops = lucky.getDrops();
		assertNotNull(drops);
		assertEquals(40, drops.getGot());
		assertEquals(30, drops.getExpected(), 1e-9);
		assertEquals(2, drops.getSlots());
		assertTrue(drops.getPercentile() > 0.9);

		Drops dry = new Analyst(data).analyse(structure, greenPage(4, 9), false, true, -1, -1).getPages().get(0).getDrops();
		assertTrue(dry.getPercentile() < 0.05);
	}

	@Test
	public void anOwnedSlotWithItsCountUnreadGivesNoReading()
	{
		Progress progress = greenPage(14, 26);
		Progress fresh = new Progress();
		fresh.setCounter("Beast kills", 1000);
		fresh.addOwned(HEAD);
		fresh.addOwned(SHIELD);
		fresh.setObtained(HEAD, 11);
		fresh.markPageRead("Beast", 1);
		// The shield is owned but its count was never read: guessing one would read as dry.
		assertNull(new Analyst(data).analyse(structure, fresh, false, true, -1, -1).getPages().get(0).getDrops());
		assertNotNull(new Analyst(data).analyse(structure, progress, false, true, -1, -1).getDrops());
	}

	@Test
	public void theTileKnowsItsCopiesAndTheAverage()
	{
		Report.PageReport page = new Analyst(data).analyse(structure, greenPage(14, 26), false, true, -1, -1).getPages().get(0);
		for (Report.ItemReport item : page.getItems())
		{
			if (item.getItemId() == HEAD)
			{
				assertEquals(14, item.getObtained());
				assertEquals(10, item.getExpectedCount(), 1e-9);
			}
			if (item.getItemId() == PET || item.getItemId() == STACK)
			{
				assertEquals(-1, item.getExpectedCount(), 0);
			}
		}
	}

	@Test
	public void anUnreadLogSaysNothingAboutLuck()
	{
		// Kill counts seen in chat, but neither the log nor the page read: every slot would read as missing.
		Progress progress = new Progress();
		progress.setCounter("Beast kills", 1000);
		Report report = new Analyst(data).analyse(structure, progress, false, true, -1, -1);
		assertNull(report.getDrops());
		assertNull(report.getLuck());
		assertNull(report.getPages().get(0).getDrops());
	}

	@Test
	public void countsAreSetAgainstTheKillsTheyWereReadAt()
	{
		Progress progress = greenPage(10, 20);
		progress.setCounter("Beast kills", 1000);
		progress.setObtained(HEAD, 10, Collections.singletonList("Beast kills"));
		progress.setObtained(SHIELD, 20, Collections.singletonList("Beast kills"));
		// A thousand more kills with no read: the game announces no second copies, so the log's counts stand still.
		progress.setCounter("Beast kills", 2000);
		Drops drops = new Analyst(data).analyse(structure, progress, false, true, -1, -1).getDrops();
		assertEquals(30, drops.getExpected(), 1e-9);
		assertTrue(drops.getPercentile() > 0.4 && drops.getPercentile() < 0.6);
		Progress back = Progress.load(new Gson(), new Gson().toJson(progress)).getValue();
		assertEquals(1000, (int) back.countedAt(HEAD).get("Beast kills"));
	}

	@Test
	public void aSlotWithAnUncountedSourceIsLeftOut()
	{
		ItemOdds twoSources = new ItemOdds(Arrays.asList(new ItemOdds.Roll("Beast kills", 0.01, 1),
			new ItemOdds.Roll("Other kills", 0.01, 1)), 0, true);
		assertEquals(-1, twoSources.expectedCount(Collections.singletonMap("Beast kills", 100)), 0);
		Map<String, Integer> both = new HashMap<>();
		both.put("Beast kills", 100);
		both.put("Other kills", 100);
		assertEquals(2, twoSources.expectedCount(both), 1e-9);
	}

	@Test
	public void percentileMatchesThePoissonCount()
	{
		assertEquals(0.5, Odds.dropPercentile(0, 0), 0);
		// Mean 1: P(0) = 0.3679, P(1) = 0.3679; one drop sits at 0.3679 + 0.3679 / 2.
		assertEquals(0.3679 + 0.3679 / 2, Odds.dropPercentile(1, 1), 1e-3);
		// A huge mean never underflows to nonsense.
		double mid = Odds.dropPercentile(5000, 5000);
		assertTrue(mid > 0.45 && mid < 0.55);
	}

	@Test
	public void countsSurviveASaveAndAWholeLogRead()
	{
		Progress progress = greenPage(14, 26);
		Gson gson = new Gson();
		Progress back = Progress.load(gson, gson.toJson(progress)).getValue();
		assertEquals(14, back.obtained(HEAD));
		back.replaceOwned(new java.util.HashSet<>(Arrays.asList(HEAD, PET)));
		assertEquals(0, back.obtained(SHIELD));
		assertEquals(14, back.obtained(HEAD));
		assertEquals(14, back.copy().obtained(HEAD));
		// Nothing the game could not have saved is kept.
		assertTrue(!back.setObtained(HEAD, 0));
	}
}

package com.codex.loginsight.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.codex.loginsight.data.Activity;
import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import org.junit.Test;

/** The in-game card for the page you are grinding. */
public class GrindTest
{
	private static final int PET = 1;
	private static final int HEAD = 2;
	private static final int SHIELD = 3;

	private final LogData data = data();
	private final LogStructure structure = new LogStructure(Collections.singletonList(new LogStructure.Tab("Bosses",
		Collections.singletonList(new LogStructure.Page("Bosses", "Beast", Arrays.asList(PET, HEAD, SHIELD))))), names());

	private static LogData data()
	{
		Activity beast = new Activity(0, "Killing the beast", Activity.Category.COMBAT, 50, 40, 0, Arrays.asList(
			new Activity.Drop(0, PET, 1000, 0), new Activity.Drop(0, HEAD, 100, 0), new Activity.Drop(0, SHIELD, 50, 0)));
		Map<Integer, ItemOdds> odds = new HashMap<>();
		odds.put(PET, new ItemOdds(Collections.singletonList(new ItemOdds.Roll("Beast kills", 1 / 1000.0, 1)), 0));
		odds.put(HEAD, new ItemOdds(Collections.singletonList(new ItemOdds.Roll("Beast kills", 1 / 100.0, 1)), 0));
		odds.put(SHIELD, new ItemOdds(Collections.singletonList(new ItemOdds.Roll("Beast kills", 1 / 50.0, 1)), 0));
		return new LogData(Collections.singletonList(beast), Collections.singletonList("Beast kills"), odds,
			Collections.singleton(PET));
	}

	private static Map<Integer, String> names()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(PET, "Beastling");
		names.put(HEAD, "Beast head");
		names.put(SHIELD, "Beast shield");
		return names;
	}

	@Test
	public void theCardWatchesTheDriestSlotUnlessOneIsWanted()
	{
		Progress p = new Progress();
		p.setCounter("Beast kills", 120);
		p.addOwned(SHIELD);
		p.markPageRead("Beast", 1);
		Session session = new Session(new HashSet<>(p.getOwned()), 0);
		session.observe("Beast kills", 100, true);
		session.observe("Beast kills", 120, true);
		Report report = new Analyst(data).analyse(structure, p, false, true, -1, -1).withSession(session.read(data, p, 60_000));
		Grind grind = Grind.of(report, "Beast kills", 1_000);
		assertEquals("Beast", grind.getPage());
		assertEquals(120, grind.getCount());
		// The first kill message of a session counts its own kill too.
		assertEquals(21, grind.getAdded());
		assertEquals(2, grind.getMissing());
		// At 120 kills the 1 in 100 head is far drier than the 1 in 1,000 pet.
		assertEquals(HEAD, grind.getFocus().getItemId());
		assertFalse(grind.isFocusWanted());
		assertTrue(Double.isFinite(grind.getHoursToNext()));

		// A wanted slot is the one watched, however dry the rest.
		p.toggleWanted(PET);
		Report wanting = new Analyst(data).analyse(structure, p, false, true, -1, -1);
		Grind hunt = Grind.of(wanting, "Beast kills", 1_000);
		assertEquals(PET, hunt.getFocus().getItemId());
		assertTrue(hunt.isFocusWanted());
		assertEquals(0, hunt.getAdded());
	}

	@Test
	public void theCardStepsAsideAfterAWhileAndOnlyForAPageItKnows()
	{
		Progress p = new Progress();
		p.setCounter("Beast kills", 10);
		p.markPageRead("Beast", 1);
		Report report = new Analyst(data).analyse(structure, p, false, true, -1, -1);
		Grind grind = Grind.of(report, "Beast kills", 1_000);
		assertTrue(grind.isShowing(1_000 + Grind.SHOW_MS - 1));
		assertFalse(grind.isShowing(1_000 + Grind.SHOW_MS));
		assertNull(Grind.of(report, "Imp kills", 1_000));
		assertNull(Grind.of(report, null, 1_000));
		assertNull(Grind.of(null, "Beast kills", 1_000));
		// A finished page has nothing left to grind.
		p.addOwned(PET);
		p.addOwned(HEAD);
		p.addOwned(SHIELD);
		assertNull(Grind.of(new Analyst(data).analyse(structure, p, false, true, -1, -1), "Beast kills", 1_000));
		assertSame(null, Grind.of(Report.loggedOut(), "Beast kills", 0));
	}

	@Test
	public void noCardUntilWhatYouOwnOnThePageIsKnown()
	{
		// A first kill before the log was ever opened: every slot reads as missing, so the card would claim
		// "3 slots left" and a dry slot the account may have owned for years.
		Progress p = new Progress();
		p.setCounter("Beast kills", 300);
		assertNull(Grind.of(new Analyst(data).analyse(structure, p, false, true, -1, -1), "Beast kills", 1_000));
		// A full read of the log is as good as opening the page.
		p.setFullReadAt(5);
		assertEquals("Beast", Grind.of(new Analyst(data).analyse(structure, p, false, true, -1, -1), "Beast kills", 1_000).getPage());
	}
}

