package com.codex.loginsight.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class OddsTest
{
	@Test
	public void oneSlotTakesItsDropRate()
	{
		// A single 1 in 100 slot takes 100 attempts on average.
		assertEquals(100, Odds.attemptsToAll(new double[]{100}, 0), 1.5);
		assertEquals(100, Odds.attemptsToNext(0.01, Double.POSITIVE_INFINITY), 1e-9);
	}

	@Test
	public void twoEqualSlotsTakeOneAndAHalfTimesAsLong()
	{
		// Waiting for both of two 1 in 100 slots: 100 * (1 + 1/2) on average.
		assertEquals(150, Odds.attemptsToAll(new double[]{100, 100}, 0), 2);
	}

	@Test
	public void fixedRewardSetsAFloor()
	{
		assertEquals(500, Odds.attemptsToAll(new double[]{10}, 500), 1);
		assertEquals(500, Odds.attemptsToAll(new double[0], 500), 1e-9);
		// A 1 in 10 roll racing a reward earned at 5 attempts usually ends a little sooner than 5.
		assertEquals(1 - Math.pow(0.9, 5), Odds.attemptsToNext(0.1, 5) * 0.1, 1e-9);
	}

	@Test
	public void finishingIsNeverQuickerThanTheNextSlot()
	{
		// One 1 in 3 slot: the next slot and the last are the same wait.
		assertEquals(Odds.attemptsToNext(1 / 3.0, Double.POSITIVE_INFINITY), Odds.attemptsToAll(new double[]{3}, 0), 0.05);
	}

	@Test
	public void piecesInOrderWaitOneAfterAnother()
	{
		// Three pieces that each take 100 attempts and only drop in order take 300 on average,
		// and run much tighter than one 300 attempt slot, so racing another slot ends sooner.
		assertEquals(300, Odds.attemptsToAll(0, new double[]{300}, new int[]{3}), 3);
		double chained = Odds.attemptsToAll(0, new double[]{300, 300}, new int[]{3, 1});
		double single = Odds.attemptsToAll(0, new double[]{300, 300}, new int[]{1, 1});
		assertEquals(450, single, 5);
		assertTrue(chained < single - 20 && chained > 300);
		// Erlang: three stages of mean 1 are all done by 3 with chance 1 - e^-3 (1 + 3 + 4.5).
		assertEquals(1 - Math.exp(-3) * 8.5, Odds.runDone(3, 3, 3), 1e-12);
	}

	@Test
	public void luckIsHalfWayWhenExactlyAverage()
	{
		assertEquals(0.5, Odds.luckPercentile(new double[]{0.5}, 0) + Odds.luckPercentile(new double[]{0.5}, 1) - 0.5, 1e-9);
		// Owning a slot nobody would expect yet is very lucky; missing a sure thing is very dry.
		assertTrue(Odds.luckPercentile(new double[]{0.02}, 1) > 0.98);
		assertTrue(Odds.luckPercentile(new double[]{0.98}, 0) < 0.02);
	}

	@Test
	public void luckPercentileOfSeveralSlots()
	{
		double[] chances = {0.5, 0.5};
		// Outcomes: 0 owned 25%, 1 owned 50%, 2 owned 25%.
		assertEquals(0.125, Odds.luckPercentile(chances, 0), 1e-9);
		assertEquals(0.5, Odds.luckPercentile(chances, 1), 1e-9);
		assertEquals(0.875, Odds.luckPercentile(chances, 2), 1e-9);
	}
}

package com.codex.loginsight.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.codex.loginsight.data.Activity;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class ProspectTest
{
	private static Prospect prospect(double perHour, double[] means, int[] stages, double[] exact)
	{
		return new Prospect("Killing the beast", Activity.Category.COMBAT, perHour, 0, false, null, -1, null, means, stages,
			exact, Collections.emptyList());
	}

	@Test
	public void oneRolledSlotFollowsTheGeometricOdds()
	{
		Prospect p = prospect(50, new double[]{100}, new int[]{1}, new double[0]);
		// Two hours is 100 kills at 1 in 100.
		double owned = 1 - Math.pow(0.99, 100);
		assertEquals(owned, p.expectedSlots(2), 1e-9);
		assertEquals(owned, p.chanceOfAny(2), 1e-9);
		assertEquals(owned, p.chanceOfAll(2), 1e-9);
		// Half of all players have it by ln 2 / -ln 0.99 kills.
		assertEquals(Math.log(0.5) / Math.log(0.99) / 50, p.hoursToAll(0.5), 1e-6);
		assertEquals(Math.log(0.1) / Math.log(0.99) / 50, p.hoursToAll(0.9), 1e-6);
		assertEquals(0, p.expectedSlots(0), 0);
	}

	@Test
	public void earnedSlotsArePaidForCheapestFirst()
	{
		Prospect p = prospect(10, new double[0], new int[0], new double[]{50, 30});
		assertEquals(0, p.expectedSlots(2.9), 0);
		assertEquals(1, p.expectedSlots(3), 0);
		assertEquals(1, p.expectedSlots(7.9), 0);
		assertEquals(2, p.expectedSlots(8), 0);
		assertEquals(0, p.chanceOfAny(2), 0);
		assertEquals(1, p.chanceOfAny(3), 0);
		assertEquals(0, p.chanceOfAll(7.9), 0);
		assertEquals(1, p.chanceOfAll(8), 0);
		assertEquals(8, p.hoursToAll(0.5), 1e-6);
	}

	@Test
	public void piecesThatDropInOrderWaitOneAfterAnother()
	{
		// Two pieces sharing a 40-kill run: 20 kills each on average.
		Prospect p = prospect(20, new double[]{40}, new int[]{2}, new double[0]);
		assertEquals(2, p.getRemaining());
		double x = 1;
		double first = 1 - Math.exp(-x);
		double second = 1 - Math.exp(-x) * (1 + x);
		assertEquals(first + second, p.expectedSlots(1), 1e-9);
		// Only the first piece can be the first new slot.
		assertEquals(first, p.chanceOfAny(1), 1e-9);
		assertEquals(second, p.chanceOfAll(1), 1e-9);
		assertEquals(2, p.expectedSlots(1000), 1e-6);
	}

	@Test
	public void setupHoursComeBeforeAnyAttempt()
	{
		Prospect p = new Prospect("Diving", Activity.Category.OTHER, 10, 2, false, null, -1, null, new double[]{10},
			new int[]{1}, new double[0], Collections.emptyList());
		assertEquals(0, p.expectedSlots(2), 0);
		assertEquals(1 - Math.pow(0.9, 10), p.expectedSlots(3), 1e-9);
		assertEquals(2 + Math.log(0.5) / Math.log(0.9) / 10, p.hoursToAll(0.5), 1e-6);
	}

	@Test
	public void projectionOfOnePartMatchesItsOwnQuantiles()
	{
		Prospect p = prospect(50, new double[]{100, 400}, new int[]{1, 1}, new double[0]);
		Projection projection = Projection.of(Collections.singletonList(p), 0);
		assertNotNull(projection);
		assertEquals(p.hoursToAll(0.5), projection.getMedian(), 1e-9);
		assertEquals(p.hoursToAll(0.9), projection.getLikely(), 1e-9);
		assertEquals(0.5, projection.chanceBy(projection.getMedian()), 0.02);
		double previous = -1;
		for (double c : projection.getChance())
		{
			assertTrue(c >= previous);
			previous = c;
		}
	}

	@Test
	public void projectionAddsUpActivitiesHuntedInTurn()
	{
		// Two one-hour exponential waits in a row are an Erlang wait of two: half done by 1.678 hours.
		Prospect a = prospect(1000, new double[]{1000}, new int[]{1}, new double[0]);
		Prospect b = prospect(500, new double[]{500}, new int[]{1}, new double[0]);
		Projection projection = Projection.of(Arrays.asList(a, b), 0);
		assertNotNull(projection);
		assertEquals(1.678, projection.getMedian(), 1.678 * 0.02);
		assertEquals(3.890, projection.getLikely(), 3.890 * 0.02);
		assertEquals(1 - Math.exp(-2) * 3, projection.chanceBy(2), 0.02);
	}

	@Test
	public void nothingToProjectGivesNoProjection()
	{
		assertNull(Projection.of(Collections.emptyList(), 2));
		assertNull(Projection.of(Collections.singletonList(prospect(0, new double[]{10}, new int[]{1}, new double[0])), 0));
	}
}

package com.codex.loginsight.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.codex.loginsight.data.Activity;
import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/** The play session's tally, dry milestones, and a skilling pet's odds at a higher level. */
public class SessionAndMilestoneTest
{
	private static final int PET = 1;
	private static final int HEAD = 2;
	private static final int TOKEN = 3;
	private static final int OTHER = 9;

	private static ItemOdds odds(String label, double in, int guaranteedBy)
	{
		return new ItemOdds(Collections.singletonList(new ItemOdds.Roll(label, 1 / in, 1)), guaranteedBy);
	}

	private static LogData data()
	{
		Activity beast = new Activity(0, "Killing the beast", Activity.Category.COMBAT, 50, 40, 0, Arrays.asList(
			new Activity.Drop(0, PET, 1000, 0), new Activity.Drop(0, HEAD, 100, 0), new Activity.Drop(0, TOKEN, 50, 0)));
		Map<Integer, ItemOdds> odds = new HashMap<>();
		odds.put(PET, odds("Beast kills", 1000, 0));
		odds.put(HEAD, odds("Beast kills", 100, 0));
		odds.put(TOKEN, odds("Beast kills", 50, 60));
		odds.put(OTHER, odds("Imp kills", 10, 0));
		return new LogData(Collections.singletonList(beast), Arrays.asList("Beast kills", "Imp kills"), odds,
			Collections.singleton(PET));
	}

	private static Progress progress(int beastKills)
	{
		Progress p = new Progress();
		p.setCounter("Beast kills", beastKills);
		p.setCounter("Imp kills", 3);
		return p;
	}

	// ---- Session ----

	@Test
	public void aSessionCountsTheKillsAddedAndTheSlotsTheyGave()
	{
		LogData data = data();
		Progress p = progress(40);
		Session session = new Session(p.getOwned(), 1_000);
		// The first kill message sets where the counter started: one below it.
		session.observe("Beast kills", 41, true);
		p.setCounter("Beast kills", 41);
		for (int kc = 42; kc <= 140; kc++)
		{
			session.observe("Beast kills", kc, true);
			p.setCounter("Beast kills", kc);
		}
		p.addOwned(HEAD);
		p.addFind(new Progress.Find(HEAD, "Beast head", "Beast", "Beast kills", 120, 0.01, 0.5, 5_000));
		Session.Summary s = session.read(data, p, 1_000 + 80 * 60_000L);
		assertEquals(80 * 60_000L, s.getMillis());
		assertEquals(1, s.getGains().size());
		assertEquals(100, s.getGains().get(0).getAdded());
		assertEquals(100, s.addedTotal());
		assertEquals(1, s.getFinds().size());
		Luck luck = s.getLuck();
		assertNotNull(luck);
		// The pet, the head, and the token: guaranteed at 60, which this session passed.
		assertEquals(3, luck.getSlots());
		double expected = (1 - Math.pow(1 - 1 / 1000.0, 100)) + (1 - Math.pow(1 - 1 / 100.0, 100)) + 1;
		assertEquals(expected, luck.getExpected(), 1e-9);
		assertEquals(1, luck.getOwned());
	}

	@Test
	public void staleCountsAndPageReadsAreNotTonightsKills()
	{
		LogData data = data();
		Progress p = progress(100);
		Session session = new Session(p.getOwned(), 0);
		// Weeks since the count was saved: the first kill message tonight says 301, which is one kill.
		session.observe("Beast kills", 301, true);
		p.setCounter("Beast kills", 301);
		// A page opened for the first time this session only sets where that counter starts.
		session.observe("Imp kills", 50, false);
		p.setCounter("Imp kills", 50);
		Session.Summary s = session.read(data, p, 60_000);
		assertEquals(1, s.getGains().size());
		assertEquals("Beast kills", s.getGains().get(0).getLabel());
		assertEquals(1, s.getGains().get(0).getAdded());
	}

	@Test
	public void aLogReadMidSessionIsNotALuckyNight()
	{
		LogData data = data();
		Progress p = progress(10);
		Session session = new Session(p.getOwned(), 1_000);
		session.observe("Beast kills", 11, true);
		p.setCounter("Beast kills", 11);
		// Pressing Search reads in a head owned for years: owned now, but it did not drop tonight.
		p.addOwned(HEAD);
		Session.Summary s = session.read(data, p, 2_000);
		assertEquals(0, s.getLuck().getOwned());
		// Nor is it a slot tonight's kills could have given: it was owned all along.
		assertEquals(2, s.getLuck().getSlots());
		assertTrue(s.getFinds().isEmpty());
		// A find from before the session is not tonight's either.
		p.addFind(new Progress.Find(PET, "Beastling", "Beast", "Beast kills", 5, 0.001, 0.9, 500));
		assertTrue(session.read(data, p, 2_000).getFinds().isEmpty());
	}

	@Test
	public void aQuietSessionIsEmpty()
	{
		Session session = new Session(new HashSet<>(), 0);
		Session.Summary s = session.read(data(), progress(5), 1_000);
		assertTrue(s.isEmpty());
		assertNull(s.getLuck());
	}

	// ---- Dry milestones ----

	@Test
	public void theKillThatPassesAMilestoneIsNoticedOnce()
	{
		LogData data = data();
		Progress p = progress(0);
		// The head is 1 in 100: half of players have it by 69 kills, nine in ten by 230.
		assertEquals(69, DryWatch.countFor(1 / 100.0, 0.5));
		assertEquals(230, DryWatch.countFor(1 / 100.0, 0.9));
		// Half is only the average: nothing is said there.
		assertTrue(DryWatch.passed(data, p.getOwned(), p.getCounters(), "Beast kills", 68, 69).isEmpty());
		List<DryWatch.Milestone> at230 = DryWatch.passed(data, p.getOwned(), p.getCounters(), "Beast kills", 229, 230);
		assertEquals(1, at230.size());
		assertEquals(HEAD, at230.get(0).getItemId());
		assertEquals("9 in 10 players", at230.get(0).players());
		assertTrue(DryWatch.passed(data, p.getOwned(), p.getCounters(), "Beast kills", 230, 231).isEmpty());
	}

	@Test
	public void milestonesSkipOwnedGuaranteedAndFirstReadSlots()
	{
		LogData data = data();
		Progress p = progress(0);
		p.addOwned(HEAD);
		// Owned: nothing to say. The token is guaranteed by 60, so "dry" means nothing for it.
		assertTrue(DryWatch.passed(data, p.getOwned(), p.getCounters(), "Beast kills", 229, 230).isEmpty());
		assertTrue(DryWatch.passed(data, p.getOwned(), p.getCounters(), "Beast kills", 30, 140).isEmpty());
		// A count read for the first time, or going back, is not a kill.
		assertTrue(DryWatch.passed(data, new HashSet<>(), p.getCounters(), "Beast kills", 0, 5000).isEmpty());
		assertTrue(DryWatch.passed(data, new HashSet<>(), p.getCounters(), "Beast kills", 300, 200).isEmpty());
	}

	@Test
	public void aJumpPastSeveralMilestonesSaysTheFurthestFirst()
	{
		LogData data = data();
		List<DryWatch.Milestone> passed = DryWatch.passed(data, new HashSet<>(), progress(0).getCounters(), "Beast kills",
			60, 2400);
		// The head passes 9 in 10 (230) and 99 in 100 (459); the pet passes 9 in 10 (2,302).
		assertEquals(2, passed.size());
		assertEquals(HEAD, passed.get(0).getItemId());
		assertEquals("99 in 100 players", passed.get(0).players());
		assertEquals(PET, passed.get(1).getItemId());
		assertEquals("9 in 10 players", passed.get(1).players());
	}

	@Test
	public void theKillThatDropsTheSlotIsNotCalledDryOnIt()
	{
		LogData data = data();
		Progress p = progress(0);
		DryWatch.Queue queue = new DryWatch.Queue();
		// Kill 230 drops the head. The kill count line comes first, the "new item" line just after.
		queue.add("Beast kills", 229, 230, 1_000);
		// Checked at once (the old way) the head would still look missing.
		assertEquals(1, DryWatch.passed(data, p.getOwned(), p.getCounters(), "Beast kills", 229, 230).size());
		assertTrue(queue.due(1_000).isEmpty());
		p.addOwned(HEAD);
		assertTrue(queue.due(1_000 + DryWatch.SETTLE_TICKS - 1).isEmpty());
		List<DryWatch.Pending> due = queue.due(1_000 + DryWatch.SETTLE_TICKS);
		assertEquals(1, due.size());
		assertTrue(queue.isEmpty());
		DryWatch.Pending kill = due.get(0);
		// By the time it is checked the slot is owned, so nothing is said about it.
		assertTrue(DryWatch.passed(data, p.getOwned(), p.getCounters(), kill.getLabel(), kill.getBefore(), kill.getAfter()).isEmpty());

		// Without a drop, the same kill still gets its line, just a moment later.
		Progress dry = progress(0);
		queue.add("Beast kills", 229, 230, 2_000);
		DryWatch.Pending late = queue.due(2_000 + DryWatch.SETTLE_TICKS).get(0);
		assertEquals(1, DryWatch.passed(data, dry.getOwned(), dry.getCounters(), late.getLabel(), late.getBefore(), late.getAfter()).size());
	}

	@Test
	public void quickKillsOfOneCounterAreCheckedTogether()
	{
		DryWatch.Queue queue = new DryWatch.Queue();
		queue.add("Beast kills", 228, 229, 10);
		queue.add("Beast kills", 229, 230, 11);
		queue.add("Other kills", 5, 6, 11);
		assertTrue(queue.due(10 + DryWatch.SETTLE_TICKS).isEmpty());
		List<DryWatch.Pending> due = queue.due(11 + DryWatch.SETTLE_TICKS);
		assertEquals(2, due.size());
		// One check across both kills: 228 to 230 still passes 230 once.
		assertEquals(228, due.get(0).getBefore());
		assertEquals(230, due.get(0).getAfter());
		// A tick count that starts again (a new login) settles what waited rather than holding it for ever.
		queue.add("Beast kills", 300, 301, 50_000);
		assertEquals(1, queue.due(5).size());
	}

	@Test
	public void aCounterThatNeverRestsIsStillCheckedInGoodTime()
	{
		// A count every other tick for a minute: waiting for a quiet moment would wait for ever.
		DryWatch.Queue queue = new DryWatch.Queue();
		int checked = 0;
		for (int tick = 0; tick < 100; tick++)
		{
			if (tick % 2 == 0)
			{
				queue.add("Fast kills", tick / 2, tick / 2 + 1, tick);
			}
			for (DryWatch.Pending p : queue.due(tick))
			{
				checked++;
				assertTrue("checked by " + tick, tick <= 3 * DryWatch.SETTLE_TICKS + (p.getBefore() * 2));
			}
		}
		assertTrue("checked " + checked + " times", checked >= 100 / (3 * DryWatch.SETTLE_TICKS) - 1);
	}

	@Test
	public void milestonesWaitUntilTheLogHasBeenRead()
	{
		// Never searched: every slot would look missing.
		assertTrue(!DryWatch.ownedKnown(0, -1, 0));
		// Read, but the game counts more slots than were read in since.
		assertTrue(!DryWatch.ownedKnown(5, 800, 790));
		assertTrue(DryWatch.ownedKnown(5, 800, 800));
		// The game's count not sent yet (-1) is no reason to stay quiet once the log was read.
		assertTrue(DryWatch.ownedKnown(5, -1, 800));
	}

	// ---- Skilling pets at a higher level ----

	@Test
	public void aSkillingPetSaysWhatLevelsWouldDo()
	{
		Activity.Drop rocky = new Activity.Drop(0, 20663, 35_490, 0, "THIEVING", 36_490);
		PetPlan.LevelUp up = Analyst.levelUp(rocky, new Unlocks(Collections.singletonMap("THIEVING", 40), Collections.emptySet()));
		assertNotNull(up);
		assertEquals(40, up.getLevel());
		assertEquals("Thieving", up.skillName());
		assertEquals(1 / 34_015.0, up.getChance(), 1e-12);
		// A 99 is told what 200M experience does; one with 200M has nothing left to gain.
		Activity.Drop at99 = new Activity.Drop(0, 20663, 34_015, 0, "THIEVING", 36_490);
		PetPlan.LevelUp maxed = Analyst.levelUp(at99, new Unlocks(Collections.singletonMap("THIEVING", 99), Collections.emptySet()));
		assertTrue(maxed.isMaxedExperience());
		assertEquals(15 / 34_015.0, maxed.getChance(), 1e-12);
		Activity.Drop at200m = new Activity.Drop(0, 20663, 34_015 / 15.0, 0, "THIEVING", 36_490);
		assertNull(Analyst.levelUp(at200m, new Unlocks(Collections.singletonMap("THIEVING", 99), Collections.emptySet())));
		// Unknown levels and flat-rate pets say nothing.
		assertNull(Analyst.levelUp(rocky, Unlocks.UNKNOWN));
		assertNull(Analyst.levelUp(new Activity.Drop(0, PET, 1000, 0),
			new Unlocks(Collections.singletonMap("THIEVING", 40), Collections.emptySet())));
	}
}

package com.codex.loginsight.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class SetupTest
{
	private static Report.PageReport page(String name, int owned, int count, String label, boolean read)
	{
		return new Report.PageReport("Bosses", name, owned, 10, Collections.emptyList(), count, label, null,
			Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY, null, 0, read, Collections.emptyList());
	}

	private static Report report(int officialOwned, int knownOwned, long fullReadAt, List<Report.PageReport> pages)
	{
		return new Report(true, true, officialOwned, 1500, knownOwned, 1500, fullReadAt, 0, pages.size(), 0, null,
			Double.POSITIVE_INFINITY, 0, false, pages, Collections.emptyList(), Collections.emptyList(), Collections.emptyList());
	}

	@Test
	public void aFreshInstallHasEverythingLeft()
	{
		Setup setup = Setup.of(report(-1, 0, 0, Collections.singletonList(page("Vorkath", 0, -1, "Vorkath", false))), 3);
		assertFalse(setup.isLogRead());
		assertFalse(setup.isDone());
	}

	@Test
	public void pagesYouHaveFindsOnButNoCountAreNamedMostFindsFirst()
	{
		List<Report.PageReport> pages = Arrays.asList(
			page("Zulrah", 2, -1, "Zulrah", false),
			page("Vorkath", 5, -1, "Vorkath", false),
			page("Giant Mole", 0, -1, "Giant Mole", false), // never played: nothing to credit
			page("Barrows Chests", 9, 300, "Barrows Chests", false), // counted already
			page("Miscellaneous", 4, -1, null, false), // no kill count to read on this page
			page("Hespori", 1, -1, "Hespori", true), // opened, and still showed none
			page("Kraken", 1, -1, "Kraken", false),
			page("Cerberus", 3, -1, "Cerberus", false));
		Setup setup = Setup.of(report(30, 30, 1, pages), 1);
		assertTrue(setup.isLogRead());
		assertEquals(Arrays.asList("Vorkath", "Cerberus", "Zulrah"), names(setup.getToOpen()));
		assertEquals(4, setup.getToOpenTotal());
		assertEquals(1, setup.getPagesCounted());
		assertEquals(7, setup.getPagesCountable());
		assertFalse(setup.isDone());
	}

	@Test
	public void notificationsOffIsTheOnlyThingLeft()
	{
		Setup setup = Setup.of(report(30, 30, 1, Collections.singletonList(page("Vorkath", 3, 120, "Vorkath", true))), 0);
		assertTrue(setup.noticesOff());
		assertFalse(setup.isDone());
		assertTrue(Setup.of(report(30, 30, 1, Collections.singletonList(page("Vorkath", 3, 120, "Vorkath", true))), 2).isDone());
	}

	@Test
	public void anUnreadSettingIsNotHeldAgainstYou()
	{
		Setup setup = Setup.of(report(30, 30, 1, Collections.emptyList()), Setup.NOTICES_UNKNOWN);
		assertFalse(setup.noticesKnown());
		assertFalse(setup.noticesOff());
		assertTrue(setup.isDone());
	}

	@Test
	public void slotsGainedElsewhereAskForAnotherRead()
	{
		// The game counts more slots than Log Insight knows: some came on mobile or with the plugin off.
		assertFalse(Setup.of(report(42, 30, 1, Collections.emptyList()), 3).isLogRead());
	}

	@Test
	public void theSettingTravelsWithTheReport()
	{
		Report r = report(30, 30, 1, Collections.emptyList()).withNotices(0);
		assertTrue(r.setup().noticesOff());
		assertTrue(r.withSession(null).setup().noticesOff());
	}

	private static List<String> names(List<Report.PageReport> pages)
	{
		String[] out = new String[pages.size()];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = pages.get(i).getName();
		}
		return Arrays.asList(out);
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.ItemOdds;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SlotResolverTest
{
	private static final int PAGE_A = 1;
	private static final int PAGE_B = 2;
	private static final int PAGE_C = 3;

	private final Map<Integer, ItemOdds> odds = new HashMap<>();

	public SlotResolverTest()
	{
		odds.put(PAGE_A, odds("Hard clues completed"));
		odds.put(PAGE_B, odds("Elite clues completed"));
		odds.put(PAGE_C, odds("Elite clues completed"));
	}

	private static ItemOdds odds(String label)
	{
		return new ItemOdds(Collections.singletonList(new ItemOdds.Roll(label, 0.01, 1)), 0);
	}

	private SlotResolver.Result resolve(Set<Integer> owned, String recent)
	{
		return SlotResolver.resolve(Arrays.asList(PAGE_A, PAGE_B, PAGE_C), owned, odds::get, recent);
	}

	@Test
	public void theOnlyMissingSlotWithTheNameIsTheOne()
	{
		SlotResolver.Result result = resolve(new HashSet<>(Arrays.asList(PAGE_A, PAGE_C)), null);
		assertEquals(PAGE_B, result.owned);
		assertFalse(result.ambiguous());
	}

	@Test
	public void theCounterThatJustRoseSettlesIt()
	{
		SlotResolver.Result result = resolve(new HashSet<>(), "Hard clues completed");
		assertEquals(PAGE_A, result.owned);
	}

	@Test
	public void twoSlotsStillPossibleMarksNone()
	{
		// Both elite-clue slots are missing and an elite casket was just opened: either could be the one.
		SlotResolver.Result result = resolve(new HashSet<>(), "Elite clues completed");
		assertEquals(-1, result.owned);
		assertTrue(result.ambiguous());
		assertTrue(result.shown == PAGE_B || result.shown == PAGE_C);
	}

	@Test
	public void noRecentKillAndSeveralMissingMarksNone()
	{
		assertTrue(resolve(new HashSet<>(), null).ambiguous());
	}

	@Test
	public void anUnknownNameIsNothing()
	{
		SlotResolver.Result result = SlotResolver.resolve(Collections.emptyList(), new HashSet<>(), odds::get, null);
		assertEquals(-1, result.owned);
		assertFalse(result.ambiguous());
	}

	@Test
	public void aWholeLogReadReplacesASlotMarkedInError()
	{
		Progress progress = new Progress();
		progress.addOwned(PAGE_A);
		progress.addOwned(PAGE_B);
		progress.toggleWanted(PAGE_C);
		progress.replaceOwned(new HashSet<>(Arrays.asList(PAGE_B, PAGE_C)));
		assertEquals(new HashSet<>(Arrays.asList(PAGE_B, PAGE_C)), progress.getOwned());
		assertFalse(progress.isWanted(PAGE_C));
	}
}

package com.codex.loginsight.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.List;
import org.junit.Test;

public class TrophiesTest
{
	private static Progress.Find find(int id, double chance, double luckier)
	{
		return new Progress.Find(id, "Item " + id, "Page", "Page kills", 100, chance, luckier, id);
	}

	@Test
	public void theRarestStayOnTheShelfRarestFirst()
	{
		Progress p = new Progress();
		p.addFind(find(1, 1 / 512.0, 0.4));
		p.addFind(find(2, 1 / 5000.0, 0.97));
		p.addFind(find(3, 1 / 10_000.0, -1));
		p.addFind(find(4, 0, -1));
		List<Progress.Find> shelf = p.getTrophies();
		assertEquals(3, shelf.size());
		assertEquals(3, shelf.get(0).getItemId());
		assertEquals(2, shelf.get(1).getItemId());
		assertEquals(1, shelf.get(2).getItemId());
	}

	@Test
	public void aGreatDropIsNotPushedOffByOrdinaryOnes()
	{
		Progress p = new Progress();
		p.addFind(find(99, 1 / 5000.0, 0.9));
		for (int i = 0; i < 60; i++)
		{
			p.addFind(find(1000 + i, 1 / 20.0, 0.5));
		}
		// Forty recent finds are kept; the visage dropped out of them long ago but keeps its place on the shelf.
		assertTrue(p.getFinds().stream().noneMatch(f -> f.getItemId() == 99));
		assertEquals(99, p.getTrophies().get(0).getItemId());
		assertEquals(Progress.TROPHIES, p.getTrophies().size());
	}

	@Test
	public void sameOddsGoToTheLuckierFind()
	{
		Progress p = new Progress();
		p.addFind(find(1, 1 / 1000.0, 0.2));
		p.addFind(find(2, 1 / 1000.0, 0.9));
		assertEquals(2, p.getTrophies().get(0).getItemId());
	}

	@Test
	public void anOlderSaveStartsItsShelfFromItsFinds()
	{
		Gson gson = new Gson();
		// Saved before trophies existed: the field is absent.
		String old = "{\"owned\":[1],\"finds\":[{\"itemId\":7,\"name\":\"Visage\",\"chance\":2.0E-4,\"luckier\":0.9,\"count\":5,\"at\":1}]}";
		Progress p = gson.fromJson(old, Progress.class);
		assertEquals(7, p.getTrophies().get(0).getItemId());
		// And once saved again the shelf round-trips on its own.
		Progress back = gson.fromJson(gson.toJson(p), Progress.class);
		assertEquals(1, back.getTrophies().size());
		assertEquals(1, p.copy().getTrophies().size());
	}
}

package com.codex.loginsight.data;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Collections;
import org.junit.Test;

public class LogDataTest
{
	private static final int VORKI = 21992;
	private static final int TANZANITE_FANG = 12922;
	private static final int ABYSSAL_ORPHAN = 13262;

	@Test
	public void bundledTablesLoad() throws Exception
	{
		LogData data = LogData.load(new Gson());
		assertTrue(data.getActivities().size() > 200);
		assertTrue(data.getLabels().contains("Vorkath kills"));
		assertTrue(data.isPet(VORKI));
		assertFalse(data.dropsOf(VORKI).isEmpty());

		// Zulrah rolls its uniques twice a kill, so the fang is about 1 in 512.
		ItemOdds fang = data.odds(TANZANITE_FANG);
		assertNotNull(fang);
		assertEquals("Zulrah kills", fang.mainLabel());
		assertEquals(1 / 512.0, fang.mainChance(), 1 / 512.0 * 0.01);

		ItemOdds orphan = data.odds(ABYSSAL_ORPHAN);
		assertEquals(Math.pow(1 - 1 / 2560.0, 2560), orphan.dryChance(Collections.singletonMap("Abyssal Sire kills", 2560)), 1e-6);
		assertEquals(-1, orphan.dryChance(Collections.emptyMap()), 1e-9);
	}

	@Test
	public void splitCountersKeepTheirCurrentOdds() throws Exception
	{
		// Collection Log Luck splits these counters into stretches (first kill off task, before a buff);
		// every kill must not roll all of them at once.
		LogData data = LogData.load(new Gson());
		assertEquals(1 / 100.0, data.odds(13225).mainChance(), 1e-6); // TzRek-Jad on task
		assertEquals(1 / 75.0, data.odds(21291).mainChance(), 1e-6); // Jal-nib-rek on task
		assertEquals(1 / 200.0, data.odds(19701).mainChance(), 1e-6); // Jar of darkness after its buff
		assertEquals(1 / 75.0, data.odds(31245).mainChance(), 1e-6); // Belle's folly after its buffs
		assertEquals(1, data.odds(11920).getRolls().stream().filter(r -> r.getLabel().equals("King Black Dragon kills")).count());
	}

	@Test
	public void secondRowsForOneSlotAreAlternatives()
	{
		LogData.Raw raw = new LogData.Raw();
		LogData.RawActivity a = new LogData.RawActivity();
		a.n = "Killing araxxor";
		a.c = "C";
		a.m = 45;
		a.i = 40;
		a.d.add(new double[]{1, 3000, 0});
		a.d.add(new double[]{2, 200, 0});
		a.d.add(new double[]{1, 1500, 2});
		raw.activities.add(a);
		LogData data = LogData.fromRaw(raw);
		Activity araxxor = data.getActivities().get(0);
		assertEquals(2, araxxor.getDrops().size());
		assertEquals(1, araxxor.getDrops().get(0).getItemId());
		assertEquals(1500, araxxor.getDrops().get(0).getAttempts(), 1e-9);
		assertEquals(1, data.dropsOf(1).size());
	}

	private static final int ROCKY = 20663;
	private static final int TANGLEROOT = 20661;

	private static Activity.Drop only(LogData data, int itemId)
	{
		assertEquals(1, data.dropsOf(itemId).size());
		return data.dropsOf(itemId).get(0);
	}

	@Test
	public void skillingPetsFollowTheAccountsLevel() throws Exception
	{
		LogData data = LogData.load(new Gson());
		// Bundled at level 99: Rocky from seed stalls is 1 in 36,490 - 25 x 99.
		assertEquals(34_015, only(data, ROCKY).getAttempts(), 1e-9);
		assertEquals(new java.util.TreeSet<>(java.util.Arrays.asList("AGILITY", "FARMING", "FISHING", "HUNTER", "MINING",
			"RUNECRAFTING", "THIEVING", "WOODCUTTING")), data.scaledSkills());

		// A level 40 thief rolls 1 in 35,490; a level 99 one with 200M experience fifteen times as often.
		LogData forty = data.atLevels(Collections.singletonMap("THIEVING", 40), Collections.emptySet());
		assertEquals(35_490, only(forty, ROCKY).getAttempts(), 1e-9);
		LogData maxed = data.atLevels(Collections.singletonMap("THIEVING", 99), Collections.singleton("THIEVING"));
		assertEquals(34_015 / 15.0, only(maxed, ROCKY).getAttempts(), 1e-9);
		// Fruit trees use the wiki's base of 9,000, not Log Adviser's rounded 6,500.
		LogData farmer = data.atLevels(Collections.singletonMap("FARMING", 51), Collections.emptySet());
		assertEquals(9_000 - 25 * 51, only(farmer, TANGLEROOT).getAttempts(), 1e-9);

		// Everything else is untouched, and unknown levels change nothing.
		assertEquals(only(data, TANZANITE_FANG).getAttempts(), only(forty, TANZANITE_FANG).getAttempts(), 1e-9);
		assertEquals(data.getActivities().size(), forty.getActivities().size());
		assertTrue(data.atLevels(null, null) == data);
		assertTrue(data.atLevels(Collections.singletonMap("THIEVING", 99), Collections.emptySet()) == data);
		assertTrue(data.atLevels(Collections.singletonMap("SLAYER", 50), Collections.emptySet()) == data);
	}

	@Test
	public void petAttemptsStayInBounds()
	{
		assertEquals(36_465, Activity.Drop.petAttempts(36_490, 0, false), 1e-9);
		assertEquals(34_015, Activity.Drop.petAttempts(36_490, 126, false), 1e-9);
		assertEquals(1, Activity.Drop.petAttempts(100, 99, false), 1e-9);
	}

	@Test
	public void oldTablesWithoutPetBasesStillLoad()
	{
		LogData.Raw raw = new LogData.Raw();
		LogData.RawActivity a = new LogData.RawActivity();
		a.n = "Thieving";
		a.c = "O";
		a.m = 1000;
		a.i = 1000;
		a.d.add(new double[]{ROCKY, 34_015, 0});
		raw.activities.add(a);
		LogData data = LogData.fromRaw(raw);
		assertFalse(only(data, ROCKY).isLevelScaled());
		assertTrue(data.atLevels(Collections.singletonMap("THIEVING", 30), Collections.emptySet()) == data);
	}
}

package com.codex.loginsight.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.codex.loginsight.core.Progress;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.SwingUtilities;
import org.junit.Test;

/** Figures that read the same way everywhere, and a card that never shows an empty plinth. */
public class CohesionTest
{
	@Test
	public void aDropThatIsAlmostCertainNeverReadsAsCertain()
	{
		// 1/1.7 still missing after 213 chests: one minus the share still waiting is exactly 1.0 in a double.
		double stillWaiting = Math.pow(1 - 1 / 1.7, 213);
		assertEquals(1.0, 1 - stillWaiting, 0);
		assertEquals(">99% dry", Format.dry(stillWaiting));
		assertEquals(">99%", Format.have(stillWaiting));
		// A guaranteed drop past its guarantee is overdue, not a figure beside the ">99% dry" rows.
		assertEquals("Overdue", Format.dry(0));
	}

	@Test
	public void expectedSlotsDropTrailingZeros()
	{
		assertEquals("9", Format.slots(9.0));
		assertEquals("9", Format.slots(9.04));
		assertEquals("2.4", Format.slots(2.4));
		assertEquals("0.5", Format.slots(0.5));
		assertEquals("0.48", Format.slots(0.48));
		assertEquals("2", Format.slots(1.999));
		assertEquals("74", Format.slots(74.2));
		assertEquals("10", Format.slots(9.96));
	}

	@Test
	public void theDialsFirstDayLineFitsItsCard()
	{
		Graphics2D g = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		int width = g.getFontMetrics(Theme.small()).stringWidth(LuckDial.NOT_READ_LINE);
		g.dispose();
		// The dial's card is 209 px wide at sidebar width, less its padding.
		assertTrue(width + " px", width <= 190);
	}

	private static Progress.Find find(int id, String name)
	{
		return new Progress.Find(id, name, "Vorkath", "Vorkath kills", 300, 1 / 5000.0, 0.9, 0);
	}

	@Test
	public void theFindsCardHeadsWithTheNameAndCountsTheLogOnce()
	{
		List<Progress.Find> finds = Arrays.asList(find(22006, "Skeletal visage"), find(21992, "Vorki"));
		FindsShare.Spec named = FindsShare.Spec.of(finds, " Gilded Quill ", 872, 1690, 0, ZoneOffset.UTC);
		assertEquals("Gilded Quill", named.heading());
		assertEquals("Finest finds  ·  872 of 1,690 slots", named.subheading());
		FindsShare.Spec anonymous = FindsShare.Spec.of(finds, null, 872, 1690, 0, ZoneOffset.UTC);
		assertEquals("Finest finds", anonymous.heading());
		assertEquals("872 of 1,690 slots", anonymous.subheading());
		// Before the log is read its size is unknown: no "0 of 0".
		assertEquals("Finest finds", FindsShare.Spec.of(finds, "Gilded Quill", 0, 0, 0, ZoneOffset.UTC).subheading());
		assertNull(FindsShare.Spec.of(Collections.emptyList(), "Gilded Quill", 1, 2, 0, ZoneOffset.UTC));
		assertEquals(Arrays.asList(22006, 21992), named.itemIds());
		assertEquals("codex-finds-1970-01-01.png", FindsShare.fileName(0, ZoneOffset.UTC));
		BufferedImage card = FindsShare.render(named, Collections.emptyMap());
		assertEquals(FindsShare.WIDTH * FindsShare.SCALE, card.getWidth());
	}

	/** Pictures that arrive when told to, like the item manager's. */
	private static final class SlowIcons implements ItemIcons
	{
		final Map<Integer, BufferedImage> images = new java.util.HashMap<>();
		final Set<BufferedImage> arrived = Collections.newSetFromMap(new IdentityHashMap<>());
		final List<Runnable> waiting = new ArrayList<>();
		int asked;

		@Override
		public BufferedImage icon(int itemId, Runnable onLoaded)
		{
			asked++;
			waiting.add(onLoaded);
			return images.computeIfAbsent(itemId, id -> new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB));
		}

		@Override
		public boolean ready(BufferedImage image)
		{
			return arrived.contains(image);
		}

		void arrive()
		{
			arrived.addAll(images.values());
			for (Runnable r : waiting)
			{
				r.run();
			}
		}
	}

	private static void flush() throws Exception
	{
		SwingUtilities.invokeAndWait(() -> { });
		SwingUtilities.invokeAndWait(() -> { });
	}

	@Test
	public void theCardWaitsForEveryPictureAndIsMadeOnce() throws Exception
	{
		SlowIcons icons = new SlowIcons();
		List<Map<Integer, BufferedImage>> made = new ArrayList<>();
		SwingUtilities.invokeAndWait(() -> IconWait.forItems(icons, Arrays.asList(22006, 21992, 22006), 60_000, made::add));
		flush();
		assertEquals(0, made.size());
		// The same item twice is asked for once.
		assertEquals(2, icons.asked);
		icons.arrive();
		flush();
		assertEquals(1, made.size());
		assertEquals(2, made.get(0).size());
		// A late second callback does not make a second card.
		icons.arrive();
		flush();
		assertEquals(1, made.size());
	}

	@Test
	public void aPictureThatNeverComesIsGivenUpOn() throws Exception
	{
		SlowIcons icons = new SlowIcons();
		List<Map<Integer, BufferedImage>> made = new ArrayList<>();
		SwingUtilities.invokeAndWait(() -> IconWait.forItems(icons, Collections.singletonList(22006), 50, made::add));
		Thread.sleep(400);
		flush();
		assertEquals(1, made.size());
		assertTrue(made.get(0).isEmpty());
	}

	@Test
	public void aClosedPanelOnlyMarksItsTabsStale() throws Exception
	{
		com.codex.loginsight.core.Report report = com.codex.loginsight.core.Report.loggedOut();
		LogInsightPanel[] panel = new LogInsightPanel[1];
		SwingUtilities.invokeAndWait(() ->
		{
			panel[0] = new LogInsightPanel((id, cb) -> null);
			panel[0].update(report, null);
		});
		// Closed: the report waits rather than rebuilding a page nobody sees.
		assertTrue(panel[0].isStale(0));
		SwingUtilities.invokeAndWait(() -> panel[0].onActivate());
		assertTrue(!panel[0].isStale(0));
		SwingUtilities.invokeAndWait(() -> panel[0].update(report, null));
		// Open: the tab in view is rebuilt at once, the rest wait.
		assertTrue(!panel[0].isStale(0));
		assertTrue(panel[0].isStale(2));
	}

	@Test
	public void aFindWithNoPictureAtAllDoesNotHoldTheCardUp() throws Exception
	{
		List<Map<Integer, BufferedImage>> made = new ArrayList<>();
		ItemIcons none = (id, cb) -> null;
		SwingUtilities.invokeAndWait(() -> IconWait.forItems(none, Collections.singletonList(22006), 60_000, made::add));
		assertEquals(1, made.size());
	}

	@Test
	public void theFirstDayVsAverageNoteFitsItsTile()
	{
		Graphics2D g = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		int width = g.getFontMetrics(Theme.small()).stringWidth(LedgerView.NO_COUNTS);
		g.dispose();
		// A tile is about 97 px at sidebar width and its note gets 16 px less: "needs kill counts" (83 px) was cut.
		assertTrue(width + " px", width <= 80);
	}

	@Test
	public void aCardStillWaitingWhenThePluginStopsIsNeverMade() throws Exception
	{
		SlowIcons icons = new SlowIcons();
		List<Map<Integer, BufferedImage>> made = new ArrayList<>();
		IconWait[] wait = new IconWait[1];
		SwingUtilities.invokeAndWait(() -> wait[0] = IconWait.forItems(icons, Collections.singletonList(22006), 50, made::add));
		// The plugin stops before the picture comes: the give-up timer must not go on to save or copy a card.
		SwingUtilities.invokeAndWait(() -> wait[0].cancel());
		Thread.sleep(300);
		icons.arrive();
		flush();
		assertEquals(0, made.size());
	}
}

package com.codex.loginsight.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class FormatTest
{
	@Test
	public void dryReadsTheWayPlayersSayIt()
	{
		// 18% of players would have a 1/3,000 slot by 612 kc: "18% dry", not "82% dry".
		double stillWaiting = Math.pow(1 - 1 / 3000.0, 612);
		assertEquals("18% dry", Format.dry(stillWaiting));
		assertEquals(">99% dry", Format.dry(0.001));
	}

	@Test
	public void chancesDropNeedlessDecimals()
	{
		assertEquals("1/3", Format.chance(1 / 3.0));
		assertEquals("1/2.5", Format.chance(1 / 2.5));
		assertEquals("1/5,000", Format.chance(1 / 5000.0));
		assertEquals("Always", Format.chance(1));
	}

	@Test
	public void sourcesReadAsNames()
	{
		assertEquals("King Black Dragon", Format.source("Killing king black dragon"));
		assertEquals("Hard Caskets", Format.source("Opening hard caskets"));
		assertEquals("Tombs of Amascut Chests", Format.source("Tombs of amascut reward chests (300)"));
		assertEquals("Leviathan", Format.source("Killing the leviathan"));
		assertEquals("Raid level 300", Format.detail("Tombs of amascut reward chests (300)"));
		assertNull(Format.detail("Killing vorkath"));
	}

	@Test
	public void hoursRoundSensibly()
	{
		assertEquals("<1m", Format.hours(0.001));
		assertEquals("45m", Format.hours(0.75));
		assertEquals("3h 12m", Format.hours(3.2));
		assertEquals("2,616h", Format.hours(2616.08));
		assertEquals("-", Format.hours(Double.POSITIVE_INFINITY));
	}

	@Test
	public void luckLineNeverSaysLuckierThanNobody()
	{
		assertEquals("Luckier than 68% of players", LuckDial.luckLine(68));
		assertEquals("Luckier than 99% of players", LuckDial.luckLine(100));
		assertEquals("Drier than 99% of players", LuckDial.luckLine(0));
		assertEquals("Drier than 70% of players", LuckDial.luckLine(30));
	}

	@Test
	public void trophyPodiumAndStanding()
	{
		org.junit.Assert.assertArrayEquals(new int[]{1, 0, 2}, TrophyShelf.order(3));
		org.junit.Assert.assertArrayEquals(new int[]{0, 1}, TrophyShelf.order(2));
		assertEquals("top 3%", TrophyShelf.standing(0.97));
		assertEquals("top 1%", TrophyShelf.standing(0.999));
		assertEquals("a late one", TrophyShelf.standing(0.3));
		assertNull(TrophyShelf.standing(-1));
		assertEquals("Hallowed Sepulchre", Format.detail("Looting (hallowed sepulchre)"));
	}

	@Test
	public void longActivityNamesFitACard()
	{
		assertEquals("Fossil Island Notes", Format.source("Spending 100 numulite at the fossil island notes chest"));
		assertEquals("Barracuda Salvage", Format.source("Sorting through barracuda salvage"));
		assertEquals("Tempor Tantrum Trials", Format.source("Completing tempor tantrum barracuda trials"));
		assertEquals("Royal Titans", Format.detail("Killing branda, the fire queen (royal titans)"));
		assertEquals("And gambling quiver, Fortis Colosseum", Format.detail("Sol heredit (and gambling quiver, fortis colosseum)"));
		assertEquals("Level 146, on task", Format.detail("Killing araxytes (level 146, on task)"));
	}

	@Test
	public void detailsNeitherMisspellNorRepeatTheName()
	{
		assertEquals("Non-Zaros", Format.detail("Killing spiritual mages (non-zaros)"));
		assertNull(Format.detail("Pulling from the reward guardian (guardians of the rift)"));
	}
}

package com.codex.loginsight.ui;

import static org.junit.Assert.assertEquals;
import com.codex.loginsight.core.Progress;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class TrophyShelfTest
{
	@Test
	public void fourthAndFifthGetARowEachUnderThePodium()
	{
		List<Progress.Find> finds = new ArrayList<>();
		for (int i = 0; i < 5; i++)
		{
			finds.add(new Progress.Find(100 + i, "Item " + i, "Page", null, 0, 1 / (1000.0 - i), -1, i));
		}
		assertEquals(TrophyShelf.HEIGHT, new TrophyShelf(finds.subList(0, 3), null).getPreferredSize().height);
		assertEquals(TrophyShelf.height(2), new TrophyShelf(finds, null).getPreferredSize().height);
		assertEquals(TrophyShelf.height(1), new TrophyShelf(finds.subList(0, 4), null).getPreferredSize().height);
		assertEquals(TrophyShelf.HEIGHT + 8 + 2 * TrophyShelf.ROW, TrophyShelf.height(2));
	}
}
